            $__log_source = (string) ($input['source'] ?? 'errors');
            $__resolved = $__log_resolve($__log_source, $__log_site);
            if (!$__resolved) $__log_fail('Unknown log.');
            [$__log_path, $__log_kind, $__log_needle] = $__resolved;

