                    : (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
                document.documentElement.setAttribute('data-theme', t);
                document.documentElement.setAttribute('data-theme-pref', pref);
            } catch (e) {}
        })();
    </script>
    <link rel="icon" type="image/svg+xml" href="data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'><circle cx='32' cy='32' r='30' fill='%23009b95'/><g fill='none' stroke='%23ffffff' stroke-width='5' stroke-linecap='round' stroke-linejoin='round'><path d='M 17 27 Q 24.5 20 32 27 T 47 27'/><path d='M 17 40 Q 24.5 33 32 40 T 47 40'/></g></svg>">
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400..600;1,9..144,400..600&family=Geist:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after { box-sizing: border-box; }
        html, body { margin: 0; padding: 0; }
        html { background: #0f1210; }
        html[data-theme="light"] { background: #fbfaf7; }

        :root {
            --font-sans: 'Geist', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
            --font-serif: 'Fraunces', Georgia, serif;
            --font-mono: 'JetBrains Mono', ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
            /* sRGB fallback first; browsers without oklch() support silently
               drop the override on the next line and keep the hex value.
               Without the fallback, the whole declaration would be invalid on
               Firefox <113 / Chrome <111 / Safari <16.4 and --accent would be
               unset — which reads as "transparent" for backgrounds and
               "black" for SVG fills (hence the invisible add button and the
               solid-black logo disc on older browsers). */
            --accent: #3a97a9;
            --accent: oklch(62% 0.11 190);
            --accent-fg: #0a1a1c;
            /* Inked: hairlines do the work, corners near-square, nothing floats. */
            --radius-lg: 6px;
            --radius-md: 4px;
            --radius-sm: 3px;
            --radius-pill: 999px;
        }

        html[data-theme="dark"], html:not([data-theme]) {
            --bg: #0f1210;
            --bg-sunk: #0b0e0c;
            --panel: #181c19;
            --panel-hover: #1e2320;
            --panel-border: #3a3f3a;
            --panel-border-strong: #565c56;
            --brand: #1dbcb5;
            --brand: oklch(72% 0.12 190);
            --text: #edeee9;
            --text-dim: #8a8e85;
            --text-faint: #5d615a;
            /* Dark-mode teal is brighter so it reads cleanly against the
               warmer panel — matches the landing page palette. */
            --accent: #4db0c2;
            --accent: oklch(72% 0.12 190);
            --pill-bg: #1e2320;
            --pill-wp-bg: rgba(77, 176, 194, 0.18);
            --pill-wp-bg: color-mix(in oklch, var(--accent) 18%, transparent);
            --pill-wp-fg: #71c0ce;
            --pill-wp-fg: color-mix(in oklch, var(--accent) 80%, white);
            --pill-static-bg: #1e2320;
            --pill-static-fg: #9a9d94;
            --input-bg: #0b0e0c;
            --danger: #d66a6a;
            /* Syntax highlighting in the Files editor. */
            --hl-cmt: #6c716a; --hl-str: #b3c78c; --hl-kw: #7cc3cf; --hl-num: #e0b078; --hl-var: #c7b6e6; --hl-tag: #5fb6c4; --hl-attr: #d8c68e; --hl-fn: #e9e7dc;
            --shadow-lg: none;
            color-scheme: dark;
        }

        html[data-theme="light"] {
            --bg: #fbfaf7;
            --bg-sunk: #f4f2ec;
            --panel: #ffffff;
            --panel-hover: #f6f4ee;
            --panel-border: #c9c4b6;
            --panel-border-strong: #9a948a;
            --brand: #00746f;
            --brand: oklch(48% 0.14 190);
            --text: #1a1c1b;
            --text-dim: #6b6f6a;
            --text-faint: #9a9d97;
            /* White on teal reads stronger than the dark accent-fg does on
               the lighter background — override just for light mode. */
            --accent-fg: #ffffff;
            --pill-bg: #f1ede5;
            --pill-wp-bg: rgba(58, 151, 169, 0.14);
            --pill-wp-bg: color-mix(in oklch, var(--accent) 14%, transparent);
            --pill-wp-fg: #20535d;
            --pill-wp-fg: color-mix(in oklch, var(--accent) 55%, black);
            --pill-static-bg: #f1ede5;
            --pill-static-fg: #8a8781;
            --input-bg: #fbfaf7;
            --danger: #b44848;
            --hl-cmt: #8a8e85; --hl-str: #4f7d2a; --hl-kw: #1f7a8c; --hl-num: #b0641d; --hl-var: #7a4fa8; --hl-tag: #0f6d7a; --hl-attr: #8a6a10; --hl-fn: #2f3a3c;
            --shadow-lg: none;
            color-scheme: light;
        }

        body {
            background: var(--bg);
            color: var(--text);
            font-family: var(--font-sans);
            font-size: 15px;
            line-height: 1.5;
            min-height: 100vh;
            padding: 2.5rem 1.25rem 4rem;
            -webkit-font-smoothing: antialiased;
            font-feature-settings: "ss01", "cv11";
        }

        /* The page widens for mail and databases; ease the width so a view
           switch reads as the same page reshaping, not a new one landing. */
        .wrap { position: relative; max-width: 820px; margin: 0 auto; transition: max-width 280ms cubic-bezier(0.2, 0.7, 0.2, 1); }

        /* Top nav */
        .nav { position: relative; }
        .nav { display: flex; align-items: center; justify-content: space-between; margin-bottom: 2rem; }
        .logo { display: inline-flex; align-items: center; gap: 12px; color: var(--text); text-decoration: none; font-weight: 600; font-size: 1.05rem; letter-spacing: -0.01em; }
        /* Brand mark: cove/bay silhouette in a circle. Classes are scoped to
           .logo-mark so they don't collide with unrelated elements. Colors
           are driven by CSS variables with sensible defaults, so each theme
           can override individual layers without touching the inline SVG. */
        /* Each layer gets a pair of declarations — the sRGB hex applies
           everywhere, then the oklch override kicks in on browsers that
           understand it. Without the fallback, unsupported oklch() in a
           var() default makes the whole `fill`/`stroke` declaration invalid
           and SVG falls back to fill:black (which is what produces the
           solid-black disc + missing layers on Firefox <113). */
        .logo-mark { width: 34px; height: 34px; display: block; flex-shrink: 0; fill: none; stroke: var(--brand); stroke-width: 4; }
        /* Square icon button that cross-fades a moon (light mode) with a sun
           (dark mode). Both SVGs are stacked absolutely so the button size
           stays constant during the transition. */
        .theme-btn { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; border-radius: var(--radius-sm); border: 1px solid var(--panel-border); color: var(--text-dim); background: var(--panel); cursor: pointer; padding: 0; position: relative; flex: none; transition: border-color 120ms, background 120ms, color 120ms; }
        .theme-btn:hover { color: var(--text); background: var(--bg-sunk); }
        .theme-btn svg { width: 15px; height: 15px; position: absolute; transition: opacity 200ms ease, transform 300ms ease; }
        .theme-btn svg { opacity: 0; transform: rotate(-40deg) scale(0.7); }
        /* The icon shows the PREFERENCE (System = half disc), not just the paint. */
        html[data-theme-pref="system"] .theme-btn .icon-system,
        html[data-theme-pref="light"]  .theme-btn .icon-sun,
        html[data-theme-pref="dark"]   .theme-btn .icon-moon { opacity: 1; transform: rotate(0) scale(1); }
        .nav .theme-menu { position: absolute; left: auto; right: 0; top: calc(100% + 6px); z-index: 300; min-width: 150px; padding: 0.3rem; background: var(--panel); border: 1px solid var(--panel-border); border-radius: var(--radius-md); }
        .nav .theme-menu .ctx-item[aria-checked="true"]::after { content: "\2713"; color: var(--accent); font-size: 0.85em; }

        /* Card */
        .card { background: var(--panel); border: 1px solid var(--panel-border); border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-lg); }
        .card-head { display: flex; align-items: center; justify-content: space-between; padding: 1.1rem 1.5rem; border-bottom: 1px solid var(--panel-border); gap: 1rem; }
        .card-title { font-family: var(--font-serif); font-style: italic; font-weight: 500; font-size: 1.45rem; margin: 0; letter-spacing: -0.01em; }
        .card-actions { display: flex; align-items: center; gap: 0.45rem; }

        /* Pills */
        .pill { display: inline-flex; align-items: center; gap: 0.4em; padding: 0.38rem 0.8rem; border-radius: var(--radius-md); font-family: var(--font-mono); font-size: 0.8rem; font-weight: 400; border: 1px solid var(--panel-border); background: transparent; color: var(--text-dim); text-decoration: none; cursor: pointer; transition: color 120ms, border-color 120ms, background 120ms; white-space: nowrap; }
        .pill:hover { color: var(--text); border-color: var(--text-faint); }
        .pill.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-fg); font-weight: 500; }
        .pill.primary:hover { filter: brightness(1.08); color: var(--accent-fg); border-color: var(--accent); }
        .pill:disabled { opacity: 0.5; cursor: not-allowed; }
        .pill-icon { width: 13px; height: 13px; flex: none; opacity: 0.85; }
        .pill:hover .pill-icon { opacity: 1; }

        /* Filter row */
        .filter-row { display: flex; align-items: center; gap: 0.5rem; padding: 0.6rem 1.5rem; border-bottom: 1px solid var(--panel-border); }
        .filter-input { flex: 1; min-width: 0; background: transparent; border: 0; color: var(--text); font-family: var(--font-mono); font-size: 0.88rem; padding: 0.15rem 0; outline: 0; }
        .filter-input::placeholder { color: var(--text-faint); }
        .filter-kbd { font-family: var(--font-mono); font-size: 0.68rem; color: var(--text-faint); border: 1px solid var(--panel-border); border-radius: var(--radius-sm); padding: 0.1rem 0.35rem; }
        .filter-clear { background: transparent; border: 0; color: var(--text-dim); cursor: pointer; font-size: 1.05rem; line-height: 1; padding: 0 0.35rem; border-radius: var(--radius-sm); }
        .filter-clear:hover { color: var(--text); background: var(--panel-hover); }
        /* Chip showing an active type-only filter (set by clicking a row pill).
           Separate state from the free-text filter so users can't hand-edit the
           "type:xxx" tokens and get into a weird parse state. */
        .filter-chip { display: inline-flex; align-items: center; gap: 0.1rem; padding: 0.18rem 0.22rem 0.18rem 0.65rem; background: var(--pill-wp-bg); color: var(--pill-wp-fg); border-radius: var(--radius-pill); font-family: var(--font-mono); font-size: 0.76rem; font-weight: 500; letter-spacing: 0.02em; white-space: nowrap; }
        .filter-chip-x { display: inline-flex; align-items: center; justify-content: center; width: 18px; height: 18px; background: transparent; border: 0; color: inherit; cursor: pointer; border-radius: 50%; font-size: 0.95rem; line-height: 1; padding: 0; }
        .filter-chip-x:hover { background: rgba(58, 151, 169, 0.28); background: color-mix(in oklch, var(--accent) 28%, transparent); }

        /* Add row */
        /* New-site alert: appears after creating a WP site so the one-time
           login is one click away, without hunting for the new row. */
        .new-site-alert { display: flex; align-items: center; gap: 0.75rem; padding: 0.75rem 1.25rem; border-bottom: 1px solid var(--panel-border); background: var(--bg-sunk); background: color-mix(in oklab, var(--accent) 12%, var(--panel)); color: var(--text); font-size: 0.92rem; }
        .new-site-alert-icon { display: inline-grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--accent); color: var(--accent-fg); flex: none; }
        .new-site-alert-text { flex: 1; min-width: 0; }
        .new-site-alert-text strong { font-family: var(--font-mono); font-weight: 500; }
        .new-site-alert-close { background: transparent; border: 0; color: var(--text-dim); cursor: pointer; font-size: 1.15rem; line-height: 1; padding: 0.25rem 0.55rem; border-radius: var(--radius-sm); flex: none; }
        .new-site-alert-close:hover { color: var(--text); background: var(--panel-hover); }

        .add-row { position: relative; padding: 0.9rem 1.5rem; border-bottom: 1px solid var(--panel-border); background: var(--bg-sunk); }
        .add-row.is-creating { overflow: hidden; }
        .add-drop { display: flex; align-items: center; gap: 0.7rem; padding: 0.6rem 0.9rem; margin-bottom: 0.7rem; border: 1px dashed var(--panel-border); border-radius: var(--radius-md); font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); cursor: pointer; transition: border-color 120ms, background 120ms; }
        .add-drop:hover, .add-drop.is-over { border-color: var(--accent); color: var(--text); }
        .add-drop.is-over { background: color-mix(in oklch, var(--accent) 10%, transparent); border-style: solid; }
        .add-drop.has-file { border-style: solid; border-color: var(--accent); }
        .add-drop-art { width: 16px; height: 16px; flex: none; color: var(--text-faint); }
        .add-drop-art svg { width: 100%; height: 100%; }
        .add-drop.has-file .add-drop-art, .add-drop.is-over .add-drop-art { color: var(--accent); }
        .add-drop-text { flex: 1; min-width: 0; }
        .add-drop-text u { text-decoration-color: var(--text-faint); }
        .add-drop-file { display: inline-flex; align-items: center; gap: 0.2rem; padding: 0.15rem 0.25rem 0.15rem 0.6rem; border-radius: var(--radius-pill); background: var(--pill-wp-bg); color: var(--pill-wp-fg); font-size: 0.72rem; white-space: nowrap; }
        .add-progress { font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); padding: 0 0 0.6rem; }
        .add-row.is-importing .plain-toggle, .add-row.is-importing .wp-version, .add-row.has-import .plain-toggle, .add-row.has-import .wp-version { display: none; }
        /* Indeterminate progress stripe across the top while cove add is
           running — site creation takes 5-10s so we need a clear "working"
           cue beyond just the button text swap. Solid accent block slides
           across; a gradient-fade version blended with the row background
           and looked the wrong green. */
        .add-row.is-creating::before {
            content: '';
            position: absolute; top: 0; height: 3px; width: 30%;
            /* A thin 2px stripe of var(--accent) perceptually muted to olive
               against the cream bg-sunk; a brighter, more saturated teal at
               3px reads unambiguously as teal (same hue as the brand, just
               higher chroma so it survives the narrow band). */
            background: #3fb6cf;
            background: oklch(72% 0.15 190);
            animation: add-row-slide 1.3s linear infinite;
        }
        @keyframes add-row-slide {
            from { left: -30%; }
            to   { left: 100%; }
        }
        /* Inline spinner for the create button (reuses the .site-action-btn
           .btn-spinner pattern but scoped so pill button layout isn't altered). */
        .pill .btn-spinner { display: inline-block; width: 11px; height: 11px; border: 1.5px solid currentColor; border-top-color: transparent; border-radius: 50%; animation: spin 0.6s linear infinite; flex: none; }
        .add-row form { display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap; }
        .add-row input[type="text"] { background: var(--input-bg); border: 1px solid var(--panel-border); color: var(--text); font-family: var(--font-mono); font-size: 0.9rem; padding: 0.5rem 0.8rem; border-radius: var(--radius-md); min-width: 200px; flex: 1; }
        .add-row input[type="text"]:focus { outline: 0; border-color: var(--accent); }
        .add-row .plain-toggle { display: inline-flex; align-items: center; gap: 0.4rem; color: var(--text-dim); font-size: 0.85rem; cursor: pointer; }
        .add-row .plain-toggle input { accent-color: var(--accent); }
        .add-row select.wp-version { background: var(--input-bg); border: 1px solid var(--panel-border); color: var(--text); font-family: var(--font-mono); font-size: 0.85rem; padding: 0.5rem 0.7rem; border-radius: var(--radius-md); flex: none; cursor: pointer; }
        .add-row select.wp-version:focus { outline: 0; border-color: var(--accent); }

        /* Site list — one grid on the <ul>, rows inherit its columns via
           subgrid so type/modified/size/actions align vertically across rows
           instead of each row sizing independently. */
        .site-list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: 1fr auto auto auto auto; column-gap: 0.9rem; }
        .site-row { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; align-items: center; padding: 0.8rem 1.5rem; border-bottom: 1px solid var(--panel-border); transition: background 100ms; cursor: pointer; }
        .site-row:last-child { border-bottom: 0; }
        .site-row:hover { background: var(--panel-hover); }
        .site-domain-cell { display: inline-flex; align-items: center; gap: 0.35rem; min-width: 0; }
        .site-domain { font-family: var(--font-mono); font-size: 0.88rem; color: var(--text-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .site-domain .host-accent { color: var(--accent); }
        /* The one spot on a row that opens the site — everywhere else on the
           row opens the context menu. Always visible (not hover-gated) so a
           site stays one tap away on touch. */
        .site-open-link { display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px; border-radius: var(--radius-sm); color: var(--text-faint); flex: none; }
        .site-open-link:hover { color: var(--accent); background: var(--panel-border); }
        .site-open-link svg { width: 13px; height: 13px; }
        .site-domain mark { background: rgba(58, 151, 169, 0.28); background: color-mix(in oklch, var(--accent) 28%, transparent); color: inherit; padding: 0 1px; border-radius: var(--radius-sm); }
        .site-type { display: inline-flex; justify-content: center; min-width: 64px; padding: 0.2rem 0.55rem; border-radius: var(--radius-pill); font-family: var(--font-mono); font-size: 0.68rem; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; cursor: pointer; user-select: none; transition: filter 120ms; }
        .site-type:hover { filter: brightness(1.15); }
        /* One grid child holding the pill plus its version, so adding the
           version does not shift the row's subgrid columns. */
        .site-type-cell { display: inline-flex; align-items: baseline; gap: 0.45rem; min-width: 0; }
        .site-wp-version { font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); white-space: nowrap; }
        /* Local sites aren't exposed, so an insecure release is a nudge to
           update rather than a warning — hence the dot, not a red badge. */
        .site-wp-version.insecure { color: var(--text-dim); }
        .site-wp-version.insecure::after { content: "●"; margin-left: 0.25rem; color: var(--pill-warn-fg, #d08c30); font-size: 0.6em; vertical-align: middle; }
        .site-type.wp { background: var(--pill-wp-bg); color: var(--pill-wp-fg); }
        .site-type.static { background: var(--pill-static-bg); color: var(--pill-static-fg); }
        /* Pinned-PHP chip: only rendered when a site is pinned off the default,
           so the common case stays visually quiet. While a version change is
           applying (or installing), the chip pulses with the target version. */
        .site-php-version { font-family: var(--font-mono); font-size: 0.66rem; color: var(--text-faint); white-space: nowrap; border: 1px solid var(--panel-border); border-radius: var(--radius-pill); padding: 0.05rem 0.45rem; }
        .site-php-version.applying { border-color: var(--accent); color: var(--text-dim); animation: php-pulse 1.2s ease-in-out infinite; }
        @keyframes php-pulse { 50% { opacity: 0.45; } }
        .site-modified { font-family: var(--font-mono); font-size: 0.8rem; color: var(--text-faint); min-width: 44px; text-align: right; }
        .site-size { font-family: var(--font-mono); font-size: 0.82rem; color: var(--text-dim); min-width: 64px; text-align: right; }
        .site-actions { display: flex; gap: 0.15rem; opacity: 0; transition: opacity 100ms; }
        .site-row:hover .site-actions, .site-row:focus-within .site-actions { opacity: 1; }
        /* Fixed button size + both children stacked in one grid cell. Since
           grid-area "stack" collocates them at the same position and size is
           locked by width/height, toggling opacity on .loading can't shift
           any neighbour. */
        .site-action-btn { display: inline-grid; grid-template-areas: "stack"; place-items: center; box-sizing: border-box; width: 3.5em; height: 1.75em; padding: 0; background: transparent; border: 0; color: var(--text-dim); cursor: pointer; border-radius: var(--radius-sm); font-family: var(--font-mono); font-size: 0.78rem; line-height: 1; }
        .site-action-btn > * { grid-area: stack; }
        .site-action-btn:hover { background: var(--panel-border); color: var(--text); }
        .site-action-btn.danger:hover { color: var(--danger); }
        .site-action-btn:disabled { cursor: wait; }
        .site-action-btn .btn-spinner { width: 10px; height: 10px; border: 1.5px solid currentColor; border-top-color: transparent; border-radius: 50%; animation: spin 0.6s linear infinite; opacity: 0; pointer-events: none; }
        .site-action-btn.loading .btn-label { opacity: 0; }
        .site-action-btn.loading .btn-spinner { opacity: 1; }

        /* Empty + loading states — scoped to direct children of .site-list so
           the global .loading class doesn't leak into unrelated elements
           (notably .site-action-btn.loading, which uses its own state class). */
        .site-list > .empty, .site-list > .loading { grid-column: 1 / -1; padding: 3rem 1.5rem; text-align: center; color: var(--text-dim); }
        .empty-hint { margin-top: 0.35rem; font-family: var(--font-mono); font-size: 0.82rem; color: var(--text-faint); }
        .empty-hint code { background: var(--panel-hover); padding: 0.1rem 0.4rem; border-radius: var(--radius-sm); }
        .empty-art { display: block; width: 104px; height: 68px; margin: 0 auto 1rem; }
        .empty-art .art-line { stroke: var(--text-dim); stroke-width: 2; fill: none; }
        .empty-art .art-fill { fill: var(--accent); opacity: 0.14; stroke: none; }
        .empty-art .art-wave { stroke: var(--accent); stroke-width: 2; fill: none; opacity: 0.55; }

        /* Column headers — subgrid row mirroring .site-row's columns. */
        .site-head { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; align-items: center; padding: 0.5rem 1.5rem; border-bottom: 1px solid var(--panel-border); }
        .site-head-btn, .site-head-label { background: transparent; border: 0; padding: 0; font-family: var(--font-mono); font-size: 0.66rem; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-faint); text-align: left; }
        .site-head-btn { cursor: pointer; border-radius: var(--radius-sm); }
        .site-head-btn:hover { color: var(--text); }
        .site-head-btn.active { color: var(--text-dim); }
        .site-head-label { justify-self: center; }
        .site-head-right { justify-self: end; text-align: right; }
        .sort-arrow { display: inline-block; min-width: 1em; text-align: right; }

        /* Bulk delete — appears in the filter row when a filter narrows the list. */
        .bulk-delete-btn { background: transparent; border: 1px solid var(--panel-border); color: var(--text-dim); cursor: pointer; font-family: var(--font-mono); font-size: 0.76rem; padding: 0.18rem 0.65rem; border-radius: var(--radius-pill); white-space: nowrap; transition: color 120ms, border-color 120ms, background 120ms; }
        .bulk-delete-btn:hover { color: var(--danger); border-color: var(--danger); }
        .bulk-delete-btn.armed { color: white; background: var(--danger); border-color: var(--danger); }

        /* Service dots in the top bar. They used to live only in the footer,
           which on an install with hundreds of sites sits ~14,000px down the
           page — the most glanceable status was the least reachable thing. */
        .nav-services { display: flex; align-items: center; gap: 0.85rem; margin-left: auto; margin-right: 0.85rem; font-family: var(--font-mono); font-size: 0.74rem; white-space: nowrap; flex-shrink: 0; }
        .dot.sweep-dot { gap: 0.35rem; color: var(--text-faint); }
        .sweep-list { display: flex; flex-direction: column; gap: 0; max-height: 52vh; overflow-y: auto; margin: -0.3rem -0.4rem; }
        .sweep-group { font-family: var(--font-mono); font-size: 0.64rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-faint); padding: 0.6rem 0.4rem 0.25rem; }
        .sweep-row { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 0.75rem; padding: 0.22rem 0.4rem; font-family: var(--font-mono); font-size: 0.78rem; border-radius: var(--radius-sm, 4px); }
        .sweep-row:hover { background: var(--panel-hover); }
        .sweep-row.is-pending { color: var(--text-faint); }
        .sweep-row.is-running { color: var(--text); }
        .sweep-name { background: transparent; border: 0; padding: 0; font: inherit; color: inherit; text-align: left; cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .sweep-name:hover { color: var(--accent); }
        .sweep-id { color: var(--text-faint); font-size: 0.7rem; }
        .sweep-row .st-chip.ch-saved { background: var(--pill-wp-bg); color: var(--pill-wp-fg); border-color: transparent; }
        .sweep-row .st-chip.ch-failed { color: var(--danger); border-color: var(--danger); }
        .sweep-row .st-chip.ch-running { color: var(--accent); border-color: var(--accent); }
        .dot.sweep-dot:hover { color: var(--text); }

        /* Keyboard selection. Distinct from :hover so the two can coexist. */
        /* Selected rows: fill plus a hairline, never an accent stripe. */
        .site-row.is-selected { background: var(--panel-hover); box-shadow: inset 0 0 0 1px var(--panel-border-strong); }
        .site-row.is-selected .site-actions { opacity: 1; }
        /* Transient: only while this row's context menu is open. Deliberately
           separate from .is-selected — a mouse action shouldn't leave keyboard
           selection behind, which read as a highlight stuck on the last row. */
        .site-row.has-menu { background: var(--panel-hover); }
        .site-row.has-menu .site-actions { opacity: 1; }

        /* Pinned sites float to the top of the list. */
        .site-row.is-pinned .site-domain::before { content: '●'; color: var(--accent); font-size: 0.62rem; margin-right: 0.4rem; vertical-align: middle; opacity: 0.9; }

        /* Context menu — opened by clicking a row (right- or left-click). */
        .ctx-menu { position: fixed; z-index: 300; min-width: 190px; padding: 0.3rem; background: var(--panel); border: 1px solid var(--panel-border); border-radius: var(--radius-md); box-shadow: 0 12px 34px rgba(0,0,0,0.28); font-size: 0.85rem; }
        .ctx-title { padding: 0.35rem 0.6rem 0.45rem; font-family: var(--font-mono); font-size: 0.72rem; color: var(--text-faint); border-bottom: 1px solid var(--panel-border); margin-bottom: 0.25rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
        .ctx-item { display: flex; align-items: center; justify-content: space-between; gap: 1rem; width: 100%; background: transparent; border: 0; text-align: left; padding: 0.42rem 0.6rem; border-radius: var(--radius-sm); color: var(--text); cursor: pointer; font: inherit; }
        .ctx-item:hover { background: var(--panel-hover); }
        .ctx-item.danger { color: var(--danger); }
        .ctx-item .ctx-key { font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); }
        .ctx-sep { height: 1px; background: var(--panel-border); margin: 0.25rem 0; }

        /* Command palette. With 274 sites the list is not navigable by
           scrolling, so search is the real navigation and deserves to be one
           keystroke away. */
        .palette-backdrop { position: fixed; inset: 0; z-index: 400; background: rgba(0,0,0,0.45); display: flex; align-items: flex-start; justify-content: center; padding: 12vh 1rem 1rem; }
        .palette { width: 100%; max-width: 560px; background: var(--panel); border: 1px solid var(--panel-border); border-radius: var(--radius-lg); box-shadow: 0 24px 60px rgba(0,0,0,0.4); overflow: hidden; display: flex; flex-direction: column; max-height: 70vh; }
        .palette-input { width: 100%; background: transparent; border: 0; border-bottom: 1px solid var(--panel-border); padding: 0.95rem 1.1rem; color: var(--text); font-family: var(--font-mono); font-size: 0.95rem; outline: none; }
        .palette-input::placeholder { color: var(--text-faint); }
        .palette-list { list-style: none; margin: 0; padding: 0.35rem; overflow-y: auto; flex: 1; }
        .palette-item { display: flex; align-items: center; gap: 0.7rem; padding: 0.5rem 0.75rem; border-radius: var(--radius-md); cursor: pointer; }
        .palette-item.active { background: var(--panel-hover); }
        .palette-item .pi-name { flex: 1; font-family: var(--font-mono); font-size: 0.85rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
        .palette-item .pi-meta { font-family: var(--font-mono); font-size: 0.72rem; color: var(--text-faint); }
        .palette-item .pi-kind { font-family: var(--font-mono); font-size: 0.62rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-faint); border: 1px solid var(--panel-border); border-radius: var(--radius-pill); padding: 0.05rem 0.4rem; }
        .palette-empty { padding: 1.4rem; text-align: center; color: var(--text-dim); font-size: 0.87rem; }
        .palette-hint { display: flex; gap: 1rem; flex-wrap: wrap; padding: 0.5rem 0.9rem; border-top: 1px solid var(--panel-border); font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); }

        /* Footer */
        .card-foot { display: flex; align-items: center; justify-content: space-between; padding: 0.75rem 1.5rem; border-top: 1px solid var(--panel-border); color: var(--text-dim); font-family: var(--font-mono); font-size: 0.78rem; gap: 1rem; flex-wrap: wrap; }
        .services { display: flex; gap: 1.1rem; flex-wrap: wrap; }
        .dot { display: inline-flex; align-items: center; gap: 0.45rem; color: var(--text-dim); text-decoration: none; background: transparent; border: 0; padding: 0; font-family: inherit; font-size: inherit; cursor: default; }
        .dot.link, .dot[role="button"] { cursor: pointer; }
        .dot.is-busy::before { animation: dot-pulse 1.4s ease-in-out infinite; }
        @keyframes dot-pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.45; transform: scale(0.7); } }
        .dot .dot-meta { color: var(--text-faint); }
        .dot.link:hover, .dot[role="button"]:hover { color: var(--text); }
        .dot::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 6px rgba(58, 151, 169, 0.6); box-shadow: 0 0 6px color-mix(in oklch, var(--accent) 60%, transparent); }
        .totals { display: inline-flex; align-items: center; gap: 0.5rem; }
        .refresh-btn { background: transparent; border: 0; color: var(--text-dim); cursor: pointer; padding: 0.15rem 0.35rem; font-size: 0.95rem; border-radius: var(--radius-sm); }
        .refresh-btn:hover { color: var(--text); background: var(--panel-hover); }
        .refresh-btn.spinning { animation: spin 1s linear infinite; pointer-events: none; }
        @keyframes spin { to { transform: rotate(360deg); } }

        /* Pop-in fade for banners, menus, modals, palette and snackbar.
           Toggling display:none → visible replays the animation, so showing
           an element is all it takes to get the fade. */
        @keyframes cove-fade { from { opacity: 0; } }
        .new-site-alert, .filter-chip, .add-row, .modal-backdrop, .ctx-menu, .palette-backdrop, .snackbar { animation: cove-fade 140ms ease; }
        /* View switch: the incoming card takes the flow at once, while the
           outgoing one is lifted out of flow, pinned where it was, and faded
           over it — a crossfade with no frame where the background shows. */
        @keyframes cove-view-out { to { opacity: 0; } }
        .wrap > .card.is-leaving { position: absolute; left: 0; right: 0; max-height: 90vh; overflow: hidden; pointer-events: none; z-index: 5; animation: cove-view-out 200ms ease forwards; }
        @media (prefers-reduced-motion: reduce) {
            .wrap { transition: none; }
            .wrap > .card.is-leaving { display: none !important; }
        }

        /* Modal */
        .modal-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,0.55); display: grid; place-items: center; z-index: 80; padding: 1rem; }
        .modal-backdrop.is-wide .modal { max-width: min(1040px, 94vw); width: min(1040px, 94vw); }
        /* One tooltip for the whole dashboard: any element with data-tip. */
        .ui-tip { position: fixed; z-index: 200; pointer-events: none; max-width: min(520px, 90vw); padding: 0.4rem 0.6rem; background: var(--panel); color: var(--text); border: 1px solid var(--panel-border); border-radius: var(--radius-md); box-shadow: 0 6px 24px rgba(0, 0, 0, 0.25); font-family: var(--font-mono); font-size: 0.7rem; line-height: 1.45; white-space: pre-line; overflow-wrap: anywhere; }
        .ui-tip[hidden] { display: none; }
        html[data-theme="light"] .modal-backdrop { background: rgba(20,20,18,0.35); }
        .modal { background: var(--panel); border: 1px solid var(--panel-border); border-radius: var(--radius-lg); padding: 1.5rem; min-width: min(420px, 90vw); max-width: 540px; }
        .modal h3 { font-family: var(--font-serif); font-style: italic; font-weight: 500; font-size: 1.25rem; margin: 0 0 0.3rem; }
        .modal .modal-sub { color: var(--text-dim); font-size: 0.85rem; margin: 0 0 1rem; }
        .modal pre { background: var(--input-bg); border: 1px solid var(--panel-border); border-radius: var(--radius-md); padding: 0.85rem 1rem; margin: 0; font-family: var(--font-mono); font-size: 0.82rem; color: var(--text); overflow-x: auto; }
        .db-creds { background: var(--input-bg); border: 1px solid var(--panel-border); border-radius: var(--radius-md); padding: 0.9rem 1rem; display: flex; flex-direction: column; gap: 0.7rem; }
        .db-cred-row { display: grid; grid-template-columns: 85px 1fr; align-items: baseline; gap: 0.75rem; font-family: var(--font-mono); font-size: 0.82rem; }
        .db-cred-label { color: var(--text-dim); font-weight: 500; }
        .svc-status::before { content: ''; display: inline-block; width: 7px; height: 7px; border-radius: 50%; margin-right: 0.5rem; background: var(--accent); vertical-align: 1px; }
        .svc-status.is-down::before { background: var(--danger); }
        .svc-actions { display: inline-flex; gap: 0.4rem; flex: none; }
        .db-cred-value a { color: var(--accent); text-decoration: none; }
        .db-cred-value a:hover { text-decoration: underline; }
        .db-cred-value { color: var(--text); word-break: break-all; background: transparent; padding: 0; }
        .modal .modal-foot { margin-top: 1rem; display: flex; justify-content: space-between; align-items: center; color: var(--text-faint); font-family: var(--font-mono); font-size: 0.75rem; }

        /* PHP version picker rows. Installed versions are one click; missing
           ones are greyed but still actionable — clicking installs the brew
           formula first, then pins. */
        .php-options { display: flex; flex-direction: column; gap: 0.35rem; }
        .php-option { display: flex; align-items: center; justify-content: space-between; gap: 1rem; width: 100%; background: var(--input-bg); border: 1px solid var(--panel-border); border-radius: var(--radius-md); padding: 0.55rem 0.9rem; color: var(--text); cursor: pointer; font-family: var(--font-mono); font-size: 0.85rem; text-align: left; transition: border-color 120ms, background 120ms; }
        .php-option:hover { border-color: var(--accent); }
        .php-option.current { border-color: var(--accent); background: var(--pill-wp-bg); cursor: default; }
        .php-option.uninstalled .php-option-name { color: var(--text-faint); }
        .php-option .php-option-meta { font-size: 0.72rem; color: var(--text-faint); }
        .php-option:disabled { opacity: 0.65; cursor: default; }
        /* Domains modal: one row per hostname the site answers on. The primary
           and multisite-implied rows are informational, so their × is hidden. */
        .dom-list { display: flex; flex-direction: column; gap: 0.35rem; margin-bottom: 0.8rem; }
        .dom-row { display: flex; align-items: center; gap: 0.7rem; background: var(--input-bg); border: 1px solid var(--panel-border); border-radius: var(--radius-md); padding: 0.45rem 0.5rem 0.45rem 0.9rem; font-family: var(--font-mono); font-size: 0.85rem; }
        .dom-row .dom-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
        .dom-row.primary .dom-name, .dom-row.implied .dom-name { color: var(--text-dim); }
        .dom-row .dom-meta { font-size: 0.72rem; color: var(--text-faint); white-space: nowrap; }
        .dom-row .dom-remove { background: none; border: 0; color: var(--text-faint); font-size: 1.05rem; line-height: 1; cursor: pointer; padding: 0.1rem 0.35rem; border-radius: var(--radius-sm); }
        .dom-row .dom-remove:hover { color: var(--danger); }
        .dom-row .dom-remove:disabled { opacity: 0.4; cursor: default; }
        .dom-row.primary .dom-remove, .dom-row.implied .dom-remove { visibility: hidden; }
        .dom-form { display: flex; gap: 0.5rem; align-items: stretch; }
        .dom-form .modal-input { flex: 1; }
        .modal-hint a { color: var(--accent); text-decoration: none; cursor: pointer; }
        .modal-hint a:hover { text-decoration: underline; }

        /* Wider variant for log output, which is unreadable at 540px. */
        .modal-wide { max-width: min(900px, 92vw); width: 900px; }
        .modal-title-dim { font-family: var(--font-mono); font-style: normal; font-size: 0.9rem; color: var(--text-faint); }
        .modal-input { width: 100%; background: var(--input-bg); border: 1px solid var(--panel-border); border-radius: var(--radius-md); padding: 0.6rem 0.8rem; color: var(--text); font-family: var(--font-mono); font-size: 0.9rem; outline: none; }
        .modal-input:focus { border-color: var(--accent); }
        .modal-input:disabled { opacity: 0.6; }
        .modal-hint { margin-top: 0.4rem; min-height: 1.1em; font-family: var(--font-mono); font-size: 0.76rem; color: var(--text-faint); }
        .modal-actions { margin-top: 1.1rem; display: flex; justify-content: flex-end; gap: 0.6rem; }
        .log-pane { max-height: 55vh; overflow: auto; white-space: pre-wrap; word-break: break-word; font-size: 0.76rem !important; line-height: 1.5; }

        /* Snackbar */
        /* Centered via auto margins + fit-content width — no transform needed,
           so the fade animation can't interfere with positioning. */
        .snackbar { position: fixed; bottom: 1.5rem; left: 0; right: 0; margin-inline: auto; width: max-content; max-width: 90vw; display: flex; align-items: center; gap: 0.9rem; background: var(--text); color: var(--bg); padding: 0.7rem 1.15rem; border-radius: var(--radius-md); font-size: 0.88rem; z-index: 200; box-shadow: 0 10px 30px rgba(0,0,0,0.25); }
        .snackbar.error { background: var(--danger); color: white; }
        .snackbar-action { background: transparent; border: 0; padding: 0; color: inherit; font: inherit; font-weight: 600; text-decoration: underline; text-underline-offset: 2px; cursor: pointer; }
        .snackbar-action:hover { opacity: 0.8; }

        /* View switch: sites | mail. Mail is a sibling view rather than a
           card below the sites — on a real install the list is thousands of
           pixels tall, so anything under it is unreachable. */
        .nav-views { display: flex; align-items: center; gap: 0.15rem; margin-left: 1.4rem; }
        .nav-view { position: relative; display: inline-flex; align-items: center; gap: 0.4rem; background: transparent; border: 0; padding: 0.35rem 0.55rem; font-family: var(--font-mono); font-size: 0.8rem; color: var(--text-dim); cursor: pointer; border-radius: var(--radius-sm); }
        .nav-view:hover { color: var(--text); background: var(--panel-hover); }
        .nav-view.is-active { color: var(--text); }
        .nav-view.is-active::after { content: ''; position: absolute; left: 0.55rem; right: 0.55rem; bottom: -3px; height: 2px; background: var(--brand); }
        .nav-badge { font-size: 0.64rem; font-weight: 500; line-height: 1; padding: 0.22rem 0.42rem; border-radius: var(--radius-pill); background: var(--accent); color: var(--accent-fg); }

        /* Mail. The reader needs the width an HTML email was designed for,
           so this view alone widens the page. */
        body.view-mail .wrap { max-width: 1120px; }
        .mail-unread-toggle { display: inline-flex; align-items: center; gap: 0.35rem; font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); cursor: pointer; white-space: nowrap; user-select: none; }
        .mail-unread-toggle input { accent-color: var(--accent); margin: 0; }
        .mail-delete-all.armed { color: white; background: var(--danger); border-color: var(--danger); }
        .mail-body { display: grid; grid-template-columns: minmax(280px, 360px) minmax(0, 1fr); height: calc(100vh - 262px); min-height: 460px; }
        .mail-list { list-style: none; margin: 0; padding: 0; overflow-y: auto; border-right: 1px solid var(--panel-border); }
        .mail-row { display: grid; grid-template-columns: 10px minmax(0, 1fr); column-gap: 0.55rem; padding: 0.7rem 1rem 0.7rem 0.9rem; border-bottom: 1px solid var(--panel-border); cursor: pointer; transition: background 100ms; }
        .mail-row:hover { background: var(--panel-hover); }
        .mail-row.is-selected { background: var(--panel-hover); box-shadow: inset 0 0 0 1px var(--panel-border-strong); }
        .mail-dot { width: 7px; height: 7px; border-radius: 50%; margin-top: 0.45rem; background: transparent; }
        .mail-row.is-unread .mail-dot { background: var(--accent); }
        .mail-main { min-width: 0; }
        .mail-line { display: flex; align-items: center; gap: 0.5rem; min-width: 0; }
        .mail-from { flex: 1; min-width: 0; font-size: 0.86rem; color: var(--text-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .mail-row.is-unread .mail-from, .mail-row.is-unread .mail-subject { color: var(--text); font-weight: 500; }
        .mail-age { font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); flex: none; }
        .mail-att { flex: none; width: 12px; height: 12px; color: var(--text-faint); }
        .mail-subject { font-size: 0.86rem; color: var(--text-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin: 0.1rem 0 0.15rem; }
        .mail-site { flex: none; font-family: var(--font-mono); font-size: 0.62rem; letter-spacing: 0.04em; padding: 0.06rem 0.45rem; border-radius: var(--radius-pill); background: var(--pill-wp-bg); color: var(--pill-wp-fg); cursor: pointer; white-space: nowrap; }
        .mail-site:hover { filter: brightness(1.15); }
        .mail-snippet { flex: 1; min-width: 0; font-size: 0.76rem; color: var(--text-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .mail-list > .empty, .mail-list > .loading { padding: 3rem 1.5rem; text-align: center; color: var(--text-dim); }
        .mail-reader { overflow-y: auto; min-width: 0; display: flex; flex-direction: column; }
        .mail-reader-empty { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; color: var(--text-dim); padding: 2rem; text-align: center; }
        .mail-msg-head { padding: 1.1rem 1.5rem 0.9rem; border-bottom: 1px solid var(--panel-border); }
        .mail-msg-head .loading { color: var(--text-dim); }
        .mail-msg-error { color: var(--danger); font-size: 0.9rem; }
        .mail-msg-subject { font-family: var(--font-serif); font-weight: 500; font-size: 1.25rem; margin: 0 0 0.55rem; letter-spacing: -0.01em; line-height: 1.3; overflow-wrap: anywhere; }
        .mail-meta-row { display: grid; grid-template-columns: 3rem minmax(0, 1fr); gap: 0.5rem; align-items: baseline; font-family: var(--font-mono); font-size: 0.78rem; line-height: 1.6; }
        .mail-meta-k { color: var(--text-faint); text-transform: uppercase; letter-spacing: 0.06em; font-size: 0.64rem; }
        .mail-meta-v { color: var(--text-dim); overflow-wrap: anywhere; }
        /* Links found in the message — most local mail exists to carry one
           (password reset, login, verification), so they get a front-row seat
           with a copy button beside each. */
        .mail-links { display: flex; flex-wrap: wrap; gap: 0.4rem; margin-top: 0.7rem; }
        .mail-links:empty { display: none; }
        .mail-link { display: inline-flex; align-items: stretch; border: 1px solid var(--panel-border); border-radius: var(--radius-md); font-family: var(--font-mono); font-size: 0.74rem; max-width: 100%; overflow: hidden; }
        .mail-link a { color: var(--accent); text-decoration: none; padding: 0.3rem 0.6rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 440px; }
        .mail-link a:hover { background: var(--panel-hover); }
        .mail-link-copy { background: transparent; border: 0; border-left: 1px solid var(--panel-border); color: var(--text-dim); font: inherit; padding: 0 0.55rem; cursor: pointer; }
        .mail-link-copy:hover { color: var(--text); background: var(--panel-hover); }
        .mail-msg-bar { display: flex; align-items: center; gap: 0.75rem; padding: 0.5rem 1.5rem; border-bottom: 1px solid var(--panel-border); background: var(--bg-sunk); flex-wrap: wrap; }
        .mail-parts { display: flex; gap: 0.15rem; }
        .mail-part { background: transparent; border: 1px solid transparent; padding: 0.28rem 0.55rem; font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); cursor: pointer; border-radius: var(--radius-sm); }
        .mail-part:hover { color: var(--text); background: var(--panel-hover); }
        .mail-part.is-active { color: var(--text); background: var(--panel); border-color: var(--panel-border); }
        .mail-bar-note { font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); }
        .mail-msg-actions { margin-left: auto; display: flex; gap: 0.35rem; }
        .mail-msg-actions .pill { padding: 0.26rem 0.6rem; font-size: 0.74rem; }
        .mail-frame { display: block; width: 100%; border: 0; background: #fff; min-height: 240px; color-scheme: light; }
        .mail-pre { margin: 0; padding: 1.1rem 1.5rem; font-family: var(--font-mono); font-size: 0.82rem; line-height: 1.55; color: var(--text); white-space: pre-wrap; overflow-wrap: anywhere; }
        .mail-pre a { color: var(--accent); }
        .mail-attachments { display: flex; flex-wrap: wrap; gap: 0.4rem; padding: 0.8rem 1.5rem; border-top: 1px solid var(--panel-border); }
        .mail-back { display: none; margin-bottom: 0.7rem; }
        .mail-pager { display: flex; align-items: center; gap: 0.35rem; margin-left: auto; }
        .pager-btn { background: transparent; border: 1px solid var(--panel-border); color: var(--text-dim); width: 26px; height: 24px; border-radius: var(--radius-sm); cursor: pointer; font-size: 0.95rem; line-height: 1; padding: 0; }
        .pager-btn:hover { color: var(--text); }
        .pager-btn:disabled { opacity: 0.35; cursor: default; }
        @media (max-width: 860px) {
            .mail-body { grid-template-columns: 1fr; height: auto; min-height: 60vh; }
            .mail-list { border-right: 0; }
            .mail-body.has-msg .mail-list { display: none; }
            .mail-body:not(.has-msg) .mail-reader { display: none; }
            .mail-back { display: inline-flex; }
            .mail-link a { max-width: 240px; }
        }

        /* Databases. Wider still: a grid of a dozen columns needs the room. */
        body.view-db .wrap { max-width: 1280px; }
        .db-body { display: grid; grid-template-columns: minmax(250px, 330px) minmax(0, 1fr); height: calc(100vh - 262px); min-height: 460px; }
        .db-list { list-style: none; margin: 0; padding: 0; overflow-y: auto; border-right: 1px solid var(--panel-border); }
        .db-row { display: flex; flex-direction: column; gap: 0.2rem; padding: 0.55rem 1rem 0.55rem 0.9rem; border-bottom: 1px solid var(--panel-border); cursor: pointer; transition: background 100ms; min-width: 0; }
        .db-row-line { display: flex; align-items: baseline; gap: 0.6rem; min-width: 0; }
        .db-row-site { align-self: flex-start; }
        .db-row:hover { background: var(--panel-hover); }
        .db-row.is-selected { background: var(--panel-hover); box-shadow: inset 0 0 0 1px var(--panel-border-strong); }
        .db-row-name { flex: 1; min-width: 0; font-family: var(--font-mono); font-size: 0.82rem; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .db-row.is-view .db-row-name { font-style: italic; color: var(--text-dim); }
        .db-row-meta { flex: none; font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); white-space: nowrap; }
        .db-list > .empty, .db-list > .loading { padding: 3rem 1.5rem; text-align: center; color: var(--text-dim); }
        .db-main { overflow: hidden; min-width: 0; display: flex; flex-direction: column; }
        .db-main > div { min-height: 0; }
        #dbTable, #dbSql { flex: 1; display: flex; flex-direction: column; min-height: 0; }
        .db-bar { flex: none; }
        .db-rows-search { display: flex; align-items: center; border: 1px solid var(--panel-border); border-radius: var(--radius-md); background: var(--input-bg); overflow: hidden; }
        .db-rows-search select { background: transparent; border: 0; border-right: 1px solid var(--panel-border); color: var(--text-dim); font-family: var(--font-mono); font-size: 0.72rem; padding: 0.28rem 0.4rem; max-width: 150px; cursor: pointer; }
        .db-rows-search input { background: transparent; border: 0; color: var(--text); font-family: var(--font-mono); font-size: 0.76rem; padding: 0.28rem 0.55rem; width: 180px; outline: 0; }
        .db-rows-search:focus-within { border-color: var(--accent); }
        /* Grid: the wrap scrolls both ways, the header sticks, and every
           cell stays on one line — a 4 KB serialized option gets an ellipsis
           and shows itself on a double-click. */
        .db-grid-wrap { flex: 1; overflow: auto; min-height: 0; }
        .db-grid { border-collapse: separate; border-spacing: 0; font-family: var(--font-mono); font-size: 0.76rem; min-width: 100%; }
        .db-grid th { position: sticky; top: 0; z-index: 2; background: var(--panel); text-align: left; font-weight: 500; padding: 0.45rem 0.7rem; border-bottom: 1px solid var(--panel-border); border-right: 1px solid var(--panel-border); white-space: nowrap; cursor: pointer; user-select: none; vertical-align: bottom; }
        .db-grid th:hover { background: var(--panel-hover); }
        .db-grid th .col-type { display: block; font-size: 0.62rem; font-weight: 400; color: var(--text-faint); letter-spacing: 0.02em; }
        .db-grid th .col-key { color: var(--accent); margin-right: 0.25rem; }
        .db-grid th .sort-arrow { color: var(--text-dim); margin-left: 0.3rem; }
        .db-grid td { padding: 0.32rem 0.7rem; border-bottom: 1px solid var(--panel-border); border-right: 1px solid var(--panel-border); white-space: nowrap; max-width: 360px; overflow: hidden; text-overflow: ellipsis; color: var(--text-dim); vertical-align: top; }
        .db-grid tr:hover td { background: var(--panel-hover); }
        .db-grid td.is-null { color: var(--text-faint); font-style: italic; }
        .db-grid td.is-num { text-align: right; color: var(--text); }
        .db-grid td.is-bin { color: var(--text-faint); }
        .db-grid td.is-editable { cursor: text; }
        .db-grid td.is-editing { padding: 0; max-width: none; overflow: visible; white-space: normal; }
        .db-edit { display: block; width: 100%; min-width: 260px; min-height: 2.4rem; box-sizing: border-box; background: var(--input-bg); color: var(--text); border: 1px solid var(--accent); border-radius: 0; padding: 0.3rem 0.6rem; font: inherit; line-height: 1.4; resize: vertical; outline: 0; }
        .db-edit-hint { display: block; padding: 0.15rem 0.6rem 0.25rem; font-size: 0.64rem; color: var(--text-faint); background: var(--input-bg); }
        .db-grid td.db-row-actions { padding: 0.15rem 0.35rem; border-right: 0; width: 1%; }
        .db-row-del { visibility: hidden; background: transparent; border: 1px solid transparent; color: var(--text-faint); font: inherit; font-size: 0.7rem; padding: 0.1rem 0.4rem; border-radius: var(--radius-sm); cursor: pointer; white-space: nowrap; }
        .db-grid tr:hover .db-row-del, .db-row-del.armed { visibility: visible; }
        .db-row-del:hover { color: var(--danger); border-color: var(--danger); }
        .db-row-del.armed { visibility: visible; color: white; background: var(--danger); border-color: var(--danger); }
        .db-grid-empty { padding: 2.5rem 1.5rem; text-align: center; color: var(--text-dim); font-family: var(--font-sans); }
        /* Overview of a database: what a WordPress install would tell you
           first if it could. */
        .db-overview { padding: 1.25rem 1.5rem; overflow-y: auto; }
        .db-overview h2 { font-family: var(--font-serif); font-weight: 500; font-size: 1.25rem; margin: 0 0 0.25rem; letter-spacing: -0.01em; }
        .db-overview .db-ov-sub { color: var(--text-dim); font-size: 0.88rem; margin: 0 0 1rem; }
        .db-ov-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 0.6rem; margin-bottom: 1.1rem; }
        .db-ov-stat { border: 1px solid var(--panel-border); border-radius: var(--radius-md); padding: 0.6rem 0.8rem; min-width: 0; }
        .db-ov-stat .k { display: block; font-family: var(--font-mono); font-size: 0.64rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-faint); margin-bottom: 0.2rem; }
        .db-ov-stat .v { display: block; font-family: var(--font-mono); font-size: 0.86rem; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .db-ov-stat .v a { color: var(--accent); text-decoration: none; }
        .db-ov-list { list-style: none; margin: 0; padding: 0; border: 1px solid var(--panel-border); border-radius: var(--radius-md); overflow: hidden; }
        .db-ov-list li { display: flex; justify-content: space-between; gap: 1rem; padding: 0.4rem 0.8rem; border-bottom: 1px solid var(--panel-border); font-family: var(--font-mono); font-size: 0.76rem; cursor: pointer; }
        .db-ov-list li:last-child { border-bottom: 0; }
        .db-ov-list li:hover { background: var(--panel-hover); }
        .db-ov-list li span:first-child { color: var(--text-dim); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
        .db-ov-list li span:last-child { color: var(--text-faint); flex: none; }
        .db-ov-label { font-family: var(--font-mono); font-size: 0.66rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-faint); margin: 0 0 0.4rem; }
        /* Structure */
        .db-structure { flex: 1; overflow: auto; padding: 1rem 1.5rem; }
        .db-structure table { border-collapse: collapse; font-family: var(--font-mono); font-size: 0.76rem; width: 100%; margin-bottom: 1.2rem; }
        .db-structure th { text-align: left; font-weight: 500; font-size: 0.64rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-faint); padding: 0.3rem 0.6rem; border-bottom: 1px solid var(--panel-border); }
        .db-structure td { padding: 0.32rem 0.6rem; border-bottom: 1px solid var(--panel-border); color: var(--text-dim); vertical-align: top; }
        .db-structure td:first-child { color: var(--text); }
        .db-structure pre { margin: 0; padding: 0.9rem 1rem; border: 1px solid var(--panel-border); border-radius: var(--radius-md); background: var(--bg-sunk); font-family: var(--font-mono); font-size: 0.74rem; line-height: 1.5; color: var(--text-dim); white-space: pre-wrap; overflow-wrap: anywhere; }
        /* SQL console */
        .db-sql-editor { flex: none; border-bottom: 1px solid var(--panel-border); background: var(--bg-sunk); }
        .db-sql-editor textarea { display: block; width: 100%; box-sizing: border-box; background: transparent; border: 0; color: var(--text); font-family: var(--font-mono); font-size: 0.84rem; line-height: 1.55; padding: 0.9rem 1.5rem 0.4rem; resize: vertical; outline: 0; min-height: 6.5rem; }
        .db-sql-editor textarea::placeholder { color: var(--text-faint); }
        .db-sql-actions { display: flex; align-items: center; gap: 0.5rem; padding: 0.4rem 1.5rem 0.7rem; }
        .db-sql-actions .mail-bar-note { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
        .db-sql-actions select { background: var(--input-bg); border: 1px solid var(--panel-border); color: var(--text-dim); font-family: var(--font-mono); font-size: 0.72rem; padding: 0.3rem 0.5rem; border-radius: var(--radius-md); max-width: 220px; cursor: pointer; }
        .db-kbd { opacity: 0.7; font-size: 0.7em; margin-left: 0.2rem; }
        .db-sql-results { flex: 1; overflow: auto; min-height: 0; }
        .db-sql-result { border-bottom: 1px solid var(--panel-border); }
        .db-sql-result-head { display: flex; align-items: center; gap: 0.75rem; padding: 0.5rem 1.5rem; font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); background: var(--panel); border-bottom: 1px solid var(--panel-border); position: sticky; top: 0; }
        .db-sql-result-head.is-error { color: var(--danger); }
        .db-sql-result-head.is-ok { color: var(--text); }
        .db-sql-result .db-grid-wrap { max-height: 60vh; }
        @media (max-width: 860px) {
            .db-body { grid-template-columns: 1fr; height: auto; min-height: 60vh; }
            .db-list { border-right: 0; max-height: 40vh; }
            .db-main { min-height: 50vh; }
        }

        /* Logs. Same two-column shape as mail and databases. */
        body.view-logs .wrap { max-width: 1180px; }
        .logs-body { display: grid; grid-template-columns: minmax(220px, 260px) minmax(0, 1fr); height: calc(100vh - 262px); min-height: 460px; }
        .logs-side { overflow-y: auto; border-right: 1px solid var(--panel-border); display: flex; flex-direction: column; }
        .logs-side .db-list { border-right: 0; overflow: visible; flex: none; }
        .logs-side .logs-sites { flex: 1; }
        .logs-group { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; padding: 0.45rem 0.9rem 0.3rem; font-family: var(--font-mono); font-size: 0.64rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-faint); border-bottom: 1px solid var(--panel-border); background: var(--bg-sunk); }
        .logs-group-sites { border-top: 1px solid var(--panel-border); }
        .logs-site-filter { width: 90px; background: transparent; border: 0; border-bottom: 1px solid var(--panel-border); color: var(--text); font-family: var(--font-mono); font-size: 0.7rem; text-transform: none; letter-spacing: 0; padding: 0.1rem 0; outline: 0; }
        .logs-site-filter::placeholder { color: var(--text-faint); }
        .logs-site-filter:focus { border-bottom-color: var(--accent); }
        .logs-side .db-row { padding: 0.45rem 1rem 0.45rem 0.9rem; }
        .logs-side .db-row.is-quiet .db-row-name { color: var(--text-dim); }
        .logs-side .db-row-name { font-size: 0.8rem; }
        .logs-main { min-width: 0; display: flex; flex-direction: column; overflow: hidden; }
        .logs-bar { flex: none; }
        .logs-path { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; cursor: copy; }
        .logs-path:hover { color: var(--text-dim); }
        .logs-live-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: var(--text-faint); }
        .logs-live-dot.is-live { background: var(--accent); animation: php-pulse 2.4s ease-in-out infinite; }
        .log-levels { display: flex; gap: 0.15rem; }
        .log-level { background: transparent; border: 1px solid transparent; padding: 0.18rem 0.5rem; font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-dim); cursor: pointer; border-radius: var(--radius-sm); }
        .log-level:hover { color: var(--text); background: var(--panel-hover); }
        .log-level.is-active { color: var(--text); border-color: var(--panel-border); background: var(--bg-sunk); }
        .log-list { list-style: none; margin: 0; padding: 0; overflow-y: auto; flex: 1; min-height: 0; }
        .log-list > .empty, .log-list > .loading { padding: 3rem 1.5rem; text-align: center; color: var(--text-dim); }
        .log-row { display: grid; grid-template-columns: 3.4rem auto minmax(0, 1fr); column-gap: 0.7rem; align-items: start; padding: 0.55rem 1.25rem 0.55rem 1rem; border-bottom: 1px solid var(--panel-border); cursor: pointer; }
        .log-row:hover { background: var(--panel-hover); }
        .log-row.is-new { animation: cove-fade 400ms ease; }
        .log-time { font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); padding-top: 0.15rem; white-space: nowrap; }
        .log-level-chip { font-family: var(--font-mono); font-size: 0.6rem; letter-spacing: 0.06em; text-transform: uppercase; padding: 0.12rem 0.45rem; border-radius: var(--radius-pill); border: 1px solid var(--panel-border); color: var(--text-dim); white-space: nowrap; margin-top: 0.1rem; min-width: 4.6rem; text-align: center; }
        .log-level-chip.error { color: var(--danger); border-color: var(--danger); }
        .log-level-chip.warning { color: var(--pill-warn-fg, #d08c30); border-color: var(--pill-warn-fg, #d08c30); }
        .log-level-chip.deprecated, .log-level-chip.notice { color: var(--text-faint); }
        .log-level-chip.info { color: var(--text-dim); }
        .log-main { min-width: 0; }
        .log-msg { font-family: var(--font-mono); font-size: 0.78rem; line-height: 1.45; color: var(--text); overflow-wrap: anywhere; }
        .log-row.is-collapsed .log-msg { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .log-meta { display: flex; align-items: center; gap: 0.5rem; margin-top: 0.15rem; min-width: 0; font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); }
        .log-file { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
        .log-count { flex: none; padding: 0.02rem 0.4rem; border-radius: var(--radius-pill); background: var(--panel-border); color: var(--text-dim); font-size: 0.64rem; }
        .log-detail { margin: 0.5rem 0 0; padding: 0.7rem 0.9rem; background: var(--bg-sunk); border: 1px solid var(--panel-border); border-radius: var(--radius-md); font-family: var(--font-mono); font-size: 0.72rem; line-height: 1.5; color: var(--text-dim); white-space: pre-wrap; overflow-wrap: anywhere; max-height: 50vh; overflow: auto; }
        @media (max-width: 860px) {
            .logs-body { grid-template-columns: 1fr; height: auto; min-height: 60vh; }
            .logs-side { border-right: 0; max-height: 36vh; }
            .log-levels { display: none; }
        }

        /* Site page. One site: facts, its views, its network, its actions. */
        body.view-site .wrap { max-width: 1040px; }
        .sp-head { align-items: flex-start; }
        .view-head { display: flex; flex-direction: column; gap: 0.25rem; min-width: 0; }
        .view-back { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
        .sp-head-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 0.45rem; }
        .sp-head .card-title { overflow-wrap: anywhere; }
        .site-back { align-self: flex-start; background: transparent; border: 0; padding: 0; font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); cursor: pointer; }
        .site-back:hover { color: var(--text); }
        .site-facts { display: flex; flex-wrap: wrap; align-items: center; gap: 0.35rem 0.85rem; font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); min-width: 0; }
        .site-facts .fact { white-space: nowrap; }
        .site-facts .fact-type { min-width: 0; }
        .site-facts .fact-ver.insecure::after { content: "●"; margin-left: 0.25rem; color: var(--pill-warn-fg, #d08c30); font-size: 0.6em; vertical-align: middle; }
        .site-facts .fact-path { cursor: copy; color: var(--text-faint); overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
        .site-facts .fact-path:hover { color: var(--text); }
        .site-body { padding: 1.25rem 1.5rem 1.5rem; display: flex; flex-direction: column; gap: 1.25rem; }
        .site-top { display: grid; grid-template-columns: minmax(260px, 400px) minmax(0, 1fr); gap: 1rem; align-items: start; }
        .site-shot { position: relative; display: block; aspect-ratio: 16 / 10; border: 1px solid var(--panel-border); border-radius: var(--radius-md); background: var(--bg-sunk); overflow: hidden; text-decoration: none; color: var(--text-faint); }
        .site-shot img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: top; }
        .site-shot.is-stale img { opacity: 0.75; }
        .site-shot-empty { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; padding: 1rem; text-align: center; font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-faint); }
        .site-shot-bar { position: absolute; left: 0; right: 0; bottom: 0; display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; padding: 0.3rem 0.6rem; font-family: var(--font-mono); font-size: 0.66rem; color: var(--text-dim); background: color-mix(in oklch, var(--panel) 88%, transparent); border-top: 1px solid var(--panel-border); opacity: 0; transition: opacity 120ms; }
        .site-shot:hover .site-shot-bar, .site-shot.is-busy .site-shot-bar { opacity: 1; }
        .site-shot-refresh { background: transparent; border: 1px solid var(--panel-border); border-radius: var(--radius-pill); color: var(--text-dim); font: inherit; padding: 0.05rem 0.5rem; cursor: pointer; }
        .site-shot-refresh:hover { color: var(--text); border-color: var(--text-faint); }
        .site-shot-refresh:disabled { opacity: 0.6; cursor: default; }
        .site-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 0.75rem; }
        .site-top .site-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }
        @media (max-width: 760px) { .site-top { grid-template-columns: 1fr; } }
        .site-tile { text-align: left; background: var(--bg-sunk); border: 1px solid var(--panel-border); border-radius: var(--radius-md); padding: 0.85rem 1rem; cursor: pointer; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; column-gap: 0.9rem; color: var(--text); font: inherit; transition: border-color 120ms, background 120ms; }
        .site-tile-text { display: flex; flex-direction: column; gap: 0.3rem; min-width: 0; }
        .tile-art { width: 64px; height: 44px; flex: none; opacity: 0.9; }
        .tile-art .art-line { stroke: var(--text-dim); stroke-width: 1.6; fill: none; }
        .tile-art .art-fill { fill: var(--accent); opacity: 0.12; stroke: none; transition: opacity 120ms; }
        .tile-art .art-wave { stroke: var(--accent); stroke-width: 1.6; fill: none; opacity: 0.5; }
        .tile-art .art-dot { fill: var(--accent); }
        .site-tile:hover .tile-art .art-fill { opacity: 0.22; }
        .site-tile:hover .tile-art .art-line { stroke: var(--text); }
        .site-tile:hover { border-color: var(--text-faint); background: var(--panel-hover); }
        .site-tile-name { font-family: var(--font-mono); font-size: 0.86rem; color: var(--text); }
        .site-tile-name::after { content: " →"; color: var(--text-faint); }
        .site-tile-desc { font-size: 0.78rem; color: var(--text-dim); line-height: 1.4; }
        .site-section { border: 1px solid var(--panel-border); border-radius: var(--radius-md); overflow: hidden; }
        .site-section-head { display: flex; align-items: center; gap: 0.6rem; padding: 0.5rem 0.9rem; font-family: var(--font-mono); font-size: 0.64rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-faint); background: var(--bg-sunk); border-bottom: 1px solid var(--panel-border); }
        .site-section-head .sec-meta { text-transform: none; letter-spacing: 0; color: var(--text-dim); }
        .site-section-head .pill { margin-left: auto; padding: 0.2rem 0.55rem; font-size: 0.7rem; text-transform: none; letter-spacing: 0; }
        .site-net-list { list-style: none; margin: 0; padding: 0; max-height: 52vh; overflow-y: auto; }
        .site-net-list > .loading, .site-net-list > .empty { padding: 2rem 1rem; text-align: center; color: var(--text-dim); }
        .net-row { display: grid; grid-template-columns: minmax(0, 1fr) auto auto auto; align-items: center; column-gap: 0.9rem; padding: 0.55rem 0.9rem; border-bottom: 1px solid var(--panel-border); cursor: pointer; }
        .net-row:last-of-type { border-bottom: 0; }
        .net-row:hover { background: var(--panel-hover); }
        .net-row.is-off .net-name { color: var(--text-dim); }
        .net-main { min-width: 0; display: flex; flex-direction: column; gap: 0.1rem; }
        .net-name { font-size: 0.88rem; color: var(--text); font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .net-main-chip { font-family: var(--font-mono); font-size: 0.6rem; letter-spacing: 0.04em; padding: 0.06rem 0.45rem; border-radius: var(--radius-pill); background: var(--pill-wp-bg); color: var(--pill-wp-fg); margin-left: 0.5rem; font-weight: 400; vertical-align: middle; }
        .net-main-chip.net-status { background: transparent; border: 1px solid var(--panel-border); color: var(--text-faint); }
        .net-url { font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); text-decoration: none; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .net-url:hover { color: var(--accent); }
        .net-updated { font-family: var(--font-mono); font-size: 0.72rem; color: var(--text-faint); white-space: nowrap; }
        .net-row .pill { padding: 0.26rem 0.6rem; font-size: 0.74rem; }
        .site-manage { display: flex; flex-wrap: wrap; gap: 0.5rem; padding: 0.9rem; }
        .site-manage .pill.danger { color: var(--danger); border-color: color-mix(in oklch, var(--danger) 45%, transparent); }
        .site-manage .pill.danger:hover { color: white; background: var(--danger); border-color: var(--danger); }
        .pill .pill-meta { color: var(--text-faint); font-size: 0.7rem; }
        .pill .pill-meta:empty { display: none; }
        @media (max-width: 620px) {
            .net-row { grid-template-columns: minmax(0, 1fr) auto; }
            .net-updated, .net-row .net-open { display: none; }
        }

        /* Site page tabs: plugins, themes, users, cron, wp-cli. */
        .site-tabs { padding: 0.35rem 1.5rem; }
        .st-toolbar { display: flex; align-items: center; gap: 0.6rem; padding: 0.6rem 1.5rem; border-bottom: 1px solid var(--panel-border); flex-wrap: wrap; }
        .st-toolbar .st-filter { flex: 1; min-width: 160px; }
        .st-toolbar .st-count { margin-left: auto; }
        .st-list { list-style: none; margin: 0; padding: 0; max-height: calc(100vh - 330px); min-height: 220px; overflow-y: auto; }
        .st-list > .loading, .st-list > .empty, .st-empty { padding: 3rem 1.5rem; text-align: center; color: var(--text-dim); }
        .st-row { display: grid; align-items: center; column-gap: 0.9rem; padding: 0.5rem 1.5rem; border-bottom: 1px solid var(--panel-border); }
        .st-row:hover { background: var(--panel-hover); }
        .st-plugins, .st-themes { grid-template-columns: minmax(0, 1fr) auto auto auto minmax(9rem, auto); }
        .st-users { grid-template-columns: minmax(0, 1fr) auto auto auto; }
        .st-cron { grid-template-columns: minmax(0, 1fr) auto auto auto; }
        .st-main { min-width: 0; display: flex; flex-direction: column; gap: 0.1rem; }
        .st-title { font-size: 0.88rem; color: var(--text); font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .st-title.st-mono { font-family: var(--font-mono); font-size: 0.8rem; font-weight: 400; }
        .st-row.is-off .st-title { color: var(--text-dim); font-weight: 400; }
        .st-sub { font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .st-ver { font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); white-space: nowrap; }
        .st-upd { color: var(--accent); }
        .st-row.is-due .st-ver { color: var(--pill-warn-fg, #d08c30); }
        .st-chip { font-family: var(--font-mono); font-size: 0.62rem; letter-spacing: 0.04em; padding: 0.08rem 0.5rem; border-radius: var(--radius-pill); border: 1px solid var(--panel-border); color: var(--text-dim); white-space: nowrap; }
        .st-chip.st-status-active, .st-chip.st-status-active-network, .st-chip.st-status-must-use, .st-chip.st-status-parent { background: var(--pill-wp-bg); color: var(--pill-wp-fg); border-color: transparent; }
        .st-chip.st-none { color: var(--text-faint); border-style: dashed; }
        .st-roles { display: flex; gap: 0.25rem; flex-wrap: wrap; justify-content: flex-end; }
        .st-auto { background: transparent; border: 1px solid var(--panel-border); color: var(--text-faint); font-family: var(--font-mono); font-size: 0.62rem; letter-spacing: 0.04em; padding: 0.08rem 0.5rem; border-radius: var(--radius-pill); cursor: pointer; }
        .st-auto.is-on { color: var(--accent); border-color: var(--accent); }
        .st-auto:hover { color: var(--text); }
        .st-actions { display: flex; gap: 0.3rem; justify-content: flex-end; min-width: 0; }
        .st-actions .pill { padding: 0.22rem 0.55rem; font-size: 0.72rem; }
        .st-del { color: var(--text-faint); }
        .st-del.armed { color: white; background: var(--danger); border-color: var(--danger); }
        .st-busy { font-family: var(--font-mono); font-size: 0.72rem; color: var(--text-faint); }
        .site-health { display: flex; flex-wrap: wrap; align-items: center; gap: 0.35rem 0.6rem; font-family: var(--font-mono); font-size: 0.72rem; color: var(--text-faint); }
        .site-health:empty { display: none; }
        .site-health .fact { color: var(--text-faint); }
        .site-health-bit { background: transparent; border: 1px solid var(--panel-border); border-radius: var(--radius-pill); padding: 0.12rem 0.6rem; font: inherit; color: var(--text-dim); cursor: pointer; }
        .site-health-bit b { color: var(--text); font-weight: 500; }
        .site-health-bit:hover { border-color: var(--text-faint); color: var(--text); }
        .site-health-bit.is-bad b { color: var(--danger); }
        .site-health-bit.is-warn b { color: var(--pill-warn-fg, #d08c30); }
        .tr-body { padding: 1rem 1.5rem 1.5rem; display: flex; flex-direction: column; gap: 1rem; }
        .tr-empty { padding: 3rem 1.5rem; text-align: center; color: var(--text-dim); }
        .tr-empty.small { padding: 1.2rem 0.9rem; font-family: var(--font-mono); font-size: 0.72rem; color: var(--text-faint); text-align: left; }
        .tr-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 0.6rem; }
        .tr-tile { display: flex; flex-direction: column; gap: 0.15rem; padding: 0.7rem 0.9rem; border: 1px solid var(--panel-border); border-radius: var(--radius-md); background: var(--bg-sunk); min-width: 0; }
        .tr-tile-v { font-family: var(--font-mono); font-size: 1.15rem; color: var(--text); }
        .tr-tile.is-bad .tr-tile-v { color: var(--danger); }
        .tr-tile.is-warn .tr-tile-v { color: var(--pill-warn-fg, #d08c30); }
        .tr-tile-l { font-family: var(--font-mono); font-size: 0.64rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-faint); }
        .tr-tile-s { font-family: var(--font-mono); font-size: 0.68rem; color: var(--text-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .tr-chart { display: grid; grid-template-columns: repeat(var(--n), minmax(0, 1fr)); gap: 2px; align-items: end; height: 120px; padding: 0.4rem 0 0; border-bottom: 1px solid var(--panel-border); }
        .tr-bar { position: relative; height: 100%; display: flex; align-items: flex-end; }
        .tr-bar-fill { display: block; width: 100%; min-height: 1px; background: color-mix(in oklch, var(--accent) 55%, var(--panel-border)); border-radius: 2px 2px 0 0; }
        .tr-bar:hover .tr-bar-fill { background: var(--accent); }
        .tr-bar-err { position: absolute; left: 0; right: 0; bottom: 0; background: var(--danger); border-radius: 2px 2px 0 0; }
        .tr-axis { display: flex; justify-content: space-between; font-family: var(--font-mono); font-size: 0.64rem; color: var(--text-faint); margin-top: -0.6rem; }
        .tr-lists { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 0.75rem; }
        .tr-list { border: 1px solid var(--panel-border); border-radius: var(--radius-md); overflow: hidden; min-width: 0; }
        .tr-list ul { list-style: none; margin: 0; padding: 0.3rem 0; }
        .tr-list li { display: flex; align-items: baseline; justify-content: space-between; gap: 0.75rem; padding: 0.28rem 0.9rem; font-family: var(--font-mono); font-size: 0.74rem; min-width: 0; }
        .tr-list li:hover { background: var(--panel-hover); }
        .tr-list li.is-click { cursor: pointer; }
        .tr-list .site-section-head { justify-content: space-between; }
        .tr-more { background: transparent; border: 0; padding: 0; font: inherit; letter-spacing: inherit; text-transform: inherit; color: var(--text-faint); cursor: pointer; }
        .tr-more:hover { color: var(--accent); }
        .tr-detail { display: grid; grid-template-columns: 7.5rem minmax(0, 1fr); gap: 0.4rem 0.8rem; font-family: var(--font-mono); font-size: 0.78rem; }
        .tr-detail dt { color: var(--text-dim); } .tr-detail dd { margin: 0; color: var(--text); overflow-wrap: anywhere; }
        .tr-detail a { color: var(--accent); text-decoration: none; } .tr-detail a:hover { text-decoration: underline; }
        .tr-table-wrap { max-height: 56vh; overflow: auto; margin: 0 -0.4rem; }
        .tr-table { width: 100%; border-collapse: collapse; font-family: var(--font-mono); font-size: 0.74rem; }
        .tr-table th { position: sticky; top: 0; background: var(--input-bg); text-align: left; font-weight: 500; font-size: 0.62rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-faint); padding: 0.35rem 0.4rem; border-bottom: 1px solid var(--panel-border); }
        .tr-table td { padding: 0.3rem 0.4rem; border-bottom: 1px solid var(--panel-border); white-space: nowrap; vertical-align: baseline; }
        .tr-table td.tr-cell-path { white-space: normal; overflow-wrap: anywhere; max-width: 520px; }
        .tr-table tr.is-click { cursor: pointer; } .tr-table tr.is-click:hover td { background: var(--panel-hover); }
        .tr-table .num { text-align: right; color: var(--text-dim); }
        .tr-modal-tools { display: flex; align-items: center; gap: 0.6rem; margin: 0 0 0.6rem; }
        .tr-modal-tools .filter-input { flex: 1; }
        .tr-back { background: transparent; border: 0; padding: 0; font: inherit; color: var(--text-dim); cursor: pointer; } .tr-back:hover { color: var(--text); }
        .tr-path { color: var(--text); text-decoration: none; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
        a.tr-path:hover { color: var(--accent); }
        .tr-n { flex: none; color: var(--text-faint); }
        .tr-n.is-bad { color: var(--danger); }
        .bulk-list { list-style: none; margin: 0 0 0.9rem; padding: 0.5rem 0.8rem; max-height: 200px; overflow-y: auto; background: var(--bg-sunk); border: 1px solid var(--panel-border); border-radius: var(--radius-md); font-family: var(--font-mono); font-size: 0.78rem; color: var(--text-dim); display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 0.15rem 1rem; }
        .bulk-list li { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .st-snapshots { grid-template-columns: minmax(0, 1fr) auto auto minmax(10rem, auto); }
        .st-snapshots .st-title { font-family: var(--font-mono); font-size: 0.8rem; font-weight: 500; }
        .st-snapshots.is-auto .st-title { font-weight: 400; color: var(--text-dim); }
        .st-toolbar .st-note { flex: 1; min-width: 200px; }
        .st-foot { padding: 0.6rem 1.5rem; font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); border-top: 1px solid var(--panel-border); }
        .st-foot:empty { display: none; }
        .st-restore.armed { color: white; background: var(--danger); border-color: var(--danger); }
        .st-toolbar .st-hist-note { flex: 0 1 260px; min-width: 160px; }
        .st-history { grid-template-columns: minmax(0, 1fr) auto auto 1.2rem; cursor: pointer; }
        .st-history .st-title { font-weight: 500; }
        .st-history.is-auto .st-title { font-weight: 400; color: var(--text-dim); }
        .st-history.is-open { background: var(--panel-hover); }
        .st-history .st-when { font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); white-space: nowrap; }
        .st-hist-files { display: flex; gap: 0.35rem; font-family: var(--font-mono); font-size: 0.68rem; color: var(--text-faint); white-space: nowrap; }
        .st-hist-files .f-add { color: #3d9a5c; } .st-hist-files .f-del { color: var(--danger); }
        .st-chev { color: var(--text-faint); font-size: 0.8rem; transition: transform 0.15s; text-align: center; }
        .st-history.is-open .st-chev { transform: rotate(90deg); }
        .st-detail { list-style: none; margin: 0; padding: 0.35rem 1.5rem 0.7rem 2.2rem; border-bottom: 1px solid var(--panel-border); background: var(--bg-sunk); }
        .st-detail-head { display: flex; align-items: center; gap: 0.6rem; flex-wrap: wrap; padding: 0.25rem 0 0.45rem; font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); }
        .st-detail-head .pill { margin-left: auto; padding: 0.22rem 0.55rem; font-size: 0.72rem; }
        .st-comp { display: grid; grid-template-columns: 5.6rem minmax(0, 1fr) auto auto auto; align-items: center; column-gap: 0.75rem; padding: 0.3rem 0; font-size: 0.82rem; }
        .st-comp + .st-comp, .st-comp + .st-diff-wrap + .st-comp { border-top: 1px solid var(--panel-border); }
        .st-comp .st-chip { justify-self: start; }
        .st-chip.ch-new, .st-chip.ch-updated { background: var(--pill-wp-bg); color: var(--pill-wp-fg); border-color: transparent; }
        .st-chip.ch-deleted { color: var(--danger); border-color: var(--danger); }
        .st-chip.ch-downgraded { color: var(--pill-warn-fg, #d08c30); border-color: var(--pill-warn-fg, #d08c30); }
        .st-comp-main { min-width: 0; display: flex; flex-direction: column; gap: 0.05rem; }
        .st-comp-name { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--text); }
        .st-comp-sub { font-family: var(--font-mono); font-size: 0.68rem; color: var(--text-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .st-comp-ver { font-family: var(--font-mono); font-size: 0.74rem; color: var(--text-dim); white-space: nowrap; }
        .st-comp-ver .arrow { color: var(--text-faint); padding: 0 0.2rem; }
        .st-comp .st-actions .pill.armed { color: white; background: var(--danger); border-color: var(--danger); }
        .st-comp-more { padding: 0.35rem 0 0; font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); }
        .st-diff-wrap { padding: 0.15rem 0 0.5rem; }
        .st-diff { margin: 0; padding: 0.5rem 0.75rem; max-height: 380px; overflow: auto; background: var(--input-bg); border: 1px solid var(--panel-border); border-radius: var(--radius-md); font-family: var(--font-mono); font-size: 0.7rem; line-height: 1.45; white-space: pre; font-variant-ligatures: none; color: var(--text-dim); }
        .st-diff .d-add { color: #3d9a5c; } .st-diff .d-del { color: var(--danger); } .st-diff .d-hunk { color: var(--accent); } .st-diff .d-meta { color: var(--text-faint); }
        .st-diff-note { font-family: var(--font-mono); font-size: 0.68rem; color: var(--text-faint); padding: 0.2rem 0 0; }
        .site-cli { padding: 1rem 1.5rem 1.5rem; display: flex; flex-direction: column; gap: 0.6rem; }
        .st-cli-line { display: flex; align-items: center; gap: 0.5rem; background: var(--input-bg); border: 1px solid var(--panel-border); border-radius: var(--radius-md); padding: 0.35rem 0.5rem 0.35rem 0.8rem; }
        .st-cli-line:focus-within { border-color: var(--accent); }
        .st-cli-prompt { font-family: var(--font-mono); font-size: 0.82rem; color: var(--text-faint); white-space: nowrap; }
        .st-cli-input { flex: 1; min-width: 0; background: transparent; border: 0; outline: 0; color: var(--text); font-family: var(--font-mono); font-size: 0.82rem; }
        /* JetBrains Mono ligates "--" into one long dash, which reads as a
           missing character in a command line or code. Off wherever text
           is typed or shown verbatim. */
        .st-cli-line, .st-cli-input, .st-cli-out, .st-cli-examples, #siteCliMeta, .files-code, .files-code textarea, .files-hl, .db-sql-editor textarea, .log-msg, .log-detail, .tr-list, .filter-input, .modal-input, .file-name-input { font-variant-ligatures: none; font-feature-settings: "liga" 0, "calt" 0; }
        .st-cli-examples { display: flex; flex-wrap: wrap; gap: 0.35rem; align-items: center; font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); }
        .st-cli-examples button { background: transparent; border: 1px solid var(--panel-border); border-radius: var(--radius-pill); color: var(--text-dim); font: inherit; padding: 0.1rem 0.55rem; cursor: pointer; }
        .st-cli-examples button:hover { color: var(--text); border-color: var(--text-faint); }
        .st-cli-out { margin: 0; padding: 0.9rem 1rem; background: var(--bg-sunk); border: 1px solid var(--panel-border); border-radius: var(--radius-md); font-family: var(--font-mono); font-size: 0.76rem; line-height: 1.5; color: var(--text); white-space: pre-wrap; overflow-wrap: anywhere; max-height: 60vh; overflow: auto; }
        .st-cli-out.is-error { color: var(--danger); }
        @media (max-width: 760px) {
            .st-plugins, .st-themes { grid-template-columns: minmax(0, 1fr) auto minmax(7rem, auto); }
            .st-plugins .st-chip, .st-themes .st-chip, .st-auto { display: none; }
            .st-users { grid-template-columns: minmax(0, 1fr) auto; }
            .st-roles, .st-users .st-ver { display: none; }
            .st-cron { grid-template-columns: minmax(0, 1fr) auto auto; }
            .st-cron .st-chip { display: none; }
        }

        /* Files. A file manager over each site's directory: sites on the
           left, a breadcrumb bar and listing (or the open file) on the right. */
        body.view-files .wrap { max-width: 1280px; }
        .files-body { display: grid; grid-template-columns: minmax(220px, 260px) minmax(0, 1fr); height: calc(100vh - 262px); min-height: 460px; }
        .files-side { overflow-y: auto; border-right: 1px solid var(--panel-border); display: flex; flex-direction: column; }
        .files-side .db-list { border-right: 0; overflow: visible; flex: 1; }
        .files-side .db-row { padding: 0.45rem 1rem 0.45rem 0.9rem; }
        .files-side .db-row-name { font-size: 0.8rem; }
        .files-main { min-width: 0; display: flex; flex-direction: column; overflow: hidden; position: relative; }
        .files-bar { flex: none; flex-wrap: nowrap; }
        .files-crumbs { flex: 1; min-width: 0; display: flex; align-items: center; gap: 0.1rem; font-family: var(--font-mono); font-size: 0.76rem; color: var(--text-dim); overflow: hidden; white-space: nowrap; }
        .files-crumb { background: transparent; border: 0; padding: 0.2rem 0.35rem; border-radius: var(--radius-sm); font: inherit; color: var(--text-dim); cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 16rem; }
        .files-crumb:hover { color: var(--text); background: var(--panel-hover); }
        .files-crumb.is-current { color: var(--text); cursor: default; }
        .files-crumb.is-current:hover { background: transparent; }
        .files-crumb-sep { color: var(--text-faint); flex: none; }
        .files-crumbs .files-crumb:first-child { flex: none; }
        .files-dirty { font-family: var(--font-mono); font-size: 0.66rem; color: var(--pill-warn-fg, #d08c30); border: 1px solid currentColor; border-radius: var(--radius-pill); padding: 0.05rem 0.45rem; margin-left: 0.4rem; flex: none; }
        .files-actions { flex: none; }
        .files-actions .pill.armed, .files-row-del.armed { color: white; background: var(--danger); border-color: var(--danger); }

        .file-list { list-style: none; margin: 0; padding: 0; overflow-y: auto; flex: 1; min-height: 0; }
        .file-list > .empty, .file-list > .loading { padding: 3rem 1.5rem; text-align: center; color: var(--text-dim); }
        .file-head, .file-row { display: grid; grid-template-columns: 1.1rem minmax(0, 1fr) 5.5rem 4.2rem 3.6rem; column-gap: 0.7rem; align-items: center; padding: 0 1.25rem 0 1rem; }
        .file-head { position: sticky; top: 0; z-index: 2; background: var(--panel); border-bottom: 1px solid var(--panel-border); font-family: var(--font-mono); font-size: 0.64rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-faint); }
        .file-head button { background: transparent; border: 0; padding: 0.45rem 0; font: inherit; color: inherit; text-align: left; cursor: pointer; letter-spacing: inherit; text-transform: inherit; }
        .file-head button:hover, .file-head button.is-sorted { color: var(--text-dim); }
        .file-head .file-size, .file-head .file-time { text-align: right; }
        .file-row { padding-top: 0.42rem; padding-bottom: 0.42rem; border-bottom: 1px solid var(--panel-border); cursor: pointer; min-height: 2.1rem; }
        .file-row:hover { background: var(--panel-hover); }
        .file-row.is-selected { background: var(--panel-hover); box-shadow: inset 0 0 0 1px var(--panel-border-strong); }
        .file-row.is-hidden .file-name, .file-row.is-hidden .file-icon { opacity: 0.55; }
        .file-row.is-broken .file-name { color: var(--danger); text-decoration: line-through; }
        .file-icon { width: 15px; height: 15px; color: var(--text-faint); display: block; }
        .file-row.is-dir .file-icon { color: var(--accent); }
        .file-name { font-family: var(--font-mono); font-size: 0.8rem; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; display: flex; align-items: center; gap: 0.5rem; }
        .file-row.is-dir .file-name { font-weight: 500; }
        .file-link { font-family: var(--font-mono); font-size: 0.64rem; color: var(--text-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; min-width: 0; }
        .file-link::before { content: '→ '; }
        .file-size, .file-time { font-family: var(--font-mono); font-size: 0.72rem; color: var(--text-faint); text-align: right; white-space: nowrap; }
        .file-row-actions { display: flex; justify-content: flex-end; gap: 0.15rem; visibility: hidden; }
        .file-row:hover .file-row-actions, .file-row.is-selected .file-row-actions, .file-row-actions:has(.armed) { visibility: visible; }
        .file-row-btn { background: transparent; border: 1px solid transparent; color: var(--text-faint); font-family: var(--font-mono); font-size: 0.72rem; padding: 0.1rem 0.35rem; border-radius: var(--radius-sm); cursor: pointer; line-height: 1.2; }
        .file-row-btn:hover { color: var(--text); background: var(--panel); border-color: var(--panel-border); }
        .file-row-btn.armed { color: white; background: var(--danger); border-color: var(--danger); }
        .file-row.is-editing { cursor: default; }
        .file-name-input { width: 100%; background: var(--input-bg); border: 1px solid var(--accent); border-radius: var(--radius-sm); color: var(--text); font-family: var(--font-mono); font-size: 0.8rem; padding: 0.15rem 0.4rem; outline: 0; }
        .file-list .file-row.is-up .file-name { color: var(--text-dim); }

        .files-drop { position: absolute; inset: 0; display: none; align-items: center; justify-content: center; background: color-mix(in oklch, var(--accent) 12%, var(--panel)); border: 2px dashed var(--accent); z-index: 5; font-family: var(--font-mono); font-size: 0.85rem; color: var(--text); pointer-events: none; }
        .files-main.is-dragging .files-drop { display: flex; }

        .files-editor { flex: 1; min-height: 0; display: none; flex-direction: column; }
        .files-main.has-file .file-list, .files-main.has-file .file-head { display: none; }
        .files-main.has-file .files-editor { display: flex; }
        /* The editor: a transparent textarea over a highlighted layer that
           shares its font, padding and wrapping exactly. */
        .files-code { position: relative; flex: 1; min-height: 0; display: flex; }
        .files-code .files-hl, .files-code textarea { margin: 0; font-family: var(--font-mono); font-size: 0.8rem; line-height: 1.55; padding: 0.9rem 1.25rem; tab-size: 4; white-space: pre; box-sizing: border-box; }
        .files-hl { position: absolute; top: 0; left: 0; right: 0; bottom: 0; overflow: hidden; pointer-events: none; color: var(--text); background: transparent; }
        .files-hl code { font: inherit; }
        .files-code textarea { position: relative; z-index: 1; flex: 1; width: 100%; min-height: 0; background: transparent; border: 0; color: transparent; caret-color: var(--text); resize: none; outline: 0; overflow: auto; }
        .files-code.is-plain textarea { color: var(--text); }
        .files-code.is-plain textarea:disabled { color: var(--text-dim); }
        .files-code.is-plain .files-hl { display: none; }
        .files-code:has(textarea:disabled) .files-hl { color: var(--text-dim); }
        .files-code.is-wrapped .files-hl, .files-code.is-wrapped textarea { white-space: pre-wrap; overflow-wrap: anywhere; }
        .hl-cmt { color: var(--hl-cmt); font-style: italic; }
        .hl-str { color: var(--hl-str); }
        .hl-kw { color: var(--hl-kw); }
        .hl-num { color: var(--hl-num); }
        .hl-var { color: var(--hl-var); }
        .hl-tag { color: var(--hl-tag); }
        .hl-attr { color: var(--hl-attr); }
        .hl-fn { color: var(--hl-fn); }
        .files-preview { flex: 1; min-height: 0; overflow: auto; display: flex; align-items: center; justify-content: center; padding: 1.5rem; background: var(--bg-sunk); background-image: linear-gradient(45deg, var(--panel-border) 25%, transparent 25%, transparent 75%, var(--panel-border) 75%), linear-gradient(45deg, var(--panel-border) 25%, transparent 25%, transparent 75%, var(--panel-border) 75%); background-size: 16px 16px; background-position: 0 0, 8px 8px; }
        .files-preview img { max-width: 100%; max-height: 100%; box-shadow: 0 2px 12px rgba(0,0,0,0.25); background: white; }
        .files-note { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0.4rem; padding: 3rem 1.5rem; text-align: center; color: var(--text-dim); }
        .files-note .empty-hint { color: var(--text-faint); }
        .files-note .pill { margin-top: 0.6rem; }
        @media (max-width: 860px) {
            .files-body { grid-template-columns: 1fr; height: auto; min-height: 60vh; }
            .files-side { border-right: 0; max-height: 36vh; }
            .file-head, .file-row { grid-template-columns: 1.1rem minmax(0, 1fr) 5.5rem 3.6rem; }
            .file-time { display: none; }
        }

        /* Responsive */
        @media (max-width: 620px) {
            body { padding: 1.25rem 0.75rem 3rem; }
            .card-head { padding: 0.9rem 1rem; flex-wrap: wrap; }
            .card-actions { width: 100%; justify-content: flex-end; }
            .site-list { grid-template-columns: 1fr auto auto; column-gap: 0.6rem; }
            .site-row { padding: 0.7rem 1rem; }
            .site-size, .site-modified, .head-size, .head-modified { display: none; }
            .site-actions { opacity: 1; }
            .add-row { padding: 0.8rem 1rem; }
            .card-foot { padding: 0.75rem 1rem; }
        }
    </style>
</head>
<body>
    <div class="wrap">
        <nav class="nav">
            <a class="logo" href="/">
                <svg class="logo-mark" viewBox="0 0 64 64" aria-hidden="true" focusable="false" stroke-linecap="round" stroke-linejoin="round">
                    <circle cx="32" cy="32" r="26"/><path d="M 17 27 Q 24.5 20 32 27 T 47 27"/><path d="M 17 40 Q 24.5 33 32 40 T 47 40"/>
                </svg>
                <span>Cove</span>
            </a>
            <div class="nav-views" role="tablist" aria-label="View">
                <button type="button" class="nav-view is-active" role="tab" data-view="sites" aria-selected="true">sites</button>
                <button type="button" class="nav-view" role="tab" data-view="mail" aria-selected="false">mail<span class="nav-badge" id="mailBadge" style="display: none;"></span></button>
                <button type="button" class="nav-view" role="tab" data-view="db" aria-selected="false">databases</button>
                <button type="button" class="nav-view" role="tab" data-view="logs" aria-selected="false">logs</button>
                <button type="button" class="nav-view" role="tab" data-view="files" aria-selected="false">files</button>
            </div>
            <div class="nav-services services">
                <button type="button" class="dot link" data-service="caddy" title="Caddy status">caddy</button>
                <button type="button" class="dot link" data-service="mariadb" title="MariaDB status and credentials">mariadb</button>
                <button type="button" class="dot link" data-service="mailpit" title="Mailpit status">mailpit</button>
                <button type="button" class="dot link is-busy sweep-dot" id="navSweep" data-service="history" title="The nightly history sweep is running — click for the site it is on" style="display: none;">6/80</button>
            </div>
            <button class="theme-btn" id="btnTheme" title="Theme" aria-label="Theme" aria-haspopup="menu">
                <svg class="icon-system" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="8" cy="8" r="6"/><path d="M8 2a6 6 0 0 1 0 12z" fill="currentColor" stroke="none"/></svg>
                <svg class="icon-moon" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M13.5 9.2A5.5 5.5 0 0 1 6.8 2.5a5.75 5.75 0 1 0 6.7 6.7Z"/></svg>
                <svg class="icon-sun" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="8" cy="8" r="3"/><path d="M8 1.5v1.8M8 12.7v1.8M2.6 2.6l1.3 1.3M12.1 12.1l1.3 1.3M1.5 8h1.8M12.7 8h1.8M2.6 13.4l1.3-1.3M12.1 3.9l1.3-1.3"/></svg>
            </button>
            <div class="ctx-menu theme-menu" id="themeMenu" role="menu" style="display: none;">
                <button class="ctx-item" role="menuitemradio" data-theme-pref="system"><span>System</span></button>
                <button class="ctx-item" role="menuitemradio" data-theme-pref="light"><span>Light</span></button>
                <button class="ctx-item" role="menuitemradio" data-theme-pref="dark"><span>Dark</span></button>
            </div>
        </nav>

        <section class="card" id="sitesCard">
            <header class="card-head">
                <h1 class="card-title">Sites</h1>
                <div class="card-actions">
                    <button class="pill primary" id="btnToggleAdd">+ add site</button>
                </div>
            </header>

            <div id="alerts"></div>
            <template id="tpl-alert">
                <div class="new-site-alert">
                    <span class="new-site-alert-icon" aria-hidden="true">
                        <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 8.2l3 3 7-7"/></svg>
                    </span>
                    <div class="new-site-alert-text">
                        <strong></strong> is ready.
                    </div>
                    <button class="pill primary alert-login">log in to admin</button>
                    <a class="pill primary alert-open" target="_blank" rel="noopener">open site</a>
                    <button class="new-site-alert-close" aria-label="Dismiss" title="Dismiss">×</button>
                </div>
            </template>

            <div class="filter-row">
                <span class="filter-chip" id="typeChip" aria-label="Active type filter" style="display: none;">
                    <span id="typeChipLabel"></span>
                    <button type="button" class="filter-chip-x" id="typeChipClear" aria-label="Remove type filter" title="Remove">×</button>
                </span>
                <input
                    class="filter-input"
                    id="filterInput"
                    type="text"
                    placeholder="filter sites by name or type…"
                    spellcheck="false"
                    autocomplete="off"
                    autocapitalize="off"
                    autocorrect="off"
                    aria-label="Filter sites"
                    autofocus
                >
                <button
                    type="button"
                    class="bulk-delete-btn"
                    id="btnBulkDelete"
                    title="Delete every site matching the current filter"
                    style="display: none;"></button>
                <span class="filter-kbd" id="filterKbd" aria-hidden="true">/</span>
                <button class="filter-clear" id="btnFilterClear" aria-label="Clear filter" title="Clear all (Esc)" style="display: none;">×</button>
            </div>

            <div class="add-row" id="addRow" style="display: none;">
                <div class="add-drop" id="addDrop" title="Import a backup: a zip or tar.gz holding a WordPress tree and a .sql dump — a Cove snapshot export, a Local export, a host backup">
                    <span class="add-drop-art" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v11M7 9l5-5 5 5"/><path d="M4 15v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4"/></svg></span>
                    <span class="add-drop-text" id="addDropText">drop a backup zip here to import a site, or <u>choose one</u> — otherwise create a fresh site below</span>
                    <span class="add-drop-file" id="addDropFile" style="display: none;"><span id="addDropName"></span><button type="button" class="filter-chip-x" id="addDropClear" aria-label="Remove the archive" title="Remove">×</button></span>
                    <input type="file" id="addDropInput" accept=".zip,.tar.gz,.tgz,application/zip,application/gzip" style="display: none;">
                </div>
                <div class="add-progress" id="addProgress" style="display: none;"><span id="addProgressText"></span></div>
                <form id="addForm">
                    <input type="text" id="newSiteName" placeholder="site-name" required>
                    <label class="plain-toggle">
                        <input type="checkbox" id="newSitePlain">
                        plain (no WordPress)
                    </label>
                    <select class="wp-version" id="wpVersionSelect" title="WordPress version to install" aria-label="WordPress version">
                        <option value="latest">latest</option>
                        <option value="nightly">nightly</option>
                    </select>
                    <button class="pill primary" type="submit" id="btnCreate" disabled>
                        <span class="btn-spinner" id="createSpinner" aria-hidden="true" style="display: none;"></span>
                        <span id="createLabel">create</span>
                    </button>
                </form>
            </div>

            <ul class="site-list" id="siteList">
                <li class="site-head" id="siteHead" style="display: none;">
                    <button type="button" class="site-head-btn" data-sort="name" title="Sort by name">name<span class="sort-arrow"></span></button>
                    <button type="button" class="site-head-btn" data-sort="type" title="Sort by type">type<span class="sort-arrow"></span></button>
                    <button type="button" class="site-head-btn site-head-right head-modified" data-sort="modified" title="Sort by last modified">modified<span class="sort-arrow"></span></button>
                    <button type="button" class="site-head-btn site-head-right head-size" data-sort="size" title="Sort by disk size">size<span class="sort-arrow"></span></button>
                    <span aria-hidden="true"></span>
                </li>
                <template id="tpl-site-row">
                    <li class="site-row">
                        <span class="site-domain-cell">
                            <span class="site-domain"></span>
                            <a class="site-open-link" target="_blank" rel="noopener">
                                <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6.5 4.5h5v5"/><path d="M11.5 4.5 4.5 11.5"/></svg>
                            </a>
                        </span>
                        <span class="site-type-cell">
                            <span class="site-type"></span>
                            <span class="site-wp-version"></span>
                            <span class="site-php-version"></span>
                        </span>
                        <span class="site-modified"></span>
                        <span class="site-size"></span>
                        <div class="site-actions">
                            <button class="site-action-btn site-login-btn">
                                <span class="btn-label">login</span>
                                <span class="btn-spinner" aria-hidden="true"></span>
                            </button>
                        </div>
                    </li>
                </template>
                <li class="loading" id="siteLoading">Loading sites…</li>
                <li class="empty" id="emptyNone" style="display: none;">
                        <svg class="empty-art" viewBox="0 0 104 68" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                            <path class="art-fill" d="M52 12 L68 38 H52 Z"/>
                            <path class="art-line" d="M52 10 v30"/>
                            <path class="art-line" d="M52 14 L67 37 H52 Z"/>
                            <path class="art-line" d="M49 20 L39 37 H49 Z"/>
                            <path class="art-line" d="M36 42 h32 l-6 9 H42 Z"/>
                            <path class="art-wave" d="M8 56 Q 15 52, 22 56 T 36 56 T 50 56 T 64 56 T 78 56 T 92 56"/>
                            <path class="art-wave" d="M20 62 Q 27 58, 34 62 T 48 62 T 62 62 T 76 62" opacity="0.35"/>
                        </svg>
                    <div>No sites in the cove yet.</div>
                    <div class="empty-hint">Click <em>+ add site</em>, or run <code>cove add myblog</code>.</div>
                </li>
                <li class="empty" id="emptyFilter" style="display: none;">
                        <svg class="empty-art" viewBox="0 0 104 68" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                            <path class="art-line" d="M52 44 v-14 q0 -6 6 -6 h4"/>
                            <path class="art-line" d="M62 18 h8 q3 0 3 3 v3 h-11 q-3 0 -3 -3 v-3 Z"/>
                            <path class="art-line" d="M73 21 l7 -4 v11 l-7 -4"/>
                            <path class="art-fill" d="M46 44 h12 v8 H46 Z"/>
                            <path class="art-line" d="M46 52 v-8 h12 v8"/>
                            <path class="art-wave" d="M8 56 Q 15 52, 22 56 T 36 56 T 50 56 T 64 56 T 78 56 T 92 56"/>
                            <path class="art-wave" d="M20 62 Q 27 58, 34 62 T 48 62 T 62 62 T 76 62" opacity="0.35"/>
                        </svg>
                    <div>Nothing surfaced for <code id="emptyFilterQuery"></code>.</div>
                    <div class="empty-hint">Press Esc to clear.</div>
                </li>
            </ul>

            <footer class="card-foot">
                <div class="totals">
                    <span id="siteCount"></span>
                    <span id="totalSize" style="display: none;"></span>
                    <button type="button" class="refresh-btn" id="btnRefreshSizes" title="Refresh disk sizes">↻</button>
                </div>
            </footer>
        </section>

        <!-- Mail: a Cove-native inbox over Mailpit's API (proxied same-origin
             at /mail-api/). Every Cove site receives mail at its own
             <site>.localhost domain, so the To address is the site — the one
             filter Mailpit's own UI cannot offer. -->
        <section class="card mail-card" id="mailCard" style="display: none;">
            <header class="card-head">
                <div class="view-head"><button type="button" class="site-back view-back" id="mailBack" style="display: none;"></button><h1 class="card-title">Mail</h1></div>
                <div class="card-actions">
                    <a class="pill" href="https://mail.cove.localhost<?= $__cove_port_suffix ?>" target="_blank" rel="noopener" title="Open Mailpit's own interface">
                        mailpit
                        <svg class="pill-icon" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6.5 4.5h5v5"/><path d="M11.5 4.5 4.5 11.5"/></svg>
                    </a>
                    <button type="button" class="pill" id="btnMailReadAll" title="Mark every listed message as read">mark all read</button>
                    <button type="button" class="pill mail-delete-all" id="btnMailDeleteAll" title="Delete every message matching the current filter">delete all</button>
                </div>
            </header>

            <div class="filter-row">
                <span class="filter-chip" id="mailSiteChip" aria-label="Active site filter" style="display: none;">
                    <span id="mailSiteChipLabel"></span>
                    <button type="button" class="filter-chip-x" id="mailSiteChipClear" aria-label="Remove site filter" title="Remove">×</button>
                </span>
                <input
                    class="filter-input"
                    id="mailSearch"
                    type="text"
                    placeholder="search mail… (from: to: subject: has:attachment)"
                    spellcheck="false"
                    autocomplete="off"
                    autocapitalize="off"
                    autocorrect="off"
                    aria-label="Search mail"
                >
                <label class="mail-unread-toggle" title="Only unread messages">
                    <input type="checkbox" id="mailUnreadOnly">
                    unread
                </label>
                <span class="filter-kbd" id="mailKbd" aria-hidden="true">/</span>
                <button class="filter-clear" id="btnMailSearchClear" aria-label="Clear search" title="Clear all (Esc)" style="display: none;">×</button>
            </div>

            <div class="mail-body" id="mailBody">
                <ul class="mail-list" id="mailList">
                    <template id="tpl-mail-row">
                        <li class="mail-row">
                            <span class="mail-dot" aria-hidden="true"></span>
                            <div class="mail-main">
                                <div class="mail-line">
                                    <span class="mail-from"></span>
                                    <svg class="mail-att" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M10.5 5.5 6 10a1.6 1.6 0 0 0 2.3 2.3l5-5a3 3 0 0 0-4.3-4.3l-5.5 5.5a4.4 4.4 0 0 0 6.2 6.2l4-4"/></svg>
                                    <span class="mail-age"></span>
                                </div>
                                <div class="mail-subject"></div>
                                <div class="mail-line">
                                    <span class="mail-site" role="button"></span>
                                    <span class="mail-snippet"></span>
                                </div>
                            </div>
                        </li>
                    </template>
                    <li class="loading" id="mailLoading">Loading mail…</li>
                    <li class="empty" id="mailError" style="display: none;">
                        <div>Mailpit isn't answering.</div>
                        <div class="empty-hint">Check the mailpit dot in the top bar, or run <code>cove status</code>.</div>
                    </li>
                    <li class="empty" id="mailEmptyNone" style="display: none;">
                        <svg class="empty-art" viewBox="0 0 104 68" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                            <path class="art-fill" d="M30 18 h44 v30 H30 Z"/>
                            <path class="art-line" d="M30 18 h44 v30 H30 Z"/>
                            <path class="art-line" d="M30 18 L52 36 L74 18"/>
                            <path class="art-wave" d="M8 56 Q 15 52, 22 56 T 36 56 T 50 56 T 64 56 T 78 56 T 92 56"/>
                            <path class="art-wave" d="M20 62 Q 27 58, 34 62 T 48 62 T 62 62 T 76 62" opacity="0.35"/>
                        </svg>
                        <div>No mail yet.</div>
                        <div class="empty-hint">Everything your sites send lands here instead of the internet.</div>
                    </li>
                    <li class="empty" id="mailEmptyFilter" style="display: none;">
                        <div>Nothing matches <code id="mailEmptyQuery"></code>.</div>
                        <div class="empty-hint">Press Esc to clear.</div>
                    </li>
                </ul>

                <div class="mail-reader" id="mailReader">
                    <div class="mail-reader-empty" id="mailReaderEmpty">
                        <svg class="empty-art" viewBox="0 0 104 68" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                            <path class="art-line" d="M34 14 h36 v40 H34 Z"/>
                            <path class="art-line" d="M41 24 h22 M41 32 h22 M41 40 h14"/>
                            <path class="art-wave" d="M8 60 Q 15 56, 22 60 T 36 60 T 50 60 T 64 60 T 78 60 T 92 60"/>
                        </svg>
                        <div>Select a message.</div>
                        <div class="empty-hint">↑↓ to move · ⌫ to delete · u to toggle unread</div>
                    </div>
                    <div id="mailMsg" style="display: none;">
                        <div class="mail-msg-head">
                            <button type="button" class="pill mail-back" id="btnMailBack">← inbox</button>
                            <div class="loading" id="mailMsgLoading">Loading message…</div>
                            <div class="mail-msg-error" id="mailMsgError" style="display: none;"></div>
                            <div id="mailMsgHead" style="display: none;">
                                <h2 class="mail-msg-subject" id="mailMsgSubject"></h2>
                                <div id="mailMsgMeta"></div>
                                <div class="mail-links" id="mailMsgLinks"></div>
                            </div>
                        </div>
                        <div id="mailMsgMain" style="display: none;">
                            <div class="mail-msg-bar">
                                <div class="mail-parts" id="mailParts" role="tablist">
                                    <button type="button" class="mail-part" role="tab" data-part="html">html</button>
                                    <button type="button" class="mail-part" role="tab" data-part="text">text</button>
                                    <button type="button" class="mail-part" role="tab" data-part="headers">headers</button>
                                </div>
                                <span class="mail-bar-note" id="mailRemoteNote" style="display: none;"></span>
                                <div class="mail-msg-actions">
                                    <button type="button" class="pill" id="btnMailUnread">mark unread</button>
                                    <button type="button" class="pill" id="btnMailDelete">delete</button>
                                    <a class="pill" id="mailOpenInMailpit" target="_blank" rel="noopener" title="Open this message in Mailpit (raw source, spam score, HTML check)">mailpit ↗</a>
                                </div>
                            </div>
                            <div class="mail-msg-body">
                                <!-- No scripts, no forms, no remote loads: the sandbox denies
                                     script execution, and the CSP injected into the srcdoc
                                     limits images to inline parts served via /mail-api/.
                                     allow-same-origin is what lets the frame be measured
                                     (and 'self' resolve for those inline parts); with no
                                     allow-scripts nothing inside can act on that origin.
                                     Popups escape the sandbox so a reset link opens as a
                                     normal tab. -->
                                <iframe class="mail-frame" id="mailFrame" sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox" referrerpolicy="no-referrer" title="Message"></iframe>
                                <pre class="mail-pre" id="mailText"></pre>
                                <pre class="mail-pre" id="mailHeaders"></pre>
                            </div>
                            <div class="mail-attachments" id="mailAttachments" style="display: none;"></div>
                        </div>
                    </div>
                </div>
            </div>

            <footer class="card-foot">
