    <script>
        const PORT_SUFFIX = '<?= $__cove_port_suffix ?>';
        const SITES_DIR = 'SITES_DIR_PLACEHOLDER';
        // Adminer needs the username to deep-link straight into a site's schema.
        const DB_USER = '<?= htmlspecialchars($config_data['DB_USER'] ?? '', ENT_QUOTES) ?>';

        // No framework: state lives on `app`, and every method that mutates
        // state ends by calling render(). Renderers are idempotent and only
        // write DOM they own — crucially they never write input values, so
        // typing never fights the renderer; inputs push into state via their
        // own listeners and open()-style methods set values explicitly.
        const $id = (id) => document.getElementById(id);
        const show = (el, on) => { if (el) el.style.display = on ? '' : 'none'; };

        const app = {
            // Respect the OS theme preference on first visit, dark otherwise.
            // themePref is what the user chose ('light' | 'dark' | 'system');
            // theme is the effective mode the tokens paint.
            themePref: (['light', 'dark'].includes(localStorage.getItem('theme')) ? localStorage.getItem('theme') : 'system'),
            theme: (['light', 'dark'].includes(localStorage.getItem('theme')) ? localStorage.getItem('theme') : (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark')),
            sites: [],
            isLoading: true,
            adding: false,
            showDbModal: false,
            isRefreshingSizes: false,
            filter: '',
            typeFilter: null, // null | 'WordPress' | 'Plain' — set via the row type pills, cleared via the chip × or overall filter clear
            // Default to most-recently-modified rather than alphabetical: on an
            // install with hundreds of sites, "what was I just working on" is a
            // far better landing state than "what starts with A".
            sort: ['name', 'type', 'size', 'modified'].includes(localStorage.getItem('sort')) ? localStorage.getItem('sort') : 'modified',
            sortDir: ['asc', 'desc'].includes(localStorage.getItem('sortDir')) ? localStorage.getItem('sortDir') : 'desc',
            pinned: (() => { try { return JSON.parse(localStorage.getItem('pinned')) || []; } catch (e) { return []; } })(),
            selectedName: null,
            ctxMenu: { open: false, site: null, x: 0, y: 0, openedAt: 0 },
            fileCtx: { open: false, target: null, x: 0, y: 0, openedAt: 0 },
            sitePage: { name: null, tab: 'overview', tabs: {}, shot: { busy: null, asked: {}, unsupported: false }, net: { items: [], loading: false, error: null, loadedFor: null }, busy: null, cli: { cmd: '', output: '', code: 0, ms: 0, ran: null, running: false, history: [], histIdx: -1 } },
            siteDeleteConfirm: null,
            tabCtx: { open: false, x: 0, y: 0, openedAt: 0, items: [], title: '' },
            palette: { open: false, query: '', index: 0 },
            rename: { open: false, site: null, value: '', busy: false },
            logView: { open: false, site: '', text: '', truncated: false, busy: false, raw: false },
            phpModal: { open: false, site: null },
            domainsModal: { open: false, site: null, busy: false, pending: null },
            // { supported, default, versions: [{version, installed}] } — fetched
            // lazily; null until loaded, refreshed after any pin change.
            phpInfo: null,
            phpInstallPoll: null,
            // name → target version while a change is in flight. Kept separate
            // from the site objects because getSites() rebuilds those from the
            // server and would drop a flag stored on them mid-install.
            phpApplying: {},
            newSite: { name: '', isPlain: false, wpVersion: 'latest', isLoading: false },
            // Populated lazily the first time the add row opens — no reason
            // to hit wp.org on a page load that never creates a site. Stays
            // empty when offline, leaving 'latest' and 'nightly' available.
            wpVersions: [],
            wpVersionsLoaded: false,
            snackbar: { visible: false, message: '', isError: false, timer: null, action: null, actionLabel: '' },
            // Deletes are staged for a short undo window before anything is
            // sent to the backend. One batch at a time; staging more sites
            // merges into it and restarts the window.
            pendingDelete: null, // { sites: [...], timer }
            bulkArmed: false,
            bulkConfirm: null, // { names: [...] } while the bulk-delete dialog is open
            importFile: null,  // a File dropped on the add-site row, to import instead of installing
            importing: null,   // { pct, phase } while an import runs
            bulkArmTimer: null,
            // Persistent dismissible banners for newly-created sites — the
            // snackbar only lives ~3.5s, not long enough to reach for the
            // admin login after spinning up a fresh install.
            alerts: [],
            deleteQueue: [],
            isProcessingQueue: false,
            _paletteItems: [],
            // 'sites' | 'mail'. Mail is a sibling view of the sites list,
            // reachable from the nav, the hash (#mail, #mail/<site>), a
            // site's row menu, and the palette.
            view: 'sites',
            mail: {
                items: [], total: 0, unread: 0, matched: 0,
                start: 0, limit: 50,
                query: '', site: null, unreadOnly: false,
                loading: false, loaded: false, error: null,
                selectedId: null, msg: null, msgLoading: false, msgError: null,
                part: 'html', headers: null, renderedId: null, remoteBlocked: 0,
                deleteArmed: false, armTimer: null, searchTimer: null, syncTimer: null,
                seq: 0, ws: null, pollTimer: null, wsRetry: null, info: null,
            },
            db: {
                list: [], tables: [], tablesFor: null, wp: null, server: '',
                name: null, table: null, part: 'rows', sql: false,
                filter: '', loading: false, loaded: false, error: null,
                rows: { columns: [], pk: [], items: [], total: 0, start: 0, limit: 100, sort: '', dir: 'asc', q: '', col: '', loading: false, error: null, seq: 0, timer: null },
                structure: null,
                edit: null, // { row, col, value, busy }
                delArm: null, delTimer: null,
                console: { text: '', results: null, ms: 0, running: false, history: [] },
            },
            logs: {
                system: [], sites: [], dir: '', sourcesLoaded: false, siteFilter: '',
                source: 'errors', site: null, tab: 'errors',
                level: 'all', query: '',
                entries: [], size: 0, nextBefore: null, scanned: 0, path: '', kind: 'php', missing: false,
                loading: false, error: null, seq: 0, live: true, pollTimer: null,
                expanded: {}, clearArm: false, armTimer: null, newIds: {},
            },
            files: {
                site: null, path: '', file: null, target: null,
                entries: [], root: '', writable: true, loadedFor: null,
                loading: false, error: null, seq: 0, fileSeq: 0,
                filter: '', siteFilter: '', sort: 'name', dir: 'asc', hidden: true, wrap: false, selected: null, scrolledFor: null,
                dirty: false, saving: false, conflict: false, renderedPath: null,
                edit: null, delArm: null, armTimer: null, drag: 0, uploading: null,
            },

            get adminerUrl() { return 'https://db.cove.localhost' + PORT_SUFFIX; },
            get mailpitUrl() { return 'https://mail.cove.localhost' + PORT_SUFFIX; },
            get totalBytes() { return this.sites.reduce((t, s) => t + (s.size_bytes || 0), 0); },
            get filteredSites() {
                // Two independent filters ANDed together: typeFilter (chip,
                // exact match on site.type) and filter (free text, substring
                // match on name OR type). Keeping them separate means the
                // user can type anything in the input without worrying about
                // stepping on the type constraint.
                let base = [...this.sites];
                if (this.typeFilter) {
                    base = base.filter(s => s.type === this.typeFilter);
                }
                const q = this.filter.trim().toLowerCase();
                if (q) {
                    base = base.filter(s =>
                        s.name.toLowerCase().includes(q) ||
                        (s.type || '').toLowerCase().includes(q));
                }
                const dir = this.sortDir === 'asc' ? 1 : -1;
                if (this.sort === 'size') {
                    base.sort((a, b) => dir * ((a.size_bytes || 0) - (b.size_bytes || 0)));
                } else if (this.sort === 'modified') {
                    base.sort((a, b) => dir * ((a.modified_at || 0) - (b.modified_at || 0)));
                } else if (this.sort === 'type') {
                    // Version segments compare numerically so 6.10 outranks 6.9.
                    // Plain sites have no wp_version and stay grouped together.
                    const vcmp = (a, b) => {
                        const pa = (a.wp_version || '').split('.'), pb = (b.wp_version || '').split('.');
                        for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
                            const d = (parseInt(pa[i], 10) || 0) - (parseInt(pb[i], 10) || 0);
                            if (d) return d;
                        }
                        return 0;
                    };
                    base.sort((a, b) => dir * (a.type.localeCompare(b.type) || vcmp(a, b)) || a.name.localeCompare(b.name));
                } else {
                    base.sort((a, b) => dir * a.name.localeCompare(b.name));
                }
                // Pinned sites float above the chosen sort rather than replacing
                // it: out of hundreds of sites only a handful are ever active.
                if (this.pinned.length) {
                    base.sort((a, b) => (this.pinned.includes(b.name) ? 1 : 0) - (this.pinned.includes(a.name) ? 1 : 0));
                }
                return base;
            },

            get typeFilterLabel() {
                return this.typeFilter === 'WordPress' ? 'type: wp' : 'type: static';
            },

            setTypeFilter(v) {
                this.typeFilter = v;
                // An armed bulk-delete is scoped to the current result set —
                // disarm when the filter changes underneath it.
                this.bulkArmed = false;
                this.render();
            },

            clearAllFilters() {
                this.filter = '';
                $id('filterInput').value = '';
                this.typeFilter = null;
                this.bulkArmed = false;
                this.render();
            },

            get siteCountLabel() {
                const total = this.sites.length;
                const visible = this.filteredSites.length;
                const suffix = ' site' + (total === 1 ? '' : 's');
                return visible === total ? total + suffix : visible + ' of ' + total + suffix;
            },

            init() {
                this.applyTheme();
                this.bindStaticEvents();
                this.bindMailEvents();
                this.bindDbEvents();
                this.bindLogsEvents();
                this.bindFilesEvents();
                this.bindSiteEvents();
                this.bindSiteTabEvents();
                this.bindTips();
                this.render();
                this.sweepPoll();

                // If the tab closes during an undo window, flush the staged
                // deletes with keepalive requests so they aren't lost. No
                // reload_server here: the next reload from any source
                // regenerates from disk and prunes via tombstones.
                window.addEventListener('pagehide', () => {
                    if (!this.pendingDelete) return;
                    for (const s of this.pendingDelete.sites) {
                        fetch('/api.php', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ action: 'delete_site', site_name: s.name }),
                            keepalive: true
                        }).catch(() => {});
                    }
                    this.pendingDelete = null;
                });

                // `/` focuses the filter (GitHub-style). Ignored when typing
                // in a form field or holding a modifier key.
                window.addEventListener('keydown', (e) => {
                    const el = document.activeElement;
                    const tag = el && el.tagName;
                    const typing = tag === 'INPUT' || tag === 'TEXTAREA' || (el && el.isContentEditable);

                    // Cmd/Ctrl+K opens the palette from anywhere, including
                    // from inside the filter box — it's the one shortcut that
                    // should never be swallowed by a focused field.
                    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
                        e.preventDefault();
                        this.palette.open ? this.closePalette() : this.openPalette();
                        return;
                    }
                    if (this.palette.open) {
                        // Palette owns its own keys via its input's listeners;
                        // catch Esc here too in case the input lost focus.
                        if (e.key === 'Escape') this.closePalette();
                        return;
                    }

                    if (this.view === 'files') {
                        this.filesKeydown(e, typing);
                        return;
                    }

                    if (this.view === 'site') {
                        if (e.key === 'Escape') {
                            if (this.tabCtx.open) { this.closeTabCtx(); return; }
                            if (this.siteDeleteConfirm) { this.closeSiteDeleteConfirm(); return; }
                            if (this.bulkConfirm) { this.closeBulkConfirm(); return; }
                        if (this.phpModal.open) { this.closePhpModal(); return; }
                            if (this.domainsModal.open) { this.closeDomainsModal(); return; }
                            if (this.rename.open) { this.closeRename(); return; }
                            if (this.showDbModal) { this.setDbModal(false); return; }
                            if (typing) return;
                            if (this.sitePage.tab !== 'overview') { this.setSiteTab('overview'); return; }
                            this.setView('sites');
                            return;
                        }
                        if (e.key === 'Enter' && (e.metaKey || e.ctrlKey) && !typing) {
                            const s = this.pageSite;
                            if (s && s.type === 'WordPress') { e.preventDefault(); this.getLoginLink(s.name); }
                        }
                        return;
                    }

                    if (this.view === 'logs') {
                        if (e.key === 'Escape' && !typing) {
                            if (this.ctxMenu.open) { this.closeRowMenu(); return; }
                            if (this.showDbModal) { this.setDbModal(false); return; }
                            if (this.logs.query || this.logs.level !== 'all') { this.logsClearFilters(); return; }
                            if (this.logs.site) { this.setLogsSite(null); return; }
                        }
                        if (e.key === '/' && !e.ctrlKey && !e.metaKey && !e.altKey && !typing) {
                            e.preventDefault();
                            $id('logsSearch').focus();
                        }
                        return;
                    }

                    if (this.view === 'db') {
                        if (this.dbKeydown(e, typing)) return;
                        if (e.key === 'Escape') {
                            if (this.ctxMenu.open) { this.closeRowMenu(); return; }
                            if (this.showDbModal) { this.setDbModal(false); return; }
                        }
                        if (e.key === '/' && !e.ctrlKey && !e.metaKey && !e.altKey && !typing) {
                            e.preventDefault();
                            $id('dbFilter').focus();
                        }
                        return;
                    }

                    // The mail view has its own keys; the site-list keys below
                    // would otherwise act on rows the user cannot see.
                    if (this.view === 'mail') {
                        if (this.mailKeydown(e, typing)) return;
                        if (e.key === 'Escape') {
                            if (this.ctxMenu.open) { this.closeRowMenu(); return; }
                            if (this.showDbModal) { this.setDbModal(false); return; }
                        }
                        if (e.key === '/' && !e.ctrlKey && !e.metaKey && !e.altKey && !typing) {
                            e.preventDefault();
                            $id('mailSearch').focus();
                        }
                        return;
                    }

                    // Arrows work while filtering (type to narrow, arrow to pick).
                    // j/k only outside a text field, or they'd eat typed letters.
                    const isDown = e.key === 'ArrowDown' || (!typing && e.key === 'j');
                    const isUp   = e.key === 'ArrowUp'   || (!typing && e.key === 'k');
                    if ((isDown || isUp) && !e.metaKey && !e.ctrlKey && !e.altKey) {
                        e.preventDefault();
                        this.moveSelection(isDown ? 1 : -1);
                        return;
                    }

                    if (e.key === 'Enter' && this.selectedName && !this.adding) {
                        const site = this.selectedSite();
                        if (!site) return;
                        e.preventDefault();
                        if ((e.metaKey || e.ctrlKey) && site.type === 'WordPress') {
                            this.getLoginLink(site.name);
                        } else {
                            this.openSitePage(site.name);
                        }
                        return;
                    }

                    if ((e.metaKey || e.ctrlKey) && (e.key === 'Backspace' || e.key === 'Delete') && this.selectedName) {
                        e.preventDefault();
                        this.deleteSite(this.selectedName);
                        return;
                    }

                    if (e.key === 'Escape') {
                        if (this.ctxMenu.open) { this.closeRowMenu(); return; }
                        if (this.bulkConfirm) { this.closeBulkConfirm(); return; }
                        if (this.phpModal.open) { this.closePhpModal(); return; }
                        if (this.domainsModal.open) { this.closeDomainsModal(); return; }
                        if (this.rename.open) { this.closeRename(); return; }
                        if (this.logView.open) { this.closeLog(); return; }
                        if (this.showDbModal) { this.setDbModal(false); return; }
                        if (this.selectedName && !typing) { this.selectedName = null; this.render(); return; }
                    }

                    if (e.key === '/' && !e.ctrlKey && !e.metaKey && !e.altKey) {
                        if (typing) return;
                        e.preventDefault();
                        $id('filterInput').focus();
                    }
                });

                // A scroll or resize would leave the menu floating away from
                // the row it belongs to, so dismiss rather than reposition.
                window.addEventListener('scroll', () => { if (this.ctxMenu.open) this.closeRowMenu(); }, { passive: true });
                window.addEventListener('resize', () => { if (this.ctxMenu.open) this.closeRowMenu(); });

                // Click anywhere outside the context menu dismisses it. The
                // click that opened the menu also bubbles here, so skip it.
                document.addEventListener('click', (e) => {
                    if (!this.ctxMenu.open || e.timeStamp === this.ctxMenu.openedAt) return;
                    if (!$id('ctxMenu').contains(e.target)) this.closeRowMenu();
                });

                // Non-blocking: the context menu's "php X.Y" meta and the
                // platform-support check want this early, but nothing waits on it.
                this.loadPhpInfo();

                this.getSites().then(() => {
                    // If the size cache is empty (fresh install or just deleted),
                    // kick off a background refresh so sizes populate without
                    // making the user hunt for the ↻ button.
                    if (this.sites.length > 0 && this.sites.every(s => s.size_bytes === null)) {
                        this.refreshSizes();
                    }
                });

                // Mail: pick the view from the hash, then keep the unread
                // badge live over Mailpit's websocket (or a poll when the
                // socket is unavailable).
                this.readViewFromUrl();
                this.refreshMailCounts();
                this.connectMailEvents();
            },

            // One-time listeners on elements that are never re-created. Row,
            // alert, palette and menu clicks are delegated from their fixed
            // containers, so rebuilding children never orphans a handler.
            bindStaticEvents() {
                $id('btnTheme').addEventListener('click', () => { this.closeThemeMenu(); this.toggleTheme(); });
                $id('btnTheme').addEventListener('contextmenu', (e) => { e.preventDefault(); this.themeMenuOpen ? this.closeThemeMenu() : this.openThemeMenu(); });
                $id('themeMenu').addEventListener('click', (e) => {
                    const b = e.target.closest('[data-theme-pref]');
                    if (!b) return;
                    this.setThemePref(b.dataset.themePref);
                    this.closeThemeMenu();
                });
                document.addEventListener('click', (e) => { if (this.themeMenuOpen && !e.target.closest('#themeMenu, #btnTheme')) this.closeThemeMenu(); });
                document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && this.themeMenuOpen) this.closeThemeMenu(); });
                try { window.matchMedia('(prefers-color-scheme: light)').addEventListener('change', () => { if (this.themePref === 'system') { this.applyTheme(); this.renderChrome(); } }); } catch (e) {}
                document.querySelectorAll('[data-service]').forEach(b => b.addEventListener('click', () => b.dataset.service === 'history' ? this.sweepGo() : this.openService(b.dataset.service)));
                $id('btnToggleAdd').addEventListener('click', () => this.toggleAdd());
                $id('btnRefreshSizes').addEventListener('click', () => this.refreshSizes());
                $id('btnDbClose').addEventListener('click', () => this.setDbModal(false));
                $id('dbModal').addEventListener('click', (e) => { if (e.target === $id('dbModal')) this.setDbModal(false); });

                // Filter row
                const filterInput = $id('filterInput');
                filterInput.addEventListener('input', () => {
                    this.filter = filterInput.value;
                    this.bulkArmed = false;
                    this.render();
                });
                filterInput.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') {
                        e.preventDefault();
                        e.stopPropagation();
                        this.filter = '';
                        filterInput.value = '';
                        this.bulkArmed = false;
                        filterInput.blur();
                        this.render();
                    }
                });
                $id('typeChipClear').addEventListener('click', () => { this.setTypeFilter(null); filterInput.focus(); });
                $id('btnFilterClear').addEventListener('click', () => { this.clearAllFilters(); filterInput.focus(); });
                $id('btnBulkDelete').addEventListener('click', () => this.bulkDelete());
                $id('btnBulkDeleteCancel').addEventListener('click', () => this.closeBulkConfirm());
                $id('btnBulkDeleteConfirm').addEventListener('click', () => this.confirmBulkDelete());
                $id('bulkDeleteModal').addEventListener('click', (e) => { if (e.target === e.currentTarget) this.closeBulkConfirm(); });
                $id('bulkDeleteInput').addEventListener('input', () => this.renderBulkConfirm());
                $id('bulkDeleteInput').addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); this.confirmBulkDelete(); } if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); this.closeBulkConfirm(); } });

                // Add-site form
                const nameInput = $id('newSiteName');
                nameInput.addEventListener('input', () => {
                    const clean = nameInput.value.toLowerCase().replace(/[^a-z0-9-]/g, '');
                    if (clean !== nameInput.value) nameInput.value = clean;
                    this.newSite.name = clean;
                    this.render();
                });
                $id('newSitePlain').addEventListener('change', (e) => {
                    this.newSite.isPlain = e.target.checked;
                    this.render();
                });
                $id('wpVersionSelect').addEventListener('change', (e) => { this.newSite.wpVersion = e.target.value; });
                $id('addForm').addEventListener('submit', (e) => { e.preventDefault(); this.addSite(); });
                const drop = $id('addDrop');
                const dropInput = $id('addDropInput');
                drop.addEventListener('click', (e) => { if (e.target.closest('#addDropClear')) return; dropInput.click(); });
                dropInput.addEventListener('change', (e) => { const f = e.target.files && e.target.files[0]; e.target.value = ''; if (f) this.setImportFile(f); });
                $id('addDropClear').addEventListener('click', (e) => { e.stopPropagation(); this.setImportFile(null); });
                const row = $id('addRow');
                let dragDepth = 0;
                row.addEventListener('dragenter', (e) => { if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes('Files')) return; e.preventDefault(); dragDepth++; drop.classList.add('is-over'); });
                row.addEventListener('dragover', (e) => { if (!drop.classList.contains('is-over')) return; e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; });
                row.addEventListener('dragleave', () => { if (!drop.classList.contains('is-over')) return; dragDepth = Math.max(0, dragDepth - 1); if (!dragDepth) drop.classList.remove('is-over'); });
                row.addEventListener('drop', (e) => { if (!drop.classList.contains('is-over')) return; e.preventDefault(); dragDepth = 0; drop.classList.remove('is-over'); const f = e.dataTransfer.files && e.dataTransfer.files[0]; if (f) this.setImportFile(f); });

                // Sort headers
                document.querySelectorAll('.site-head-btn[data-sort]').forEach(btn => {
                    btn.addEventListener('click', () => this.setSort(btn.dataset.sort));
                });

                // Site rows: one delegated listener instead of per-row handlers.
                // The ↗ icon is the only thing that opens the site; the type
                // pill filters and the login button logs in; a click anywhere
                // else on the row opens the site's page (right-click: the menu).
                const list = $id('siteList');
                list.addEventListener('click', (e) => {
                    const row = e.target.closest('.site-row');
                    if (!row) return;
                    const site = this.sites.find(s => s.name === row.dataset.name);
                    if (!site) return;
                    if (e.target.closest('.site-open-link')) return; // plain link — let it navigate
                    if (e.target.closest('.site-type')) { this.setTypeFilter(site.type); return; }
                    if (e.target.closest('.site-login-btn')) { this.getLoginLink(site.name); return; }
                    // Don't open the page when the click ends a drag-to-select —
                    // users still grab the domain/size text to copy it.
                    if (window.getSelection && window.getSelection().toString()) return;
                    this.openSitePage(site.name);
                });
                list.addEventListener('contextmenu', (e) => {
                    const row = e.target.closest('.site-row');
                    if (!row) return;
                    const site = this.sites.find(s => s.name === row.dataset.name);
                    if (!site) return;
                    e.preventDefault();
                    this.openRowMenu(site, e);
                });

                // New-site alerts (delegated)
                $id('alerts').addEventListener('click', (e) => {
                    const box = e.target.closest('.new-site-alert');
                    if (!box) return;
                    const alert = this.alerts.find(a => String(a.id) === box.dataset.id);
                    if (!alert) return;
                    if (e.target.closest('.alert-login')) { this.loginToNewSite(alert); return; }
                    if (e.target.closest('.alert-open')) { this.dismissAlert(alert.id); return; } // link navigates itself
                    if (e.target.closest('.new-site-alert-close')) this.dismissAlert(alert.id);
                });

                // Context menu items act on whichever site the menu was opened for.
                const withCtxSite = (fn) => () => {
                    const site = this.ctxMenu.site;
                    this.closeRowMenu();
                    if (site) fn(site);
                };
                $id('ctxManage').addEventListener('click', withCtxSite(s => this.openSitePage(s.name)));
                $id('ctxOpen').addEventListener('click', withCtxSite(s => this.openSite(s)));
                $id('ctxLogin').addEventListener('click', withCtxSite(s => this.getLoginLink(s.name)));
                $id('ctxRename').addEventListener('click', withCtxSite(s => this.promptRename(s)));
                $id('ctxReveal').addEventListener('click', withCtxSite(s => this.revealSite(s.name)));
                $id('ctxDb').addEventListener('click', withCtxSite(s => this.openDbForSite(s)));
                $id('ctxPhp').addEventListener('click', withCtxSite(s => this.openPhpModal(s)));
                $id('ctxLog').addEventListener('click', withCtxSite(s => this.openLogsForSite(s.name)));
                $id('ctxMail').addEventListener('click', withCtxSite(s => this.openMailForSite(s.name)));
                $id('ctxFiles').addEventListener('click', withCtxSite(s => this.openFilesForSite(s.name)));

                // PHP version picker
                $id('btnPhpClose').addEventListener('click', () => this.closePhpModal());
                $id('phpModal').addEventListener('click', (e) => { if (e.target === $id('phpModal')) this.closePhpModal(); });
                $id('phpOptions').addEventListener('click', (e) => {
                    const btn = e.target.closest('.php-option');
                    if (btn && !btn.disabled) this.choosePhp(btn.dataset.version);
                });
                $id('ctxCopy').addEventListener('click', withCtxSite(s => this.copyPath(s.full_path)));

                // Domains (cove mappings)
                $id('ctxDomains').addEventListener('click', withCtxSite(s => this.openDomainsModal(s)));
                $id('btnDomainsClose').addEventListener('click', () => this.closeDomainsModal());
                $id('domainsModal').addEventListener('click', (e) => { if (e.target === $id('domainsModal')) this.closeDomainsModal(); });
                $id('domainsForm').addEventListener('submit', (e) => { e.preventDefault(); this.addDomain($id('domainsInput').value); });
                $id('domainsList').addEventListener('click', (e) => {
                    const btn = e.target.closest('.dom-remove');
                    if (btn && !btn.disabled) this.removeDomain(btn.dataset.domain);
                });
                $id('domainsHint').addEventListener('click', (e) => {
                    const a = e.target.closest('a[data-domain]');
                    if (a) { e.preventDefault(); this.addDomain(a.dataset.domain); }
                });
                $id('ctxPin').addEventListener('click', withCtxSite(s => this.togglePin(s.name)));
                $id('ctxDelete').addEventListener('click', withCtxSite(s => this.deleteSite(s.name)));

                // Command palette
                const paletteInput = $id('paletteInput');
                paletteInput.addEventListener('input', () => {
                    this.palette.query = paletteInput.value;
                    this.palette.index = 0;
                    this.renderPalette();
                });
                paletteInput.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown') { e.preventDefault(); this.paletteMove(1); }
                    else if (e.key === 'ArrowUp') { e.preventDefault(); this.paletteMove(-1); }
                    else if (e.key === 'Enter') { e.preventDefault(); this.paletteRun(e); }
                    else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); this.closePalette(); }
                });
                $id('paletteBackdrop').addEventListener('click', (e) => { if (e.target === $id('paletteBackdrop')) this.closePalette(); });
                const paletteList = $id('paletteList');
                paletteList.addEventListener('click', (e) => {
                    const li = e.target.closest('.palette-item');
                    if (li) this.paletteRunItem(this._paletteItems[Number(li.dataset.index)]);
                });
                paletteList.addEventListener('mouseover', (e) => {
                    const li = e.target.closest('.palette-item');
                    if (!li || Number(li.dataset.index) === this.palette.index) return;
                    this.palette.index = Number(li.dataset.index);
                    // Just move the highlight — a full re-render mid-hover would
                    // reset scroll position in the list.
                    paletteList.querySelectorAll('.palette-item').forEach(n =>
                        n.classList.toggle('active', Number(n.dataset.index) === this.palette.index));
                });

                // Rename modal
                const renameInput = $id('renameInput');
                renameInput.addEventListener('input', () => {
                    this.rename.value = renameInput.value;
                    this.renderRename();
                });
                renameInput.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); this.closeRename(); }
                });
                $id('renameForm').addEventListener('submit', (e) => { e.preventDefault(); this.submitRename(); });
                $id('btnRenameCancel').addEventListener('click', () => this.closeRename());
                $id('renameModal').addEventListener('click', (e) => { if (e.target === $id('renameModal')) this.closeRename(); });

                // Log modal
                $id('btnLogRaw').addEventListener('click', () => { this.logView.raw = !this.logView.raw; this.renderLog(); });
                $id('btnLogRefresh').addEventListener('click', () => this.viewLog({ name: this.logView.site }, true));
                $id('btnLogClose').addEventListener('click', () => this.closeLog());
                $id('logModal').addEventListener('click', (e) => { if (e.target === $id('logModal')) this.closeLog(); });

                // Snackbar action (undo etc.)
                $id('snackAction').addEventListener('click', () => { if (this.snackbar.action) this.snackbar.action(); });
            },

            // --- Rendering -------------------------------------------------
            // Everything below reads state and writes DOM. Cheap enough to run
            // wholesale after any state change: a few hundred rows rebuild in
            // low single-digit milliseconds.
            render() {
                this.renderChrome();
                this.renderAlerts();
                this.renderList();
                this.renderFooter();
                this.renderCtxMenu();
                this.renderModals();
                this.renderView();
                // Site chips in the database list and overview come from the
                // sites list, which usually lands after the first db render.
                if (this.view === 'db') { this.renderDbList(); if (this.db.name && !this.db.table && !this.db.sql) this.renderDbOverview(); }
                if (this.view === 'files') this.renderFilesSide();
                if (this.view === 'site') { this.renderSitePage(); this.loadSiteTab(); }
                if (this.palette.open) this.renderPalette();
            },

            renderChrome() {
                $id('btnToggleAdd').textContent = this.adding ? 'cancel' : '+ add site';

                // Filter row
                const chip = $id('typeChip');
                show(chip, !!this.typeFilter);
                if (this.typeFilter) $id('typeChipLabel').textContent = this.typeFilterLabel;
                const bulk = $id('btnBulkDelete');
                const visible = this.filteredSites.length;
                show(bulk, (this.filter || this.typeFilter) && visible > 0 && visible < this.sites.length);
                bulk.textContent = 'delete ' + visible + ' shown…';
                show($id('filterKbd'), !this.filter && !this.typeFilter);
                show($id('btnFilterClear'), this.filter || this.typeFilter);

                // Add row
                const addRow = $id('addRow');
                show(addRow, this.adding);
                addRow.classList.toggle('is-creating', this.newSite.isLoading);
                $id('newSiteName').disabled = this.newSite.isLoading;
                $id('newSitePlain').disabled = this.newSite.isLoading;
                const sel = $id('wpVersionSelect');
                show(sel, !this.newSite.isPlain);
                sel.disabled = this.newSite.isLoading || this.newSite.isPlain;
                $id('btnCreate').disabled = !this.newSite.name || this.newSite.isLoading;
                show($id('createSpinner'), this.newSite.isLoading);
                $id('createLabel').textContent = this.newSite.isLoading ? 'creating…' : (this.importFile ? 'create & import' : 'create');
                this.renderImportProgress();

                // Theme button tooltip tracks the mode it would switch to.
                $id('btnTheme').title = 'Theme: ' + ({ system: 'System', light: 'Light', dark: 'Dark' })[this.themePref] + ' (click to switch light and dark, right-click for options)';
            },

            renderAlerts() {
                const wrap = $id('alerts');
                wrap.querySelectorAll('.new-site-alert').forEach(n => n.remove());
                const tpl = $id('tpl-alert');
                for (const alert of this.alerts) {
                    const node = tpl.content.firstElementChild.cloneNode(true);
                    node.dataset.id = String(alert.id);
                    node.querySelector('strong').textContent = alert.name + '.localhost';
                    const login = node.querySelector('.alert-login');
                    const open = node.querySelector('.alert-open');
                    if (alert.isPlain) {
                        login.remove();
                        open.href = 'https://' + alert.name + '.localhost' + PORT_SUFFIX;
                    } else {
                        open.remove();
                        login.disabled = alert.isLoggingIn;
                        login.textContent = alert.isLoggingIn ? 'opening…' : 'log in to admin';
                    }
                    wrap.appendChild(node);
                }
            },

            renderList() {
                const list = $id('siteList');
                const rows = this.filteredSites;
                list.querySelectorAll('.site-row').forEach(n => n.remove());

                show($id('siteHead'), !this.isLoading && rows.length > 0);
                document.querySelectorAll('.site-head-btn[data-sort]').forEach(btn => {
                    btn.classList.toggle('active', this.sort === btn.dataset.sort);
                    btn.querySelector('.sort-arrow').textContent =
                        this.sort === btn.dataset.sort ? (this.sortDir === 'asc' ? '↑' : '↓') : '';
                });

                show($id('siteLoading'), this.isLoading);
                show($id('emptyNone'), !this.isLoading && this.sites.length === 0);
                const emptyFilter = !this.isLoading && this.sites.length > 0 && rows.length === 0;
                show($id('emptyFilter'), emptyFilter);
                if (emptyFilter) $id('emptyFilterQuery').textContent = this.filter || this.typeFilterLabel;

                const tpl = $id('tpl-site-row');
                const anchor = $id('siteLoading'); // rows insert before the loading li to keep list order
                for (const site of rows) {
                    const row = tpl.content.firstElementChild.cloneNode(true);
                    row.dataset.name = site.name;
                    row.classList.toggle('is-selected', this.selectedName === site.name);
                    row.classList.toggle('has-menu', this.ctxMenu.open && this.ctxMenu.site && this.ctxMenu.site.name === site.name);
                    row.classList.toggle('is-pinned', this.isPinned(site.name));

                    row.querySelector('.site-domain').innerHTML = this.highlightedDomain(site.domain, this.filter);
                    const openLink = row.querySelector('.site-open-link');
                    openLink.href = site.domain;
                    openLink.title = 'Open ' + site.domain.replace('https://', '');

                    const isWp = site.type === 'WordPress';
                    const type = row.querySelector('.site-type');
                    type.classList.add(isWp ? 'wp' : 'static');
                    type.textContent = isWp ? 'WP' : 'STATIC';
                    type.title = 'Filter to ' + (isWp ? 'WordPress' : 'static') + ' sites';

                    const ver = row.querySelector('.site-wp-version');
                    if (site.wp_version) {
                        ver.textContent = site.wp_version;
                        if (site.wp_status) ver.classList.add(site.wp_status);
                        ver.title = site.wp_status === 'insecure'
                            ? 'WordPress ' + site.wp_version + ' — wp.org marks this release insecure. Update with: cove core update ' + site.name
                            : 'WordPress ' + site.wp_version;
                    } else {
                        ver.remove();
                    }

                    const php = row.querySelector('.site-php-version');
                    const applying = this.phpApplying[site.name];
                    if (applying) {
                        php.classList.add('applying');
                        php.textContent = applying === 'default' ? 'php default…' : 'php ' + applying + '…';
                        php.title = 'Switching PHP version…';
                    } else if (site.php_version) {
                        php.textContent = 'php ' + site.php_version;
                        php.title = 'Pinned to PHP ' + site.php_version + ' (native php-fpm). Change via the row menu.';
                    } else {
                        php.remove();
                    }

                    const mod = row.querySelector('.site-modified');
                    mod.textContent = this.formatRelative(site.modified_at);
                    mod.title = site.modified_at ? new Date(site.modified_at * 1000).toLocaleString() : '';
                    row.querySelector('.site-size').textContent = this.formatSize(site.size_bytes);

                    const login = row.querySelector('.site-login-btn');
                    if (isWp) {
                        login.classList.toggle('loading', !!site.isLoggingIn);
                        login.disabled = !!site.isLoggingIn;
                        login.title = 'One-time admin login for ' + site.name;
                    } else {
                        login.remove();
                    }
                    list.insertBefore(row, anchor);
                }
            },

            renderFooter() {
                $id('siteCount').textContent = this.siteCountLabel;
                const totalEl = $id('totalSize');
                show(totalEl, this.totalBytes > 0);
                totalEl.textContent = '· ' + this.formatSize(this.totalBytes);
                $id('btnRefreshSizes').classList.toggle('spinning', this.isRefreshingSizes);
                $id('btnRefreshSizes').disabled = this.isRefreshingSizes;
                $id('btnRefreshSizes').title = this.isRefreshingSizes ? 'Refreshing…' : 'Refresh disk sizes';
            },

            renderCtxMenu() {
                const menu = $id('ctxMenu');
                show(menu, this.ctxMenu.open);
                const site = this.ctxMenu.site;
                if (!this.ctxMenu.open || !site) return;
                menu.style.left = this.ctxMenu.x + 'px';
                menu.style.top = this.ctxMenu.y + 'px';
                $id('ctxTitle').textContent = site.domain.replace('https://', '');
                const isWp = site.type === 'WordPress';
                show($id('ctxLogin'), isWp);
                show($id('ctxDb'), isWp);
                $id('ctxReveal').querySelector('span').textContent = this.revealLabel;
                $id('ctxPin').querySelector('span').textContent = this.isPinned(site.name) ? 'Unpin from top' : 'Pin to top';
                // Effective PHP as the item's meta; hide the item entirely on
                // platforms where per-site pins aren't supported.
                show($id('ctxPhp'), !this.phpInfo || this.phpInfo.supported !== false);
                const effPhp = site.php_version || (this.phpInfo && this.phpInfo.default) || '';
                $id('ctxPhpMeta').textContent = effPhp ? 'php ' + effPhp : '';
                // Extra addresses beyond <site>.localhost: explicit mappings
                // plus the wildcard a subdomain multisite gets for free.
                const extraDomains = (site.mappings || []).length + (site.multisite === 'subdomain' ? 1 : 0);
                $id('ctxDomainsMeta').textContent = extraDomains ? '+' + extraDomains : '';
            },

            renderPhpModal() {
                show($id('phpModal'), this.phpModal.open);
                if (!this.phpModal.open) return;
                const site = this.phpModal.site;
                $id('phpModalSite').textContent = site.name + '.localhost';
                const wrap = $id('phpOptions');
                wrap.textContent = '';
                const info = this.phpInfo;
                if (!info) {
                    const loading = document.createElement('div');
                    loading.className = 'modal-hint';
                    loading.textContent = 'Loading…';
                    wrap.appendChild(loading);
                    return;
                }
                // The pin may have changed since the menu opened — read the
                // live site entry rather than the captured one.
                const live = this.sites.find(s => s.name === site.name) || site;
                const pin = live.php_version || null;
                const tpl = $id('tpl-php-option');
                const options = [{
                    version: 'default',
                    label: 'default — PHP ' + info.default,
                    meta: pin ? 'FrankenPHP' : 'current · FrankenPHP',
                    installed: true,
                    current: !pin,
                }];
                for (const v of info.versions) {
                    options.push({
                        version: v.version,
                        label: 'PHP ' + v.version,
                        meta: pin === v.version ? 'current · php-fpm'
                            : (v.installed ? 'installed' : 'not installed — click to install'),
                        installed: v.installed,
                        current: pin === v.version,
                    });
                }
                const applying = this.phpApplying[site.name];
                for (const o of options) {
                    const btn = tpl.content.firstElementChild.cloneNode(true);
                    btn.dataset.version = o.version;
                    btn.classList.toggle('current', o.current);
                    btn.classList.toggle('uninstalled', !o.installed);
                    btn.disabled = !!applying || o.current;
                    btn.querySelector('.php-option-name').textContent = o.label;
                    btn.querySelector('.php-option-meta').textContent = o.meta;
                    wrap.appendChild(btn);
                }
                // Only populated when the modal is reopened while a change is
                // still in flight — the normal path closes the modal instantly
                // and shows progress on the row chip instead.
                $id('phpModalHint').textContent = applying
                    ? 'Switching to ' + (applying === 'default' ? 'the default PHP' : 'PHP ' + applying) + '…'
                    : '';
            },

            renderModals() {
                show($id('dbModal'), this.showDbModal);
                show($id('renameModal'), this.rename.open);
                this.renderRename();
                show($id('logModal'), this.logView.open);
                this.renderLog();
                this.renderPhpModal();
                this.renderDomainsModal();
            },

            renderRename() {
                if (!this.rename.open) return;
                $id('renameInput').disabled = this.rename.busy;
                $id('renameHint').textContent = this.rename.value ? this.rename.value + '.localhost' : ' ';
                $id('btnRenameCancel').disabled = this.rename.busy;
                const submit = $id('btnRenameSubmit');
                submit.disabled = this.rename.busy || !this.rename.value;
                submit.textContent = this.rename.busy ? 'renaming…' : 'rename';
            },

            renderLog() {
                if (!this.logView.open) return;
                $id('logTitle').textContent = this.logView.site;
                show($id('logTruncated'), this.logView.truncated);
                $id('logPane').textContent = this.logDisplay;
                $id('btnLogRaw').textContent = this.logView.raw ? 'formatted' : 'raw';
                $id('btnLogRefresh').disabled = this.logView.busy;
            },

            renderPalette() {
                const backdrop = $id('paletteBackdrop');
                show(backdrop, this.palette.open);
                if (!this.palette.open) return;
                const items = this.paletteResults;
                this._paletteItems = items;
                const list = $id('paletteList');
                list.innerHTML = '';
                const tpl = $id('tpl-palette-item');
                items.forEach((item, i) => {
                    const li = tpl.content.firstElementChild.cloneNode(true);
                    li.dataset.index = String(i);
                    li.classList.toggle('active', i === this.palette.index);
                    li.querySelector('.pi-kind').textContent = item.kind;
                    li.querySelector('.pi-name').textContent = item.label;
                    li.querySelector('.pi-meta').textContent = item.meta;
                    list.appendChild(li);
                });
                if (!items.length) {
                    const empty = document.createElement('li');
                    empty.className = 'palette-empty';
                    empty.textContent = 'No matches.';
                    list.appendChild(empty);
                }
            },

            renderSnackbar() {
                const bar = $id('snackbar');
                show(bar, this.snackbar.visible);
                bar.classList.toggle('error', this.snackbar.isError);
                $id('snackMsg').textContent = this.snackbar.message;
                const action = $id('snackAction');
                show(action, !!this.snackbar.action);
                action.textContent = this.snackbar.actionLabel;
            },

            // --- Behavior --------------------------------------------------
            osTheme() {
                return (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches) ? 'light' : 'dark';
            },

            applyTheme() {
                this.theme = this.themePref === 'system' ? this.osTheme() : this.themePref;
                document.documentElement.dataset.theme = this.theme;
                document.documentElement.dataset.themePref = this.themePref;
                const menu = $id('themeMenu');
                if (menu) menu.querySelectorAll('[data-theme-pref]').forEach(b => b.setAttribute('aria-checked', String(b.dataset.themePref === this.themePref)));
            },

            setThemePref(pref) {
                this.themePref = (pref === 'light' || pref === 'dark') ? pref : 'system';
                localStorage.setItem('theme', this.themePref);
                this.applyTheme();
                this.renderChrome();
            },

            // Click flips light and dark (from System, flip whatever the OS shows
            // and lock it). Right-click opens the System / Light / Dark menu.
            toggleTheme() {
                this.setThemePref(this.theme === 'light' ? 'dark' : 'light');
            },

            openThemeMenu() {
                const m = $id('themeMenu');
                if (!m) return;
                m.style.display = '';
                this.themeMenuOpen = true;
                // Open to the right of the toggle when the viewport has the
                // room, otherwise hang from its right edge as before.
                const btn = $id('btnTheme').getBoundingClientRect();
                const base = (m.offsetParent || document.body).getBoundingClientRect();
                const fits = btn.left + m.offsetWidth <= window.innerWidth - 12;
                m.style.right = 'auto';
                m.style.left = Math.round((fits ? btn.left : btn.right - m.offsetWidth) - base.left) + 'px';
            },
            closeThemeMenu() { const m = $id('themeMenu'); if (m) { m.style.display = 'none'; this.themeMenuOpen = false; } },

            toggleAdd() {
                if (this.importing) return;
                this.adding = !this.adding;
                if (!this.adding && this.importFile) this.setImportFile(null);
                this.render();
                if (this.adding) {
                    this.loadWpVersions();
                    $id('newSiteName').focus();
                }
            },

            // Fetched once per page load, and cached server-side for a day.
            // Deliberately silent on failure: an offline machine should
            // still be able to create a site, it just won't be offered a
            // pinned version alongside 'latest' and 'nightly'.
            async loadWpVersions() {
                if (this.wpVersionsLoaded) return;
                this.wpVersionsLoaded = true;
                try {
                    const res = await fetch('/api.php?action=wp_versions');
                    const data = await res.json();
                    if (Array.isArray(data)) {
                        this.wpVersions = data;
                        // 'latest' and 'nightly' are hard-coded first options;
                        // real versions append after them.
                        const sel = $id('wpVersionSelect');
                        for (const v of data) {
                            const opt = document.createElement('option');
                            opt.value = v.version;
                            opt.textContent = v.version + (v.status === 'insecure' ? ' — insecure' : '');
                            sel.appendChild(opt);
                        }
                    }
                } catch (e) { /* offline — 'latest' still works */ }
            },

            formatSize(bytes) {
                if (bytes === null || bytes === undefined) return '—';
                if (bytes === 0) return '0 B';
                const units = ['B', 'KB', 'MB', 'GB', 'TB'];
                const i = Math.min(units.length - 1, Math.floor(Math.log(bytes) / Math.log(1024)));
                const v = bytes / Math.pow(1024, i);
                return (v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)) + ' ' + units[i];
            },

            formatRelative(ts) {
                if (!ts) return '—';
                const s = Math.max(0, Date.now() / 1000 - ts);
                if (s < 60) return 'now';
                if (s < 3600) return Math.floor(s / 60) + 'm';
                if (s < 86400) return Math.floor(s / 3600) + 'h';
                if (s < 86400 * 30) return Math.floor(s / 86400) + 'd';
                if (s < 86400 * 365) return Math.floor(s / 86400 / 30) + 'mo';
                return Math.floor(s / 86400 / 365) + 'y';
            },

            escapeHtml(s) {
                return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
            },

            // Wrap every case-insensitive occurrence of `query` in <mark> while
            // escaping every other substring. Safe for innerHTML use because the
            // inner text comes from the trusted domain, not from query (query
            // only controls WHERE to split).
            highlightMatch(text, query) {
                const q = (query || '').trim();
                if (!q) return this.escapeHtml(text);
                const lower = text.toLowerCase();
                const lowerQ = q.toLowerCase();
                let out = '';
                let i = 0;
                while (i < text.length) {
                    const idx = lower.indexOf(lowerQ, i);
                    if (idx === -1) { out += this.escapeHtml(text.slice(i)); break; }
                    out += this.escapeHtml(text.slice(i, idx));
                    out += '<mark>' + this.escapeHtml(text.slice(idx, idx + q.length)) + '</mark>';
                    i = idx + q.length;
                }
                return out;
            },

            // Wrap the site name in <span class="host-accent"> so it reads
            // teal while the .localhost suffix stays dim — matches the
            // landing-page dashboard mock. Split at the first dot; if
            // there's none, the whole string is treated as the name.
            highlightedDomain(domain, query) {
                const stripped = String(domain).replace(/^https?:\/\//, '');
                const dotIdx = stripped.indexOf('.');
                if (dotIdx === -1) return '<span class="host-accent">' + this.highlightMatch(stripped, query) + '</span>';
                const name = stripped.slice(0, dotIdx);
                const suffix = stripped.slice(dotIdx);
                return '<span class="host-accent">' + this.highlightMatch(name, query) + '</span>' + this.highlightMatch(suffix, query);
            },

            // --- Mail ------------------------------------------------------
            // A Cove-native inbox over Mailpit's REST API, proxied same-origin
            // at /mail-api/ by the Caddyfile. Mailpit's own UI stays one click
            // away for what it does better (spam scoring, HTML checks, relay,
            // raw source); what it cannot do is filter by site — every Cove
            // site receives mail at its own <site>.localhost, so the To
            // address is the site.
            mailApi(path, opts = {}) {
                const { method = 'GET', body, timeoutMs = 10000 } = opts;
                const ctrl = new AbortController();
                const timer = setTimeout(() => ctrl.abort(), timeoutMs);
                return fetch('/mail-api' + path, {
                    method,
                    headers: body ? { 'Content-Type': 'application/json' } : {},
                    body: body ? JSON.stringify(body) : undefined,
                    signal: ctrl.signal,
                }).then(async (r) => {
                    if (!r.ok) throw new Error('mailpit ' + r.status);
                    const ct = r.headers.get('content-type') || '';
                    return ct.includes('json') ? r.json() : r.text();
                }).finally(() => clearTimeout(timer));
            },

            setView(view, opts = {}) {
                view = ['mail', 'db', 'logs', 'files', 'site'].includes(view) ? view : 'sites';
                if (view === this.view && !opts.force) return;
                const prev = this.view;
                this.view = view;
                this.closeRowMenu();
                if (this.closeTabCtx) this.closeTabCtx();
                if (prev !== view) this.crossfadeFrom(prev);
                document.body.classList.toggle('view-mail', view === 'mail');
                document.body.classList.toggle('view-db', view === 'db');
                document.body.classList.toggle('view-logs', view === 'logs');
                document.body.classList.toggle('view-files', view === 'files');
                document.body.classList.toggle('view-site', view === 'site');
                document.title = view === 'site' ? 'Cove — ' + (this.sitePage.name || 'site') : { mail: 'Cove — mail', db: 'Cove — databases', logs: 'Cove — logs', files: 'Cove — files', sites: 'Cove — sites' }[view];
                this.syncUrl();
                this.render();
                if (view === 'mail') {
                    this.loadMail();
                    this.loadMailInfo();
                    if (!this.mail.selectedId) $id('mailSearch').focus();
                }
                if (view === 'db') {
                    if (!this.db.loaded) this.loadDbList();
                    if (this.db.name && this.db.tablesFor !== this.db.name) this.loadDbTables();
                    if (this.db.name && this.db.table) this.loadDbRows();
                }
                if (view === 'logs') {
                    // Chrome and sidebar reflect the (possibly new) site right
                    // away; sizes and last-activity times are refreshed each
                    // visit, since they are cheap and change constantly.
                    this.renderLogs();
                    this.loadLogSources();
                    this.loadLogs();
                    this.startLogsPolling();
                } else {
                    this.stopLogsPolling();
                }
                if (view === 'site') {
                    this.renderSitePage();
                    this.loadSiteNetwork();
                    this.loadSiteTab();
                }
                if (view === 'files') {
                    // A URL names a path that may be a folder or a file; the
                    // server settles it. Otherwise the listing is refreshed
                    // on every visit, since it is cheap and files change
                    // under the dashboard all the time.
                    const f = this.files;
                    this.renderFiles();
                    if (f.site) {
                        if (f.target !== null) { const t = f.target; f.target = null; this.filesNavigate(t, t === '' ? 'dir' : null); }
                        else { this.loadFilesDir(); if (f.file && !f.dirty) this.loadFile(); }
                    }
                }
            },

            // The URL is a real path naming the view and what is open in
            // it, pushed with history.pushState so Back and Forward walk the
            // views: /, /mail, /mail/<site>, /db, /db/<database>[/<table>],
            // /logs, /logs/@<source>, /logs/<site>/<tab>. The old #hash form
            // is still understood on load and rewritten.
            get viewPath() {
                if (this.view === 'mail') return '/mail' + (this.mail.site ? '/' + this.mail.site : '');
                if (this.view === 'db') return '/db' + (this.db.name ? '/' + encodeURIComponent(this.db.name) + (this.db.table ? '/' + encodeURIComponent(this.db.table) : '') : '');
                if (this.view === 'site') return '/site/' + (this.sitePage.name || '') + (this.sitePage.tab && this.sitePage.tab !== 'overview' ? '/' + this.sitePage.tab : '');
                if (this.view === 'files') return '/files' + (this.files.site ? '/' + this.files.site + this.filesEncode(this.files.file ? this.files.file.path : this.files.path) : '');
                if (this.view === 'logs') return '/logs' + (this.logs.site ? '/' + this.logs.site + (this.logs.tab ? '/' + this.logs.tab : '') : (this.logs.source !== 'errors' ? '/@' + this.logs.source : ''));
                return '/';
            },

            syncUrl(opts = {}) {
                const path = this.viewPath;
                if (location.pathname === path && !location.hash) return;
                const url = path + location.search;
                if (opts.replace) history.replaceState({ cove: true }, '', url);
                else history.pushState({ cove: true }, '', url);
            },

            readViewFromUrl() {
                let p = location.pathname.replace(/\/+$/, '') || '/';
                // Legacy #mail / #db / #logs links: same grammar, hash-prefixed.
                if (p === '/' && /^#(mail|db|logs|files)(\/|$)/i.test(location.hash || '')) {
                    p = '/' + location.hash.slice(1);
                    history.replaceState({ cove: true }, '', p + location.search);
                }
                let m;
                if ((m = /^\/mail(?:\/([a-z0-9-]+))?$/i.exec(p))) {
                    this.mail.site = m[1] ? m[1].toLowerCase() : null;
                    this.setView('mail', { force: true });
                } else if ((m = /^\/db(?:\/([^\/]+)(?:\/([^\/]+))?)?$/.exec(p))) {
                    const name = m[1] ? decodeURIComponent(m[1]) : null;
                    const table = m[2] ? decodeURIComponent(m[2]) : null;
                    if (name !== this.db.name) { this.db.tables = []; this.db.wp = null; this.db.tablesFor = null; }
                    if (table !== this.db.table) this.resetDbTable();
                    this.db.name = name;
                    this.db.table = table;
                    this.setView('db', { force: true });
                } else if ((m = /^\/logs(?:\/(?:@([a-z0-9.-]+)|([a-z0-9-]+)(?:\/(errors|debug|access))?))?$/i.exec(p))) {
                    if (m[1]) { this.logs.site = null; this.logs.source = m[1].toLowerCase(); }
                    else if (m[2]) { this.logs.site = m[2].toLowerCase(); this.logs.tab = m[3] ? m[3].toLowerCase() : null; }
                    else { this.logs.site = null; this.logs.source = 'errors'; }
                    this.setView('logs', { force: true });
                } else if ((m = /^\/site\/([a-z0-9-]+)(?:\/(plugins|themes|users|cron|traffic|history|snapshots|cli))?$/i.exec(p))) {
                    this.sitePage.name = m[1].toLowerCase();
                    this.sitePage.tab = m[2] ? m[2].toLowerCase() : 'overview';
                    this.setView('site', { force: true });
                } else if ((m = /^\/files(?:\/([a-z0-9-]+)(?:\/(.+))?)?$/i.exec(p))) {
                    const site = m[1] ? m[1].toLowerCase() : null;
                    const dec = (s) => { try { return decodeURIComponent(s); } catch (e) { return s; } };
                    const target = m[2] ? m[2].split('/').map(dec).filter(s => s !== '' && s !== '.' && s !== '..').join('/') : '';
                    if (site !== this.files.site) { this.files.entries = []; this.files.loadedFor = null; this.files.file = null; this.files.path = ''; }
                    this.files.site = site;
                    this.files.target = site ? target : null;
                    this.setView('files', { force: true });
                } else {
                    // Unknown path (or /): the sites list, and the address bar
                    // brought back to a real one.
                    this.setView('sites', { force: true });
                    if (p !== '/') history.replaceState({ cove: true }, '', '/' + location.search);
                }
            },

            // From a site's row menu: the inbox scoped to that site.
            openMailForSite(name) {
                this.mail.site = name;
                this.mail.query = '';
                this.mail.start = 0;
                $id('mailSearch').value = '';
                this.setView('mail', { force: true });
            },

            setMailSite(site) {
                this.mail.site = site || null;
                this.mail.start = 0;
                this.syncUrl();
                this.loadMail();
            },

            mailClearFilters() {
                this.mail.query = '';
                $id('mailSearch').value = '';
                this.mail.unreadOnly = false;
                $id('mailUnreadOnly').checked = false;
                this.setMailSite(null);
            },

            get mailQuery() {
                const parts = [];
                if (this.mail.site) parts.push('to:@' + this.mail.site + '.localhost');
                if (this.mail.unreadOnly) parts.push('is:unread');
                if (this.mail.query.trim()) parts.push(this.mail.query.trim());
                return parts.join(' ');
            },

            async loadMail(opts = {}) {
                const m = this.mail;
                if (!opts.keepStart) m.start = 0;
                const seq = ++m.seq;
                // Only the first paint shows the loading row; refreshes keep the
                // rows in place so a search keystroke doesn't flash the list.
                m.loading = !m.loaded;
                const q = this.mailQuery;
                const qs = 'limit=' + m.limit + '&start=' + m.start;
                const path = q ? '/v1/search?query=' + encodeURIComponent(q) + '&' + qs : '/v1/messages?' + qs;
                this.renderMail();
                try {
                    const data = await this.mailApi(path);
                    if (seq !== m.seq) return; // superseded by a newer request
                    m.items = Array.isArray(data.messages) ? data.messages : [];
                    m.total = data.total || 0;
                    m.unread = data.unread || 0;
                    // messages_count is the filtered total on a search, the
                    // overall total on a plain listing.
                    m.matched = typeof data.messages_count === 'number' ? data.messages_count : m.total;
                    m.error = null;
                    // A new filter or search that no longer contains the open
                    // message closes the reader; a refresh or page turn keeps it.
                    if (!opts.keepStart && m.selectedId && !m.items.some(x => x.ID === m.selectedId)) {
                        m.selectedId = null; m.msg = null; m.renderedId = null;
                    }
                    // Paged past the end (e.g. after deletes): step back.
                    if (m.start > 0 && m.items.length === 0 && m.matched > 0) {
                        m.start = Math.max(0, Math.floor((m.matched - 1) / m.limit) * m.limit);
                        return this.loadMail({ keepStart: true });
                    }
                } catch (e) {
                    if (seq !== m.seq) return;
                    m.error = 'Mailpit is not answering.';
                }
                m.loaded = true;
                m.loading = false;
                this.renderMail();
                this.renderView();
            },

            mailPage(delta) {
                const m = this.mail;
                const next = m.start + delta * m.limit;
                if (next < 0 || next >= m.matched) return;
                m.start = next;
                this.loadMail({ keepStart: true });
                $id('mailList').scrollTop = 0;
            },

            async loadMailInfo() {
                try { this.mail.info = await this.mailApi('/v1/info', { timeoutMs: 4000 }); } catch (e) { this.mail.info = null; }
                this.renderMailFooter();
            },

            // Cheap: one row, but the envelope carries the global counts.
            async refreshMailCounts() {
                try {
                    const d = await this.mailApi('/v1/messages?limit=1', { timeoutMs: 4000 });
                    this.mail.total = d.total || 0;
                    this.mail.unread = d.unread || 0;
                } catch (e) { /* badge simply stays put */ }
                this.renderView();
                if (this.view === 'mail') this.renderMailFooter();
            },

            // Mailpit pushes {Type:'new'|'delete'|'update'|'prune'|'truncate', Data}
            // and {Type:'stats', Data:{Total, Unread}} over a websocket. It is
            // not a documented contract, so a poll takes over whenever the
            // socket is unavailable and the socket is retried in the background.
            connectMailEvents() {
                const m = this.mail;
                if (m.ws || !('WebSocket' in window)) { this.startMailPolling(); return; }
                let ws;
                try {
                    ws = new WebSocket((location.protocol === 'https:' ? 'wss://' : 'ws://') + location.host + '/mail-api/events');
                } catch (e) { this.startMailPolling(); return; }
                m.ws = ws;
                ws.onopen = () => this.stopMailPolling();
                ws.onmessage = (ev) => {
                    let evt;
                    try { evt = JSON.parse(ev.data); } catch (e) { return; }
                    if (evt.Type === 'stats' && evt.Data) {
                        m.total = evt.Data.Total || 0;
                        m.unread = evt.Data.Unread || 0;
                        this.renderView();
                        if (this.view === 'mail') this.renderMailFooter();
                        return;
                    }
                    if (this.view === 'mail') {
                        clearTimeout(m.syncTimer);
                        m.syncTimer = setTimeout(() => this.loadMail({ keepStart: true }), 300);
                    }
                };
                ws.onclose = () => {
                    m.ws = null;
                    this.startMailPolling();
                    clearTimeout(m.wsRetry);
                    m.wsRetry = setTimeout(() => this.connectMailEvents(), 15000);
                };
                ws.onerror = () => { try { ws.close(); } catch (e) {} };
            },

            startMailPolling() {
                if (this.mail.pollTimer) return;
                this.mail.pollTimer = setInterval(() => {
                    if (document.hidden) return;
                    if (this.view === 'mail') this.loadMail({ keepStart: true });
                    else this.refreshMailCounts();
                }, 15000);
            },

            stopMailPolling() {
                clearInterval(this.mail.pollTimer);
                this.mail.pollTimer = null;
            },

            async openMail(id) {
                const m = this.mail;
                if (!id) return;
                m.selectedId = id;
                m.msg = null; m.msgError = null; m.headers = null; m.msgLoading = true;
                this.renderMail();
                try {
                    const msg = await this.mailApi('/v1/message/' + encodeURIComponent(id));
                    if (m.selectedId !== id) return;
                    m.msg = msg;
                    m.part = msg.HTML ? 'html' : 'text';
                    // Fetching a message marks it read on Mailpit's side too.
                    const row = m.items.find(x => x.ID === id);
                    if (row && !row.Read) { row.Read = true; m.unread = Math.max(0, m.unread - 1); }
                } catch (e) {
                    if (m.selectedId !== id) return;
                    m.msgError = 'Could not load this message. It may have been deleted.';
                }
                m.msgLoading = false;
                this.renderMail();
                this.renderView();
            },

            closeMail() {
                this.mail.selectedId = null;
                this.mail.msg = null;
                this.mail.renderedId = null;
                this.renderMail();
            },

            mailMove(delta) {
                const m = this.mail;
                if (!m.items.length) return;
                let i = m.items.findIndex(x => x.ID === m.selectedId);
                i = i === -1 ? (delta > 0 ? 0 : m.items.length - 1) : Math.max(0, Math.min(m.items.length - 1, i + delta));
                this.openMail(m.items[i].ID);
                const row = $id('mailList').querySelector('.mail-row[data-id="' + CSS.escape(m.items[i].ID) + '"]');
                if (row && row.scrollIntoView) row.scrollIntoView({ block: 'nearest' });
            },

            // Returns true when the key was consumed.
            mailKeydown(e, typing) {
                const m = this.mail;
                if (e.metaKey || e.ctrlKey || e.altKey) return false;
                const isDown = e.key === 'ArrowDown' || (!typing && e.key === 'j');
                const isUp   = e.key === 'ArrowUp'   || (!typing && e.key === 'k');
                if (isDown || isUp) { e.preventDefault(); this.mailMove(isDown ? 1 : -1); return true; }
                if (typing) return false; // the search box handles its own Esc
                if (this.showDbModal || this.ctxMenu.open) return false;
                if ((e.key === 'Backspace' || e.key === 'Delete') && m.selectedId) {
                    e.preventDefault();
                    this.mailDelete([m.selectedId]);
                    return true;
                }
                if (e.key === 'u' && m.selectedId) {
                    const it = m.items.find(x => x.ID === m.selectedId);
                    if (it) this.mailSetRead([it.ID], !it.Read);
                    return true;
                }
                if (e.key === 'Escape') {
                    if (m.selectedId) { this.closeMail(); return true; }
                    if (this.mailQuery) { this.mailClearFilters(); return true; }
                    return false;
                }
                return false;
            },

            setMailPart(part) {
                const m = this.mail;
                m.part = part;
                if (part === 'headers' && m.msg && m.headers === null) {
                    const id = m.msg.ID;
                    m.headers = '';
                    this.mailApi('/v1/message/' + encodeURIComponent(id) + '/headers').then(h => {
                        if (!m.msg || m.msg.ID !== id) return;
                        m.headers = Object.keys(h || {}).sort().map(k => (h[k] || []).map(v => k + ': ' + v).join('\n')).join('\n');
                        this.renderMailReader();
                    }).catch(() => {
                        if (!m.msg || m.msg.ID !== id) return;
                        m.headers = '(could not load headers)';
                        this.renderMailReader();
                    });
                }
                this.renderMailReader();
            },

            async mailSetRead(ids, read) {
                try {
                    await this.mailApi('/v1/messages', { method: 'PUT', body: { IDs: ids, Read: read } });
                } catch (e) {
                    this.showSnack('Mailpit did not answer.', true);
                    return false;
                }
                // An empty ID list means "everything" to Mailpit.
                for (const it of this.mail.items) if (!ids.length || ids.includes(it.ID)) it.Read = read;
                this.refreshMailCounts();
                this.renderMail();
                return true;
            },

            async mailReadAll() {
                const q = this.mailQuery;
                let ids = [];
                if (q) {
                    // No read-by-search endpoint in Mailpit 1.30, so page the
                    // search for its IDs. Capped: a filter is rarely huge.
                    try {
                        for (let start = 0; start < 5000; start += 200) {
                            const d = await this.mailApi('/v1/search?query=' + encodeURIComponent(q) + '&limit=200&start=' + start);
                            const page = Array.isArray(d.messages) ? d.messages : [];
                            ids.push(...page.map(x => x.ID));
                            if (page.length < 200) break;
                        }
                    } catch (e) { this.showSnack('Mailpit did not answer.', true); return; }
                    if (!ids.length) return;
                }
                if (await this.mailSetRead(ids, true)) this.showSnack(q ? 'Matching mail marked read.' : 'Everything marked read.');
            },

            async mailDelete(ids) {
                const m = this.mail;
                try {
                    await this.mailApi('/v1/messages', { method: 'DELETE', body: { IDs: ids } });
                } catch (e) {
                    this.showSnack('Mailpit did not answer.', true);
                    return;
                }
                const idx = m.items.findIndex(x => x.ID === m.selectedId);
                m.items = m.items.filter(x => !ids.includes(x.ID));
                m.matched = Math.max(0, m.matched - ids.length);
                if (ids.includes(m.selectedId)) {
                    // Land on the neighbour so triaging a pile is ⌫ ⌫ ⌫.
                    m.selectedId = null; m.msg = null; m.renderedId = null;
                    const next = m.items[Math.min(idx, m.items.length - 1)];
                    if (next) this.openMail(next.ID);
                }
                this.showSnack(ids.length === 1 ? 'Message deleted.' : ids.length + ' messages deleted.');
                this.loadMail({ keepStart: true });
            },

            // Two clicks, like the sites' bulk delete: the first arms the
            // button for a few seconds, the second fires.
            async mailDeleteAll() {
                const m = this.mail;
                if (!m.deleteArmed) {
                    m.deleteArmed = true;
                    clearTimeout(m.armTimer);
                    m.armTimer = setTimeout(() => { m.deleteArmed = false; this.renderMailChrome(); }, 3500);
                    this.renderMailChrome();
                    return;
                }
                m.deleteArmed = false;
                clearTimeout(m.armTimer);
                const q = this.mailQuery;
                try {
                    if (q) await this.mailApi('/v1/search?query=' + encodeURIComponent(q), { method: 'DELETE' });
                    else await this.mailApi('/v1/messages', { method: 'DELETE', body: { IDs: [] } });
                } catch (e) {
                    this.showSnack('Mailpit did not answer.', true);
                    this.renderMailChrome();
                    return;
                }
                m.selectedId = null; m.msg = null; m.renderedId = null; m.items = [];
                this.showSnack(q ? 'Matching mail deleted.' : 'Inbox emptied.');
                this.loadMail();
            },

            mailAddrLabel(a) {
                if (!a) return '';
                return a.Name || a.Address || '';
            },

            mailAddrFull(a) {
                if (!a) return '';
                return a.Name ? a.Name + ' <' + a.Address + '>' : (a.Address || '');
            },

            // The site a message belongs to: the first recipient at a
            // *.localhost domain. Mail from a site to an outside address still
            // maps by its sender.
            mailSiteOf(it) {
                const pick = (list) => {
                    for (const a of (list || [])) {
                        const mm = /@([a-z0-9-]+)\.localhost$/i.exec(a.Address || '');
                        if (mm) return mm[1].toLowerCase();
                    }
                    return null;
                };
                return pick(it.To) || pick(it.Cc) || pick(it.From ? [it.From] : []);
            },

            mailLinks(msg) {
                const out = [], seen = new Set();
                const push = (u) => {
                    u = String(u || '').trim().replace(/[)\].,;'"!>]+$/, '');
                    if (!/^https?:\/\//i.test(u) || seen.has(u)) return;
                    seen.add(u); out.push(u);
                };
                if (msg.HTML) {
                    const re = /href\s*=\s*["']([^"']+)["']/gi;
                    let x;
                    while ((x = re.exec(msg.HTML))) push(this.decodeEntities(x[1]));
                }
                if (msg.Text) {
                    const re = /https?:\/\/[^\s<>"']+/gi;
                    let x;
                    while ((x = re.exec(msg.Text))) push(x[0]);
                }
                return out.slice(0, 8);
            },

            decodeEntities(s) {
                const t = document.createElement('textarea');
                t.innerHTML = s;
                return t.value;
            },

            linkify(text) {
                return this.escapeHtml(text).replace(/https?:\/\/[^\s<>"']+/g, (u) => {
                    const clean = u.replace(/[)\].,;'"!]+$/, '');
                    const tail = u.slice(clean.length);
                    return '<a href="' + clean + '" target="_blank" rel="noopener noreferrer">' + clean + '</a>' + tail;
                });
            },

            // The srcdoc for the sandboxed frame. Mailpit hands back the HTML
            // untouched with cid: references intact and lists the inline parts
            // separately, so the references are pointed at the proxied part
            // URLs here. A CSP inside the document keeps everything else out —
            // the sandbox already denies scripts and forms; this also stops
            // remote images, fonts and stylesheets so a message never phones
            // home when opened.
            mailHtmlDoc(msg) {
                let html = msg.HTML || '';
                for (const p of (msg.Inline || [])) {
                    if (!p.ContentID) continue;
                    const url = '/mail-api/v1/message/' + encodeURIComponent(msg.ID) + '/part/' + encodeURIComponent(p.PartID);
                    html = html.split('cid:' + p.ContentID).join(url);
                }
                html = html.replace(/<script[\s\S]*?<\/script\s*>/gi, '').replace(/<meta[^>]+http-equiv[^>]*>/gi, '');
                const csp = "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; form-action 'none'";
                const head = '<meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="' + csp + '"><base target="_blank">'
                    + '<style>html{color-scheme:light}body{margin:0;padding:16px;background:#fff;color:#1a1c1b;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',system-ui,sans-serif;line-height:1.45}</style>';
                if (/<head[^>]*>/i.test(html)) return html.replace(/<head[^>]*>/i, (t) => t + head);
                if (/<html[^>]*>/i.test(html)) return html.replace(/<html[^>]*>/i, (t) => t + '<head>' + head + '</head>');
                return '<!doctype html><html><head>' + head + '</head><body>' + html + '</body></html>';
            },

            renderMail() {
                if (this.view !== 'mail') return;
                this.renderMailChrome();
                this.renderMailList();
                this.renderMailReader();
                this.renderMailFooter();
            },

            renderMailChrome() {
                this.renderViewBack('mailBack', this.mail.site);
                const m = this.mail;
                const chip = $id('mailSiteChip');
                show(chip, !!m.site);
                if (m.site) $id('mailSiteChipLabel').textContent = 'site: ' + m.site;
                const active = !!(m.query || m.site || m.unreadOnly);
                show($id('mailKbd'), !active);
                show($id('btnMailSearchClear'), active);
                const del = $id('btnMailDeleteAll');
                del.classList.toggle('armed', m.deleteArmed);
                del.textContent = m.deleteArmed ? ('sure? delete ' + m.matched) : (active ? 'delete matching' : 'delete all');
                del.disabled = !m.matched;
                $id('btnMailReadAll').disabled = !m.matched;
            },

            renderMailList() {
                const m = this.mail;
                const list = $id('mailList');
                list.querySelectorAll('.mail-row').forEach(n => n.remove());
                show($id('mailLoading'), m.loading);
                show($id('mailError'), !m.loading && !!m.error);
                const empty = !m.loading && !m.error && m.items.length === 0;
                const q = this.mailQuery;
                show($id('mailEmptyNone'), empty && !q);
                show($id('mailEmptyFilter'), empty && !!q);
                if (empty && q) $id('mailEmptyQuery').textContent = q;

                const tpl = $id('tpl-mail-row');
                const anchor = $id('mailLoading');
                for (const it of m.items) {
                    const row = tpl.content.firstElementChild.cloneNode(true);
                    row.dataset.id = it.ID;
                    row.classList.toggle('is-unread', !it.Read);
                    row.classList.toggle('is-selected', it.ID === m.selectedId);
                    const from = row.querySelector('.mail-from');
                    from.textContent = this.mailAddrLabel(it.From) || '(unknown sender)';
                    from.title = this.mailAddrFull(it.From);
                    const age = row.querySelector('.mail-age');
                    const ts = Date.parse(it.Created) / 1000;
                    age.textContent = this.formatRelative(ts);
                    age.title = isNaN(ts) ? '' : new Date(it.Created).toLocaleString();
                    row.querySelector('.mail-subject').textContent = it.Subject || '(no subject)';
                    const site = this.mailSiteOf(it);
                    const chip = row.querySelector('.mail-site');
                    if (site) { chip.textContent = site; chip.title = 'Only mail for ' + site + '.localhost'; }
                    else chip.remove();
                    const att = row.querySelector('.mail-att');
                    if (it.Attachments) att.setAttribute('title', it.Attachments + ' attachment' + (it.Attachments === 1 ? '' : 's'));
                    else att.remove();
                    row.querySelector('.mail-snippet').textContent = it.Snippet || '';
                    list.insertBefore(row, anchor);
                }
            },

            renderMailReader() {
                const m = this.mail;
                const has = !!m.selectedId;
                $id('mailBody').classList.toggle('has-msg', has);
                show($id('mailReaderEmpty'), !has);
                show($id('mailMsg'), has);
                if (!has) return;
                show($id('mailMsgLoading'), m.msgLoading);
                show($id('mailMsgError'), !m.msgLoading && !!m.msgError);
                if (m.msgError) $id('mailMsgError').textContent = m.msgError;
                const ready = !!m.msg && !m.msgLoading;
                show($id('mailMsgHead'), ready);
                show($id('mailMsgMain'), ready);
                if (!ready) return;
                const msg = m.msg;

                if (m.renderedId !== msg.ID) {
                    m.renderedId = msg.ID;
                    m.remoteBlocked = 0;
                    $id('mailMsgSubject').textContent = msg.Subject || '(no subject)';
                    const meta = [['from', this.mailAddrFull(msg.From)], ['to', (msg.To || []).map(a => this.mailAddrFull(a)).join(', ')]];
                    if (msg.Cc && msg.Cc.length) meta.push(['cc', msg.Cc.map(a => this.mailAddrFull(a)).join(', ')]);
                    if (msg.Bcc && msg.Bcc.length) meta.push(['bcc', msg.Bcc.map(a => this.mailAddrFull(a)).join(', ')]);
                    if (msg.ReplyTo && msg.ReplyTo.length) meta.push(['reply', msg.ReplyTo.map(a => this.mailAddrFull(a)).join(', ')]);
                    const when = Date.parse(msg.Date);
                    meta.push(['date', isNaN(when) ? (msg.Date || '—') : new Date(when).toLocaleString()]);
                    $id('mailMsgMeta').innerHTML = meta.map(([k, v]) =>
                        '<div class="mail-meta-row"><span class="mail-meta-k">' + k + '</span><span class="mail-meta-v">' + this.escapeHtml(v || '—') + '</span></div>').join('');
                    $id('mailMsgLinks').innerHTML = this.mailLinks(msg).map(u => {
                        const label = u.replace(/^https?:\/\//i, '');
                        return '<span class="mail-link"><a href="' + this.escapeHtml(u) + '" target="_blank" rel="noopener noreferrer" title="' + this.escapeHtml(u) + '">' + this.escapeHtml(label) + '</a>'
                            + '<button type="button" class="mail-link-copy" data-url="' + this.escapeHtml(u) + '" title="Copy link">copy</button></span>';
                    }).join('');

                    const frame = $id('mailFrame');
                    frame.style.height = '';
                    if (msg.HTML) {
                        frame.onload = () => {
                            try {
                                const d = frame.contentDocument;
                                const h = Math.max(d.documentElement.scrollHeight, d.body ? d.body.scrollHeight : 0);
                                frame.style.height = Math.min(Math.max(h + 8, 240), 6000) + 'px';
                                m.remoteBlocked = d.querySelectorAll('img[src^="http"], img[src^="//"]').length;
                                this.renderMailReader();
                            } catch (e) {}
                        };
                        frame.srcdoc = this.mailHtmlDoc(msg);
                    } else {
                        frame.onload = null;
                        frame.srcdoc = '';
                    }
                    $id('mailText').innerHTML = msg.Text ? this.linkify(msg.Text) : '<span style="color: var(--text-faint)">(no text part)</span>';

                    const att = $id('mailAttachments');
                    const files = msg.Attachments || [];
                    show(att, files.length > 0);
                    att.innerHTML = files.map(f =>
                        '<a class="pill" href="/mail-api/v1/message/' + encodeURIComponent(msg.ID) + '/part/' + encodeURIComponent(f.PartID) + '" target="_blank" rel="noopener" download="' + this.escapeHtml(f.FileName || 'attachment') + '">'
                        + this.escapeHtml(f.FileName || 'attachment') + ' <span style="color: var(--text-faint)">' + this.formatSize(f.Size) + '</span></a>').join('');
                    $id('mailOpenInMailpit').href = this.mailpitUrl + '/view/' + encodeURIComponent(msg.ID);
                }

                const row = m.items.find(x => x.ID === msg.ID);
                $id('btnMailUnread').textContent = (row && !row.Read) ? 'mark read' : 'mark unread';
                document.querySelectorAll('#mailParts .mail-part').forEach(b => {
                    const part = b.dataset.part;
                    show(b, part !== 'html' || !!msg.HTML);
                    b.classList.toggle('is-active', m.part === part);
                    b.setAttribute('aria-selected', m.part === part ? 'true' : 'false');
                });
                show($id('mailFrame'), m.part === 'html');
                show($id('mailText'), m.part === 'text');
                show($id('mailHeaders'), m.part === 'headers');
                if (m.part === 'headers') $id('mailHeaders').textContent = m.headers === '' ? 'Loading…' : (m.headers || '');
                const note = $id('mailRemoteNote');
                show(note, m.part === 'html' && m.remoteBlocked > 0);
                note.textContent = m.remoteBlocked + ' remote image' + (m.remoteBlocked === 1 ? '' : 's') + ' blocked';
            },

            renderMailFooter() {
                if (this.view !== 'mail') return;
                const m = this.mail;
                const total = m.total, unread = m.unread;
                const q = this.mailQuery;
                let label;
                if (m.error && !m.loaded) label = '';
                else if (q) label = m.matched + ' of ' + total + ' message' + (total === 1 ? '' : 's');
                else label = total + ' message' + (total === 1 ? '' : 's') + (unread ? ' · ' + unread + ' unread' : '');
                $id('mailCount').textContent = label;
                const db = $id('mailDbSize');
                show(db, !!(m.info && m.info.DatabaseSize));
                if (m.info && m.info.DatabaseSize) { db.textContent = '· ' + this.formatSize(m.info.DatabaseSize) + ' on disk'; db.title = m.info.Database || ''; }
                const pager = $id('mailPager');
                show(pager, m.matched > m.limit);
                if (m.matched > m.limit) {
                    $id('mailRange').textContent = (m.start + 1) + '–' + Math.min(m.start + m.limit, m.matched);
                    $id('btnMailNewer').disabled = m.start === 0;
                    $id('btnMailOlder').disabled = m.start + m.limit >= m.matched;
                }
            },

            // Keep the outgoing card on screen, out of flow, while it fades;
            // renderView leaves .is-leaving cards alone until the fade ends.
            crossfadeFrom(prev) {
                const out = $id({ sites: 'sitesCard', mail: 'mailCard', db: 'dbCard', logs: 'logsCard', files: 'filesCard', site: 'siteCard' }[prev]);
                if (!out || out.style.display === 'none') return;
                if (window.scrollY > 0) window.scrollTo({ top: 0, behavior: 'instant' });
                document.querySelectorAll('.wrap > .card.is-leaving').forEach(el => { el.classList.remove('is-leaving'); el.style.top = ''; el.style.display = 'none'; });
                out.style.top = out.offsetTop + 'px';
                out.classList.add('is-leaving');
                setTimeout(() => {
                    out.classList.remove('is-leaving');
                    out.style.top = '';
                    this.renderView();
                }, 220);
            },

            renderView() {
                const card = (id, on) => { const el = $id(id); if (!el.classList.contains('is-leaving')) show(el, on); };
                card('sitesCard', this.view === 'sites');
                card('mailCard', this.view === 'mail');
                card('dbCard', this.view === 'db');
                card('logsCard', this.view === 'logs');
                card('filesCard', this.view === 'files');
                card('siteCard', this.view === 'site');
                document.querySelectorAll('.nav-view').forEach(b => {
                    // A site's page lives under the sites tab.
                    const on = b.dataset.view === this.view || (this.view === 'site' && b.dataset.view === 'sites');
                    b.classList.toggle('is-active', on);
                    b.setAttribute('aria-selected', on ? 'true' : 'false');
                });
                const badge = $id('mailBadge');
                const n = this.mail.unread;
                show(badge, n > 0);
                badge.textContent = n > 99 ? '99+' : String(n);
                document.querySelector('.nav-view[data-view="mail"]').title = n ? (n + ' unread message' + (n === 1 ? '' : 's')) : 'Mail';
            },

            bindMailEvents() {
                document.querySelectorAll('.nav-view').forEach(b => b.addEventListener('click', () => this.setView(b.dataset.view)));
                // The wordmark is "home": the sites view, in place. Plain
                // left-clicks only, so ⌘-click and middle-click still open a
                // fresh tab like any link.
                document.querySelector('.nav .logo').addEventListener('click', (e) => {
                    if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
                    e.preventDefault();
                    if (this.view !== 'sites') { this.setView('sites'); return; }
                    if (window.scrollY > 0) window.scrollTo({ top: 0, behavior: 'smooth' });
                });
                window.addEventListener('popstate', () => this.readViewFromUrl());

                const search = $id('mailSearch');
                search.addEventListener('input', () => {
                    this.mail.query = search.value;
                    clearTimeout(this.mail.searchTimer);
                    this.mail.searchTimer = setTimeout(() => this.loadMail(), 250);
                    this.renderMailChrome();
                });
                search.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter') { e.preventDefault(); clearTimeout(this.mail.searchTimer); this.loadMail(); }
                    if (e.key === 'Escape') {
                        e.preventDefault(); e.stopPropagation();
                        this.mail.query = ''; search.value = ''; search.blur();
                        this.loadMail();
                    }
                });
                $id('btnMailSearchClear').addEventListener('click', () => { this.mailClearFilters(); search.focus(); });
                $id('mailSiteChipClear').addEventListener('click', () => { this.setMailSite(null); search.focus(); });
                $id('mailUnreadOnly').addEventListener('change', (e) => { this.mail.unreadOnly = e.target.checked; this.loadMail(); });
                $id('btnMailReadAll').addEventListener('click', () => this.mailReadAll());
                $id('btnMailDeleteAll').addEventListener('click', () => this.mailDeleteAll());
                $id('btnMailNewer').addEventListener('click', () => this.mailPage(-1));
                $id('btnMailOlder').addEventListener('click', () => this.mailPage(1));

                $id('mailList').addEventListener('click', (e) => {
                    const row = e.target.closest('.mail-row');
                    if (!row) return;
                    const chip = e.target.closest('.mail-site');
                    if (chip) { this.setMailSite(chip.textContent); return; }
                    this.openMail(row.dataset.id);
                });
                $id('mailParts').addEventListener('click', (e) => {
                    const b = e.target.closest('.mail-part');
                    if (b) this.setMailPart(b.dataset.part);
                });
                $id('btnMailUnread').addEventListener('click', () => {
                    const it = this.mail.items.find(x => x.ID === this.mail.selectedId);
                    if (it) this.mailSetRead([it.ID], !it.Read);
                    else if (this.mail.selectedId) this.mailSetRead([this.mail.selectedId], false);
                });
                $id('btnMailDelete').addEventListener('click', () => { if (this.mail.selectedId) this.mailDelete([this.mail.selectedId]); });
                $id('btnMailBack').addEventListener('click', () => this.closeMail());
                $id('mailMsgLinks').addEventListener('click', (e) => {
                    const b = e.target.closest('.mail-link-copy');
                    if (!b) return;
                    navigator.clipboard.writeText(b.dataset.url)
                        .then(() => this.showSnack('Link copied.'))
                        .catch(() => this.showSnack('Could not copy.', true));
                });
                document.addEventListener('visibilitychange', () => {
                    if (!document.hidden && this.view === 'mail') this.loadMail({ keepStart: true });
                });
            },

            // --- Databases -------------------------------------------------
            // A native browser over MariaDB via api.php's db_* actions. Every
            // Cove site owns one database (its name is in wp-config.php), so
            // the list maps databases back to sites the way the inbox maps
            // recipients. Adminer remains the tool for exports, imports and
            // schema changes; this covers looking, fixing a value, and asking
            // the database a question.
            dbSiteOf(name) {
                const s = this.sites.find(x => x.db_name === name);
                return s ? s.name : null;
            },

            get dbVisibleList() {
                const q = this.db.filter.trim().toLowerCase();
                if (this.db.name) {
                    return this.db.tables.filter(t => !q || t.name.toLowerCase().includes(q));
                }
                return this.db.list.filter(d => !q || d.name.toLowerCase().includes(q) || (this.dbSiteOf(d.name) || '').includes(q));
            },

            resetDbTable() {
                const r = this.db.rows;
                Object.assign(r, { columns: [], pk: [], items: [], total: 0, start: 0, sort: '', dir: 'asc', q: '', col: '', loading: false, error: null });
                this.db.structure = null;
                this.db.edit = null;
                this.db.delArm = null;
                this.db.part = 'rows';
                const f = $id('dbRowsFilter'); if (f) f.value = '';
            },

            async loadDbList() {
                const d = this.db;
                d.loading = !d.loaded;
                this.renderDb();
                // Names first (instant), then a second pass for table counts
                // and sizes, which can take seconds on a box with thousands
                // of tables.
                const res = await this.apiPost('db_list', { light: true }, { quiet: true, timeoutMs: 15000 });
                if (res.success) { d.list = res.databases || []; d.server = res.server || ''; d.error = null; }
                else d.error = res.message || 'MariaDB is not answering.';
                d.loaded = true;
                d.loading = false;
                this.renderDb();
                if (!res.success) return;
                const full = await this.apiPost('db_list', {}, { quiet: true, timeoutMs: 60000 });
                if (full.success) { d.list = full.databases || d.list; this.renderDbList(); this.renderDbFooter(); if (d.name && !d.table && !d.sql) this.renderDbOverview(); }
            },

            async loadDbTables() {
                const d = this.db;
                const name = d.name;
                if (!name) return;
                this.renderDb();
                const res = await this.apiPost('db_tables', { db: name }, { quiet: true, timeoutMs: 20000 });
                if (d.name !== name) return;
                if (res.success) { d.tables = res.tables || []; d.wp = res.wp || null; d.error = null; }
                else { d.error = res.message || 'Could not read that database.'; d.tables = []; }
                d.tablesFor = name;
                this.renderDb();
            },

            openDb(name) {
                if (name === this.db.name) return;
                this.db.name = name;
                this.db.tables = [];
                this.db.tablesFor = null;
                this.db.wp = null;
                this.db.filter = '';
                $id('dbFilter').value = '';
                this.resetDbTable();
                this.db.table = null;
                this.syncUrl();
                this.renderDb();
                this.loadDbTables();
            },

            closeDb() {
                this.db.name = null;
                this.db.table = null;
                this.db.tables = [];
                this.db.tablesFor = null;
                this.db.wp = null;
                this.db.filter = '';
                $id('dbFilter').value = '';
                this.resetDbTable();
                this.syncUrl();
                this.renderDb();
                if (!this.db.list.length) this.loadDbList();
            },

            openDbTable(table, opts = {}) {
                if (table === this.db.table && !opts.force) { this.db.sql = false; this.renderDb(); return; }
                this.resetDbTable();
                this.db.table = table;
                this.db.sql = false;
                if (opts.q) { this.db.rows.q = opts.q; this.db.rows.col = opts.col || ''; $id('dbRowsFilter').value = opts.q; }
                this.syncUrl();
                this.renderDb();
                this.loadDbRows();
            },

            closeDbTable() {
                this.db.table = null;
                this.resetDbTable();
                this.syncUrl();
                this.renderDb();
            },

            // From a site's row menu or the palette: straight to its schema.
            openDbForSite(site) {
                const name = site.db_name || ('cove_' + site.name).replace(/[^a-zA-Z0-9_]/g, '_');
                if (name !== this.db.name) { this.db.tables = []; this.db.tablesFor = null; this.db.wp = null; this.resetDbTable(); this.db.table = null; }
                this.db.name = name;
                this.db.filter = '';
                $id('dbFilter').value = '';
                this.setView('db', { force: true });
            },

            async loadDbRows() {
                const d = this.db, r = d.rows;
                if (!d.name || !d.table) return;
                const seq = ++r.seq;
                r.loading = r.items.length === 0;
                r.error = null;
                this.renderDbTable();
                const res = await this.apiPost('db_rows', { db: d.name, table: d.table, start: r.start, limit: r.limit, sort: r.sort, dir: r.dir, q: r.q, col: r.col }, { quiet: true, timeoutMs: 30000 });
                if (seq !== r.seq) return;
                if (res.success) {
                    r.columns = res.columns || []; r.pk = res.pk || []; r.items = res.rows || []; r.total = res.total || 0;
                    if (r.start > 0 && r.items.length === 0 && r.total > 0) {
                        r.start = Math.max(0, Math.floor((r.total - 1) / r.limit) * r.limit);
                        return this.loadDbRows();
                    }
                } else {
                    r.error = res.message || 'Could not read rows.';
                    r.items = []; r.total = 0;
                }
                r.loading = false;
                this.renderDbTable();
                this.renderDbFooter();
            },

            dbPage(delta) {
                const r = this.db.rows;
                const next = r.start + delta * r.limit;
                if (next < 0 || next >= r.total) return;
                r.start = next;
                this.loadDbRows();
                $id('dbGridWrap').scrollTop = 0;
            },

            dbSort(col) {
                const r = this.db.rows;
                if (r.sort === col) r.dir = r.dir === 'asc' ? 'desc' : 'asc';
                else { r.sort = col; r.dir = 'asc'; }
                r.start = 0;
                this.loadDbRows();
            },

            setDbPart(part) {
                this.db.part = part;
                this.db.edit = null;
                if (part === 'structure' && this.db.structure === null) {
                    const d = this.db, name = d.name, table = d.table;
                    d.structure = { loading: true };
                    this.apiPost('db_structure', { db: name, table }, { quiet: true, timeoutMs: 20000 }).then(res => {
                        if (d.name !== name || d.table !== table) return;
                        d.structure = res.success ? res : { error: res.message || 'Could not read the structure.' };
                        this.renderDbTable();
                    });
                }
                this.renderDbTable();
            },

            toggleDbSql(on) {
                this.db.sql = typeof on === 'boolean' ? on : !this.db.sql;
                this.db.edit = null;
                this.renderDb();
                if (this.db.sql) $id('dbSqlText').focus();
            },

            // Returns true when the key was consumed.
            dbKeydown(e, typing) {
                const d = this.db;
                const el = document.activeElement;
                if (el && el.id === 'dbSqlText') {
                    if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') { e.preventDefault(); this.runDbSql(); return true; }
                    if (e.key === 'Escape') { e.preventDefault(); el.blur(); return true; }
                    return false;
                }
                if (el && el.classList && el.classList.contains('db-edit')) return false; // the editor owns its keys
                if (typing) return false;
                if (e.metaKey || e.ctrlKey || e.altKey) return false;
                if (e.key === 'Escape') {
                    if (this.showDbModal || this.ctxMenu.open) return false;
                    if (d.edit) { this.cancelDbEdit(); return true; }
                    if (d.sql) { this.toggleDbSql(false); return true; }
                    if (d.filter) { d.filter = ''; $id('dbFilter').value = ''; this.renderDb(); return true; }
                    if (d.table) { this.closeDbTable(); return true; }
                    if (d.name) { this.closeDb(); return true; }
                    return false;
                }
                return false;
            },

            // --- Editing a cell. Double-click; ↵ saves, Esc cancels,
            // ⌘⌫ writes NULL. Long values are fetched in full first.
            async startDbEdit(rowIdx, colIdx) {
                const d = this.db, r = d.rows;
                if (!r.pk.length || d.part !== 'rows') return;
                const col = r.columns[colIdx];
                if (!col) return;
                let value = r.items[rowIdx] ? r.items[rowIdx][colIdx] : undefined;
                if (value === undefined) return;
                if (value && typeof value === 'object') {
                    if (value.t === 'bin') { this.showSnack('Binary values cannot be edited here.', true); return; }
                    const res = await this.apiPost('db_cell', { db: d.name, table: d.table, pk: this.dbRowKey(rowIdx), col: col.name }, { timeoutMs: 20000 });
                    if (!res.success) return;
                    value = res.value;
                }
                d.edit = { row: rowIdx, col: colIdx, value: value === null ? '' : String(value), isNull: value === null, busy: false };
                this.renderDbGrid();
                const ta = $id('dbGrid').querySelector('.db-edit');
                if (ta) { ta.focus(); ta.select(); }
            },

            cancelDbEdit() {
                this.db.edit = null;
                this.renderDbGrid();
            },

            dbRowKey(rowIdx) {
                const r = this.db.rows;
                const row = r.items[rowIdx];
                const key = {};
                for (const c of r.pk) {
                    const i = r.columns.findIndex(x => x.name === c);
                    const v = row[i];
                    key[c] = (v && typeof v === 'object') ? null : v;
                }
                return key;
            },

            async saveDbEdit(asNull = false) {
                const d = this.db, r = d.rows, ed = d.edit;
                if (!ed || ed.busy) return;
                const col = r.columns[ed.col];
                const original = r.items[ed.row][ed.col];
                const unchanged = asNull ? original === null : (original !== null && typeof original !== 'object' && String(original) === ed.value);
                if (unchanged) { this.cancelDbEdit(); return; }
                ed.busy = true;
                const res = await this.apiPost('db_update', { db: d.name, table: d.table, pk: this.dbRowKey(ed.row), col: col.name, value: ed.value, null: asNull }, { timeoutMs: 20000 });
                if (!res.success) { ed.busy = false; this.renderDbGrid(); return; }
                if (res.row) r.items[ed.row] = res.row;
                else r.items[ed.row][ed.col] = asNull ? null : ed.value;
                d.edit = null;
                this.renderDbGrid();
                this.showSnack(res.affected ? 'Saved.' : 'No change.');
            },

            async deleteDbRow(rowIdx) {
                const d = this.db, r = d.rows;
                if (d.delArm !== rowIdx) {
                    d.delArm = rowIdx;
                    clearTimeout(d.delTimer);
                    d.delTimer = setTimeout(() => { d.delArm = null; this.renderDbGrid(); }, 3500);
                    this.renderDbGrid();
                    return;
                }
                d.delArm = null;
                clearTimeout(d.delTimer);
                const res = await this.apiPost('db_delete_row', { db: d.name, table: d.table, pk: this.dbRowKey(rowIdx) }, { timeoutMs: 20000 });
                if (!res.success) { this.renderDbGrid(); return; }
                r.items.splice(rowIdx, 1);
                r.total = Math.max(0, r.total - 1);
                this.showSnack('Row deleted.');
                this.renderDbGrid();
                this.renderDbFooter();
                if (r.items.length === 0 && r.total > 0) this.loadDbRows();
            },

            // --- SQL console ------------------------------------------------
            async runDbSql() {
                const c = this.db.console;
                const sql = $id('dbSqlText').value;
                c.text = sql;
                if (!sql.trim() || c.running) return;
                c.running = true;
                this.renderDbSql();
                const res = await this.apiPost('db_query', { db: this.db.name || '', sql }, { quiet: true, timeoutMs: 120000 });
                c.running = false;
                if (!res.success) {
                    c.results = [{ type: 'error', message: res.message || (res.transport ? 'The dashboard did not answer.' : 'Query failed.') }];
                } else {
                    c.results = res.results || [];
                    c.ms = res.ms || 0;
                    this.pushDbHistory(sql);
                    // Data-changing statements: freshen whatever is open behind the console.
                    if (c.results.some(x => x.type === 'ok')) {
                        if (this.db.table) this.loadDbRows();
                        if (this.db.name) this.loadDbTables();
                    }
                }
                this.renderDbSql();
            },

            get dbHistory() {
                try { return JSON.parse(localStorage.getItem('cove-sql-history') || '[]'); } catch (e) { return []; }
            },

            pushDbHistory(sql) {
                const h = this.dbHistory.filter(x => x !== sql);
                h.unshift(sql);
                try { localStorage.setItem('cove-sql-history', JSON.stringify(h.slice(0, 40))); } catch (e) {}
            },

            // --- Rendering ---------------------------------------------------
            renderDb() {
                if (this.view !== 'db') return;
                this.renderDbChrome();
                this.renderDbList();
                this.renderDbMain();
                this.renderDbFooter();
            },

            renderDbChrome() {
                const d = this.db;
                const chip = $id('dbChip');
                show(chip, !!d.name);
                if (d.name) $id('dbChipLabel').textContent = d.name;
                $id('dbFilter').placeholder = d.name ? 'filter tables…' : 'filter databases…';
                show($id('dbKbd'), !d.filter);
                show($id('btnDbFilterClear'), !!d.filter);
                $id('btnDbSql').classList.toggle('primary', d.sql);
                const site = d.name ? this.dbSiteOf(d.name) : null;
                this.renderViewBack('dbBack', site);
                const adminer = this.adminerUrl + '/?username=' + encodeURIComponent(DB_USER) + (d.name ? '&db=' + encodeURIComponent(d.name) + (d.table ? '&select=' + encodeURIComponent(d.table) : '') : '');
                $id('dbAdminerLink').href = adminer;
                $id('dbAdminerLink').title = 'Open ' + (d.table ? d.table + ' in Adminer' : d.name ? d.name + ' in Adminer' : 'Adminer') + (site ? ' (' + site + '.localhost)' : '') + ' — exports, imports, schema changes, users';
            },

            renderDbList() {
                const d = this.db;
                const list = $id('dbList');
                list.querySelectorAll('.db-row').forEach(n => n.remove());
                const loading = d.name ? d.tablesFor !== d.name : d.loading;
                show($id('dbLoading'), loading);
                show($id('dbError'), !loading && !!d.error);
                const rows = loading ? [] : this.dbVisibleList;
                const empty = !loading && !d.error && rows.length === 0;
                show($id('dbEmpty'), empty);
                if (empty) $id('dbEmptyQuery').textContent = d.filter || (d.name ? '(no tables)' : '(no databases)');
                const tpl = $id('tpl-db-row');
                const anchor = $id('dbLoading');
                for (const it of rows) {
                    const row = tpl.content.firstElementChild.cloneNode(true);
                    row.dataset.name = it.name;
                    row.querySelector('.db-row-name').textContent = it.name;
                    row.querySelector('.db-row-name').title = it.name;
                    const chip = row.querySelector('.db-row-site');
                    if (d.name) {
                        chip.remove();
                        row.classList.toggle('is-view', !!it.view);
                        row.classList.toggle('is-selected', it.name === d.table);
                        row.querySelector('.db-row-meta').textContent = it.view ? 'view' : ((it.rows === null ? '' : '~' + this.formatCount(it.rows)) + (it.bytes ? ' · ' + this.formatSize(it.bytes) : ''));
                        row.querySelector('.db-row-meta').title = it.view ? 'View' : (it.engine || '') + (it.collation ? ' · ' + it.collation : '') + ' · row count is the engine\'s estimate';
                    } else {
                        const site = this.dbSiteOf(it.name);
                        if (site) { chip.textContent = site; chip.title = site + '.localhost'; chip.setAttribute('role', 'presentation'); }
                        else chip.remove();
                        row.classList.toggle('is-selected', it.name === d.name);
                        row.querySelector('.db-row-meta').textContent = it.tables === null ? '' : it.tables + ' table' + (it.tables === 1 ? '' : 's') + (it.bytes ? ' · ' + this.formatSize(it.bytes) : '');
                    }
                    list.insertBefore(row, anchor);
                }
            },

            renderDbMain() {
                const d = this.db;
                const mode = d.sql ? 'sql' : d.table ? 'table' : d.name ? 'overview' : 'empty';
                show($id('dbMainEmpty'), mode === 'empty');
                show($id('dbOverview'), mode === 'overview');
                show($id('dbTable'), mode === 'table');
                show($id('dbSql'), mode === 'sql');
                if (mode === 'overview') this.renderDbOverview();
                if (mode === 'table') this.renderDbTable();
                if (mode === 'sql') this.renderDbSql();
            },

            renderDbOverview() {
                const d = this.db, esc = (s) => this.escapeHtml(s == null ? '—' : String(s));
                const box = $id('dbOverview');
                const meta = d.list.find(x => x.name === d.name);
                const site = this.dbSiteOf(d.name);
                let html = '<h2>' + esc(d.name) + '</h2>';
                const sub = [];
                if (site) sub.push('<a href="https://' + esc(site) + '.localhost' + PORT_SUFFIX + '" target="_blank" rel="noopener" style="color: var(--accent); text-decoration: none;">' + esc(site) + '.localhost</a>');
                if (meta && meta.tables !== null) sub.push(meta.tables + ' table' + (meta.tables === 1 ? '' : 's') + ' · ' + this.formatSize(meta.bytes));
                if (d.server) sub.push('MariaDB ' + esc(d.server.replace(/-MariaDB.*$/, '')));
                html += '<p class="db-ov-sub">' + sub.join(' · ') + '</p>';
                if (d.tablesFor !== d.name) { html += '<div class="loading">Loading…</div>'; box.innerHTML = html; return; }
                if (d.error) { html += '<div class="mail-msg-error">' + esc(d.error) + '</div>'; box.innerHTML = html; return; }
                const wp = d.wp;
                if (wp) {
                    const stat = (k, v, title) => '<div class="db-ov-stat"' + (title ? ' title="' + esc(title) + '"' : '') + '><span class="k">' + k + '</span><span class="v">' + v + '</span></div>';
                    html += '<div class="db-ov-grid">'
                        + stat('site url', wp.siteurl ? '<a href="' + esc(wp.siteurl) + '" target="_blank" rel="noopener">' + esc(wp.siteurl.replace(/^https?:\/\//, '')) + '</a>' : '—', wp.siteurl)
                        + stat('home', wp.home ? '<a href="' + esc(wp.home) + '" target="_blank" rel="noopener">' + esc(wp.home.replace(/^https?:\/\//, '')) + '</a>' : '—', wp.home)
                        + stat('prefix', esc(wp.prefix))
                        + stat('theme', esc(wp.stylesheet || wp.template || '—'))
                        + stat('posts · users · comments', esc(this.formatCount(wp.posts)) + ' · ' + esc(this.formatCount(wp.users)) + ' · ' + esc(this.formatCount(wp.comments)))
                        + stat('options', esc(this.formatCount(wp.options)) + ' · ' + this.formatSize(wp.autoload_bytes) + ' autoloaded', wp.autoload_count + ' autoloaded options are read on every request')
                        + '</div>';
                    if (wp.largest && wp.largest.length) {
                        html += '<p class="db-ov-label">largest autoloaded options</p><ul class="db-ov-list" id="dbOvLargest">'
                            + wp.largest.map(o => '<li data-option="' + esc(o.name) + '" title="Open in ' + esc(wp.prefix) + 'options"><span>' + esc(o.name) + '</span><span>' + this.formatSize(o.bytes) + '</span></li>').join('')
                            + '</ul>';
                    }
                } else if (d.tables.length) {
                    html += '<p class="db-ov-sub">Not a WordPress database — pick a table on the left, or open the SQL console.</p>';
                } else {
                    html += '<p class="db-ov-sub">Empty database. The SQL console is the place to start.</p>';
                }
                box.innerHTML = html;
            },

            renderDbTable() {
                const d = this.db, r = d.rows;
                if (this.view !== 'db' || !d.table || d.sql) return;
                document.querySelectorAll('#dbParts .mail-part').forEach(b => {
                    b.classList.toggle('is-active', d.part === b.dataset.part);
                    b.setAttribute('aria-selected', d.part === b.dataset.part ? 'true' : 'false');
                });
                show($id('dbRowsSearch'), d.part === 'rows');
                show($id('btnDbRowsRefresh'), d.part === 'rows');
                show($id('dbGridWrap'), d.part === 'rows');
                show($id('dbStructure'), d.part === 'structure');
                // Column picker for the filter
                const sel = $id('dbRowsCol');
                const want = ['<option value="">any column</option>'].concat(r.columns.map(c => '<option value="' + this.escapeHtml(c.name) + '"' + (r.col === c.name ? ' selected' : '') + '>' + this.escapeHtml(c.name) + '</option>')).join('');
                if (sel.innerHTML !== want) sel.innerHTML = want;
                const note = $id('dbRowsNote');
                if (d.part === 'rows') {
                    note.textContent = r.error ? r.error : (!r.pk.length && r.columns.length ? 'read-only — no primary key' : (r.columns.length ? 'double-click a cell to edit' : ''));
                    note.style.color = r.error ? 'var(--danger)' : '';
                } else note.textContent = '';
                if (d.part === 'rows') this.renderDbGrid();
                else this.renderDbStructure();
            },

            dbCellHtml(v, col) {
                if (v === null) return { cls: 'is-null', text: 'NULL', title: '' };
                if (typeof v === 'object') {
                    if (v.t === 'bin') return { cls: 'is-bin', text: '0x' + v.hex + (v.len > 48 ? '…' : '') + ' (' + this.formatSize(v.len) + ')', title: 'Binary, ' + v.len + ' bytes' };
                    return { cls: '', text: v.text, title: this.formatSize(v.len) + ' — double-click to see it all' };
                }
                const num = col && /^(tiny|small|medium|big)?int|^(decimal|float|double|numeric|bit)/i.test(col.type || '');
                return { cls: num ? 'is-num' : '', text: String(v), title: String(v).length > 60 ? String(v).slice(0, 400) : '' };
            },

            renderDbGrid() {
                const d = this.db, r = d.rows, esc = (s) => this.escapeHtml(s);
                const grid = $id('dbGrid');
                if (r.loading) { grid.innerHTML = '<tbody><tr><td class="db-grid-empty">Loading rows…</td></tr></tbody>'; return; }
                if (!r.columns.length) { grid.innerHTML = r.error ? '' : '<tbody><tr><td class="db-grid-empty">No columns.</td></tr></tbody>'; return; }
                const editable = r.pk.length > 0;
                let html = '<thead><tr>' + r.columns.map(c =>
                    '<th data-col="' + esc(c.name) + '" title="' + esc(c.type + (c.null ? ', nullable' : '') + (c.extra ? ', ' + c.extra : '') + ' — click to sort') + '">'
                    + (r.pk.includes(c.name) ? '<span class="col-key" title="key">⚿</span>' : '') + esc(c.name)
                    + (r.sort === c.name ? '<span class="sort-arrow">' + (r.dir === 'asc' ? '↑' : '↓') + '</span>' : '')
                    + '<span class="col-type">' + esc(c.type) + '</span></th>').join('')
                    + (editable ? '<th class="db-row-actions" aria-hidden="true"></th>' : '') + '</tr></thead><tbody>';
                if (!r.items.length) {
                    html += '<tr><td class="db-grid-empty" colspan="' + (r.columns.length + 1) + '">' + (r.q ? 'No rows contain “' + esc(r.q) + '”.' : 'No rows.') + '</td></tr>';
                }
                r.items.forEach((row, ri) => {
                    html += '<tr data-row="' + ri + '">';
                    row.forEach((v, ci) => {
                        const ed = d.edit && d.edit.row === ri && d.edit.col === ci ? d.edit : null;
                        if (ed) {
                            html += '<td class="is-editing" data-row="' + ri + '" data-col="' + ci + '"><textarea class="db-edit" rows="' + Math.min(12, Math.max(1, (ed.value.match(/\n/g) || []).length + 1)) + '"' + (ed.busy ? ' disabled' : '') + '>' + esc(ed.value) + '</textarea><span class="db-edit-hint">↵ save · shift+↵ newline · esc cancel · ⌘⌫ NULL</span></td>';
                            return;
                        }
                        const cell = this.dbCellHtml(v, r.columns[ci]);
                        html += '<td class="' + cell.cls + (editable ? ' is-editable' : '') + '" data-row="' + ri + '" data-col="' + ci + '"' + (cell.title ? ' title="' + esc(cell.title) + '"' : '') + '>' + esc(cell.text) + '</td>';
                    });
                    if (editable) html += '<td class="db-row-actions"><button type="button" class="db-row-del' + (d.delArm === ri ? ' armed' : '') + '" data-row="' + ri + '" title="Delete this row">' + (d.delArm === ri ? 'sure?' : '×') + '</button></td>';
                    html += '</tr>';
                });
                grid.innerHTML = html + '</tbody>';
            },

            renderDbStructure() {
                const d = this.db, s = d.structure, esc = (s) => this.escapeHtml(s == null ? '' : String(s));
                const box = $id('dbStructure');
                if (!s || s.loading) { box.innerHTML = '<div class="loading">Loading structure…</div>'; return; }
                if (s.error) { box.innerHTML = '<div class="mail-msg-error">' + esc(s.error) + '</div>'; return; }
                let html = '<p class="db-ov-label">columns</p><table><thead><tr><th>name</th><th>type</th><th>null</th><th>key</th><th>default</th><th>extra</th><th>collation</th></tr></thead><tbody>';
                html += s.columns.map(c => '<tr><td>' + esc(c.name) + '</td><td>' + esc(c.type) + '</td><td>' + (c.null ? 'yes' : 'no') + '</td><td>' + esc(c.key) + '</td><td>' + (c.default === null ? '<span style="color: var(--text-faint); font-style: italic;">NULL</span>' : esc(c.default)) + '</td><td>' + esc(c.extra) + '</td><td>' + esc(c.collation) + '</td></tr>').join('');
                html += '</tbody></table>';
                if (s.indexes && s.indexes.length) {
                    html += '<p class="db-ov-label">indexes</p><table><thead><tr><th>name</th><th>columns</th><th>type</th></tr></thead><tbody>';
                    html += s.indexes.map(i => '<tr><td>' + esc(i.name) + '</td><td>' + esc(i.columns.join(', ')) + '</td><td>' + (i.unique ? 'unique · ' : '') + esc(i.type) + '</td></tr>').join('');
                    html += '</tbody></table>';
                }
                if (s.create) html += '<p class="db-ov-label">create table</p><pre>' + esc(s.create) + '</pre>';
                box.innerHTML = html;
            },

            renderDbSql() {
                const d = this.db, c = d.console, esc = (s) => this.escapeHtml(s == null ? '' : String(s));
                if (this.view !== 'db' || !d.sql) return;
                $id('dbSqlNote').textContent = d.name ? 'runs against ' + d.name : 'no database selected — qualify tables as database.table';
                const hist = this.dbHistory;
                const sel = $id('dbSqlHistory');
                sel.innerHTML = '<option value="">history</option>' + hist.map((h, i) => '<option value="' + i + '">' + esc(h.replace(/\s+/g, ' ').slice(0, 60)) + '</option>').join('');
                sel.disabled = hist.length === 0;
                const run = $id('btnDbRun');
                run.disabled = c.running;
                run.innerHTML = c.running ? 'running…' : 'run <span class="db-kbd">⌘↵</span>';
                const out = $id('dbSqlResults');
                if (!c.results) { out.innerHTML = ''; return; }
                let html = '';
                c.results.forEach((res, i) => {
                    if (res.type === 'error') {
                        html += '<div class="db-sql-result"><div class="db-sql-result-head is-error">' + esc(res.message) + '</div></div>';
                    } else if (res.type === 'ok') {
                        html += '<div class="db-sql-result"><div class="db-sql-result-head is-ok">' + res.affected + ' row' + (res.affected === 1 ? '' : 's') + ' affected' + (res.insert_id ? ' · insert id ' + res.insert_id : '') + (res.info ? ' · ' + esc(res.info) : '') + (i === c.results.length - 1 ? ' · ' + c.ms + ' ms' : '') + '</div></div>';
                    } else {
                        html += '<div class="db-sql-result"><div class="db-sql-result-head">' + res.total + ' row' + (res.total === 1 ? '' : 's') + (res.truncated ? ' · showing the first ' + res.rows.length : '') + (i === c.results.length - 1 ? ' · ' + c.ms + ' ms' : '') + '</div>';
                        html += '<div class="db-grid-wrap"><table class="db-grid"><thead><tr>' + res.columns.map(col => '<th style="cursor: default;">' + esc(col) + '</th>').join('') + '</tr></thead><tbody>';
                        if (!res.rows.length) html += '<tr><td class="db-grid-empty" colspan="' + res.columns.length + '">Empty result.</td></tr>';
                        for (const row of res.rows) {
                            html += '<tr>' + row.map(v => { const cell = this.dbCellHtml(v, null); return '<td class="' + cell.cls + '"' + (cell.title ? ' title="' + esc(cell.title) + '"' : '') + '>' + esc(cell.text) + '</td>'; }).join('') + '</tr>';
                        }
                        html += '</tbody></table></div></div>';
                    }
                });
                out.innerHTML = html;
            },

            renderDbFooter() {
                if (this.view !== 'db') return;
                const d = this.db, r = d.rows;
                let label = '';
                if (d.table && !d.sql) {
                    label = d.table + ' · ' + this.formatCount(r.total) + ' row' + (r.total === 1 ? '' : 's') + (r.q ? ' matching' : '');
                } else if (d.name) {
                    label = d.tablesFor === d.name ? d.tables.length + ' table' + (d.tables.length === 1 ? '' : 's') : '';
                } else {
                    label = d.list.length + ' database' + (d.list.length === 1 ? '' : 's') + (d.server ? ' · MariaDB ' + d.server.replace(/-MariaDB.*$/, '') : '');
                }
                $id('dbCount').textContent = label;
                const pager = $id('dbPager');
                const paged = !!d.table && !d.sql && r.total > r.limit;
                show(pager, paged);
                if (paged) {
                    $id('dbRange').textContent = (r.start + 1) + '–' + Math.min(r.start + r.limit, r.total);
                    $id('btnDbNewer').disabled = r.start === 0;
                    $id('btnDbOlder').disabled = r.start + r.limit >= r.total;
                }
            },

            formatCount(n) {
                if (n === null || n === undefined) return '—';
                return Number(n).toLocaleString();
            },

            bindDbEvents() {
                const filter = $id('dbFilter');
                filter.addEventListener('input', () => { this.db.filter = filter.value; this.renderDbChrome(); this.renderDbList(); });
                filter.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); this.db.filter = ''; filter.value = ''; filter.blur(); this.renderDbChrome(); this.renderDbList(); }
                    if (e.key === 'Enter') {
                        const first = this.dbVisibleList[0];
                        if (!first) return;
                        e.preventDefault();
                        if (this.db.name) this.openDbTable(first.name); else this.openDb(first.name);
                    }
                });
                $id('btnDbFilterClear').addEventListener('click', () => { this.db.filter = ''; filter.value = ''; this.renderDbChrome(); this.renderDbList(); filter.focus(); });
                $id('dbChipClear').addEventListener('click', () => this.closeDb());
                $id('btnDbSql').addEventListener('click', () => this.toggleDbSql());
                $id('dbList').addEventListener('click', (e) => {
                    const row = e.target.closest('.db-row');
                    if (!row) return;
                    if (this.db.name) this.openDbTable(row.dataset.name); else this.openDb(row.dataset.name);
                });
                $id('dbOverview').addEventListener('click', (e) => {
                    const li = e.target.closest('#dbOvLargest li');
                    if (!li || !this.db.wp) return;
                    this.openDbTable(this.db.wp.prefix + 'options', { q: li.dataset.option, col: 'option_name', force: true });
                });
                $id('dbParts').addEventListener('click', (e) => {
                    const b = e.target.closest('.mail-part');
                    if (b) this.setDbPart(b.dataset.part);
                });
                const rowsFilter = $id('dbRowsFilter');
                rowsFilter.addEventListener('input', () => {
                    const r = this.db.rows;
                    r.q = rowsFilter.value; r.start = 0;
                    clearTimeout(r.timer);
                    r.timer = setTimeout(() => this.loadDbRows(), 300);
                });
                rowsFilter.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter') { e.preventDefault(); clearTimeout(this.db.rows.timer); this.loadDbRows(); }
                    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); this.db.rows.q = ''; rowsFilter.value = ''; rowsFilter.blur(); this.db.rows.start = 0; this.loadDbRows(); }
                });
                $id('dbRowsCol').addEventListener('change', (e) => { this.db.rows.col = e.target.value; if (this.db.rows.q) { this.db.rows.start = 0; this.loadDbRows(); } });
                $id('btnDbRowsRefresh').addEventListener('click', () => { this.db.structure = null; this.loadDbRows(); });
                $id('btnDbNewer').addEventListener('click', () => this.dbPage(-1));
                $id('btnDbOlder').addEventListener('click', () => this.dbPage(1));

                const grid = $id('dbGrid');
                grid.addEventListener('click', (e) => {
                    const th = e.target.closest('th[data-col]');
                    if (th) { this.dbSort(th.dataset.col); return; }
                    const del = e.target.closest('.db-row-del');
                    if (del) { this.deleteDbRow(Number(del.dataset.row)); return; }
                });
                grid.addEventListener('dblclick', (e) => {
                    const td = e.target.closest('td.is-editable');
                    if (!td) return;
                    e.preventDefault();
                    this.startDbEdit(Number(td.dataset.row), Number(td.dataset.col));
                });
                grid.addEventListener('keydown', (e) => {
                    const ta = e.target.closest('.db-edit');
                    if (!ta) return;
                    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); this.db.edit.value = ta.value; this.saveDbEdit(false); }
                    else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); this.cancelDbEdit(); }
                    else if ((e.metaKey || e.ctrlKey) && e.key === 'Backspace') { e.preventDefault(); this.saveDbEdit(true); }
                });
                grid.addEventListener('input', (e) => { const ta = e.target.closest('.db-edit'); if (ta && this.db.edit) this.db.edit.value = ta.value; });
                grid.addEventListener('focusout', (e) => {
                    // Clicking away saves, the way a spreadsheet does. Esc and
                    // ↵ have already cleared or marked the edit by the time
                    // this fires, so they are not double-handled.
                    const ta = e.target.closest && e.target.closest('.db-edit');
                    if (!ta) return;
                    setTimeout(() => {
                        const ed = this.db.edit;
                        if (!ed || ed.busy || document.activeElement === ta) return;
                        ed.value = ta.value;
                        this.saveDbEdit(false);
                    }, 0);
                });

                $id('btnDbRun').addEventListener('click', () => this.runDbSql());
                $id('dbSqlText').addEventListener('input', (e) => { this.db.console.text = e.target.value; });
                $id('dbSqlHistory').addEventListener('change', (e) => {
                    const h = this.dbHistory[Number(e.target.value)];
                    if (h !== undefined) { $id('dbSqlText').value = h; this.db.console.text = h; }
                    e.target.value = '';
                    $id('dbSqlText').focus();
                });
            },

            // --- Logs --------------------------------------------------------
            // The files Cove already writes, parsed in the browser. The shared
            // PHP error log names the file each entry came from, which is how
            // it gets scoped to one site; a site also owns a debug.log and a
            // Caddy access log of its own.
            get logsSelection() {
                const l = this.logs;
                if (l.site) return { source: l.tab === 'debug' ? 'debug' : l.tab === 'access' ? 'access' : 'errors', site: l.site };
                return { source: l.source, site: '' };
            },

            loadLogSources() {
                const l = this.logs;
                if (l.sourcesPromise) return l.sourcesPromise;
                l.sourcesPromise = this.apiPost('log_sources', {}, { quiet: true, timeoutMs: 20000 }).then(res => {
                    l.sourcesPromise = null;
                    if (!res.success) return;
                    l.system = res.system || [];
                    l.sites = (res.sites || []).sort((a, b) => (b.mtime || 0) - (a.mtime || 0) || a.name.localeCompare(b.name));
                    l.dir = res.dir || '';
                    l.sourcesLoaded = true;
                    this.renderLogsSide();
                });
                return l.sourcesPromise;
            },

            // A site's PHP errors live in its own debug.log when WordPress
            // has WP_DEBUG_LOG on (PHP's error_log is pointed there), and in
            // the shared error log otherwise. With no tab asked for, open
            // whichever one this site actually writes to.
            async pickLogsTab() {
                const l = this.logs;
                if (!l.site || l.tab) return;
                if (!l.sourcesLoaded) await this.loadLogSources();
                const meta = l.sites.find(x => x.name === l.site);
                l.tab = meta && meta.debug ? 'debug' : 'errors';
                this.syncUrl({ replace: true });
                this.renderLogsBar();
            },

            async loadLogs(opts = {}) {
                const l = this.logs;
                const seq = ++l.seq;
                if (l.site && !l.tab) { await this.pickLogsTab(); if (seq !== l.seq) return; }
                const sel = this.logsSelection;
                if (!opts.older) { l.entries = []; l.nextBefore = null; l.scanned = 0; l.expanded = {}; l.newIds = {}; }
                l.loading = true; l.error = null;
                this.renderLogsList();
                const res = await this.apiPost('log_read', { source: sel.source, site: sel.site, before: opts.older ? l.nextBefore : null }, { quiet: true, timeoutMs: 60000 });
                if (seq !== l.seq) return;
                l.loading = false;
                if (!res.success) { l.error = res.message || 'Could not read that log.'; this.renderLogsList(); this.renderLogsFooter(); return; }
                const parsed = (res.entries || []).map(raw => this.parseLogEntry(raw, res.kind)).reverse(); // newest first
                l.entries = opts.older ? l.entries.concat(parsed) : parsed;
                if (!opts.older) l.size = res.size || 0;
                l.nextBefore = res.next_before ?? null;
                l.scanned += res.scanned || 0;
                l.path = res.path || ''; l.kind = res.kind || 'php'; l.missing = !!res.missing;
                this.renderLogsList();
                this.renderLogsBar();
                this.renderLogsFooter();
            },

            // Live tail: only what was appended since the last read.
            async pollLogs() {
                const l = this.logs;
                if (this.view !== 'logs' || !l.live || document.hidden || l.loading) return;
                const sel = this.logsSelection;
                const seq = l.seq;
                const res = await this.apiPost('log_read', { source: sel.source, site: sel.site, since: l.size }, { quiet: true, timeoutMs: 20000 });
                if (seq !== l.seq || !res.success) return;
                if ((res.size || 0) < l.size) { this.loadLogs(); return; } // cleared underneath us
                l.size = res.size || l.size;
                if (!res.entries || !res.entries.length) return;
                const fresh = res.entries.map(raw => this.parseLogEntry(raw, res.kind)).reverse();
                fresh.forEach(e => { l.newIds[e.id] = true; });
                l.entries = fresh.concat(l.entries);
                l.missing = false;
                this.renderLogsList();
                this.renderLogsFooter();
                setTimeout(() => { fresh.forEach(e => delete l.newIds[e.id]); }, 1000);
            },

            startLogsPolling() {
                if (this.logs.pollTimer) return;
                this.logs.pollTimer = setInterval(() => this.pollLogs(), 4000);
            },

            stopLogsPolling() {
                clearInterval(this.logs.pollTimer);
                this.logs.pollTimer = null;
            },

            setLogsSource(key) {
                const l = this.logs;
                l.site = null; l.source = key;
                this.syncUrl();
                this.renderLogsSide();
                this.loadLogs();
            },

            setLogsSite(name, tab) {
                const l = this.logs;
                l.site = name || null;
                l.tab = tab && ['errors', 'debug', 'access'].includes(tab) ? tab : null;
                this.syncUrl();
                this.renderLogsChrome();
                this.renderLogsSide();
                this.loadLogs();
            },

            openLogsForSite(name) {
                this.logs.site = name;
                this.logs.tab = null;
                this.setView('logs', { force: true });
            },

            logsClearFilters() {
                const l = this.logs;
                l.query = ''; l.level = 'all';
                $id('logsSearch').value = '';
                this.renderLogsChrome();
                this.renderLogsList();
                this.renderLogsFooter();
            },

            async clearLog() {
                const l = this.logs;
                if (!l.clearArm) {
                    l.clearArm = true;
                    clearTimeout(l.armTimer);
                    l.armTimer = setTimeout(() => { l.clearArm = false; this.renderLogsChrome(); }, 3500);
                    this.renderLogsChrome();
                    return;
                }
                l.clearArm = false;
                clearTimeout(l.armTimer);
                const sel = this.logsSelection;
                const res = await this.apiPost('log_clear', { source: sel.source, site: sel.site }, { timeoutMs: 20000 });
                this.renderLogsChrome();
                if (!res.success) return;
                this.showSnack('Log cleared.');
                this.loadLogs();
                this.loadLogSources();
            },

            // One entry → { id, ts, level, msg, file, line, site, detail, raw }.
            // level ∈ error | warning | deprecated | notice | info | log.
            parseLogEntry(raw, kind) {
                const e = { id: '', ts: null, level: 'log', msg: raw, file: '', line: '', site: null, detail: '', raw };
                const firstNl = raw.indexOf('\n');
                const head = firstNl === -1 ? raw : raw.slice(0, firstNl);
                const rest = firstNl === -1 ? '' : raw.slice(firstNl + 1);
                if (kind === 'caddy') {
                    try {
                        const j = JSON.parse(raw);
                        e.ts = typeof j.ts === 'number' ? j.ts : null;
                        e.level = { error: 'error', warn: 'warning', info: 'info', debug: 'notice' }[j.level] || 'log';
                        if (j.request) {
                            const r = j.request;
                            const ms = typeof j.duration === 'number' ? Math.round(j.duration * 1000) + ' ms' : '';
                            e.msg = (r.method || '') + ' ' + (r.uri || '') + ' → ' + (j.status || '') + (ms ? ' · ' + ms : '');
                            e.file = r.host || '';
                            if (j.status >= 500) e.level = 'error'; else if (j.status >= 400) e.level = 'warning';
                            const sm = /^([a-z0-9-]+)\.localhost/i.exec(r.host || '');
                            if (sm) e.site = sm[1].toLowerCase();
                        } else {
                            e.msg = (j.msg || head) + (j.logger ? '' : '');
                            e.file = j.logger || '';
                        }
                        e.detail = JSON.stringify(j, null, 2);
                    } catch (err) { e.msg = head; e.detail = rest; }
                } else {
                    const m = /^\[([^\]]+)\]\s?(.*)$/s.exec(head);
                    let body = head;
                    if (m) {
                        const t = Date.parse(m[1].replace(/^(\d{2})-([A-Za-z]{3})-(\d{4})/, '$1 $2 $3'));
                        e.ts = isNaN(t) ? null : t / 1000;
                        body = m[2];
                    }
                    const pm = /^PHP (Fatal error|Parse error|Warning|Notice|Deprecated|Recoverable fatal error|Strict Standards|Core Warning|Compile Error|User Error|User Warning|User Notice|User Deprecated):\s+(.*?)(?: in (\S+?)(?::(\d+))?(?: on line (\d+))?)?$/s.exec(body);
                    if (pm) {
                        const lv = pm[1].toLowerCase();
                        e.level = /fatal|parse|compile|user error/.test(lv) ? 'error' : /warning/.test(lv) ? 'warning' : /deprecated/.test(lv) ? 'deprecated' : 'notice';
                        e.msg = pm[2]; e.file = pm[3] || ''; e.line = pm[5] || pm[4] || '';
                    } else if (kind === 'plain') {
                        e.msg = body.replace(/^watchdog:\s*/, '');
                        e.level = /fail|error|kill|crash/i.test(body) ? 'warning' : 'info';
                    } else {
                        // error_log() from application code, or WP's own lines.
                        const wm = /^(.*?)(?: in (\/\S+?)(?: on line (\d+))?)?$/s.exec(body);
                        e.msg = wm ? wm[1] : body; e.file = (wm && wm[2]) || ''; e.line = (wm && wm[3]) || '';
                        e.level = /fatal|uncaught|error/i.test(body) ? 'error' : /warn/i.test(body) ? 'warning' : 'log';
                    }
                    e.detail = rest;
                    const sm = /\/Sites\/([a-z0-9-]+)\.localhost\//i.exec(raw);
                    if (sm) e.site = sm[1].toLowerCase();
                }
                e.id = (e.ts || 0) + '|' + e.level + '|' + e.msg + '|' + e.file + '|' + e.line;
                return e;
            },

            logFileLabel(e) {
                if (!e.file) return '';
                let f = e.file;
                const m = /\/Sites\/[a-z0-9-]+\.localhost\/(?:public\/)?(.*)$/i.exec(f);
                if (m) f = m[1];
                else if (this.logs.dir && f.startsWith(this.logs.dir)) f = f.slice(this.logs.dir.length + 1);
                return f + (e.line ? ':' + e.line : '');
            },

            // Visible entries: level + search applied, then consecutive
            // duplicates folded into one row with a count.
            get logsVisible() {
                const l = this.logs;
                const q = l.query.trim().toLowerCase();
                const out = [];
                for (const e of l.entries) {
                    if (l.level === 'error' && e.level !== 'error') continue;
                    if (l.level === 'warning' && e.level !== 'warning') continue;
                    if (l.level === 'deprecated' && e.level !== 'deprecated' && e.level !== 'notice') continue;
                    if (q && !(e.msg + ' ' + e.file + ' ' + (e.site || '')).toLowerCase().includes(q)) continue;
                    const last = out[out.length - 1];
                    if (last && last.level === e.level && last.msg === e.msg && last.file === e.file && last.line === e.line) { last.count++; continue; }
                    out.push(Object.assign({ count: 1 }, e));
                }
                return out;
            },

            renderLogs() {
                if (this.view !== 'logs') return;
                this.renderLogsChrome();
                this.renderLogsSide();
                this.renderLogsBar();
                this.renderLogsList();
                this.renderLogsFooter();
            },

            renderLogsChrome() {
                const l = this.logs;
                this.renderViewBack('logsBack', l.site);
                show($id('logsSiteChip'), !!l.site);
                if (l.site) $id('logsSiteChipLabel').textContent = l.site;
                const active = !!(l.query || l.level !== 'all');
                show($id('logsKbd'), !active);
                show($id('btnLogsSearchClear'), active);
                document.querySelectorAll('#logsLevels .log-level').forEach(b => b.classList.toggle('is-active', b.dataset.level === l.level));
                const clear = $id('btnLogsClear');
                clear.classList.toggle('armed', l.clearArm);
                clear.textContent = l.clearArm ? 'sure? clear it' : 'clear log';
                clear.title = l.site && l.tab === 'errors' ? 'Empties the shared PHP error log — every site\'s entries, not just this one' : 'Empty this log file';
                clear.disabled = l.missing || (!l.size && !l.entries.length);
                $id('logsLive').checked = l.live;
                $id('logsLiveDot').classList.toggle('is-live', l.live);
                $id('logsLiveDot').title = l.live ? 'Following — new entries appear as they are written' : 'Paused';
            },

            renderLogsSide() {
                const l = this.logs;
                const sys = $id('logsSystem');
                sys.querySelectorAll('.db-row').forEach(n => n.remove());
                const tpl = $id('tpl-log-source');
                for (const s of l.system) {
                    const row = tpl.content.firstElementChild.cloneNode(true);
                    row.dataset.source = s.key;
                    row.classList.toggle('is-selected', !l.site && l.source === s.key);
                    row.classList.toggle('is-quiet', !s.size);
                    row.querySelector('.db-row-name').textContent = s.label;
                    row.querySelector('.db-row-meta').textContent = s.size ? this.formatSize(s.size) : '';
                    row.querySelector('.db-row-meta').title = s.mtime ? 'Last written ' + new Date(s.mtime * 1000).toLocaleString() : '';
                    sys.appendChild(row);
                }
                const list = $id('logsSites');
                list.querySelectorAll('.db-row').forEach(n => n.remove());
                show($id('logsSitesLoading'), !l.sourcesLoaded);
                const q = l.siteFilter.trim().toLowerCase();
                const rows = l.sites.filter(s => !q || s.name.includes(q));
                show($id('logsSitesEmpty'), l.sourcesLoaded && rows.length === 0);
                const anchor = $id('logsSitesLoading');
                for (const s of rows) {
                    const row = tpl.content.firstElementChild.cloneNode(true);
                    row.dataset.site = s.name;
                    row.classList.toggle('is-selected', l.site === s.name);
                    row.classList.toggle('is-quiet', !s.debug && !s.access);
                    row.querySelector('.db-row-name').textContent = s.name;
                    row.querySelector('.db-row-meta').textContent = s.mtime ? this.formatRelative(s.mtime) : '';
                    row.querySelector('.db-row-meta').title = (s.debug ? 'debug.log ' + this.formatSize(s.debug) : 'no debug.log') + ' · ' + (s.access ? 'access log ' + this.formatSize(s.access) : 'no access log');
                    list.insertBefore(row, anchor);
                }
                if (l.site && l.scrolledFor !== l.site) {
                    const sel = list.querySelector('.db-row.is-selected');
                    if (sel) { l.scrolledFor = l.site; sel.scrollIntoView({ block: 'nearest' }); }
                }
            },

            renderLogsBar() {
                const l = this.logs;
                show($id('logsParts'), !!l.site);
                if (l.site) {
                    const meta = l.sites.find(s => s.name === l.site);
                    document.querySelectorAll('#logsParts .mail-part').forEach(b => {
                        const t = b.dataset.tab;
                        b.classList.toggle('is-active', l.tab === t);
                        b.setAttribute('aria-selected', l.tab === t ? 'true' : 'false');
                        if (meta && t === 'debug') b.style.opacity = meta.debug ? '' : '0.5';
                        if (meta && t === 'access') b.style.opacity = meta.access ? '' : '0.5';
                    });
                }
                const p = $id('logsPath');
                p.textContent = l.path ? l.path.replace(/^\/Users\/[^\/]+|^\/home\/[^\/]+/, '~') : '';
                p.dataset.path = l.path || '';
            },

            renderLogsList() {
                const l = this.logs;
                const list = $id('logsList');
                list.querySelectorAll('.log-row').forEach(n => n.remove());
                const rows = l.loading && !l.entries.length ? [] : this.logsVisible;
                show($id('logsLoading'), l.loading && !l.entries.length);
                show($id('logsError'), !l.loading && !!l.error);
                if (l.error) $id('logsErrorText').textContent = l.error;
                const empty = !l.loading && !l.error && rows.length === 0;
                show($id('logsEmpty'), empty);
                if (empty) {
                    const filtered = l.entries.length > 0;
                    $id('logsEmptyText').textContent = l.missing ? 'No log file yet.' : filtered ? 'Nothing matches.' : (l.site && l.tab === 'errors' ? 'No PHP errors mention this site.' : 'Nothing logged.');
                    const meta = l.site ? l.sites.find(x => x.name === l.site) : null;
                    $id('logsEmptyHint').textContent = l.missing
                        ? (l.tab === 'debug' ? 'Set WP_DEBUG and WP_DEBUG_LOG in wp-config.php and WordPress will write one.' : '')
                        : filtered ? 'Press Esc to clear the filters.'
                        : (l.site && l.tab === 'errors' && meta && meta.debug) ? 'This site keeps its PHP errors in its own debug.log — see the debug.log tab.'
                        : (l.scanned ? 'Looked through the last ' + this.formatSize(l.scanned) + '.' : '');
                }
                const tpl = $id('tpl-log-row');
                const anchor = $id('logsLoading');
                const frag = document.createDocumentFragment();
                for (const e of rows) {
                    const row = tpl.content.firstElementChild.cloneNode(true);
                    row.dataset.id = e.id;
                    const open = !!l.expanded[e.id];
                    row.classList.toggle('is-collapsed', !open);
                    row.classList.toggle('is-new', !!l.newIds[e.id]);
                    const t = row.querySelector('.log-time');
                    t.textContent = e.ts ? this.formatRelative(e.ts) : '—';
                    t.title = e.ts ? new Date(e.ts * 1000).toLocaleString() : '';
                    const chip = row.querySelector('.log-level-chip');
                    chip.textContent = e.level === 'log' ? 'log' : e.level;
                    chip.classList.add(e.level);
                    row.querySelector('.log-msg').textContent = e.msg;
                    const site = row.querySelector('.log-site');
                    if (e.site && !l.site) { site.textContent = e.site; site.title = 'Only entries for ' + e.site + '.localhost'; }
                    else site.remove();
                    const file = row.querySelector('.log-file');
                    const fl = this.logFileLabel(e);
                    // An access log scoped to a site names that site's host on
                    // every row; drop it there.
                    if (fl && !(l.site && l.kind === 'caddy' && e.file === l.site + '.localhost')) { file.textContent = fl; file.title = e.file + (e.line ? ':' + e.line : ''); } else file.remove();
                    const count = row.querySelector('.log-count');
                    if (e.count > 1) { count.textContent = '×' + e.count; count.title = 'Repeated ' + e.count + ' times in a row'; } else count.remove();
                    const detail = row.querySelector('.log-detail');
                    const text = e.detail || (e.raw !== e.msg ? e.raw : '');
                    if (open && text) { detail.textContent = text; show(detail, true); } else detail.remove();
                    frag.appendChild(row);
                }
                list.insertBefore(frag, anchor);
            },

            renderLogsFooter() {
                if (this.view !== 'logs') return;
                const l = this.logs;
                const shown = this.logsVisible.length;
                let label = '';
                if (!l.error) {
                    label = l.entries.length + ' entr' + (l.entries.length === 1 ? 'y' : 'ies');
                    const filtered = !!(l.query || l.level !== 'all');
                    if (filtered) label = shown + ' of ' + label;
                    else if (shown !== l.entries.length) label += ' · ' + (l.entries.length - shown) + ' repeat' + (l.entries.length - shown === 1 ? '' : 's') + ' folded';
                    if (l.size) label += ' · ' + (l.scanned && l.scanned < l.size ? 'last ' + this.formatSize(l.scanned) + ' of ' : '') + this.formatSize(l.size);
                }
                $id('logsCount').textContent = label;
                show($id('btnLogsOlder'), !!l.nextBefore && !l.loading);
            },

            bindLogsEvents() {
                const search = $id('logsSearch');
                search.addEventListener('input', () => { this.logs.query = search.value; this.renderLogsChrome(); this.renderLogsList(); this.renderLogsFooter(); });
                search.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); this.logs.query = ''; search.value = ''; search.blur(); this.renderLogsChrome(); this.renderLogsList(); this.renderLogsFooter(); }
                });
                $id('btnLogsSearchClear').addEventListener('click', () => { this.logsClearFilters(); search.focus(); });
                $id('logsLevels').addEventListener('click', (e) => {
                    const b = e.target.closest('.log-level');
                    if (!b) return;
                    this.logs.level = b.dataset.level;
                    this.renderLogsChrome(); this.renderLogsList(); this.renderLogsFooter();
                });
                $id('logsSiteChipClear').addEventListener('click', () => this.setLogsSite(null));
                $id('logsLive').addEventListener('change', (e) => { this.logs.live = e.target.checked; this.renderLogsChrome(); if (this.logs.live) this.pollLogs(); });
                $id('btnLogsRefresh').addEventListener('click', () => { this.loadLogs(); this.loadLogSources(); });
                $id('btnLogsClear').addEventListener('click', () => this.clearLog());
                $id('btnLogsOlder').addEventListener('click', () => this.loadLogs({ older: true }));
                const siteFilter = $id('logsSiteFilter');
                siteFilter.addEventListener('input', () => { this.logs.siteFilter = siteFilter.value; this.renderLogsSide(); });
                siteFilter.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); this.logs.siteFilter = ''; siteFilter.value = ''; siteFilter.blur(); this.renderLogsSide(); }
                    if (e.key === 'Enter') {
                        const q = this.logs.siteFilter.trim().toLowerCase();
                        const first = this.logs.sites.find(s => !q || s.name.includes(q));
                        if (first) { e.preventDefault(); this.setLogsSite(first.name); }
                    }
                });
                $id('logsSystem').addEventListener('click', (e) => {
                    const row = e.target.closest('.db-row');
                    if (row) this.setLogsSource(row.dataset.source);
                });
                $id('logsSites').addEventListener('click', (e) => {
                    const row = e.target.closest('.db-row');
                    if (row) this.setLogsSite(row.dataset.site);
                });
                $id('logsParts').addEventListener('click', (e) => {
                    const b = e.target.closest('.mail-part');
                    if (b) this.setLogsSite(this.logs.site, b.dataset.tab);
                });
                $id('logsPath').addEventListener('click', (e) => {
                    const p = e.currentTarget.dataset.path;
                    if (!p) return;
                    navigator.clipboard.writeText(p).then(() => this.showSnack('Path copied.')).catch(() => this.showSnack('Could not copy.', true));
                });
                $id('logsList').addEventListener('click', (e) => {
                    const row = e.target.closest('.log-row');
                    if (!row) return;
                    const chip = e.target.closest('.log-site');
                    if (chip) { this.setLogsSite(chip.textContent, 'errors'); return; }
                    if (window.getSelection && window.getSelection().toString()) return;
                    const id = row.dataset.id;
                    if (this.logs.expanded[id]) delete this.logs.expanded[id]; else this.logs.expanded[id] = true;
                    this.renderLogsList();
                });
                document.addEventListener('visibilitychange', () => { if (!document.hidden && this.view === 'logs') this.pollLogs(); });
            },

            // --- Site page ---------------------------------------------------
            // One site, on its own page: what it is, where its views are,
            // the sites on its network (with a login per subsite), and the
            // management actions the row menu offers. Reached by clicking a
            // row; /site/<name> is its address.
            // "← site.localhost" above a view's title while it is scoped to a site.
            renderViewBack(id, name) {
                const b = $id(id);
                show(b, !!name);
                if (name) { b.textContent = '← ' + name + '.localhost'; b.title = 'Back to ' + name + '.localhost'; }
            },

            get pageSite() { return this.sites.find(s => s.name === this.sitePage.name) || null; },

            openSitePage(name) {
                if (name !== this.sitePage.name) this.sitePage.tab = 'overview';
                this.sitePage.name = name;
                this.setView('site', { force: true });
            },

            renderSitePage() {
                if (this.view !== 'site') return;
                const p = this.sitePage;
                const site = this.pageSite;
                $id('siteTitle').textContent = (p.name || '') + '.localhost';
                if (!site) {
                    // Renamed or deleted out from under the page, or the list
                    // has not landed yet.
                    if (!this.isLoading && this.sites.length) { this.setView('sites'); return; }
                    $id('siteFacts').textContent = '';
                    return;
                }
                const isWp = site.type === 'WordPress';
                const facts = $id('siteFacts');
                facts.innerHTML = '';
                const fact = (text, cls, title) => { const s = document.createElement('span'); s.className = 'fact' + (cls ? ' ' + cls : ''); s.textContent = text; if (title) s.title = title; facts.appendChild(s); return s; };
                const type = fact(isWp ? 'wordpress' : 'static', 'fact-type site-type ' + (isWp ? 'wp' : 'static'));
                type.dataset.type = site.type;
                if (isWp && site.wp_version) fact(site.wp_version, 'fact-ver' + (site.wp_status === 'insecure' ? ' insecure' : ''), site.wp_status === 'insecure' ? 'wp.org marks this version insecure' : (site.wp_status === 'outdated' ? 'A newer WordPress is available' : ''));
                if (site.multisite) fact('multisite · ' + site.multisite, 'fact-ms');
                const effPhp = site.php_version || (this.phpInfo && this.phpInfo.default) || '';
                if (isWp && effPhp) fact('php ' + effPhp, '', site.php_version ? 'Pinned with cove php' : 'Cove\'s default PHP');
                if (site.size_bytes) fact(this.formatSize(site.size_bytes), '', 'On disk');
                if (site.modified_at) { const rel = this.formatRelative(site.modified_at); fact(rel === 'now' ? 'modified just now' : 'modified ' + rel + ' ago', '', new Date(site.modified_at * 1000).toLocaleString()); }
                const path = fact(site.display_path, 'fact-path', 'Click to copy the path');
                path.dataset.path = site.full_path;
                $id('siteOpenLink').href = site.domain;
                this.renderSiteShot(site);
                const login = $id('btnSiteLogin');
                show(login, isWp);
                login.disabled = !!site.isLoggingIn;
                login.querySelector('.btn-label').textContent = site.isLoggingIn ? 'opening…' : 'log in to admin';
                show($id('tileDb'), isWp);
                show($id('siteNetwork'), !!site.multisite);
                if (site.multisite) {
                    // A deep link renders before the sites list lands; fetch
                    // the network once the site is known.
                    if (p.net.loadedFor !== site.name && !p.net.loading) this.loadSiteNetwork();
                    const n = p.net.loadedFor === site.name ? p.net.items.length : 0;
                    $id('siteNetworkMeta').textContent = site.multisite + (n ? ' · ' + n + ' site' + (n === 1 ? '' : 's') : '');
                    this.renderSiteNetwork();
                }
                const domains = (site.mappings || []).length + (site.multisite === 'subdomain' ? 1 : 0);
                $id('spDomainsMeta').textContent = domains ? String(domains) : '';
                show($id('spPhp'), isWp && (!this.phpInfo || this.phpInfo.supported !== false));
                $id('spPhpMeta').textContent = effPhp ? effPhp : '';
                $id('spReveal').querySelector('.pill-label').textContent = this.revealLabel.toLowerCase();
                $id('spPin').querySelector('.pill-label').textContent = this.isPinned(site.name) ? 'unpin' : 'pin to top';
                // Tabs: WordPress only; a static site has just the overview.
                if (!isWp && p.tab !== 'overview' && p.tab !== 'snapshots' && p.tab !== 'traffic' && p.tab !== 'history') { p.tab = 'overview'; this.syncUrl({ replace: true }); }
                show($id('siteTabs'), true);
                document.querySelectorAll('#siteTabs .mail-part').forEach(b => { const on = b.dataset.tab === p.tab; b.classList.toggle('is-active', on); b.setAttribute('aria-selected', on ? 'true' : 'false'); show(b, isWp || ['overview', 'snapshots', 'traffic', 'history'].includes(b.dataset.tab)); });
                for (const tb of this.siteTabs) show($id('sitePanel-' + tb), p.tab === tb);
                this.renderSiteTab();
            },

            // The front-page preview: shown from the cache at once, recaptured
            // in the background when the site changed since (or a day passed),
            // and on demand from the refresh button.
            renderSiteShot(site) {
                const s = this.sitePage.shot;
                const a = $id('siteShot');
                const img = $id('siteShotImg');
                a.href = site.domain;
                const has = !!site.shot_mtime;
                const src = has ? '/api.php?action=site_shot&site=' + encodeURIComponent(site.name) + '&v=' + site.shot_mtime : '';
                if (img.getAttribute('src') !== src) { if (src) img.src = src; else img.removeAttribute('src'); }
                show(img, has);
                const busy = s.busy === site.name;
                const stale = has && ((site.modified_at && site.modified_at > site.shot_mtime) || (Date.now() / 1000 - site.shot_mtime > 86400));
                a.classList.toggle('is-busy', busy);
                a.classList.toggle('is-stale', stale && !busy);
                const empty = $id('siteShotEmpty');
                show(empty, !has);
                empty.textContent = busy ? 'capturing…' : s.unsupported ? 'Previews need Chrome, Chromium, Brave, Edge, Arc, or Vivaldi' : (s.asked[site.name] === 'failed' ? 'The capture failed — is the site answering?' : 'no preview yet');
                $id('siteShotAge').textContent = busy ? 'capturing…' : has ? 'captured ' + (this.formatRelative(site.shot_mtime) === 'now' ? 'just now' : this.formatRelative(site.shot_mtime) + ' ago') + (stale ? ' · site changed since' : '') : '';
                const btn = $id('btnSiteShot');
                btn.disabled = busy || s.unsupported;
                btn.textContent = busy ? 'capturing…' : has ? 'refresh' : 'capture';
                if (!busy && !s.unsupported && !s.asked[site.name] && (!has || stale)) this.refreshSiteShot(site.name, true);
            },

            // --- Traffic tab --------------------------------------------------
            // Aggregates from the site's Caddy access log, plus PHP error
            // and mail counts for the same window.
            async loadTraffic(opts = {}) {
                const site = this.pageSite;
                if (!site) return;
                const t = this.siteTabState('traffic');
                if (!t.range) t.range = '24h';
                const key = site.name + '\0' + t.range;
                if (t.loadedFor === key && !opts.force) return;
                if (t.loadedFor !== key) { t.data = null; t.loadedFor = null; }
                t.loading = true; t.error = null;
                this.renderTraffic();
                const [res, mail] = await Promise.all([
                    this.apiPost('site_traffic', { site_name: site.name, range: t.range }, { quiet: true, timeoutMs: 120000 }),
                    this.mailCountFor(site.name, t.range),
                ]);
                if (this.sitePage.name !== site.name) return;
                t.loading = false;
                if (!res.success) t.error = res.message || 'Could not read the access log.';
                else { t.data = res; t.data.mail = mail; t.loadedFor = key; }
                this.renderTraffic();
            },

            // Mail this site sent in the window, from Mailpit. Its search
            // filters by day, so the count is over whole days.
            async mailCountFor(name, range) {
                const days = range === '24h' ? 1 : range === '7d' ? 7 : 3650;
                const d = new Date(Date.now() - days * 86400000);
                const after = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
                try {
                    const r = await this.mailApi('/v1/search?query=' + encodeURIComponent('to:@' + name + '.localhost after:' + after) + '&limit=1');
                    return r && typeof r.messages_count === 'number' ? r.messages_count : null;
                } catch (e) { return null; }
            },

            setTrafficRange(range) {
                const t = this.siteTabState('traffic');
                t.range = range;
                this.renderTraffic();
                this.loadTraffic();
            },

            renderTraffic() {
                if (this.view !== 'site' || this.sitePage.tab !== 'traffic') return;
                const t = this.siteTabState('traffic');
                const site = this.pageSite;
                const panel = $id('sitePanel-traffic');
                panel.querySelectorAll('.st-status').forEach(b => b.classList.toggle('is-active', b.dataset.range === (t.range || '24h')));
                panel.querySelector('.st-refresh').disabled = t.loading;
                const body = $id('trafficBody');
                const count = panel.querySelector('.st-count');
                const d = t.data;
                if (t.loading && !d) { body.innerHTML = '<div class="tr-empty">Reading the access log…</div>'; count.textContent = ''; return; }
                if (t.error) { body.innerHTML = '<div class="tr-empty">' + this.escapeHtml(t.error) + '</div>'; count.textContent = ''; return; }
                if (!d) { body.innerHTML = ''; count.textContent = ''; return; }
                const esc = (s) => this.escapeHtml(s == null ? '' : String(s));
                const fmtN = (n) => (n == null ? '—' : Number(n).toLocaleString());
                const rangeLabel = { '24h': 'last 24 hours', '7d': 'last 7 days', all: 'whole log' }[t.range || '24h'];
                count.textContent = (d.has_log ? fmtN(d.requests) + ' requests · ' + rangeLabel + (d.complete ? '' : ' · first ' + this.formatSize(d.scanned) + ' of ' + this.formatSize(d.log_size)) : 'no access log yet');
                if (!d.has_log || !d.requests) {
                    body.innerHTML = '<div class="tr-empty">' + (d.has_log ? 'No requests in the ' + esc(rangeLabel) + '.' : 'Nothing has been served yet — the access log appears with the first request.') + '</div>';
                    return;
                }
                const k = d.kinds || {};
                const tile = (label, value, sub, cls) => '<div class="tr-tile' + (cls ? ' ' + cls : '') + '"' + (sub ? ' data-tip="' + esc(sub) + '"' : '') + '><span class="tr-tile-v">' + value + '</span><span class="tr-tile-l">' + esc(label) + '</span>' + (sub ? '<span class="tr-tile-s">' + sub + '</span>' : '') + '</div>';
                const errors = (d.status['5xx'] || 0);
                const tiles = [
                    tile('requests', fmtN(d.requests), fmtN(k.page || 0) + ' pages · ' + fmtN(k.asset || 0) + ' assets'),
                    tile('page views', fmtN(k.page || 0), fmtN(k.admin || 0) + ' admin · ' + fmtN(k.rest || 0) + ' rest · ' + fmtN(k.ajax || 0) + ' ajax'),
                    tile('server errors', fmtN(errors), fmtN(d.status['4xx'] || 0) + ' × 4xx · ' + fmtN(d.status['3xx'] || 0) + ' × 3xx', errors ? 'is-bad' : ''),
                    tile('php errors', fmtN(d.php_errors), 'error log + debug.log', d.php_errors ? 'is-warn' : ''),
                    tile('response time', d.avg_ms != null ? esc(d.avg_ms) + ' ms' : '—', d.p95_ms != null ? 'p95 ' + esc(d.p95_ms) + ' ms · max ' + esc(d.max_ms) + ' ms' : ''),
                    tile('served', this.formatSize(d.bytes), (d.last_cron ? 'cron ran ' + (this.formatRelative(d.last_cron) === 'now' ? 'just now' : this.formatRelative(d.last_cron) + ' ago') : 'cron not seen')),
                    tile('mail sent', d.mail == null ? '—' : fmtN(d.mail), d.mail == null ? 'Mailpit did not answer' : 'by whole days'),
                ].join('');
                // Bars: one per bucket, empty buckets filled in so gaps show.
                const buckets = d.buckets || [];
                const step = d.bucket || 3600;
                let bars = '';
                if (buckets.length) {
                    const startT = (t.range || '24h') === 'all' ? buckets[0].t : Math.floor((Date.now() / 1000 - (t.range === '7d' ? 604800 : 86400)) / step) * step;
                    const endT = Math.floor(Date.now() / 1000 / step) * step;
                    const byT = {}; buckets.forEach(b => { byT[b.t] = b; });
                    const all = [];
                    for (let x = startT; x <= endT; x += step) all.push(byT[x] || { t: x, n: 0, err: 0, pages: 0 });
                    const max = Math.max(1, ...all.map(b => b.n));
                    const label = (ts) => { const dt = new Date(ts * 1000); return step >= 86400 ? dt.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : dt.toLocaleString(undefined, { month: 'short', day: 'numeric', hour: 'numeric' }); };
                    bars = '<div class="tr-chart" style="--n:' + all.length + '">' + all.map(b => {
                        const h = Math.round(b.n / max * 100);
                        const eh = b.n ? Math.round(b.err / b.n * h) : 0;
                        return '<div class="tr-bar" data-tip="' + esc(label(b.t)) + ' — ' + fmtN(b.n) + ' request' + (b.n === 1 ? '' : 's') + (b.err ? ', ' + fmtN(b.err) + ' × 5xx' : '') + (b.pages ? '\n' + fmtN(b.pages) + ' page view' + (b.pages === 1 ? '' : 's') : '') + '"><span class="tr-bar-fill" style="height:' + h + '%"></span>' + (eh ? '<span class="tr-bar-err" style="height:' + eh + '%"></span>' : '') + '</div>';
                    }).join('') + '</div><div class="tr-axis"><span>' + esc(label(all[0].t)) + '</span><span>' + esc(label(all[all.length - 1].t)) + '</span></div>';
                }
                const list = (key, title, rows, empty, fmt) => '<div class="tr-list"><div class="site-section-head"><span>' + esc(title) + '</span>' + (rows.length ? '<button type="button" class="tr-more" data-list="' + key + '" title="Every entry in this window, with details">all ›</button>' : '') + '</div>' + (rows.length ? '<ul>' + rows.map(fmt).join('') + '</ul>' : '<div class="tr-empty small">' + esc(empty) + '</div>') + '</div>';
                const pathRow = (r) => '<li class="is-click" data-path="' + esc(r.path) + '" data-tip="' + esc(r.path) + '\n' + fmtN(r.n) + ' request' + (r.n === 1 ? '' : 's') + ' — click for recent hits"><a href="' + esc(site.domain + r.path) + '" target="_blank" rel="noopener" class="tr-path">' + esc(r.path) + '</a><span class="tr-n">' + fmtN(r.n) + '</span></li>';
                const slowRow = (r, i) => '<li class="is-click" data-slow="' + i + '" data-tip="' + esc(r.method ? r.method + ' ' : '') + esc(r.uri) + '\n' + esc(r.status) + ' · ' + esc((r.d * 1000).toFixed(0)) + ' ms · ' + esc(new Date(r.ts * 1000).toLocaleString()) + ' — click for details"><span class="tr-path">' + esc(r.method ? r.method + ' ' : '') + esc(r.uri) + '</span><span class="tr-n' + (r.status >= 500 ? ' is-bad' : '') + '">' + esc(r.status) + ' · ' + esc((r.d * 1000).toFixed(0)) + ' ms</span></li>';
                body.innerHTML = '<div class="tr-tiles">' + tiles + '</div>' + bars
                    + '<div class="tr-lists">'
                    + list('paths', 'top pages', d.paths || [], 'No page views in this window.', pathRow)
                    + list('slow', 'slowest requests', d.slow || [], 'Nothing recorded.', slowRow)
                    + list('notfound', '404s', d.notfound || [], 'None — nothing missing.', pathRow)
                    + list('errors5', '5xx', d.errors5 || [], 'None — no server errors.', pathRow)
                    + '</div>';
            },

            // --- Traffic drill-down ------------------------------------------
            // One modal, three views: a list (every entry of one of the four
            // lists, filterable), one request, or one path's recent hits.
            trafficOpen(view, arg) {
                const site = this.pageSite;
                const t = this.siteTabState('traffic');
                if (!site || !t.data) return;
                this.trafficModal = { open: true, view, site: site.name, range: t.range || '24h', list: null, rows: null, filter: '', loading: false, error: null, request: null, path: null, hits: null, stats: null, from: null };
                const m = this.trafficModal;
                this.showDbModal = true;
                $id('dbModal').classList.add('is-wide');
                show($id('dbModal'), true);
                $id('svcActions').innerHTML = '<button class="pill" id="btnDbClose">close</button>';
                $id('btnDbClose').addEventListener('click', () => this.setDbModal(false));
                if (view === 'request') { m.request = arg; this.renderTrafficModal(); return; }
                if (view === 'path') { m.path = arg; this.trafficFetch({ detail: 'path', path: arg }, (res) => { m.hits = res.hits || []; m.stats = res.hit_stats || null; }); return; }
                m.list = arg;
                this.trafficFetch({ detail: arg }, (res) => { m.rows = arg === 'slow' ? (res.slow || []) : (res[arg] || []); });
            },

            async trafficFetch(extra, apply) {
                const m = this.trafficModal;
                m.loading = true; m.error = null;
                this.renderTrafficModal();
                const res = await this.apiPost('site_traffic', { site_name: m.site, range: m.range, limit: 300, ...extra }, { quiet: true, timeoutMs: 120000 });
                if (!this.trafficModal || this.trafficModal !== m) return;
                m.loading = false;
                if (!res.success) m.error = res.message || 'Could not read the access log.';
                else apply(res);
                this.renderTrafficModal();
            },

            renderTrafficModal() {
                const m = this.trafficModal;
                if (!m || !m.open) return;
                const esc = (s) => this.escapeHtml(s == null ? '' : String(s));
                const fmtN = (n) => (n == null ? '—' : Number(n).toLocaleString());
                const ms = (d) => (Number(d) * 1000).toFixed(0) + ' ms';
                const when = (ts) => new Date(Number(ts) * 1000).toLocaleString();
                const site = this.sites.find(x => x.name === m.site);
                const domain = site ? site.domain : '';
                const rangeLabel = { '24h': 'last 24 hours', '7d': 'last 7 days', all: 'whole log' }[m.range];
                const title = $id('svcTitle'), st = $id('svcStatus'), rows = $id('svcRows'), note = $id('svcNote');
                st.classList.remove('is-down');
                const back = m.from ? '<button type="button" class="tr-back" data-act="back">← back</button>' : '';
                if (m.loading) { title.textContent = 'Traffic'; st.textContent = 'Reading the access log…'; rows.innerHTML = ''; note.textContent = ''; return; }
                if (m.error) { title.textContent = 'Traffic'; st.textContent = m.error; st.classList.add('is-down'); rows.innerHTML = ''; note.textContent = ''; return; }
                if (m.view === 'request') {
                    const r = m.request;
                    const url = domain + r.uri;
                    title.textContent = 'Request';
                    st.textContent = (r.method || '') + ' ' + r.uri.split('?')[0] + ' · ' + r.status + ' · ' + ms(r.d);
                    rows.innerHTML = back + '<dl class="tr-detail">'
                        + '<dt>url</dt><dd><a href="' + esc(url) + '" target="_blank" rel="noopener">' + esc(url) + '</a></dd>'
                        + '<dt>when</dt><dd>' + esc(when(r.ts)) + ' (' + esc(this.formatRelative(r.ts)) + ' ago)</dd>'
                        + '<dt>status</dt><dd>' + esc(r.status) + (r.ct ? ' · ' + esc(r.ct) : '') + '</dd>'
                        + '<dt>duration</dt><dd>' + esc(ms(r.d)) + '</dd>'
                        + '<dt>response</dt><dd>' + esc(this.formatSize(r.bytes || 0)) + (r.proto ? ' · ' + esc(r.proto) : '') + '</dd>'
                        + '<dt>client</dt><dd>' + esc(r.ip || '—') + '</dd>'
                        + '<dt>user agent</dt><dd>' + esc(r.ua || '—') + '</dd>'
                        + '<dt>referer</dt><dd>' + (r.ref ? '<a href="' + esc(r.ref) + '" target="_blank" rel="noopener">' + esc(r.ref) + '</a>' : '—') + '</dd>'
                        + '</dl>';
                    note.innerHTML = '<button type="button" class="tr-back" data-act="path" data-path="' + esc(r.uri.split('?')[0]) + '">recent hits of this path ›</button>';
                    return;
                }
                if (m.view === 'path') {
                    const hits = m.hits || [], s = m.stats || {};
                    title.textContent = 'Path';
                    const statuses = Object.entries(s.status || {}).sort((a, b) => b[1] - a[1]).map(([k, v]) => v + ' × ' + k).join(', ');
                    st.textContent = m.path + ' · ' + fmtN(s.n || hits.length) + ' request' + ((s.n || hits.length) === 1 ? '' : 's') + ' in the ' + rangeLabel + (s.n ? ' · avg ' + s.avg_ms + ' ms · max ' + s.max_ms + ' ms' : '') + (statuses ? ' · ' + statuses : '');
                    const q = m.filter.trim().toLowerCase();
                    const vis = q ? hits.filter(h => (h.uri + ' ' + h.status + ' ' + h.ip + ' ' + h.ua + ' ' + h.ref).toLowerCase().includes(q)) : hits;
                    rows.innerHTML = back + '<div class="tr-modal-tools"><input class="filter-input" id="trModalFilter" type="text" placeholder="filter by query, status, client, user agent…" value="' + esc(m.filter) + '" spellcheck="false" autocomplete="off"><a class="pill" href="' + esc(domain + m.path) + '" target="_blank" rel="noopener">open ↗</a></div>'
                        + '<div class="tr-table-wrap"><table class="tr-table"><thead><tr><th>when</th><th>method</th><th>status</th><th class="num">ms</th><th class="num">size</th><th>client</th><th>query · user agent</th></tr></thead><tbody>'
                        + (vis.length ? vis.map((h, i) => '<tr class="is-click" data-hit="' + hits.indexOf(h) + '"><td>' + esc(when(h.ts)) + '</td><td>' + esc(h.method) + '</td><td' + (h.status >= 500 ? ' class="is-bad"' : '') + '>' + esc(h.status) + '</td><td class="num">' + esc((h.d * 1000).toFixed(0)) + '</td><td class="num">' + esc(this.formatSize(h.bytes || 0)) + '</td><td>' + esc(h.ip) + '</td><td class="tr-cell-path">' + esc((h.uri.includes('?') ? h.uri.slice(h.uri.indexOf('?')) + ' · ' : '') + (h.ua || '')) + '</td></tr>').join('') : '<tr><td colspan="7" class="num">Nothing matches.</td></tr>')
                        + '</tbody></table></div>';
                    note.textContent = hits.length >= 300 ? 'The newest 300 hits are shown; narrow the range for older ones.' : 'Newest first. Click a row for the full request.';
                    return;
                }
                // A whole list.
                const labels = { slow: 'slowest requests', paths: 'top pages', notfound: '404s', errors5: '5xx' };
                const all = m.rows || [];
                title.textContent = labels[m.list] || 'Traffic';
                st.textContent = fmtN(all.length) + (m.list === 'slow' ? ' slowest requests' : ' paths') + ' · ' + rangeLabel;
                const q = m.filter.trim().toLowerCase();
                let html = '<div class="tr-modal-tools"><input class="filter-input" id="trModalFilter" type="text" placeholder="filter…" value="' + esc(m.filter) + '" spellcheck="false" autocomplete="off"></div><div class="tr-table-wrap"><table class="tr-table">';
                if (m.list === 'slow') {
                    const vis = q ? all.filter(r => (r.method + ' ' + r.uri + ' ' + r.status + ' ' + r.ip + ' ' + r.ua).toLowerCase().includes(q)) : all;
                    html += '<thead><tr><th class="num">#</th><th class="num">ms</th><th>method</th><th>status</th><th>path</th><th>when</th><th>client</th></tr></thead><tbody>'
                        + (vis.length ? vis.map(r => '<tr class="is-click" data-slow="' + all.indexOf(r) + '"><td class="num">' + (all.indexOf(r) + 1) + '</td><td class="num">' + esc((r.d * 1000).toFixed(0)) + '</td><td>' + esc(r.method) + '</td><td' + (r.status >= 500 ? ' class="is-bad"' : '') + '>' + esc(r.status) + '</td><td class="tr-cell-path">' + esc(r.uri) + '</td><td>' + esc(when(r.ts)) + '</td><td>' + esc(r.ip) + '</td></tr>').join('') : '<tr><td colspan="7" class="num">Nothing matches.</td></tr>');
                } else {
                    const vis = q ? all.filter(r => r.path.toLowerCase().includes(q)) : all;
                    html += '<thead><tr><th class="num">#</th><th>path</th><th class="num">requests</th></tr></thead><tbody>'
                        + (vis.length ? vis.map(r => '<tr class="is-click" data-path="' + esc(r.path) + '"><td class="num">' + (all.indexOf(r) + 1) + '</td><td class="tr-cell-path">' + esc(r.path) + '</td><td class="num">' + fmtN(r.n) + '</td></tr>').join('') : '<tr><td colspan="3" class="num">Nothing matches.</td></tr>');
                }
                rows.innerHTML = back + html + '</tbody></table></div>';
                note.textContent = 'Up to 300 entries from this window. Click a row for ' + (m.list === 'slow' ? 'the request' : 'its recent hits') + '.';
            },

            bindTrafficModalEvents() {
                const rows = $id('svcRows');
                rows.addEventListener('input', (e) => { if (e.target.id === 'trModalFilter' && this.trafficModal) { this.trafficModal.filter = e.target.value; const pos = e.target.selectionStart; this.renderTrafficModal(); const f = $id('trModalFilter'); if (f) { f.focus(); f.setSelectionRange(pos, pos); } } });
                const onClick = (e) => {
                    const m = this.trafficModal;
                    if (!m || !m.open) return;
                    const back = e.target.closest('[data-act="back"]');
                    if (back && m.from) { const prev = m.from; prev.from = null; this.trafficModal = prev; this.renderTrafficModal(); return; }
                    const toPath = e.target.closest('[data-act="path"]');
                    const hit = e.target.closest('tr[data-hit]');
                    const slow = e.target.closest('tr[data-slow]');
                    const pathRow = e.target.closest('tr[data-path]');
                    let next = null;
                    if (toPath) next = { view: 'path', path: toPath.dataset.path };
                    else if (hit) next = { view: 'request', request: (m.hits || [])[Number(hit.dataset.hit)] };
                    else if (slow) next = { view: 'request', request: (m.rows || [])[Number(slow.dataset.slow)] };
                    else if (pathRow) next = { view: 'path', path: pathRow.dataset.path };
                    if (!next) return;
                    const prev = m;
                    this.trafficModal = { ...m, ...next, from: prev, filter: '', hits: next.view === 'path' ? null : m.hits, stats: null, loading: false, error: null };
                    if (next.view === 'path') this.trafficFetch({ detail: 'path', path: next.path }, (res) => { this.trafficModal.hits = res.hits || []; this.trafficModal.stats = res.hit_stats || null; });
                    else this.renderTrafficModal();
                };
                rows.addEventListener('click', onClick);
                $id('svcNote').addEventListener('click', onClick);
                $id('trafficBody').addEventListener('click', (e) => {
                    const t = this.siteTabState('traffic');
                    const more = e.target.closest('.tr-more');
                    if (more) { this.trafficOpen('list', more.dataset.list); return; }
                    if (e.target.closest('a')) return;
                    const slow = e.target.closest('li[data-slow]');
                    if (slow && t.data) { this.trafficOpen('request', (t.data.slow || [])[Number(slow.dataset.slow)]); return; }
                    const p = e.target.closest('li[data-path]');
                    if (p) this.trafficOpen('path', p.dataset.path);
                });
            },

            // The overview's one-line health strip: same numbers, light mode.
            async loadSiteHealth() {
                const site = this.pageSite;
                const p = this.sitePage;
                if (!site) return;
                if (p.health && p.health.for === site.name && Date.now() - p.health.at < 60000) { this.renderSiteHealth(); return; }
                p.health = { for: site.name, at: Date.now(), loading: true };
                this.renderSiteHealth();
                const [res, mail] = await Promise.all([
                    this.apiPost('site_traffic', { site_name: site.name, range: '24h', light: true }, { quiet: true, timeoutMs: 60000 }),
                    this.mailCountFor(site.name, '24h'),
                ]);
                if (this.sitePage.name !== site.name) return;
                p.health = { for: site.name, at: Date.now(), loading: false, data: res.success ? res : null, mail };
                this.renderSiteHealth();
            },

            renderSiteHealth() {
                const p = this.sitePage;
                const el = $id('siteHealth');
                const h = p.health;
                const site = this.pageSite;
                if (!h || !site || h.for !== site.name) { el.innerHTML = ''; return; }
                if (h.loading && !h.data) { el.innerHTML = '<span class="fact">last 24 hours · reading…</span>'; return; }
                const d = h.data;
                if (!d || !d.has_log) { el.innerHTML = '<span class="fact">last 24 hours · no requests logged yet</span>'; return; }
                const n = (v) => Number(v || 0).toLocaleString();
                const bit = (label, v, cls) => '<button type="button" class="site-health-bit' + (cls ? ' ' + cls : '') + '" data-go="traffic"><b>' + n(v) + '</b> ' + this.escapeHtml(label) + '</button>';
                el.innerHTML = '<span class="fact">last 24 hours</span>'
                    + bit('requests', d.requests)
                    + bit('page views', (d.kinds || {}).page)
                    + bit('5xx', d.status['5xx'], d.status['5xx'] ? 'is-bad' : '')
                    + bit('php errors', d.php_errors, d.php_errors ? 'is-warn' : '')
                    + (h.mail == null ? '' : bit('mail', h.mail))
                    + (d.last_cron ? '<span class="fact" title="' + new Date(d.last_cron * 1000).toLocaleString() + '">cron ' + (this.formatRelative(d.last_cron) === 'now' ? 'just now' : this.formatRelative(d.last_cron) + ' ago') + '</span>' : '<span class="fact">cron not seen</span>');
            },

            // --- Previews in the background ---------------------------------
            // A refresh is queued, not awaited: the capture runs detached and
            // the page polls for the file's new time. On load, one sweep of
            // stale previews is asked for so most pages already have theirs.
            async refreshSiteShot(name, auto) {
                const s = this.sitePage.shot;
                if (s.busy) return;
                s.asked[name] = 'asked';
                s.busy = name;
                if (this.pageSite && this.pageSite.name === name) this.renderSiteShot(this.pageSite);
                const res = await this.apiPost('site_shot_refresh', { site_name: name }, { quiet: true, timeoutMs: 20000 });
                if (!res.success) {
                    s.busy = null;
                    s.asked[name] = 'failed';
                    if (res.unsupported) s.unsupported = true;
                    if (!auto) this.showSnack(res.message || 'The capture failed.', true);
                    if (this.view === 'site' && this.pageSite && this.pageSite.name === name) this.renderSiteShot(this.pageSite);
                    return;
                }
                const before = res.mtime || 0;
                const t0 = Date.now();
                const poll = async () => {
                    const info = await this.apiPost('site_shot_info', { site_name: name }, { quiet: true, timeoutMs: 10000 });
                    const site = this.sites.find(x => x.name === name);
                    if (info.success && info.mtime && info.mtime !== before) {
                        if (site) site.shot_mtime = info.mtime;
                        s.busy = null; s.asked[name] = 'done';
                    } else if (info.success && !info.capturing && Date.now() - t0 > 4000) {
                        // The capture ended without a new file.
                        s.busy = null; s.asked[name] = 'failed';
                        if (!auto) this.showSnack(info.message || 'The capture failed — is the site answering?', true);
                    } else if (Date.now() - t0 > 90000) {
                        s.busy = null; s.asked[name] = 'failed';
                    } else { setTimeout(poll, 2500); }
                    if (this.view === 'site' && this.pageSite && this.pageSite.name === name) this.renderSiteShot(this.pageSite);
                };
                setTimeout(poll, 2500);
            },

            // --- Tooltips ------------------------------------------------------
            // One element for the page; anything with data-tip shows it at once
            // on hover, above the element (below when there is no room).
            bindTips() {
                const tip = document.createElement('div');
                tip.className = 'ui-tip'; tip.hidden = true;
                document.body.appendChild(tip);
                let cur = null;
                const hide = () => { cur = null; tip.hidden = true; };
                const showFor = (el) => {
                    const text = el.dataset.tip;
                    if (!text) { hide(); return; }
                    cur = el;
                    tip.textContent = text; tip.hidden = false;
                    tip.style.left = '0px'; tip.style.top = '0px';
                    const r = el.getBoundingClientRect(), tr = tip.getBoundingClientRect();
                    const x = Math.max(8, Math.min(r.left + r.width / 2 - tr.width / 2, window.innerWidth - tr.width - 8));
                    let y = r.top - tr.height - 8;
                    if (y < 8) y = r.bottom + 8;
                    tip.style.left = x + 'px'; tip.style.top = y + 'px';
                };
                document.addEventListener('mouseover', (e) => {
                    const el = e.target.closest && e.target.closest('[data-tip]');
                    if (el) { if (el !== cur) showFor(el); } else if (cur) hide();
                });
                document.addEventListener('mouseout', (e) => { if (cur && !(e.relatedTarget && cur.contains(e.relatedTarget))) hide(); });
                window.addEventListener('scroll', hide, { passive: true, capture: true });
                document.addEventListener('mousedown', hide, true);
            },

            // --- The nightly history sweep, as a whole -----------------------
            // Polled every 10 s while it runs and every minute otherwise; the
            // nav shows a pulsing "history 14/80" while it is on, and the
            // history tab's footer says where things stand.
            sweepPoll() {
                clearTimeout(this.sweepTimer);
                const tick = async () => {
                    if (document.hidden) { this.sweepTimer = setTimeout(tick, 15000); return; }
                    const st = await this.apiPost('history_sweep_status', {}, { quiet: true, timeoutMs: 15000 });
                    if (st && st.success) {
                        const prev = this.sweep;
                        this.sweep = st;
                        this.renderSweep();
                        if (this.sweepModalOpen) { if (st.running) this.renderSweepModal(); else { $id('svcStatus').textContent = 'The pass has finished.'; } }
                        if (this.view === 'site' && this.sitePage.tab === 'history') {
                            this.renderSiteTab();
                            // The sweep just moved past this site, or ended:
                            // its save (if any) belongs in the list now.
                            const here = this.sitePage.name;
                            if (prev && prev.running && ((prev.site === here && st.site !== here) || !st.running)) this.loadSiteTab({ force: true });
                        }
                    }
                    this.sweepTimer = setTimeout(tick, this.sweep && this.sweep.running ? 10000 : 60000);
                };
                tick();
            },

            renderSweep() {
                const b = $id('navSweep');
                const s = this.sweep;
                const on = !!(s && s.running);
                show(b, on);
                if (!on) return;
                const n = Number(s.done) || 0, t = Number(s.total) || 0;
                // Compact on purpose: the services row must stay on one line.
                b.textContent = t ? n + '/' + t : 'saving';
                b.title = 'History: nightly sweep running' + (s.site ? ' — saving ' + s.site + '.localhost' : '') + (t ? ' (' + n + ' of ' + t + ' sites done, ' + (Number(s.saved) || 0) + ' saved)' : '') + '. Click to see it.';
            },

            // The dot opens a modal: every site in the pass — done (with its
            // result), running, upcoming — refreshed by the poll while open.
            sweepGo() {
                if (!this.sweep || !this.sweep.running) return;
                this.sweepModalOpen = true;
                this.showDbModal = true;
                show($id('dbModal'), true);
                $id('svcActions').innerHTML = '<button class="pill" id="btnDbClose">close</button>';
                $id('btnDbClose').addEventListener('click', () => { this.sweepModalOpen = false; this.setDbModal(false); });
                this.renderSweepModal();
            },

            renderSweepModal() {
                if (!this.sweepModalOpen) return;
                const s = this.sweep || {};
                const esc = (v) => this.escapeHtml(String(v == null ? '' : v));
                $id('svcTitle').textContent = 'History sweep';
                const st = $id('svcStatus');
                st.classList.remove('is-down');
                const n = Number(s.done) || 0, t = Number(s.total) || 0;
                if (!s.running) { st.textContent = 'The pass has finished.'; }
                else {
                    const rel = Number(s.started) ? this.formatRelative(Number(s.started)) : '';
                    st.textContent = (s.site ? 'Saving ' + s.site + '.localhost' : 'Starting') + ' · ' + n + ' of ' + t + ' done · ' + (Number(s.saved) || 0) + ' saved' + (rel ? ' · started ' + (rel === 'now' ? 'just now' : rel + ' ago') : '');
                }
                const sites = Array.isArray(s.sites) ? s.sites : [];
                const groups = [['done', sites.filter(x => x.state !== 'running' && x.state !== 'pending')], ['now', sites.filter(x => x.state === 'running')], ['upcoming', sites.filter(x => x.state === 'pending')]];
                let html = '<div class="sweep-list">';
                for (const [label, rows] of groups) {
                    if (!rows.length) continue;
                    html += '<div class="sweep-group">' + label + ' · ' + rows.length + '</div>';
                    for (const r of rows) {
                        const chip = r.state === 'saved' ? 'saved' : r.state === 'unchanged' ? 'unchanged' : r.state === 'failed' ? 'failed' : r.state === 'busy' ? 'skipped' : r.state === 'running' ? 'saving…' : '';
                        html += '<div class="sweep-row is-' + esc(r.state) + '"><button type="button" class="sweep-name" data-site="' + esc(r.name) + '" title="Open the site\'s history">' + esc(r.name) + '</button>'
                            + '<span class="sweep-id">' + esc(r.state === 'saved' ? r.id : '') + '</span>'
                            + (chip ? '<span class="st-chip ch-' + esc(r.state) + '">' + esc(chip) + '</span>' : '<span></span>') + '</div>';
                    }
                }
                html += '</div>';
                const rows = $id('svcRows');
                // Re-rendered on every poll: keep the reader's place in the list.
                const prevList = rows.querySelector('.sweep-list');
                const keep = prevList ? prevList.scrollTop : 0;
                rows.innerHTML = html;
                const list = rows.querySelector('.sweep-list');
                if (list && keep) list.scrollTop = keep;
                rows.querySelectorAll('.sweep-name').forEach(b => b.addEventListener('click', () => { this.sweepModalOpen = false; this.setDbModal(false); this.openSitePage(b.dataset.site); this.setSiteTab('history'); }));
                $id('svcNote').textContent = 'Sites without plugins or themes are not in the pass. Each result is a save only when something changed.';
            },

            // One line for the history tab's footer.
            sweepLine() {
                const s = this.sweep;
                const rel = (t) => { const r = this.formatRelative(Number(t)); return r === 'now' ? 'just now' : r + ' ago'; };
                if (!s) return '';
                if (s.running) return 'nightly sweep running now' + (s.site ? ' · on ' + s.site : '') + (Number(s.total) ? ' · ' + (Number(s.done) || 0) + ' of ' + s.total + ' sites done, ' + (Number(s.saved) || 0) + ' saved' : '') + (Number(s.started) ? ' · started ' + rel(s.started) : '');
                let line = Number(s.last_done) ? 'last nightly sweep finished ' + rel(s.last_done) : 'the first nightly sweep has not finished yet';
                const doneToday = Number(s.last_done) && new Date(Number(s.last_done) * 1000).toDateString() === new Date().toDateString();
                if (Number(s.waiting_since)) line += ' · waiting for an idle desktop since ' + new Date(Number(s.waiting_since) * 1000).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) + ' (the watchdog retries every 5 min)';
                else if (!doneToday && new Date().getHours() >= 1) line += ' · the watchdog tries every 5 min and runs once the desktop is idle';
                else line += ' · next pass after 1 am once the desktop is idle';
                return line;
            },

            requestShotSweep() {
                if (this._sweepAsked) return;
                this._sweepAsked = true;
                this.apiPost('site_shot_sweep', {}, { quiet: true, timeoutMs: 10000 });
            },

            renderSiteNetwork() {
                const p = this.sitePage;
                const list = $id('siteNetList');
                list.querySelectorAll('.net-row').forEach(n => n.remove());
                const loaded = p.net.loadedFor === p.name;
                show($id('siteNetLoading'), p.net.loading && !loaded);
                show($id('siteNetError'), !p.net.loading && !!p.net.error);
                if (p.net.error) $id('siteNetErrorText').textContent = p.net.error;
                $id('btnSiteNetworkRefresh').disabled = p.net.loading;
                if (!loaded) return;
                const tpl = $id('tpl-net-row');
                const anchor = $id('siteNetLoading');
                const frag = document.createDocumentFragment();
                for (const s of p.net.items) {
                    const row = tpl.content.firstElementChild.cloneNode(true);
                    row.dataset.url = s.url;
                    row.classList.toggle('is-off', s.status !== 'public' && s.status !== 'private');
                    const name = row.querySelector('.net-name');
                    name.textContent = s.name || s.url;
                    if (s.main) { const c = document.createElement('span'); c.className = 'net-main-chip'; c.textContent = 'main'; name.appendChild(c); }
                    if (s.status !== 'public') { const c = document.createElement('span'); c.className = 'net-main-chip net-status'; c.textContent = s.status; name.appendChild(c); }
                    const url = row.querySelector('.net-url');
                    url.textContent = s.url.replace(/^https?:\/\//, '');
                    url.href = s.url;
                    const upd = row.querySelector('.net-updated');
                    const ts = s.updated ? Date.parse(s.updated.replace(' ', 'T') + 'Z') / 1000 : 0;
                    upd.textContent = ts ? this.formatRelative(ts) : '';
                    upd.title = ts ? 'Last updated ' + new Date(ts * 1000).toLocaleString() : 'Never updated';
                    row.querySelector('.net-open').href = s.url;
                    const btn = row.querySelector('.net-login');
                    btn.disabled = !!p.busy;
                    btn.textContent = p.busy === s.url ? 'opening…' : 'log in';
                    btn.title = 'One-time admin login to ' + s.url;
                    frag.appendChild(row);
                }
                list.insertBefore(frag, anchor);
                if (!p.net.items.length) { const li = document.createElement('li'); li.className = 'empty net-row'; li.textContent = 'No sites on this network.'; list.insertBefore(li, anchor); }
            },

            async loadSiteNetwork(force) {
                const p = this.sitePage;
                const name = p.name;
                const site = this.pageSite;
                if (!name || !site || !site.multisite) return;
                if (p.net.loadedFor === name && !force) return;
                if (p.net.loadedFor !== name) { p.net.items = []; p.net.loadedFor = null; }
                p.net.loading = true; p.net.error = null;
                this.renderSiteNetwork();
                const res = await this.apiPost('network_sites', { site_name: name }, { quiet: true, timeoutMs: 60000 });
                if (this.sitePage.name !== name) return;
                p.net.loading = false;
                if (!res.success) p.net.error = res.message || 'Could not read the network.';
                else { p.net.items = res.sites || []; p.net.loadedFor = name; }
                this.renderSitePage();
            },

            async loginToSubsite(url) {
                const p = this.sitePage;
                const name = p.name;
                if (!name || p.busy) return;
                p.busy = url;
                this.renderSiteNetwork();
                const res = await this.apiPost('get_login_link', { site_name: name, url });
                if (res.success && res.url) {
                    window.open(res.url, '_blank');
                    this.showSnack('Login link opened in a new tab.');
                }
                p.busy = null;
                if (this.sitePage.name === name) this.renderSiteNetwork();
            },

            bindSiteEvents() {
                $id('btnSiteBack').addEventListener('click', () => this.setView('sites'));
                for (const [id, get] of [['filesBack', () => this.files.site], ['logsBack', () => this.logs.site], ['mailBack', () => this.mail.site], ['dbBack', () => this.db.name ? this.dbSiteOf(this.db.name) : null]]) {
                    $id(id).addEventListener('click', () => { const s = get(); if (s) this.openSitePage(s); });
                }
                $id('btnSiteShot').addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); const s = this.pageSite; if (s) { this.sitePage.shot.asked[s.name] = null; this.refreshSiteShot(s.name, false); } });
                $id('siteShot').addEventListener('click', (e) => { if (e.target.closest('.site-shot-refresh')) e.preventDefault(); });
                $id('btnSiteLogin').addEventListener('click', () => { const s = this.pageSite; if (s) this.getLoginLink(s.name); });
                $id('siteFacts').addEventListener('click', (e) => {
                    const path = e.target.closest('.fact-path');
                    if (path) { this.copyPath(path.dataset.path); return; }
                    const type = e.target.closest('.fact-type');
                    if (type) { this.setTypeFilter(type.dataset.type); this.setView('sites'); }
                });
                $id('siteTiles').addEventListener('click', (e) => {
                    const t = e.target.closest('.site-tile');
                    const s = this.pageSite;
                    if (!t || !s) return;
                    if (t.dataset.go === 'files') this.openFilesForSite(s.name);
                    if (t.dataset.go === 'db') this.openDbForSite(s);
                    if (t.dataset.go === 'mail') this.openMailForSite(s.name);
                    if (t.dataset.go === 'logs') this.openLogsForSite(s.name);
                });
                $id('btnSiteNetworkRefresh').addEventListener('click', () => this.loadSiteNetwork(true));
                $id('siteNetList').addEventListener('click', (e) => {
                    const row = e.target.closest('.net-row');
                    if (!row || !row.dataset.url) return;
                    if (e.target.closest('.net-login')) { this.loginToSubsite(row.dataset.url); return; }
                    if (e.target.closest('a')) return;
                    // The row itself opens the subsite, like the ↗ on a sites row.
                    if (window.getSelection && window.getSelection().toString()) return;
                    window.open(row.dataset.url, '_blank', 'noopener');
                });
                const withSite = (fn) => () => { const s = this.pageSite; if (s) fn(s); };
                $id('spDomains').addEventListener('click', withSite(s => this.openDomainsModal(s)));
                $id('spPhp').addEventListener('click', withSite(s => this.openPhpModal(s)));
                $id('spRename').addEventListener('click', withSite(s => this.promptRename(s)));
                $id('spReveal').addEventListener('click', withSite(s => this.revealSite(s.name)));
                $id('spCopy').addEventListener('click', withSite(s => this.copyPath(s.full_path)));
                $id('spBackup').addEventListener('click', withSite(s => this.backupSite(s.name)));
                $id('spPin').addEventListener('click', withSite(s => { this.togglePin(s.name); this.renderSitePage(); }));
                $id('spDelete').addEventListener('click', withSite(s => this.openSiteDeleteConfirm(s.name)));
            },

            // --- Site page tabs: plugins, themes, users, cron, wp-cli --------
            // Each tab is a WP-CLI listing fetched when first shown and kept
            // per site; row actions run one command and refetch.
            get siteTabs() { return ['overview', 'plugins', 'themes', 'users', 'cron', 'traffic', 'history', 'snapshots', 'cli']; },

            setSiteTab(tab) {
                const p = this.sitePage;
                tab = this.siteTabs.includes(tab) ? tab : 'overview';
                const site = this.pageSite;
                if (site && site.type !== 'WordPress' && tab !== 'snapshots' && tab !== 'traffic' && tab !== 'history') tab = 'overview';
                p.tab = tab;
                this.syncUrl();
                this.renderSitePage();
                this.loadSiteTab();
                if (tab === 'cli') $id('siteCliInput').focus();
            },

            siteTabState(tab) {
                const p = this.sitePage;
                if (!p.tabs[tab]) p.tabs[tab] = { items: [], loading: false, error: null, loadedFor: null, filter: '', status: 'all', busy: {}, arm: null, ms: 0, checked: false };
                return p.tabs[tab];
            },

            async loadSiteTab(opts = {}) {
                const p = this.sitePage;
                const tab = p.tab;
                const site = this.pageSite;
                if (tab === 'traffic') { this.loadTraffic(opts); return; }
                if (tab === 'overview') { this.loadSiteHealth(); return; }
                if (!site || !['plugins', 'themes', 'users', 'cron', 'snapshots', 'history'].includes(tab)) return;
                if (site.type !== 'WordPress' && tab !== 'snapshots' && tab !== 'history') return;
                const t = this.siteTabState(tab);
                if (t.loadedFor === site.name && !opts.force) return;
                if (t.loadedFor !== site.name) { t.items = []; t.loadedFor = null; t.filter = t.filterFor === site.name ? t.filter : ''; t.status = 'all'; t.arm = null; t.open = null; t.diff = null; }
                t.loading = true; t.error = null;
                this.renderSiteTab();
                const action = { plugins: 'site_plugins', themes: 'site_themes', users: 'site_users', cron: 'site_cron', snapshots: 'site_snapshots', history: 'site_history' }[tab];
                const res = await this.apiPost(action, { site_name: site.name, check: !!opts.check }, { quiet: true, timeoutMs: opts.check ? 180000 : 90000 });
                if (this.sitePage.name !== site.name) return;
                t.loading = false;
                if (!res.success) t.error = res.message || 'wp-cli failed.';
                else { t.items = res.items || []; t.loadedFor = site.name; t.ms = res.ms || 0; t.extra = res; if (opts.check) t.checked = true; }
                if (tab === 'history') {
                    const sv = res.saving;
                    if (sv && sv.running) { t.busy['+'] = 'save'; t.saving = { started: Number(sv.started) || Date.now() / 1000, stage: sv.stage || '', files: Number(sv.files) || 0 }; this.historyPoll(site.name, true); }
                    else if (!t.busy['+']) t.saving = null;
                }
                this.renderSiteTab();
            },

            // One row action: wp plugin/theme <op> <slug>, then a refetch.
            async siteItemOp(tab, slug, op, network) {
                const site = this.pageSite;
                const t = this.siteTabState(tab);
                if (!site || t.busy[slug]) return;
                if (op === 'delete' && t.arm !== slug) {
                    t.arm = slug;
                    clearTimeout(t.armTimer);
                    t.armTimer = setTimeout(() => { t.arm = null; this.renderSiteTab(); }, 3500);
                    this.renderSiteTab();
                    return;
                }
                t.arm = null;
                t.busy[slug] = op;
                this.renderSiteTab();
                const res = await this.apiPost(tab === 'plugins' ? 'site_plugin_op' : 'site_theme_op', { site_name: site.name, slug, op, network: !!network }, { quiet: true, timeoutMs: 180000 });
                delete t.busy[slug];
                if (this.sitePage.name !== site.name) return;
                const last = (res.message || '').split('\n').filter(Boolean).pop() || '';
                this.showSnack(last.replace(/^(Success|Error|Warning): /, '') || (res.success ? 'Done.' : 'Failed.'), !res.success);
                this.loadSiteTab({ force: true });
            },

            async siteCronRun(hook) {
                const site = this.pageSite;
                const t = this.siteTabState('cron');
                const key = hook || '*';
                if (!site || t.busy[key]) return;
                t.busy[key] = 'run';
                this.renderSiteTab();
                const res = await this.apiPost('site_cron_run', hook ? { site_name: site.name, hook } : { site_name: site.name, due: true }, { quiet: true, timeoutMs: 180000 });
                delete t.busy[key];
                if (this.sitePage.name !== site.name) return;
                const last = (res.message || '').split('\n').filter(Boolean).pop() || '';
                this.showSnack(last.replace(/^(Success|Error|Warning): /, '') || (res.success ? 'Ran.' : 'Failed.'), !res.success);
                this.loadSiteTab({ force: true });
            },

            // --- History: nightly saves of plugins, themes and mu-plugins ----
            // Each row is one save (a commit); opening it lists the components
            // that changed with the way back for each.
            historyClick(e, row) {
                const t = this.siteTabState('history');
                const roll = e.target.closest('.st-hist-roll');
                if (roll) { this.historyRollback(roll.dataset.hash, roll.dataset.target, roll.dataset.key); return; }
                const dif = e.target.closest('.st-hist-diff');
                if (dif) { this.historyDiff(dif.dataset.hash, dif.dataset.target); return; }
                if (e.target.closest('.st-comp-more button')) { t.showAll = t.open; this.renderSiteTab(); return; }
                if (e.target.closest('.st-detail')) return;
                if (row && row.dataset.id) this.historyToggle(row.dataset.id);
            },

            historyToggle(id) {
                const t = this.siteTabState('history');
                t.open = t.open === id ? null : id;
                t.diff = null; t.showAll = null; t.arm = null;
                this.renderSiteTab();
            },

            // From a plugin's or theme's menu: the history tab, filtered to it.
            historyFocus(slug) {
                const site = this.pageSite;
                const t = this.siteTabState('history');
                t.filter = slug; t.filterFor = site ? site.name : null;
                const f = $id('sitePanel-history').querySelector('.st-filter');
                if (f) f.value = slug;
                this.setSiteTab('history');
            },

            // The save runs detached (a big site's first one takes minutes);
            // the tab polls for progress and reloads when it lands.
            async historySave() {
                const site = this.pageSite;
                const t = this.siteTabState('history');
                if (!site || t.busy['+']) return;
                const note = $id('histNote').value.trim();
                t.busy['+'] = 'save'; t.saving = { started: Date.now() / 1000, stage: 'starting', files: 0 };
                this.renderSiteTab();
                const res = await this.apiPost('site_history_save', { site_name: site.name, note }, { quiet: true, timeoutMs: 60000 });
                if (this.sitePage.name !== site.name) return;
                if (!res.success) { delete t.busy['+']; t.saving = null; this.showSnack(res.message || 'Could not start the save.', true); this.renderSiteTab(); return; }
                $id('histNote').value = '';
                this.historyPoll(site.name, true);
            },

            // Poll site_history_status every two seconds while a save runs —
            // also picked up when the tab opens on a site whose save is
            // already under way (from the terminal, or the nightly sweep).
            historyPoll(siteName, fresh) {
                const t = this.siteTabState('history');
                clearTimeout(t.pollTimer);
                if (fresh) t.pollMisses = 0;
                t.pollTimer = setTimeout(async () => {
                    if (this.sitePage.name !== siteName) return;
                    const st = await this.apiPost('site_history_status', { site_name: siteName }, { quiet: true, timeoutMs: 30000 });
                    if (this.sitePage.name !== siteName) return;
                    if (st.success && st.running) {
                        t.busy['+'] = 'save';
                        t.saving = { started: Number(st.started) || t.saving && t.saving.started || Date.now() / 1000, stage: st.stage || '', files: Number(st.files) || 0 };
                        this.renderSiteTab();
                        this.historyPoll(siteName, false);
                        return;
                    }
                    // Not running: the result file lands a moment after the
                    // lock goes, so give it a couple of polls.
                    const r = st.success ? st.result : null;
                    if (!r && t.pollMisses < 3 && t.busy['+']) { t.pollMisses++; this.historyPoll(siteName, false); return; }
                    delete t.busy['+']; t.saving = null;
                    if (r && r.ok === false) this.showSnack(r.message || 'The save failed.', true);
                    else if (r && r.state === 'unchanged') this.showSnack('Nothing has changed since save ' + r.id + '.');
                    else if (r && r.id) { this.showSnack('Saved ' + r.id + (r.summary && r.summary.summary ? ' — ' + r.summary.summary : '') + '.'); t.open = r.id; t.diff = null; }
                    if (r && r.finished) t.seenResult = r.finished;
                    this.loadSiteTab({ force: true });
                }, fresh ? 800 : 2000);
            },

            // Two clicks: the first arms the button (keyed so only that button
            // confirms), the second runs. The CLI saves the current state first.
            async historyRollback(hash, target, key) {
                const site = this.pageSite;
                const t = this.siteTabState('history');
                if (!site || t.busy[key] || t.busy['+']) return;
                if (t.arm !== key) {
                    t.arm = key;
                    clearTimeout(t.armTimer);
                    t.armTimer = setTimeout(() => { t.arm = null; this.renderSiteTab(); }, 4000);
                    this.renderSiteTab();
                    return;
                }
                t.arm = null;
                t.busy[key] = 'rollback';
                this.renderSiteTab();
                const res = await this.apiPost('site_history_rollback', { site_name: site.name, id: hash, target }, { quiet: true, timeoutMs: 1800000 });
                delete t.busy[key];
                if (this.sitePage.name !== site.name) return;
                if (!res.success) { this.showSnack(res.message || 'The rollback failed.', true); this.renderSiteTab(); return; }
                const n = (res.restored || []).length, d = (res.deleted || []).length, sk = (res.skipped || []).length;
                const what = target === 'all'
                    ? 'Rolled back ' + n + ' component' + (n === 1 ? '' : 's') + (d ? ', removed ' + d : '') + (sk ? ', left ' + sk + ' alone (symlinks or checkouts of their own)' : '')
                    : 'Rolled back ' + target.replace(/^file:/, '');
                this.showSnack(what + '.' + (res.safety ? ' The state from just before is save ' + res.safety + '.' : ''));
                for (const tab of ['plugins', 'themes', 'cron']) { const x = this.sitePage.tabs[tab]; if (x) x.loadedFor = null; }
                t.diff = null;
                this.getSites();
                this.loadSiteTab({ force: true });
            },

            async historyDiff(hash, target) {
                const site = this.pageSite;
                const t = this.siteTabState('history');
                const key = hash + ':' + target;
                if (!site) return;
                if (t.diff && t.diff.key === key) { t.diff = null; this.renderSiteTab(); return; }
                t.diff = { key, loading: true, text: '', truncated: false, error: null };
                this.renderSiteTab();
                const res = await this.apiPost('site_history_diff', { site_name: site.name, id: hash, target }, { quiet: true, timeoutMs: 300000 });
                if (this.sitePage.name !== site.name || !t.diff || t.diff.key !== key) return;
                t.diff.loading = false;
                if (!res.success) t.diff.error = res.message || 'Could not build the diff.';
                else { t.diff.text = res.diff || ''; t.diff.truncated = !!res.truncated; }
                this.renderSiteTab();
            },

            historyDiffHtml(text) {
                const esc = (s) => this.escapeHtml(s);
                return text.split('\n').map(l => {
                    let c = '';
                    if (/^(\+\+\+ |--- |diff |index |new file|deleted file|old mode|new mode|Binary)/.test(l)) c = 'd-meta';
                    else if (l.startsWith('@@')) c = 'd-hunk';
                    else if (l.startsWith('+')) c = 'd-add';
                    else if (l.startsWith('-')) c = 'd-del';
                    return c ? '<span class="' + c + '">' + esc(l) + '</span>' : esc(l);
                }).join('\n');
            },

            // One line that always fits: the CLI's sentence when it names one or
            // two components, otherwise WordPress (if it moved) plus counts by
            // kind of change. The full sentence stays in the row's tooltip.
            historyHeadline(sum) {
                if (!sum) return '';
                const comps = Array.isArray(sum.components) ? sum.components : [];
                if (sum.initial || comps.length <= 2) return sum.summary || '';
                const parts = [];
                if (sum.core && sum.core.version_from && sum.core.version_from !== sum.core.version) parts.push('WordPress ' + sum.core.version_from + ' → ' + sum.core.version);
                const n = {};
                for (const c of comps) n[c.change] = (n[c.change] || 0) + 1;
                const word = (k, one, many) => n[k] ? n[k] + ' ' + (n[k] === 1 ? one : many) : '';
                for (const w of [word('updated', 'updated', 'updated'), word('downgraded', 'downgraded', 'downgraded'), word('new', 'added', 'added'), word('deleted', 'removed', 'removed'), word('changed', 'edited', 'edited'), word('status', 'toggled', 'toggled')]) if (w) parts.push(w);
                return parts.join(' · ');
            },

            // The opened save: header with the whole-save rollback, then one
            // line per component — its change, versions before and after,
            // file counts, **undo** (the files from just before this save),
            // **restore this** (the files as they were in it), and **diff**.
            historyDetail(it, t) {
                const esc = (s) => this.escapeHtml(s == null ? '' : String(s));
                const site = this.pageSite;
                const sum = it.summary || {};
                const comps = Array.isArray(sum.components) ? sum.components : [];
                const li = document.createElement('li');
                li.className = 'st-detail';
                li.dataset.id = it.id;
                const f = sum.files || {};
                const filesHtml = (a, m, d) => '<span class="st-hist-files"><span class="f-add">+' + (a || 0) + '</span><span>~' + (m || 0) + '</span><span class="f-del">−' + (d || 0) + '</span></span>';
                let html = '<div class="st-detail-head"><span title="Full hash">' + esc(it.hash.slice(0, 12)) + '</span>'
                    + (sum.core && sum.core.version_from && sum.core.version_from !== sum.core.version ? '<span>WordPress ' + esc(sum.core.version_from) + ' → ' + esc(sum.core.version) + '</span>' : (it.wp ? '<span>wp ' + esc(it.wp) + '</span>' : ''))
                    + filesHtml(f.added, f.modified, f.deleted) + '<span>files</span>'
                    + (sum.initial ? '<span>first save</span>' : '');
                const allKey = it.hash + ':all';
                html += t.busy[allKey] ? '<span class="st-busy" style="margin-left:auto">rolling back…</span>'
                    : '<button type="button" class="pill st-hist-roll' + (t.arm === allKey ? ' armed' : '') + '" data-hash="' + esc(it.hash) + '" data-target="all" data-key="' + esc(allKey) + '" title="Make plugins, themes and mu-plugins exactly as they were in this save. Symlinks and folders with their own .git are left alone; the current state is saved first, so this can be undone.">' + (t.arm === allKey ? 'sure? roll back everything' : 'roll back everything to this save…') + '</button>';
                html += '</div>';
                const showAll = t.showAll === it.id;
                const cap = showAll ? comps.length : 40;
                const order = { deleted: 0, downgraded: 1, updated: 1, changed: 2, new: 3, status: 4 };
                const sorted = [...comps].sort((a, b) => (order[a.change] ?? 5) - (order[b.change] ?? 5) || String(a.title || a.slug).localeCompare(String(b.title || b.slug)));
                if (!comps.length) html += '<div class="st-comp-more">' + (sum.core && sum.core.version_from ? 'WordPress itself was updated; plugins and themes did not change.' : 'Nothing changed in plugins, themes or mu-plugins.') + '</div>';
                for (const c of sorted.slice(0, cap)) {
                    const target = c.type === 'file' ? 'file:' + c.path : c.path;
                    const touched = !!(c.added || c.modified || c.deleted);
                    const ver = c.change === 'new' ? esc(c.version) : c.change === 'deleted' ? '<s>' + esc(c.version_from) + '</s>'
                        : (c.version_from && c.version_from !== c.version ? esc(c.version_from) + '<span class="arrow">→</span>' + esc(c.version) : esc(c.version || c.version_from || ''));
                    const st = c.status_from && c.status && c.status_from !== c.status ? ' · ' + esc(c.status_from) + ' → ' + esc(c.status) : '';
                    const chg = c.change === 'status' ? (c.status === 'inactive' ? 'deactivated' : /active/.test(c.status || '') ? 'activated' : 'status') : c.change;
                    const kBefore = it.hash + ':before:' + c.path, kThis = it.hash + ':this:' + c.path;
                    let actions = '';
                    if (t.busy[kBefore] || t.busy[kThis]) actions = '<span class="st-busy">rolling back…</span>';
                    else {
                        if (sum.parent && c.change !== 'new' && touched) actions += '<button type="button" class="pill st-hist-roll' + (t.arm === kBefore ? ' armed' : '') + '" data-hash="' + esc(sum.parent) + '" data-target="' + esc(target) + '" data-key="' + esc(kBefore) + '" title="Put the files back as they were just before this save' + (c.version_from ? ' (' + esc(c.version_from) + ')' : '') + '">' + (t.arm === kBefore ? 'sure?' : (c.change === 'deleted' ? 'bring back' : 'undo') + (c.version_from && c.version_from !== c.version ? ' → ' + esc(c.version_from) : '')) + '</button>';
                        if (c.change !== 'deleted' && (touched || c.change === 'new')) actions += '<button type="button" class="pill st-hist-roll' + (t.arm === kThis ? ' armed' : '') + '" data-hash="' + esc(it.hash) + '" data-target="' + esc(target) + '" data-key="' + esc(kThis) + '" title="Put the files back exactly as they were in this save' + (c.version ? ' (' + esc(c.version) + ')' : '') + '">' + (t.arm === kThis ? 'sure?' : 'restore this') + '</button>';
                        if (touched) actions += '<button type="button" class="pill st-hist-diff' + (t.diff && t.diff.key === it.hash + ':' + target ? ' is-active' : '') + '" data-hash="' + esc(it.hash) + '" data-target="' + esc(target) + '" title="What changed in these files">diff</button>';
                    }
                    html += '<div class="st-comp" data-path="' + esc(c.path) + '"><span class="st-chip ch-' + esc(c.change) + '">' + esc(chg) + '</span>'
                        + '<div class="st-comp-main"><span class="st-comp-name">' + esc(c.title || c.slug) + '</span><span class="st-comp-sub">' + esc(c.type) + ' · ' + esc(c.path) + st + '</span></div>'
                        + '<span class="st-comp-ver">' + ver + '</span>'
                        + (touched ? filesHtml(c.added, c.modified, c.deleted) : '<span></span>')
                        + '<span class="st-actions">' + actions + '</span></div>';
                    if (t.diff && t.diff.key === it.hash + ':' + target) {
                        html += '<div class="st-diff-wrap">' + (t.diff.loading ? '<div class="st-diff-note">Building the diff…</div>'
                            : t.diff.error ? '<div class="st-diff-note">' + esc(t.diff.error) + '</div>'
                            : '<pre class="st-diff">' + (t.diff.text ? this.historyDiffHtml(t.diff.text) : '(no text changes — binary files only)') + '</pre>'
                                + (t.diff.truncated ? '<div class="st-diff-note">Cut at 300 KB. The whole diff: cove history ' + esc(site ? site.name : '') + ' diff ' + esc(it.id) + ' --target=' + esc(target) + '</div>' : '')) + '</div>';
                    }
                }
                if (comps.length > cap) html += '<div class="st-comp-more"><button type="button" class="pill">show all ' + comps.length + ' components</button></div>';
                li.innerHTML = html;
                return li;
            },

            // Snapshots: take, restore (two clicks — it replaces the live
            // files and database, though the CLI snapshots those first), delete.
            async snapshotCreate() {
                const site = this.pageSite;
                const t = this.siteTabState('snapshots');
                if (!site || t.busy['+']) return;
                const note = $id('snapNote').value.trim();
                t.busy['+'] = 'create';
                this.renderSiteTab();
                const res = await this.apiPost('site_snapshot_create', { site_name: site.name, note }, { quiet: true, timeoutMs: 1800000 });
                delete t.busy['+'];
                if (this.sitePage.name !== site.name) return;
                if (!res.success) { this.showSnack(res.message || 'The snapshot failed.', true); this.renderSiteTab(); return; }
                $id('snapNote').value = '';
                this.showSnack('Snapshot ' + (res.snapshot && res.snapshot.id ? res.snapshot.id : '') + ' saved.');
                this.loadSiteTab({ force: true });
            },

            async snapshotOp(id, op) {
                const site = this.pageSite;
                const t = this.siteTabState('snapshots');
                if (!site || t.busy[id] || t.busy['+']) return;
                if (t.arm !== op + ':' + id) {
                    t.arm = op + ':' + id;
                    clearTimeout(t.armTimer);
                    t.armTimer = setTimeout(() => { t.arm = null; this.renderSiteTab(); }, 4000);
                    this.renderSiteTab();
                    return;
                }
                t.arm = null;
                t.busy[id] = op;
                this.renderSiteTab();
                const res = await this.apiPost(op === 'restore' ? 'site_snapshot_restore' : 'site_snapshot_delete', { site_name: site.name, id }, { quiet: true, timeoutMs: 1800000 });
                delete t.busy[id];
                if (this.sitePage.name !== site.name) return;
                if (!res.success) { this.showSnack(res.message || 'Failed.', true); this.renderSiteTab(); return; }
                if (op === 'restore') {
                    this.showSnack('Restored ' + id + '.' + (res.safety ? ' The state from just before is snapshot ' + res.safety + '.' : ''));
                    for (const tab of ['plugins', 'themes', 'users', 'cron']) { const x = this.sitePage.tabs[tab]; if (x) x.loadedFor = null; }
                    this.getSites();
                } else this.showSnack('Deleted snapshot ' + id + '.');
                this.loadSiteTab({ force: true });
            },

            async snapshotDownload(id) {
                const site = this.pageSite;
                const t = this.siteTabState('snapshots');
                if (!site || t.busy[id]) return;
                t.busy[id] = 'pack';
                this.renderSiteTab();
                const res = await this.apiPost('site_snapshot_export', { site_name: site.name, id }, { quiet: true, timeoutMs: 1800000 });
                delete t.busy[id];
                if (this.sitePage.name !== site.name) return;
                this.renderSiteTab();
                if (!res.success) { this.showSnack(res.message || 'Could not pack the snapshot.', true); return; }
                this.showSnack('Packed ' + (res.name || id) + ' (' + this.formatSize(res.bytes) + ') — downloading.');
                // An attachment response leaves the page where it is.
                window.location.href = '/api.php?action=snapshot_download&site=' + encodeURIComponent(site.name) + '&id=' + encodeURIComponent(id) + '&v=' + Date.now();
            },

            async siteCronDelete(hook) {
                const site = this.pageSite;
                const t = this.siteTabState('cron');
                if (!site || t.busy[hook]) return;
                if (t.arm !== 'delete:' + hook) {
                    t.arm = 'delete:' + hook;
                    clearTimeout(t.armTimer);
                    t.armTimer = setTimeout(() => { t.arm = null; this.renderSiteTab(); }, 4000);
                    this.renderSiteTab();
                    return;
                }
                t.arm = null;
                t.busy[hook] = 'delete';
                this.renderSiteTab();
                const res = await this.apiPost('site_cron_run', { site_name: site.name, hook, op: 'delete' }, { quiet: true, timeoutMs: 180000 });
                delete t.busy[hook];
                if (this.sitePage.name !== site.name) return;
                const last = (res.message || '').split('\n').filter(Boolean).pop() || '';
                this.showSnack(last.replace(/^(Success|Error|Warning): /, '') || (res.success ? 'Unscheduled.' : 'Failed.'), !res.success);
                this.loadSiteTab({ force: true });
            },

            // The Files view, opened on a path inside this site.
            openFilesAt(siteName, path) {
                const f = this.files;
                if (!this.filesGuardDirty()) return;
                f.site = siteName; f.path = ''; f.file = null; f.entries = []; f.selected = null; f.filter = '';
                f.target = path;
                $id('filesFilter').value = '';
                this.setView('files', { force: true });
            },

            // --- Tab right-click menu ---------------------------------------
            // items: [{ label, run, danger, key, meta } | { sep: true }]
            openTabCtx(event, title, items) {
                event.preventDefault();
                this.closeRowMenu(); this.closeFileCtx();
                this.tabCtx = { open: true, x: event.clientX, y: event.clientY, openedAt: event.timeStamp, items, title };
                this.renderTabCtx();
                const rect = $id('tabCtxMenu').getBoundingClientRect();
                this.tabCtx.x = Math.max(8, Math.min(event.clientX, window.innerWidth - rect.width - 8));
                this.tabCtx.y = Math.max(8, Math.min(event.clientY, window.innerHeight - rect.height - 8));
                this.renderTabCtx();
            },

            closeTabCtx() {
                if (!this.tabCtx.open) return;
                this.tabCtx.open = false;
                show($id('tabCtxMenu'), false);
            },

            renderTabCtx() {
                const c = this.tabCtx;
                const menu = $id('tabCtxMenu');
                show(menu, c.open);
                if (!c.open) return;
                menu.style.left = c.x + 'px';
                menu.style.top = c.y + 'px';
                const box = $id('tabCtxItems');
                box.innerHTML = '';
                const title = document.createElement('div');
                title.className = 'ctx-title';
                title.textContent = c.title;
                box.appendChild(title);
                c.items.forEach((it, i) => {
                    if (it.sep) { const s = document.createElement('div'); s.className = 'ctx-sep'; box.appendChild(s); return; }
                    const b = document.createElement('button');
                    b.type = 'button';
                    b.className = 'ctx-item' + (it.danger ? ' danger' : '');
                    b.dataset.i = String(i);
                    const l = document.createElement('span'); l.textContent = it.label; b.appendChild(l);
                    if (it.key || it.meta) { const k = document.createElement('span'); k.className = 'ctx-key'; k.textContent = it.key || it.meta; b.appendChild(k); }
                    if (it.disabled) b.disabled = true;
                    box.appendChild(b);
                });
            },

            copyText(text, what) {
                navigator.clipboard.writeText(text).then(() => this.showSnack((what || 'Copied') + '.')).catch(() => this.showSnack('Could not copy.', true));
            },

            // The items for one row of one tab.
            tabCtxItemsFor(tab, it) {
                const site = this.pageSite;
                if (!site) return [];
                const ms = !!site.multisite;
                const items = [];
                if (tab === 'plugins' || tab === 'themes') {
                    const slug = it.name;
                    let dir = 'public/wp-content/themes/' + slug;
                    if (tab === 'plugins') {
                        const file = it.file || '';
                        const base = it.status === 'must-use' ? 'public/wp-content/mu-plugins/' : 'public/wp-content/plugins/';
                        // A folder plugin opens on its folder; a single file opens the file.
                        dir = file.includes('/') ? base + file.slice(0, file.indexOf('/')) : base + (file || slug);
                    }
                    if (tab === 'plugins') {
                        if (it.status === 'inactive') { items.push({ label: 'Activate', run: () => this.siteItemOp(tab, slug, 'activate') }); if (ms) items.push({ label: 'Network activate', run: () => this.siteItemOp(tab, slug, 'activate', true) }); }
                        else if (it.status === 'active') items.push({ label: 'Deactivate', run: () => this.siteItemOp(tab, slug, 'deactivate') });
                        else if (it.status === 'active-network') items.push({ label: 'Network deactivate', run: () => this.siteItemOp(tab, slug, 'deactivate', true) });
                    } else if (it.status === 'inactive') items.push({ label: 'Activate', run: () => this.siteItemOp(tab, slug, 'activate') });
                    if (it.update === 'available') items.push({ label: 'Update', meta: '→ ' + it.update_version, run: () => this.siteItemOp(tab, slug, 'update') });
                    if (it.status !== 'must-use') items.push({ label: it.auto_update === 'on' ? 'Turn auto-updates off' : 'Turn auto-updates on', run: () => this.siteItemOp(tab, slug, it.auto_update === 'on' ? 'auto-off' : 'auto-on') });
                    if (items.length) items.push({ sep: true });
                    items.push({ label: tab === 'plugins' && !(it.file || '').includes('/') ? 'Open file' : 'Browse files', run: () => this.openFilesAt(site.name, dir) });
                    items.push({ label: 'Copy slug', run: () => this.copyText(slug, 'Slug copied') });
                    items.push({ label: 'Previous versions', run: () => this.historyFocus(slug) });
                    if (it.status !== 'must-use' && it.status !== 'active' && it.status !== 'active-network' && it.status !== 'parent') {
                        items.push({ sep: true });
                        items.push({ label: 'Delete…', danger: true, run: () => this.siteItemOp(tab, slug, 'delete') });
                    }
                } else if (tab === 'users') {
                    const blogs = Array.isArray(it.blogs) ? it.blogs.filter(b => b.roles && b.roles.length) : [];
                    if (ms && blogs.length > 1) {
                        blogs.slice(0, 6).forEach(b => items.push({ label: 'Log in on ' + (b.url.replace(/^https?:\/\/[^\/]+/, '') || '/'), meta: b.roles.join(', '), run: () => this.siteUserLogin(it.user_login, b.url) }));
                    } else {
                        items.push({ label: 'Log in as ' + it.user_login, key: '↵', run: () => this.siteUserLogin(it.user_login, it.network_only && blogs[0] ? blogs[0].url : '') });
                    }
                    items.push({ sep: true });
                    items.push({ label: 'Copy login', run: () => this.copyText(it.user_login, 'Login copied') });
                    items.push({ label: 'Copy email', run: () => this.copyText(it.user_email, 'Email copied') });
                    items.push({ label: 'Copy ID', meta: '#' + it.ID, run: () => this.copyText(String(it.ID), 'ID copied') });
                } else if (tab === 'cron') {
                    items.push({ label: 'Run now', run: () => this.siteCronRun(it.hook) });
                    items.push({ label: 'Copy hook', run: () => this.copyText(it.hook, 'Hook copied') });
                    items.push({ sep: true });
                    items.push({ label: 'Unschedule…', danger: true, run: () => this.siteCronDelete(it.hook) });
                } else if (tab === 'snapshots') {
                    const dir = ((this.sitePage.tabs.snapshots && this.sitePage.tabs.snapshots.extra && this.sitePage.tabs.snapshots.extra.dir) || '') + '/' + it.id;
                    items.push({ label: 'Restore…', danger: false, run: () => this.snapshotOp(it.id, 'restore') });
                    items.push({ label: 'Download zip', run: () => this.snapshotDownload(it.id) });
                    items.push({ sep: true });
                    items.push({ label: 'Copy path', run: () => this.copyText(dir, 'Path copied') });
                    items.push({ label: 'Copy id', run: () => this.copyText(it.id, 'Id copied') });
                    items.push({ sep: true });
                    items.push({ label: 'Delete…', danger: true, run: () => this.snapshotOp(it.id, 'delete') });
                } else if (tab === 'history' && it.component) {
                    // A component row inside an opened save.
                    const save = it.save, c = it.component, sum = save.summary || {};
                    const target = c.type === 'file' ? 'file:' + c.path : c.path;
                    const touched = !!(c.added || c.modified || c.deleted);
                    const kBefore = save.hash + ':before:' + c.path, kThis = save.hash + ':this:' + c.path;
                    if (sum.parent && c.change !== 'new' && touched) items.push({ label: (c.change === 'deleted' ? 'Bring back' : 'Undo') + (c.version_from && c.version_from !== c.version ? ' → ' + c.version_from : '') + '…', run: () => { const t = this.siteTabState('history'); t.open = save.id; this.historyRollback(sum.parent, target, kBefore); } });
                    if (c.change !== 'deleted' && (touched || c.change === 'new')) items.push({ label: 'Restore as saved' + (c.version ? ' (' + c.version + ')' : '') + '…', run: () => { const t = this.siteTabState('history'); t.open = save.id; this.historyRollback(save.hash, target, kThis); } });
                    if (touched) items.push({ label: 'Diff', run: () => { const t = this.siteTabState('history'); t.open = save.id; this.historyDiff(save.hash, target); } });
                    if (items.length) items.push({ sep: true });
                    if (c.change !== 'deleted') items.push({ label: c.type === 'file' ? 'Open file' : 'Browse files', run: () => this.openFilesAt(site.name, 'public/wp-content/' + c.path) });
                    items.push({ label: 'Previous versions', run: () => this.historyFocus(c.slug) });
                    items.push({ sep: true });
                    items.push({ label: 'Copy slug', run: () => this.copyText(c.slug, 'Slug copied') });
                    items.push({ label: 'Copy path', run: () => this.copyText('public/wp-content/' + c.path, 'Path copied') });
                } else if (tab === 'history') {
                    const t = this.siteTabState('history');
                    items.push({ label: t.open === it.id ? 'Collapse' : 'What changed', run: () => this.historyToggle(it.id) });
                    items.push({ label: 'Roll back everything to this save…', danger: true, run: () => { t.open = it.id; this.historyRollback(it.hash, 'all', it.hash + ':all'); } });
                    items.push({ sep: true });
                    items.push({ label: 'Copy id', run: () => this.copyText(it.id, 'Id copied') });
                    items.push({ label: 'Copy hash', run: () => this.copyText(it.hash, 'Hash copied') });
                }
                return items;
            },

            async siteUserLogin(login, url) {
                const site = this.pageSite;
                const t = this.siteTabState('users');
                if (!site || t.busy[login]) return;
                t.busy[login] = 'login';
                this.renderSiteTab();
                const res = await this.apiPost('get_login_link', url ? { site_name: site.name, user: login, url } : { site_name: site.name, user: login });
                delete t.busy[login];
                if (res.success && res.url) { window.open(res.url, '_blank'); this.showSnack('Login link for ' + login + ' opened in a new tab.'); }
                if (this.sitePage.name === site.name) this.renderSiteTab();
            },

            async runSiteCli() {
                const site = this.pageSite;
                const c = this.sitePage.cli;
                const input = $id('siteCliInput');
                const line = input.value.trim();
                if (!site || !line || c.running) return;
                c.running = true; c.cmd = line;
                c.history = [line].concat(c.history.filter(h => h !== line)).slice(0, 50);
                c.histIdx = -1;
                try { localStorage.setItem('cove.cli.history', JSON.stringify(c.history)); } catch (e) {}
                this.renderSiteCli();
                const res = await this.apiPost('site_wp', { site_name: site.name, args: line }, { quiet: true, timeoutMs: 300000 });
                c.running = false;
                if (!res.success) { c.output = res.message || 'Failed.'; c.code = 1; c.ms = 0; }
                else { c.output = res.output; c.code = res.code; c.ms = res.ms; c.notices = res.notices || 0; }
                c.ran = line;
                this.renderSiteCli();
                // Listings the command may have changed are refetched next visit.
                for (const tab of ['plugins', 'themes', 'users', 'cron']) { const t = this.sitePage.tabs[tab]; if (t) t.loadedFor = null; }
            },

            siteTabVisible(tab) {
                const t = this.siteTabState(tab);
                const q = t.filter.trim().toLowerCase();
                let rows = t.items;
                if (tab === 'plugins' || tab === 'themes') {
                    if (t.status === 'active') rows = rows.filter(i => i.status === 'active' || i.status === 'active-network' || i.status === 'must-use' || i.status === 'parent');
                    if (t.status === 'inactive') rows = rows.filter(i => i.status === 'inactive');
                    if (t.status === 'updates') rows = rows.filter(i => i.update === 'available');
                    if (q) rows = rows.filter(i => (i.name + ' ' + (i.title || '')).toLowerCase().includes(q));
                    const rank = { 'must-use': 0, 'active-network': 1, active: 1, parent: 2, inactive: 3 };
                    rows = [...rows].sort((a, b) => (rank[a.status] ?? 4) - (rank[b.status] ?? 4) || (a.title || a.name).localeCompare(b.title || b.name));
                } else if (tab === 'users') {
                    if (q) rows = rows.filter(u => (u.user_login + ' ' + u.display_name + ' ' + u.user_email + ' ' + u.roles).toLowerCase().includes(q));
                } else if (tab === 'cron') {
                    if (q) rows = rows.filter(e => (e.hook + ' ' + e.recurrence).toLowerCase().includes(q));
                } else if (tab === 'history') {
                    if (q) rows = rows.filter(s => { const sum = s.summary || {}; const comps = Array.isArray(sum.components) ? sum.components : []; return (s.id + ' ' + (s.note || '') + ' ' + (sum.summary || '') + ' ' + comps.map(c => c.slug + ' ' + (c.title || '')).join(' ')).toLowerCase().includes(q); });
                }
                return rows;
            },

            renderSiteTab() {
                if (this.view !== 'site') return;
                const p = this.sitePage;
                const tab = p.tab;
                if (tab === 'cli') { this.renderSiteCli(); return; }
                if (tab === 'traffic') { this.renderTraffic(); return; }
                if (tab === 'overview') { this.renderSiteHealth(); return; }
                if (!['plugins', 'themes', 'users', 'cron', 'snapshots', 'history'].includes(tab)) return;
                const site = this.pageSite;
                const t = this.siteTabState(tab);
                const panel = $id('sitePanel-' + tab);
                const list = panel.querySelector('.st-list');
                list.querySelectorAll('.st-row, .st-empty, .st-detail').forEach(n => n.remove());
                const loaded = site && t.loadedFor === site.name;
                show(panel.querySelector('.st-loading'), t.loading && !loaded);
                const err = panel.querySelector('.st-error');
                show(err, !t.loading && !!t.error);
                if (t.error) err.textContent = t.error;
                const filter = panel.querySelector('.st-filter');
                if (filter && filter.value !== t.filter) filter.value = t.filter;
                const take = panel.querySelector('#btnSnapCreate');
                if (take) { take.disabled = !!t.busy['+']; take.textContent = t.busy['+'] ? 'snapshotting…' : 'take snapshot'; }
                const hsave = panel.querySelector('#btnHistSave');
                if (hsave) { hsave.disabled = !!t.busy['+']; hsave.textContent = t.busy['+'] ? 'saving…' : 'save now'; }
                let savingText = '';
                if (tab === 'history' && t.busy['+'] && t.saving) {
                    const sv = t.saving;
                    const secs = Math.max(0, Math.round(Date.now() / 1000 - sv.started));
                    const stage = { manifest: 'reading versions', hashing: 'hashing', writing: 'writing the tree', summarising: 'summarising', packing: 'packing' }[sv.stage] || 'starting';
                    savingText = 'saving: ' + stage + (sv.files ? ' · ' + sv.files.toLocaleString() + ' files' : '') + ' · ' + (secs >= 60 ? Math.floor(secs / 60) + 'm ' + (secs % 60) + 's' : secs + 's');
                }
                panel.querySelectorAll('.st-status').forEach(b => b.classList.toggle('is-active', b.dataset.status === t.status));
                const refresh = panel.querySelector('.st-refresh');
                if (refresh) refresh.disabled = t.loading;
                const check = panel.querySelector('.st-check');
                if (check) { check.disabled = t.loading; check.textContent = t.loading && t.checking ? 'checking…' : 'check for updates'; }
                const due = panel.querySelector('.st-due');
                if (due) { due.disabled = !!t.busy['*']; due.textContent = t.busy['*'] ? 'running…' : 'run all due'; }
                const count = panel.querySelector('.st-count');
                if (!loaded) { count.textContent = savingText; return; }
                const rows = this.siteTabVisible(tab);
                const label = { plugins: 'plugin', themes: 'theme', users: 'user', cron: 'event', snapshots: 'snapshot', history: 'save' }[tab];
                const updates = (tab === 'plugins' || tab === 'themes') ? t.items.filter(i => i.update === 'available').length : 0;
                count.textContent = (rows.length === t.items.length ? t.items.length : rows.length + ' of ' + t.items.length) + ' ' + label + (t.items.length === 1 ? '' : 's')
                    + (updates ? ' · ' + updates + ' update' + (updates === 1 ? '' : 's') : '')
                    + (t.ms ? ' · ' + (t.ms >= 1000 ? (t.ms / 1000).toFixed(1) + ' s' : t.ms + ' ms') : '');
                if (savingText) count.textContent = savingText;
                if (check) check.title = t.checked ? 'Checked wp.org this visit — click to check again' : 'Updates shown are as WordPress last saw them; click to ask wp.org now (loads the site\'s plugins, so it can take a while)';
                const frag = document.createDocumentFragment();
                const esc = (s) => this.escapeHtml(s == null ? '' : String(s));
                const ms = site && site.multisite;
                if (!rows.length) { const li = document.createElement('li'); li.className = 'st-empty'; li.textContent = t.items.length ? 'Nothing matches.' : (tab === 'history' ? 'No saves yet — press save now, or wait for tonight.' : 'Nothing here.'); frag.appendChild(li); }
                for (const it of rows) {
                    const li = document.createElement('li');
                    li.className = 'st-row st-' + tab;
                    if (tab === 'plugins' || tab === 'themes') {
                        const slug = it.name;
                        const busy = t.busy[slug];
                        const on = it.status === 'active' || it.status === 'active-network' || it.status === 'must-use' || it.status === 'parent';
                        const chip = it.status === 'active-network' ? 'network' : it.status === 'must-use' ? 'mu' : it.status === 'parent' ? 'parent' : it.status;
                        li.classList.toggle('is-off', !on);
                        li.dataset.slug = slug;
                        let actions = '';
                        if (busy) actions = '<span class="st-busy">' + ({ activate: 'activating…', deactivate: 'deactivating…', update: 'updating…', delete: 'deleting…' }[busy] || 'saving…') + '</span>';
                        else {
                            if (tab === 'plugins') {
                                if (it.status === 'inactive') actions += '<button type="button" class="pill st-act" data-op="activate">activate</button>' + (ms ? '<button type="button" class="pill st-act" data-op="activate" data-network="1" title="Activate for every site on the network">network activate</button>' : '');
                                else if (it.status === 'active') actions += '<button type="button" class="pill st-act" data-op="deactivate">deactivate</button>';
                                else if (it.status === 'active-network') actions += '<button type="button" class="pill st-act" data-op="deactivate" data-network="1">network deactivate</button>';
                            } else {
                                if (it.status === 'inactive') actions += '<button type="button" class="pill st-act" data-op="activate">activate</button>';
                            }
                            if (it.update === 'available') actions += '<button type="button" class="pill primary st-act" data-op="update" title="Update to ' + esc(it.update_version) + '">update</button>';
                            if (it.status !== 'must-use' && it.status !== 'active' && it.status !== 'active-network' && it.status !== 'parent') actions += '<button type="button" class="pill st-act st-del' + (t.arm === slug ? ' armed' : '') + '" data-op="delete">' + (t.arm === slug ? 'sure? delete' : '×') + '</button>';
                        }
                        li.innerHTML = '<div class="st-main"><span class="st-title">' + esc(it.title || it.name) + '</span><span class="st-sub">' + esc(it.name) + '</span></div>'
                            + '<span class="st-ver">' + esc(it.version || '') + (it.update === 'available' ? ' <span class="st-upd" title="Update available">→ ' + esc(it.update_version) + '</span>' : '') + '</span>'
                            + '<span class="st-chip st-status-' + esc(it.status) + '">' + esc(chip) + '</span>'
                            + (it.status === 'must-use' ? '<span></span>' : '<button type="button" class="st-auto' + (it.auto_update === 'on' ? ' is-on' : '') + '" data-op="' + (it.auto_update === 'on' ? 'auto-off' : 'auto-on') + '" title="Auto-updates ' + (it.auto_update === 'on' ? 'on — click to turn off' : 'off — click to turn on') + '">auto</button>')
                            + '<span class="st-actions">' + actions + '</span>';
                    } else if (tab === 'users') {
                        const supers = (t.extra && t.extra.super_admins) || [];
                        const roles = String(it.roles || '').split(',').map(r => r.trim()).filter(Boolean);
                        if (supers.includes(it.user_login)) roles.unshift('super admin');
                        const blogs = Array.isArray(it.blogs) ? it.blogs : [];
                        let chips = roles.map(r => '<span class="st-chip">' + esc(r) + '</span>');
                        let loginUrl = '';
                        if (it.network_only && blogs.length) {
                            // Roles on subsites, shown with the site's path.
                            const others = blogs.filter(b => b.roles && b.roles.length);
                            chips = others.slice(0, 2).map(b => '<span class="st-chip" title="' + esc(b.url) + '">' + esc(b.roles.join(', ')) + ' @ ' + esc(b.url.replace(/^https?:\/\/[^\/]+/, '') || '/') + '</span>');
                            if (others.length > 2) chips.push('<span class="st-chip st-none">+' + (others.length - 2) + '</span>');
                            const best = others.find(b => b.roles.includes('administrator')) || others[0];
                            if (best) loginUrl = best.url;
                        } else if (blogs.length > 1) {
                            chips.push('<span class="st-chip st-none" title="' + esc(blogs.map(b => b.url).join('\n')) + '">' + blogs.length + ' sites</span>');
                        }
                        const busy = t.busy[it.user_login];
                        li.dataset.login = it.user_login;
                        if (loginUrl) li.dataset.loginUrl = loginUrl;
                        li.innerHTML = '<div class="st-main"><span class="st-title">' + esc(it.display_name || it.user_login) + '</span><span class="st-sub">' + esc(it.user_login) + ' · ' + esc(it.user_email) + '</span></div>'
                            + '<span class="st-roles">' + (chips.length ? chips.join('') : '<span class="st-chip st-none">no role</span>') + '</span>'
                            + '<span class="st-ver" title="' + esc(it.registered || '') + '">' + esc(it.registered ? String(it.registered).slice(0, 10) : '') + '</span>'
                            + '<span class="st-actions"><button type="button" class="pill primary st-login"' + (busy ? ' disabled' : '') + ' title="One-time login as ' + esc(it.user_login) + (loginUrl ? ' on ' + esc(loginUrl) : '') + '">' + (busy ? 'opening…' : 'log in') + '</button></span>';
                    } else if (tab === 'snapshots') {
                        const busy = t.busy[it.id];
                        const armR = t.arm === 'restore:' + it.id, armD = t.arm === 'delete:' + it.id;
                        li.dataset.id = it.id;
                        li.classList.toggle('is-auto', !!it.auto);
                        const rel = it.created ? this.formatRelative(it.created) : '';
                        const when = rel === 'now' ? 'just now' : (rel ? rel + ' ago' : '');
                        li.innerHTML = '<div class="st-main"><span class="st-title" title="' + esc(it.created ? new Date(it.created * 1000).toLocaleString() : '') + '">' + esc(it.id) + (it.auto ? ' <span class="st-chip st-none">auto</span>' : '') + '</span><span class="st-sub">' + esc(it.note || (it.auto ? '' : 'no note')) + (it.wp ? ' · wp ' + esc(it.wp) : '') + '</span></div>'
                            + '<span class="st-ver">' + esc(when) + '</span>'
                            + '<span class="st-ver" title="Files' + (it.has_db ? ' + database' : '') + '">' + this.formatSize(it.files_bytes) + (it.has_db ? ' + ' + this.formatSize(it.db_bytes) + ' db' : '') + '</span>'
                            + '<span class="st-actions">' + (busy ? '<span class="st-busy">' + (busy === 'restore' ? 'restoring…' : busy === 'pack' ? 'packing…' : 'deleting…') + '</span>'
                                : '<button type="button" class="pill st-restore' + (armR ? ' armed' : '') + '" data-op="restore" title="Put these files and this database back in place (the current state is snapshotted first)">' + (armR ? 'sure? restore' : 'restore') + '</button>'
                                + '<button type="button" class="pill st-dl" data-op="download" title="Pack files and database as a zip and download it">download</button>'
                                + '<button type="button" class="pill st-del' + (armD ? ' armed' : '') + '" data-op="delete" title="Delete this snapshot">' + (armD ? 'sure? delete' : '×') + '</button>') + '</span>';
                    } else if (tab === 'history') {
                        const sum = it.summary || {};
                        const f = sum.files || {};
                        const rel = it.created ? this.formatRelative(it.created) : '';
                        const when = rel === 'now' ? 'just now' : (rel ? rel + ' ago' : '');
                        const note = it.note && it.note !== 'Nightly save' && it.note !== 'Save' ? it.note : '';
                        li.dataset.id = it.id;
                        li.classList.toggle('is-auto', !!it.auto && !note);
                        li.classList.toggle('is-open', t.open === it.id);
                        const headline = this.historyHeadline(sum) || note || 'Save';
                        li.title = (sum.summary && sum.summary !== headline ? sum.summary + '\n' : '') + (it.created ? new Date(it.created * 1000).toLocaleString() : '');
                        li.innerHTML = '<div class="st-main"><span class="st-title">' + esc(headline) + '</span><span class="st-sub">' + esc(it.id) + (note && sum.summary ? ' · ' + esc(note) : '') + (it.auto ? ' · nightly' : '') + (it.wp ? ' · wp ' + esc(it.wp) : '') + '</span></div>'
                            + '<span class="st-when">' + esc(when) + '</span>'
                            + '<span class="st-hist-files" title="Files added, modified, deleted"><span class="f-add">+' + (f.added || 0) + '</span><span>~' + (f.modified || 0) + '</span><span class="f-del">−' + (f.deleted || 0) + '</span></span>'
                            + '<span class="st-chev">›</span>';
                        frag.appendChild(li);
                        if (t.open === it.id) frag.appendChild(this.historyDetail(it, t));
                        continue;
                    } else if (tab === 'cron') {
                        const busy = t.busy[it.hook];
                        const armX = t.arm === 'delete:' + it.hook;
                        const gmt = it.next_run_gmt ? Date.parse(it.next_run_gmt.replace(' ', 'T') + 'Z') : 0;
                        const past = gmt && gmt < Date.now();
                        li.dataset.hook = it.hook;
                        li.classList.toggle('is-due', !!past);
                        li.innerHTML = '<div class="st-main"><span class="st-title st-mono">' + esc(it.hook) + '</span></div>'
                            + '<span class="st-ver" title="' + esc(it.next_run_gmt || '') + ' UTC">' + (past ? 'due' : esc(it.next_run_relative || '')) + '</span>'
                            + '<span class="st-chip' + (it.recurrence === 'Non-repeating' ? ' st-none' : '') + '">' + esc(it.recurrence === 'Non-repeating' ? 'once' : it.recurrence) + '</span>'
                            + '<span class="st-actions">' + (busy ? '<span class="st-busy">' + (busy === 'delete' ? 'unscheduling…' : 'running…') + '</span>' : '<button type="button" class="pill st-run">run now</button>' + (armX ? '<button type="button" class="pill st-del armed st-cron-del">sure? unschedule</button>' : '')) + '</span>';
                    }
                    frag.appendChild(li);
                }
                list.appendChild(frag);
                if (tab === 'history') {
                    const x = t.extra || {};
                    const dir = (x.dir || '').replace(/^\/Users\/[^\/]+|^\/home\/[^\/]+/, '~');
                    const swept = this.sweepLine();
                    $id('histFoot').textContent = x.enabled === false ? 'This site has no wp-content, so there is nothing for history to save.'
                        : (t.items.length ? [dir, this.formatSize(x.bytes || 0), swept].filter(Boolean).join(' · ')
                            : 'Plugins, themes and mu-plugins are saved to ' + dir + ' every night while the desktop is idle, and whenever you press save now' + (swept ? '; ' + swept : '') + '.');
                }
                if (tab === 'snapshots') {
                    const total = t.items.reduce((s, i) => s + (i.files_bytes || 0) + (i.db_bytes || 0), 0);
                    const dir = (t.extra && t.extra.dir ? t.extra.dir : '').replace(/^\/Users\/[^\/]+|^\/home\/[^\/]+/, '~');
                    $id('snapFoot').textContent = t.items.length ? dir + ' · ' + this.formatSize(total) + ' as reported by du; copy-on-write clones share unchanged blocks with the site, so the real footprint is smaller' : (dir ? 'Snapshots are kept under ' + dir + '. A restore snapshots the current state first, so it can be undone.' : '');
                }
            },

            renderSiteCli() {
                const c = this.sitePage.cli;
                const site = this.pageSite;
                $id('siteCliPrompt').textContent = 'cove wp ' + (site ? site.name : '') + ' ';
                $id('btnSiteCliRun').disabled = c.running;
                $id('btnSiteCliRun').textContent = c.running ? 'running…' : 'run';
                const out = $id('siteCliOut');
                const meta = $id('siteCliMeta');
                if (c.ran === null) { out.textContent = ''; show(out, false); meta.textContent = ''; return; }
                show(out, true);
                out.textContent = c.output === '' ? '(no output)' : c.output;
                out.classList.toggle('is-error', c.code !== 0);
                meta.textContent = '$ wp ' + c.ran + '  ·  exit ' + c.code + (c.ms ? ' · ' + (c.ms >= 1000 ? (c.ms / 1000).toFixed(1) + ' s' : c.ms + ' ms') : '') + (c.notices ? ' · ' + c.notices + ' PHP notice line' + (c.notices === 1 ? '' : 's') + ' hidden' : '');
            },

            bindSiteTabEvents() {
                const p = this.sitePage;
                try { p.cli.history = JSON.parse(localStorage.getItem('cove.cli.history') || '[]'); } catch (e) {}
                $id('siteTabs').addEventListener('click', (e) => {
                    const b = e.target.closest('.mail-part');
                    if (b) this.setSiteTab(b.dataset.tab);
                });
                for (const tab of ['plugins', 'themes', 'users', 'cron', 'snapshots', 'history']) {
                    const panel = $id('sitePanel-' + tab);
                    const t = () => this.siteTabState(tab);
                    const filter = panel.querySelector('.st-filter');
                    if (filter) {
                        filter.addEventListener('input', () => { t().filter = filter.value; this.renderSiteTab(); });
                        filter.addEventListener('keydown', (e) => { if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); t().filter = ''; filter.value = ''; filter.blur(); this.renderSiteTab(); } });
                    }
                    panel.querySelectorAll('.st-status').forEach(b => b.addEventListener('click', () => { t().status = b.dataset.status; this.renderSiteTab(); }));
                    const refresh = panel.querySelector('.st-refresh');
                    if (refresh) refresh.addEventListener('click', () => this.loadSiteTab({ force: true }));
                    const check = panel.querySelector('.st-check');
                    if (check) check.addEventListener('click', () => { t().checking = true; this.loadSiteTab({ force: true, check: true }).then(() => { t().checking = false; this.renderSiteTab(); }); });
                    const due = panel.querySelector('.st-due');
                    if (due) due.addEventListener('click', () => this.siteCronRun(null));
                    panel.querySelector('.st-list').addEventListener('click', (e) => {
                        const row = e.target.closest('.st-row');
                        if (tab === 'history') { this.historyClick(e, row); return; }
                        if (!row) return;
                        const act = e.target.closest('.st-act');
                        if (act) { this.siteItemOp(tab, row.dataset.slug, act.dataset.op, !!act.dataset.network); return; }
                        const auto = e.target.closest('.st-auto');
                        if (auto) { this.siteItemOp(tab, row.dataset.slug, auto.dataset.op); return; }
                        if (e.target.closest('.st-login')) { this.siteUserLogin(row.dataset.login, row.dataset.loginUrl || ''); return; }
                        if (e.target.closest('.st-run')) { this.siteCronRun(row.dataset.hook); return; }
                        const snap = e.target.closest('.st-restore, .st-snapshots .st-del');
                        if (snap && row.dataset.id) { this.snapshotOp(row.dataset.id, snap.dataset.op); return; }
                        if (e.target.closest('.st-dl') && row.dataset.id) { this.snapshotDownload(row.dataset.id); return; }
                        if (e.target.closest('.st-cron-del')) { this.siteCronDelete(row.dataset.hook); return; }
                    });
                }
                for (const tab of ['plugins', 'themes', 'users', 'cron', 'snapshots', 'history']) {
                    $id('sitePanel-' + tab).querySelector('.st-list').addEventListener('contextmenu', (e) => {
                        if (tab === 'history') {
                            const comp = e.target.closest('.st-comp');
                            const detail = comp && comp.closest('.st-detail');
                            if (comp && detail) {
                                const t = this.siteTabState('history');
                                const save = t.items.find(x => x.id === detail.dataset.id);
                                const c = save && Array.isArray((save.summary || {}).components) ? save.summary.components.find(x => x.path === comp.dataset.path) : null;
                                if (!save || !c) return;
                                const items = this.tabCtxItemsFor('history', { component: c, save });
                                if (items.length) this.openTabCtx(e, c.title || c.slug, items);
                                return;
                            }
                        }
                        const row = e.target.closest('.st-row');
                        if (!row) return;
                        const t = this.siteTabState(tab);
                        const key = tab === 'users' ? 'user_login' : tab === 'cron' ? 'hook' : (tab === 'snapshots' || tab === 'history') ? 'id' : 'name';
                        const val = row.dataset.login || row.dataset.hook || row.dataset.id || row.dataset.slug;
                        const it = t.items.find(x => String(x[key]) === val);
                        if (!it) return;
                        const items = this.tabCtxItemsFor(tab, it);
                        if (!items.length) return;
                        const title = tab === 'users' ? it.user_login : tab === 'cron' ? it.hook : (tab === 'snapshots' || tab === 'history') ? it.id : (it.title || it.name);
                        this.openTabCtx(e, title, items);
                    });
                }
                $id('tabCtxMenu').addEventListener('click', (e) => {
                    const b = e.target.closest('.ctx-item');
                    if (!b) return;
                    const it = this.tabCtx.items[Number(b.dataset.i)];
                    this.closeTabCtx();
                    if (it && it.run) it.run();
                });
                document.addEventListener('click', (e) => {
                    if (!this.tabCtx.open || e.timeStamp === this.tabCtx.openedAt) return;
                    if (!$id('tabCtxMenu').contains(e.target)) this.closeTabCtx();
                });
                window.addEventListener('scroll', () => { if (this.tabCtx.open) this.closeTabCtx(); }, { passive: true });
                window.addEventListener('resize', () => { if (this.tabCtx.open) this.closeTabCtx(); });
                $id('sitePanel-traffic').querySelectorAll('.st-status').forEach(b => b.addEventListener('click', () => this.setTrafficRange(b.dataset.range)));
                $id('sitePanel-traffic').querySelector('.st-refresh').addEventListener('click', () => this.loadTraffic({ force: true }));
                this.bindTrafficModalEvents();
                $id('siteHealth').addEventListener('click', (e) => { if (e.target.closest('.site-health-bit')) this.setSiteTab('traffic'); });
                $id('btnSnapCreate').addEventListener('click', () => this.snapshotCreate());
                $id('btnHistSave').addEventListener('click', () => this.historySave());
                $id('histNote').addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); this.historySave(); } if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); e.target.blur(); } });
                $id('snapNote').addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); this.snapshotCreate(); } if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); e.target.blur(); } });
                const input = $id('siteCliInput');
                input.addEventListener('keydown', (e) => {
                    const c = p.cli;
                    if (e.key === 'Enter') { e.preventDefault(); this.runSiteCli(); return; }
                    if (e.key === 'ArrowUp' && c.history.length) { e.preventDefault(); c.histIdx = Math.min(c.history.length - 1, c.histIdx + 1); input.value = c.history[c.histIdx]; return; }
                    if (e.key === 'ArrowDown' && c.histIdx >= 0) { e.preventDefault(); c.histIdx = c.histIdx - 1; input.value = c.histIdx >= 0 ? c.history[c.histIdx] : ''; return; }
                    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); input.blur(); }
                });
                $id('btnSiteCliRun').addEventListener('click', () => this.runSiteCli());
                $id('siteCliExamples').addEventListener('click', (e) => {
                    const b = e.target.closest('button');
                    if (!b) return;
                    input.value = b.dataset.cmd;
                    input.focus();
                });
            },

            // --- Syntax highlighting ---------------------------------------
            // A small tokenizer of Cove's own — no library, nothing fetched.
            // Each language is a list of [class, pattern] pairs compiled into
            // one alternation; the first alternative to match at a position
            // wins, and anything no rule claims is plain text. Rules must not
            // contain capturing groups (the alternation's numbering relies on
            // it). The result paints a <pre> that sits under the textarea.
            get hlLangs() {
                if (this._hlLangs) return this._hlLangs;
                const str = `'(?:[^'\\\\\\n]|\\\\.)*'|"(?:[^"\\\\\\n]|\\\\.)*"`;
                const num = `\\b0x[\\da-fA-F]+\\b|\\b\\d+(?:\\.\\d+)?(?:e[+-]?\\d+)?\\b`;
                const kw = (list) => `\\b(?:${list})\\b`;
                const L = {
                    php: [
                        ['cmt', `\\/\\*[\\s\\S]*?\\*\\/|\\/\\/[^\\n]*|#(?!\\[)[^\\n]*`],
                        ['str', str],
                        ['var', `\\$[A-Za-z_]\\w*`],
                        ['num', num],
                        ['kw', kw('abstract|and|array|as|break|callable|case|catch|class|clone|const|continue|declare|default|do|echo|else|elseif|empty|enddeclare|endfor|endforeach|endif|endswitch|endwhile|enum|extends|final|finally|fn|for|foreach|function|global|goto|if|implements|include|include_once|instanceof|insteadof|interface|isset|list|match|namespace|new|or|print|private|protected|public|readonly|require|require_once|return|static|switch|throw|trait|try|unset|use|var|while|xor|yield|true|false|null|TRUE|FALSE|NULL|self|parent|int|string|bool|float|void|mixed|never|iterable|object|__DIR__|__FILE__|__LINE__|__CLASS__|__FUNCTION__|__METHOD__|__NAMESPACE__')],
                        ['fn', `\\b[A-Za-z_]\\w*(?=\\s*\\()`],
                    ],
                    js: [
                        ['cmt', `\\/\\*[\\s\\S]*?\\*\\/|\\/\\/[^\\n]*`],
                        ['str', '`(?:[^`\\\\]|\\\\.)*`|' + str],
                        ['num', num],
                        ['kw', kw('async|await|break|case|catch|class|const|continue|debugger|default|delete|do|else|export|extends|finally|for|from|function|get|if|import|in|instanceof|let|new|of|return|set|static|super|switch|this|throw|try|typeof|var|void|while|with|yield|true|false|null|undefined|NaN|Infinity|interface|type|enum|implements|readonly|declare|namespace|abstract|as|is|keyof')],
                        ['fn', `\\b[A-Za-z_$][\\w$]*(?=\\s*\\()`],
                    ],
                    css: [
                        ['cmt', `\\/\\*[\\s\\S]*?\\*\\/`],
                        ['str', str],
                        ['kw', `@[\\w-]+|!important\\b`],
                        ['num', `#[\\da-fA-F]{3,8}\\b|\\b\\d+(?:\\.\\d+)?(?:px|em|rem|%|vh|vw|vmin|vmax|ch|s|ms|deg|fr|pt)?\\b|\\.\\d+(?:px|em|rem|%|s|ms)?\\b`],
                        ['attr', `[A-Za-z-]+(?=\\s*:(?!:))`],
                        ['fn', `\\b[a-z-]+(?=\\()`],
                        ['tag', `[.#][A-Za-z_-][\\w-]*|::?[a-z-]+(?![\\w-]*\\s*:)`],
                    ],
                    html: [
                        ['cmt', `<!--[\\s\\S]*?-->|<!DOCTYPE[^>]*>|<!doctype[^>]*>`],
                        ['tag', `<\\/?[A-Za-z][\\w:-]*|\\/?>`],
                        ['str', str],
                        ['attr', `\\b[A-Za-z_:@][\\w:.-]*(?=\\s*=)`],
                        ['num', `&[#\\w]+;`],
                    ],
                    json: [
                        ['attr', `"(?:[^"\\\\]|\\\\.)*"(?=\\s*:)`],
                        ['str', `"(?:[^"\\\\]|\\\\.)*"`],
                        ['num', `-?\\b\\d+(?:\\.\\d+)?(?:[eE][+-]?\\d+)?\\b`],
                        ['kw', kw('true|false|null')],
                    ],
                    sql: [
                        ['cmt', `--[^\\n]*|#[^\\n]*|\\/\\*[\\s\\S]*?\\*\\/`],
                        ['str', '`[^`\\n]*`|' + str],
                        ['num', num],
                        ['kw', kw('SELECT|FROM|WHERE|AND|OR|NOT|NULL|INSERT|INTO|VALUES|UPDATE|SET|DELETE|CREATE|TABLE|ALTER|DROP|INDEX|PRIMARY|KEY|DEFAULT|AUTO_INCREMENT|JOIN|LEFT|RIGHT|INNER|OUTER|CROSS|ON|AS|ORDER|BY|GROUP|HAVING|LIMIT|OFFSET|UNION|ALL|DISTINCT|IF|EXISTS|BEGIN|COMMIT|ROLLBACK|TRUNCATE|ENGINE|CHARSET|COLLATE|UNSIGNED|INT|INTEGER|VARCHAR|CHAR|TEXT|LONGTEXT|MEDIUMTEXT|DATETIME|DATE|TIMESTAMP|BIGINT|TINYINT|SMALLINT|DECIMAL|FLOAT|DOUBLE|BOOLEAN|LIKE|IN|IS|BETWEEN|CASE|WHEN|THEN|ELSE|END|COUNT|SUM|MAX|MIN|AVG|ASC|DESC|USE|SHOW|DESCRIBE|EXPLAIN|LOCK|UNLOCK|TABLES|WRITE|READ|REPLACE|IGNORE|DUPLICATE|CONSTRAINT|FOREIGN|REFERENCES|UNIQUE|CASCADE|VIEW|TRIGGER|PROCEDURE|FUNCTION|RETURNS|DECLARE|WITH')],
                        ['fn', `\\b[A-Za-z_]\\w*(?=\\s*\\()`],
                    ],
                    shell: [
                        ['cmt', `(?:^|(?<=\\s))#[^\\n]*`],
                        ['str', `"(?:[^"\\\\]|\\\\[\\s\\S])*"|'[^']*'`],
                        ['var', `\\$\\{[^}\\n]*\\}|\\$[\\w@#?*!$-]+|\\$\\(`],
                        ['num', num],
                        ['kw', kw('if|then|else|elif|fi|for|while|until|do|done|case|esac|in|function|select|return|local|export|readonly|declare|typeset|exit|echo|printf|set|unset|shift|break|continue|source|eval|exec|trap|test|read|cd|true|false')],
                        ['fn', `^\\s*[A-Za-z_][\\w-]*(?=\\s*\\(\\))`],
                    ],
                    md: [
                        ['str', '```[\\s\\S]*?```|`[^`\\n]+`'],
                        ['kw', `^#{1,6}[^\\n]*`],
                        ['cmt', `^>[^\\n]*`],
                        ['fn', `!?\\[[^\\]\\n]*\\]\\([^)\\n]*\\)`],
                        ['attr', `\\*\\*[^*\\n]+\\*\\*|__[^_\\n]+__|(?<![\\w*])\\*[^*\\n]+\\*(?!\\w)|(?<![\\w_])_[^_\\n]+_(?!\\w)`],
                        ['tag', `^\\s*(?:[-*+]|\\d+\\.)\\s|^-{3,}$|^={3,}$`],
                    ],
                    conf: [
                        ['cmt', `(?:^|(?<=\\s))[#;][^\\n]*`],
                        ['kw', `^\\s*\\[[^\\]\\n]+\\]\\s*$`],
                        ['attr', `^\\s*[\\w.-]+(?=\\s*[:=])`],
                        ['str', str],
                        ['num', num],
                        ['var', `\\$\\{[^}\\n]*\\}|\\$[A-Za-z_]\\w*|\\{\\$?[\\w.]+\\}`],
                        ['fn', kw('true|false|yes|no|on|off|null|True|False|None')],
                    ],
                    generic: [
                        ['cmt', `\\/\\*[\\s\\S]*?\\*\\/|\\/\\/[^\\n]*|(?:^|(?<=\\s))#[^\\n]*`],
                        ['str', `"""[\\s\\S]*?"""|'''[\\s\\S]*?'''|` + str],
                        ['num', num],
                        ['kw', kw('def|class|if|elif|else|for|while|return|import|from|as|with|try|except|finally|raise|pass|lambda|yield|and|or|not|in|is|None|True|False|self|func|package|var|let|const|struct|type|interface|fn|pub|mut|impl|use|mod|match|enum|trait|where|loop|break|continue|new|this|nil|end|do|then|begin|module|require|unless|when|case|switch|default|throw|throws|catch|public|private|protected|static|final|void|int|string|bool|float|double|char|long|guard|defer|extension|protocol|override|super|async|await')],
                        ['fn', `\\b[A-Za-z_]\\w*(?=\\s*\\()`],
                    ],
                };
                const out = {};
                for (const [name, rules] of Object.entries(L)) {
                    out[name] = { classes: rules.map(r => r[0]), re: new RegExp(rules.map(r => '(' + r[1] + ')').join('|'), name === 'sql' ? 'gim' : 'gm') };
                }
                this._hlLangs = out;
                return out;
            },

            hlLang(name) {
                const base = name.toLowerCase();
                const ext = base.includes('.') ? base.slice(base.lastIndexOf('.') + 1) : '';
                if (['php', 'phtml', 'inc'].includes(ext)) return 'php';
                if (['js', 'mjs', 'cjs', 'jsx', 'ts', 'tsx', 'vue'].includes(ext)) return 'js';
                if (['css', 'scss', 'sass', 'less'].includes(ext)) return 'css';
                if (['html', 'htm', 'xml', 'svg', 'xhtml', 'twig', 'hbs', 'mustache'].includes(ext)) return 'html';
                if (ext === 'json' || ext === 'webmanifest' || base === 'composer.lock') return 'json';
                if (ext === 'sql') return 'sql';
                if (['sh', 'bash', 'zsh', 'fish'].includes(ext) || ['makefile', 'dockerfile'].includes(base)) return 'shell';
                if (['md', 'markdown', 'mdx'].includes(ext) || base === 'readme') return 'md';
                if (['yml', 'yaml', 'toml', 'ini', 'conf', 'cfg', 'env', 'properties', 'htaccess', 'editorconfig', 'gitignore', 'gitattributes', 'lock'].includes(ext) || base.startsWith('.env') || base === 'caddyfile' || base === '.htaccess' || base === 'wp-cli.yml') return 'conf';
                if (['py', 'rb', 'go', 'rs', 'java', 'kt', 'swift', 'c', 'h', 'cpp', 'hpp', 'cs', 'lua', 'pl', 'r', 'scala', 'dart'].includes(ext)) return 'generic';
                if (['txt', 'log', 'csv', 'tsv', 'pot', 'po'].includes(ext)) return null;
                return null;
            },

            hlEscape(s) { return s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c])); },

            hlTokens(text, lang) {
                const L = this.hlLangs[lang];
                if (!L || !text) return this.hlEscape(text);
                const re = L.re;
                re.lastIndex = 0;
                let out = '', last = 0, m;
                while ((m = re.exec(text))) {
                    if (m[0] === '') { re.lastIndex++; continue; }
                    if (m.index > last) out += this.hlEscape(text.slice(last, m.index));
                    let cls = '';
                    for (let i = 1; i < m.length; i++) if (m[i] !== undefined) { cls = L.classes[i - 1]; break; }
                    out += '<span class="hl-' + cls + '">' + this.hlEscape(m[0]) + '</span>';
                    last = m.index + m[0].length;
                }
                return out + this.hlEscape(text.slice(last));
            },

            // HTML with script/style islands; PHP as HTML with PHP islands.
            hlHtml(text) {
                const re = /(<script\b[^>]*>)([\s\S]*?)(<\/script\s*>)|(<style\b[^>]*>)([\s\S]*?)(<\/style\s*>)/gi;
                let out = '', last = 0, m;
                while ((m = re.exec(text))) {
                    out += this.hlTokens(text.slice(last, m.index), 'html');
                    if (m[1] !== undefined) out += this.hlTokens(m[1], 'html') + this.hlTokens(m[2], 'js') + this.hlTokens(m[3], 'html');
                    else out += this.hlTokens(m[4], 'html') + this.hlTokens(m[5], 'css') + this.hlTokens(m[6], 'html');
                    last = m.index + m[0].length;
                }
                return out + this.hlTokens(text.slice(last), 'html');
            },

            hlPhp(text) {
                const re = /<\?(?:php\b|=)?[\s\S]*?(?:\?>|$(?![\s\S]))/g;
                let out = '', last = 0, m;
                while ((m = re.exec(text))) {
                    if (m[0] === '') { re.lastIndex++; continue; }
                    out += this.hlHtml(text.slice(last, m.index));
                    const open = /^<\?(?:php\b|=)?/.exec(m[0])[0];
                    const close = m[0].endsWith('?>') ? '?>' : '';
                    const inner = m[0].slice(open.length, m[0].length - close.length);
                    out += '<span class="hl-tag">' + this.hlEscape(open) + '</span>' + this.hlTokens(inner, 'php') + (close ? '<span class="hl-tag">?&gt;</span>' : '');
                    last = m.index + m[0].length;
                }
                return out + this.hlHtml(text.slice(last));
            },

            highlight(text, lang) {
                if (lang === 'php') return this.hlPhp(text);
                if (lang === 'html') return this.hlHtml(text);
                return this.hlTokens(text, lang);
            },

            // Repaint the layer under the textarea. Deferred to the next
            // frame so a burst of keystrokes costs one pass; files past the
            // size cap stay plain (the textarea shows its own text then).
            renderFilesHighlight(now) {
                const f = this.files;
                const code = $id('filesCode');
                const ta = $id('filesText');
                const lang = f.file && f.file.kind === 'text' ? this.hlLang(this.filesBase(f.file.path)) : null;
                const plain = !lang || ta.value.length > 400000;
                code.classList.toggle('is-plain', plain);
                if (plain) { $id('filesHlCode').innerHTML = ''; return; }
                cancelAnimationFrame(f.hlFrame);
                const paint = () => {
                    const text = ta.value;
                    $id('filesHlCode').innerHTML = this.highlight(text, lang) + (text.endsWith('\n') ? '​' : '');
                    this.syncFilesHighlight();
                };
                if (now) paint(); else f.hlFrame = requestAnimationFrame(paint);
            },

            syncFilesHighlight() {
                const ta = $id('filesText');
                const pre = $id('filesHl');
                pre.scrollTop = ta.scrollTop;
                pre.scrollLeft = ta.scrollLeft;
                // A visible scrollbar narrows the textarea's text column; the
                // layer wraps at the same width only when it loses the same.
                const bar = ta.offsetWidth - ta.clientWidth;
                pre.style.right = bar + 'px';
                const hbar = ta.offsetHeight - ta.clientHeight;
                pre.style.bottom = hbar + 'px';
            },

            // --- File context menu -----------------------------------------
            // Right-click on a row, on the listing itself (the open folder),
            // or on a crumb. The target is a path inside the site; the site
            // root and public/ ARE the site, so their delete is the real
            // delete-site flow with its undo window, never a file delete.
            openFileCtx(target, event) {
                event.preventDefault();
                const f = this.files;
                this.closeRowMenu();
                this.fileCtx = { open: true, target, x: event.clientX, y: event.clientY, openedAt: event.timeStamp };
                this.renderFileCtxMenu();
                const rect = $id('fileCtxMenu').getBoundingClientRect();
                this.fileCtx.x = Math.max(8, Math.min(event.clientX, window.innerWidth - rect.width - 8));
                this.fileCtx.y = Math.max(8, Math.min(event.clientY, window.innerHeight - rect.height - 8));
                this.renderFileCtxMenu();
                if (target.inList) { f.selected = target.name; this.renderFilesList(); }
            },

            closeFileCtx() {
                if (!this.fileCtx.open) return;
                this.fileCtx.open = false;
                show($id('fileCtxMenu'), false);
            },

            // target: { path, name, type, inList } — inList when it is a row
            // of the open folder (rename/delete act on rows only).
            fileCtxIsSite(t) { return t.path === '' || t.path === 'public'; },

            renderFileCtxMenu() {
                const menu = $id('fileCtxMenu');
                const c = this.fileCtx;
                show(menu, c.open);
                if (!c.open) return;
                const f = this.files;
                const t = c.target;
                menu.style.left = c.x + 'px';
                menu.style.top = c.y + 'px';
                const isDir = t.type === 'dir';
                const site = this.fileCtxIsSite(t);
                const rowOps = !!t.inList && f.writable && !site;
                $id('fctxTitle').textContent = t.path === '' ? this.filesRoot : t.name + (isDir ? '/' : '');
                show($id('fctxOpen'), !!t.inList);
                show($id('fctxRename'), rowOps);
                show($id('fctxDownload'), !isDir);
                show($id('fctxNewFile'), isDir && f.writable);
                show($id('fctxNewFolder'), isDir && f.writable);
                show($id('fctxUpload'), isDir && f.writable);
                show($id('fctxSepNew'), isDir && f.writable);
                $id('fctxReveal').querySelector('span').textContent = isDir ? this.revealLabel : (this.revealLabel.startsWith('Reveal') ? 'Reveal in Finder' : 'Show in folder');
                show($id('fctxDelete'), rowOps);
                show($id('fctxDeleteSite'), site);
                show($id('fctxSepDel'), rowOps || site);
            },

            async fileCtxRun(what) {
                const f = this.files;
                const t = this.fileCtx.target;
                if (!t) return;
                this.closeFileCtx();
                if (what === 'open') { this.filesNavigate(t.path, t.type); return; }
                if (what === 'rename') { if (t.inList) this.startFilesRename(t.name); return; }
                if (what === 'download') { const a = document.createElement('a'); a.href = this.filesRawUrl(t.path, true); a.download = t.name; document.body.appendChild(a); a.click(); a.remove(); return; }
                if (what === 'reveal') {
                    const res = await this.apiPost('file_reveal', { site: f.site, path: t.path }, { timeoutMs: 10000 });
                    if (res.success) this.showSnack('Opened in the file manager.');
                    return;
                }
                if (what === 'copy') {
                    const abs = (f.root || '') + (t.path ? '/' + t.path : '');
                    navigator.clipboard.writeText(abs).then(() => this.showSnack('Path copied.')).catch(() => this.showSnack('Could not copy.', true));
                    return;
                }
                if (what === 'newfile' || what === 'newfolder' || what === 'upload') {
                    const dir = t.type === 'dir' ? t.path : this.filesParent(t.path);
                    if (dir !== f.path || f.file) { await this.filesNavigate(dir, 'dir'); if (f.path !== dir) return; }
                    if (what === 'upload') $id('filesUploadInput').click();
                    else this.startFilesCreate(what === 'newfile' ? 'file' : 'dir');
                    return;
                }
                if (what === 'delete') { if (t.inList) this.deleteFilesEntry(t.name); return; }
                if (what === 'deletesite') { this.openSiteDeleteConfirm(f.site); return; }
            },

            // The confirm before a site is staged for deletion from the Files
            // view. Staging itself is deleteSite(): the row leaves the sites
            // list at once and the undo snackbar holds the real work back.
            openSiteDeleteConfirm(name) {
                const site = this.sites.find(s => s.name === name);
                if (!site) { this.showSnack('That site is not in the list — is it still being created?', true); return; }
                this.siteDeleteConfirm = name;
                $id('siteDeleteName').textContent = name + '.localhost';
                $id('siteDeleteSub').textContent = (site.type === 'WordPress'
                    ? 'Deletes the whole site: every file under ' + name + '.localhost/ (public/, logs, uploads) and its database. '
                    : 'Deletes the whole site: every file under ' + name + '.localhost/. ')
                    + 'The Files view cannot delete just the site folder — this is the same as "Delete site" on the sites list, with the same few seconds to undo.';
                show($id('siteDeleteModal'), true);
                $id('btnSiteDeleteConfirm').focus();
            },

            closeSiteDeleteConfirm() {
                this.siteDeleteConfirm = null;
                show($id('siteDeleteModal'), false);
            },

            confirmSiteDelete() {
                const name = this.siteDeleteConfirm;
                this.closeSiteDeleteConfirm();
                if (!name) return;
                const f = this.files;
                f.dirty = false;
                if (f.site === name) this.setFilesSite(null);
                if (this.view === 'site' && this.sitePage.name === name) this.setView('sites');
                this.deleteSite(name);
            },

            // --- Files -----------------------------------------------------
            // A file manager over each site's directory. `path` is the
            // folder on screen, `file` the one open in the editor (its parent
            // is `path`), both relative to ~/Cove/Sites/<site>.localhost.
            // The URL names whichever is deeper: /files/<site>/<path>.
            get filesVisible() {
                const f = this.files;
                const q = f.filter.trim().toLowerCase();
                let rows = f.entries.filter(e => (f.hidden || e.name[0] !== '.') && (!q || e.name.toLowerCase().includes(q)));
                const dir = f.dir === 'desc' ? -1 : 1;
                const cmp = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });
                rows.sort((a, b) => {
                    if ((a.type === 'dir') !== (b.type === 'dir')) return a.type === 'dir' ? -1 : 1;
                    let r = 0;
                    if (f.sort === 'size') r = (a.size || 0) - (b.size || 0);
                    else if (f.sort === 'mtime') r = (a.mtime || 0) - (b.mtime || 0);
                    if (r) return r * dir;
                    const n = cmp.compare(a.name, b.name);
                    return f.sort === 'name' ? n * dir : n;
                });
                return rows;
            },

            get filesRoot() { return this.files.site ? this.files.site + '.localhost' : ''; },

            filesJoin(dir, name) { return dir ? dir + '/' + name : name; },
            filesParent(path) { const i = path.lastIndexOf('/'); return i === -1 ? '' : path.slice(0, i); },
            filesBase(path) { const i = path.lastIndexOf('/'); return i === -1 ? path : path.slice(i + 1); },
            filesEncode(path) { return path ? '/' + path.split('/').map(encodeURIComponent).join('/') : ''; },
            filesRawUrl(path, dl) {
                return '/api.php?action=file_raw&site=' + encodeURIComponent(this.files.site) + '&path=' + encodeURIComponent(path) + (dl ? '&dl=1' : '');
            },

            // From a site's row menu or the sidebar: that site's root.
            openFilesForSite(name) {
                const f = this.files;
                if (!this.filesGuardDirty()) return;
                f.site = name; f.path = ''; f.file = null; f.target = null; f.entries = []; f.selected = null; f.filter = '';
                $id('filesFilter').value = '';
                this.setView('files', { force: true });
            },

            setFilesSite(name) {
                if (name === this.files.site) return;
                if (!this.filesGuardDirty()) return;
                const f = this.files;
                f.site = name || null; f.path = ''; f.file = null; f.target = null; f.entries = []; f.selected = null; f.error = null; f.filter = '';
                $id('filesFilter').value = '';
                this.syncUrl();
                this.renderFiles();
                if (f.site) this.loadFilesDir();
            },

            // An unsaved edit blocks navigation rather than being dropped.
            filesGuardDirty() {
                if (!this.files.dirty) return true;
                this.showSnack('Unsaved changes — save or discard them first.', true);
                $id('filesText').focus();
                return false;
            },

            // Open whatever `path` is. With a hint the round trip that asks is
            // skipped; without one (a URL typed by hand) the server says.
            async filesNavigate(path, hint) {
                const f = this.files;
                if (!f.site) return;
                if (!this.filesGuardDirty()) return;
                path = (path || '').replace(/^\/+|\/+$/g, '');
                let kind = hint || null;
                if (!kind) {
                    const seq = ++f.seq;
                    f.loading = true; f.error = null;
                    this.renderFilesList();
                    const res = await this.apiPost('file_list', { site: f.site, path }, { quiet: true, timeoutMs: 20000 });
                    if (seq !== f.seq) return;
                    if (!res.success) { f.loading = false; f.error = res.message || 'Not found.'; f.path = path; f.file = null; this.syncUrl({ replace: true }); this.renderFiles(); return; }
                    if (res.kind === 'dir') { this.applyFilesDir(path, res); this.syncUrl({ replace: true }); this.renderFiles(); return; }
                    kind = 'file';
                }
                if (kind === 'dir') {
                    f.selected = null;
                    f.path = path; f.file = null; f.filter = ''; $id('filesFilter').value = '';
                    this.syncUrl();
                    this.renderFiles();
                    this.loadFilesDir();
                    return;
                }
                const parent = this.filesParent(path);
                const sameDir = parent === f.path && f.loadedFor === f.site + '\0' + parent;
                f.path = parent;
                f.file = { path, kind: null, loading: true };
                f.selected = this.filesBase(path);
                this.syncUrl();
                this.renderFiles();
                if (!sameDir) this.loadFilesDir();
                this.loadFile();
            },

            filesUp() {
                const f = this.files;
                if (f.file) { this.closeFile(); return; }
                if (!f.path) return;
                const from = this.filesBase(f.path);
                this.filesNavigate(this.filesParent(f.path), 'dir').then(() => { f.selected = from; this.renderFilesList(); });
            },

            closeFile() {
                const f = this.files;
                if (!f.file) return;
                if (!this.filesGuardDirty()) return;
                f.selected = this.filesBase(f.file.path);
                f.file = null; f.conflict = false; f.renderedPath = null;
                this.syncUrl();
                this.renderFiles();
                if (f.loadedFor !== f.site + '\0' + f.path) this.loadFilesDir();
            },

            applyFilesDir(path, res) {
                const f = this.files;
                f.loading = false; f.error = null;
                f.path = path;
                f.entries = res.entries || [];
                f.root = res.root || '';
                f.writable = res.writable !== false;
                f.loadedFor = f.site + '\0' + path;
                if (f.selected && !f.entries.some(e => e.name === f.selected)) f.selected = null;
            },

            async loadFilesDir() {
                const f = this.files;
                if (!f.site) return;
                const seq = ++f.seq;
                const path = f.path;
                f.loading = true; f.error = null;
                this.renderFilesList();
                this.renderFilesFooter();
                const res = await this.apiPost('file_list', { site: f.site, path }, { quiet: true, timeoutMs: 20000 });
                if (seq !== f.seq) return;
                f.loading = false;
                if (!res.success) { f.error = res.message || 'Could not read that folder.'; f.entries = []; }
                else if (res.kind !== 'dir') { f.error = 'Not a folder.'; f.entries = []; }
                else this.applyFilesDir(path, res);
                this.renderFilesList();
                this.renderFilesBar();
                this.renderFilesFooter();
                this.renderFilesChrome();
            },

            async loadFile() {
                const f = this.files;
                if (!f.site || !f.file) return;
                const path = f.file.path;
                const seq = ++f.fileSeq;
                f.dirty = false; f.conflict = false;
                this.renderFilesEditor();
                const res = await this.apiPost('file_read', { site: f.site, path }, { quiet: true, timeoutMs: 30000 });
                if (seq !== f.fileSeq || !f.file || f.file.path !== path) return;
                if (!res.success) { f.file = { path, kind: 'error', error: res.message || 'Could not read that file.', loading: false }; }
                else f.file = Object.assign({ loading: false }, res);
                f.renderedPath = null;
                this.renderFilesEditor();
                this.renderFilesBar();
                this.renderFilesFooter();
            },

            async saveFile(force) {
                const f = this.files;
                const file = f.file;
                if (!file || file.kind !== 'text' || f.saving) return;
                if (!f.dirty && !f.conflict) return;
                const content = $id('filesText').value;
                f.saving = true;
                this.renderFilesBar();
                // After a conflict the button reads "overwrite?" and the next
                // click sends force.
                const res = await this.apiPost('file_write', { site: f.site, path: file.path, content, mtime: file.mtime, force: !!force || !!f.conflict }, { quiet: true, timeoutMs: 30000 });
                f.saving = false;
                if (!f.file || f.file.path !== file.path) return;
                if (!res.success) {
                    if (res.conflict) { f.conflict = true; f.dirty = true; this.showSnack('Changed on disk since it was opened — click again to overwrite.', true); }
                    else this.showSnack(res.message || 'Could not save.', true);
                    this.renderFilesBar(); this.renderFilesFooter();
                    return;
                }
                file.content = content; file.size = res.size; file.mtime = res.mtime;
                f.dirty = false; f.conflict = false;
                this.showSnack('Saved ' + this.filesBase(file.path) + '.');
                this.renderFilesBar(); this.renderFilesFooter();
                // The listing behind the editor shows this file's size and time.
                const e = f.entries.find(x => x.name === this.filesBase(file.path));
                if (e) { e.size = res.size; e.mtime = res.mtime; }
            },

            revertFile() {
                const f = this.files;
                if (!f.file || f.file.kind !== 'text') return;
                $id('filesText').value = f.file.content;
                this.renderFilesHighlight(true);
                f.dirty = false; f.conflict = false;
                this.renderFilesBar(); this.renderFilesFooter();
                $id('filesText').focus();
            },

            // A phantom row at the top of the listing takes the new name.
            startFilesCreate(type) {
                const f = this.files;
                if (!f.site || f.file) return;
                f.edit = { mode: 'create', type, value: '' };
                f.delArm = null;
                this.renderFilesList();
                const input = $id('filesList').querySelector('.file-name-input');
                if (input) input.focus();
            },

            startFilesRename(name) {
                const f = this.files;
                f.edit = { mode: 'rename', name, value: name };
                f.delArm = null;
                this.renderFilesList();
                const input = $id('filesList').querySelector('.file-name-input');
                if (input) { input.focus(); const dot = name.lastIndexOf('.'); input.setSelectionRange(0, dot > 0 ? dot : name.length); }
            },

            cancelFilesEdit() {
                if (!this.files.edit) return;
                this.files.edit = null;
                this.renderFilesList();
            },

            async commitFilesEdit() {
                const f = this.files;
                const ed = f.edit;
                if (!ed) return;
                const value = ed.value.trim().replace(/^\/+|\/+$/g, '');
                if (!value) { this.cancelFilesEdit(); return; }
                f.edit = null;
                if (ed.mode === 'create') {
                    const res = await this.apiPost(ed.type === 'dir' ? 'file_mkdir' : 'file_create', { site: f.site, path: f.path, name: value }, { timeoutMs: 20000 });
                    if (!res.success) { this.renderFilesList(); return; }
                    f.selected = value.split('/')[0];
                    await this.loadFilesDir();
                    if (ed.type === 'file') this.filesNavigate(res.path, 'file');
                    return;
                }
                if (value === ed.name) { this.renderFilesList(); return; }
                const res = await this.apiPost('file_rename', { site: f.site, path: this.filesJoin(f.path, ed.name), to: this.filesJoin(f.path, value) }, { timeoutMs: 20000 });
                if (!res.success) { this.renderFilesList(); return; }
                f.selected = value.includes('/') ? null : value;
                this.showSnack('Renamed to ' + value + '.');
                this.loadFilesDir();
            },

            async deleteFilesEntry(name) {
                const f = this.files;
                if (f.delArm !== name) {
                    f.delArm = name;
                    clearTimeout(f.armTimer);
                    f.armTimer = setTimeout(() => { f.delArm = null; this.renderFilesList(); }, 3500);
                    this.renderFilesList();
                    return;
                }
                f.delArm = null;
                clearTimeout(f.armTimer);
                const res = await this.apiPost('file_delete', { site: f.site, path: this.filesJoin(f.path, name) }, { timeoutMs: 60000 });
                if (!res.success) { this.renderFilesList(); return; }
                if (f.file && this.filesBase(f.file.path) === name) { f.file = null; f.dirty = false; this.syncUrl({ replace: true }); }
                if (f.selected === name) f.selected = null;
                this.showSnack('Deleted ' + name + '.');
                this.loadFilesDir();
                this.renderFilesEditor();
            },

            async deleteOpenFile() {
                const f = this.files;
                if (!f.file) return;
                const name = this.filesBase(f.file.path);
                if (f.delArm !== name) {
                    f.delArm = name;
                    clearTimeout(f.armTimer);
                    f.armTimer = setTimeout(() => { f.delArm = null; this.renderFilesBar(); }, 3500);
                    this.renderFilesBar();
                    return;
                }
                f.delArm = null; clearTimeout(f.armTimer);
                const res = await this.apiPost('file_delete', { site: f.site, path: f.file.path }, { timeoutMs: 60000 });
                if (!res.success) { this.renderFilesBar(); return; }
                f.file = null; f.dirty = false; f.conflict = false;
                this.syncUrl();
                this.showSnack('Deleted ' + name + '.');
                this.renderFiles();
                this.loadFilesDir();
            },

            async backupSite(name) {
                const btn = $id('spBackup');
                if (btn.disabled) return;
                btn.disabled = true;
                btn.querySelector('.pill-label').textContent = 'packing…';
                const res = await this.apiPost('site_backup', { site_name: name }, { quiet: true, timeoutMs: 1800000 });
                btn.disabled = false;
                btn.querySelector('.pill-label').textContent = 'backup zip';
                if (!res.success) { this.showSnack(res.message || 'The backup failed.', true); return; }
                this.showSnack('Backup ' + res.name + ' (' + this.formatSize(res.bytes) + ') saved to ~/Cove/Backups — downloading.');
                window.location.href = '/api.php?action=backup_download&name=' + encodeURIComponent(res.name);
            },

            async revealFiles() {
                const f = this.files;
                if (!f.site) return;
                const res = await this.apiPost('file_reveal', { site: f.site, path: f.file ? f.file.path : f.path }, { timeoutMs: 10000 });
                if (res.success) this.showSnack('Opened in the file manager.');
            },

            // Dropped folders arrive as entries to walk; the paths inside them
            // ride along so the tree is recreated on the other side.
            collectDropped(dt) {
                const items = dt.items ? Array.from(dt.items) : [];
                const entries = items.map(i => i.webkitGetAsEntry ? i.webkitGetAsEntry() : null).filter(Boolean);
                if (!entries.length || !entries.some(e => e.isDirectory)) {
                    return Promise.resolve(Array.from(dt.files || []).map(file => ({ file, path: file.name })));
                }
                const out = [];
                const walk = (entry, prefix) => new Promise(resolve => {
                    if (entry.isFile) { entry.file(file => { out.push({ file, path: prefix + entry.name }); resolve(); }, () => resolve()); return; }
                    if (!entry.isDirectory) { resolve(); return; }
                    const reader = entry.createReader();
                    const all = [];
                    const read = () => reader.readEntries(async (batch) => {
                        if (!batch.length) { for (const e of all) await walk(e, prefix + entry.name + '/'); resolve(); return; }
                        all.push(...batch);
                        read();
                    }, () => resolve());
                    read();
                });
                return (async () => { for (const e of entries) await walk(e, ''); return out; })();
            },

            // PHP's max_file_uploads (20) caps the parts in one request, so a
            // dropped plugin folder goes up in batches.
            async uploadFiles(list) {
                const f = this.files;
                if (!f.site || !list.length) return;
                const dir = f.path;
                const batches = [];
                for (let i = 0; i < list.length; i += 20) batches.push(list.slice(i, i + 20));
                let saved = 0, replaced = 0, failed = [];
                f.uploading = { done: 0, total: list.length, pct: 0 };
                this.renderFilesFooter();
                for (const batch of batches) {
                    const fd = new FormData();
                    fd.append('action', 'file_upload');
                    fd.append('site', f.site);
                    fd.append('path', dir);
                    for (const it of batch) { fd.append('files[]', it.file, it.file.name); fd.append('paths[]', it.path); }
                    const res = await new Promise(resolve => {
                        const xhr = new XMLHttpRequest();
                        xhr.open('POST', '/api.php');
                        xhr.upload.onprogress = (e) => { if (e.lengthComputable) { f.uploading.pct = Math.round(e.loaded / e.total * 100); this.renderFilesFooter(); } };
                        xhr.onload = () => { try { resolve(JSON.parse(xhr.responseText)); } catch (e) { resolve({ success: false, message: 'Upload failed (' + xhr.status + ').' }); } };
                        xhr.onerror = () => resolve({ success: false, message: 'Network error.' });
                        xhr.send(fd);
                    });
                    if (!res.success) { failed = failed.concat(batch.map(b => b.path)); this.showSnack(res.message || 'Upload failed.', true); }
                    else { saved += res.saved || 0; replaced += res.replaced || 0; failed = failed.concat(res.failed || []); }
                    f.uploading.done += batch.length; f.uploading.pct = 0;
                    this.renderFilesFooter();
                }
                f.uploading = null;
                const parts = [];
                if (saved) parts.push(saved + ' added');
                if (replaced) parts.push(replaced + ' replaced');
                if (failed.length) parts.push(failed.length + ' failed');
                this.showSnack('Uploaded: ' + (parts.join(', ') || 'nothing') + '.', failed.length > 0 && !saved && !replaced);
                if (f.path === dir) this.loadFilesDir(); else this.renderFilesFooter();
            },

            renderFiles() {
                if (this.view !== 'files') return;
                this.renderFilesChrome();
                this.renderFilesSide();
                this.renderFilesBar();
                this.renderFilesList();
                this.renderFilesEditor();
                this.renderFilesFooter();
            },

            renderFilesChrome() {
                const f = this.files;
                this.renderViewBack('filesBack', f.site);
                show($id('filesSiteChip'), !!f.site);
                if (f.site) $id('filesSiteChipLabel').textContent = f.site;
                const active = !!f.filter;
                show($id('filesKbd'), !active);
                show($id('btnFilesFilterClear'), active);
                $id('filesHidden').checked = f.hidden;
                const inDir = !!f.site && !f.file;
                $id('btnFilesNewFile').disabled = !inDir || !f.writable;
                $id('btnFilesNewFolder').disabled = !inDir || !f.writable;
                $id('btnFilesUpload').disabled = !inDir || !f.writable;
                $id('btnFilesReveal').disabled = !f.site;
                $id('btnFilesRefresh').disabled = !f.site;
                $id('filesFilter').disabled = !inDir;
            },

            renderFilesSide() {
                const f = this.files;
                const list = $id('filesSites');
                list.querySelectorAll('.db-row').forEach(n => n.remove());
                const loaded = !this.isLoading || this.sites.length > 0;
                show($id('filesSitesLoading'), !loaded);
                const q = f.siteFilter.trim().toLowerCase();
                const rows = [...this.sites].filter(s => !q || s.name.toLowerCase().includes(q)).sort((a, b) => a.name.localeCompare(b.name));
                show($id('filesSitesEmpty'), loaded && rows.length === 0);
                const tpl = $id('tpl-log-source');
                const anchor = $id('filesSitesLoading');
                for (const s of rows) {
                    const row = tpl.content.firstElementChild.cloneNode(true);
                    row.dataset.site = s.name;
                    row.classList.toggle('is-selected', f.site === s.name);
                    row.querySelector('.db-row-name').textContent = s.name;
                    row.querySelector('.db-row-meta').textContent = s.type === 'WordPress' ? 'wp' : 'static';
                    row.querySelector('.db-row-meta').title = s.size_bytes ? this.formatSize(s.size_bytes) + ' on disk' : '';
                    list.insertBefore(row, anchor);
                }
                if (f.site && f.scrolledFor !== f.site) {
                    const sel = list.querySelector('.db-row.is-selected');
                    if (sel) { f.scrolledFor = f.site; sel.scrollIntoView({ block: 'nearest' }); }
                }
            },

            renderFilesBar() {
                const f = this.files;
                const crumbs = $id('filesCrumbs');
                crumbs.innerHTML = '';
                const add = (label, path, current, title) => {
                    const b = document.createElement('button');
                    b.type = 'button';
                    b.className = 'files-crumb' + (current ? ' is-current' : '');
                    b.textContent = label;
                    b.dataset.path = path;
                    if (title) b.title = title;
                    crumbs.appendChild(b);
                    return b;
                };
                const sep = () => { const s = document.createElement('span'); s.className = 'files-crumb-sep'; s.textContent = '/'; crumbs.appendChild(s); };
                if (!f.site) {
                    add('~/Cove/Sites', '', true, '');
                } else {
                    const full = f.file ? f.file.path : f.path;
                    const segs = full ? full.split('/') : [];
                    const abs = (f.root || '~/Cove/Sites/' + this.filesRoot) + (full ? '/' + full : '');
                    add(this.filesRoot, '', segs.length === 0, segs.length === 0 ? 'Click to copy the path' : 'Site root');
                    segs.forEach((s, i) => {
                        sep();
                        const p = segs.slice(0, i + 1).join('/');
                        const last = i === segs.length - 1;
                        add(s, p, last, last ? 'Click to copy the path' : p);
                    });
                    crumbs.lastElementChild.dataset.abs = abs.replace(/^\/Users\/[^\/]+|^\/home\/[^\/]+/, '~');
                    crumbs.lastElementChild.dataset.absFull = abs;
                    if (f.file && f.dirty) { const d = document.createElement('span'); d.className = 'files-dirty'; d.textContent = f.conflict ? 'changed on disk' : 'unsaved'; crumbs.appendChild(d); }
                }
                const file = f.file;
                show($id('filesFileActions'), !!file && !file.loading);
                if (file && !file.loading) {
                    const text = file.kind === 'text';
                    show($id('btnFileWrap'), text);
                    $id('btnFileWrap').classList.toggle('is-on', f.wrap);
                    $id('btnFileWrap').style.color = f.wrap ? 'var(--text)' : '';
                    const dl = $id('btnFileDownload');
                    dl.href = this.filesRawUrl(file.path, true);
                    dl.setAttribute('download', this.filesBase(file.path));
                    const save = $id('btnFileSave');
                    show(save, text);
                    show($id('btnFileRevert'), text && f.dirty);
                    if (text) {
                        const ro = file.writable === false || file.lossy;
                        save.disabled = f.saving || ro || (!f.dirty && !f.conflict);
                        save.classList.toggle('armed', !!f.conflict);
                        save.textContent = f.saving ? 'saving…' : f.conflict ? 'overwrite?' : 'save';
                        save.title = ro ? (file.lossy ? 'Read-only: the file is not valid UTF-8, so saving would alter it' : 'Read-only: this file is not writable') : f.conflict ? 'The file changed on disk since it was opened — click to overwrite anyway' : 'Save (⌘S)';
                    }
                    const del = $id('btnFileDelete');
                    const armed = f.delArm === this.filesBase(file.path);
                    show(del, file.kind !== 'error');
                    del.classList.toggle('armed', armed);
                    del.textContent = armed ? 'sure? delete' : 'delete';
                }
            },

            filesIcon(e) {
                if (e.type === 'dir') return '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"><path d="M1.5 4.5a1 1 0 0 1 1-1h3.6l1.6 1.6h5.8a1 1 0 0 1 1 1v6.4a1 1 0 0 1-1 1h-11a1 1 0 0 1-1-1z"/></svg>';
                return '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"><path d="M3.5 1.5h6l3 3v10h-9z"/><path d="M9.5 1.5v3h3"/></svg>';
            },

            renderFilesList() {
                const f = this.files;
                const list = $id('filesList');
                list.querySelectorAll('.file-row').forEach(n => n.remove());
                document.querySelectorAll('#filesHead button').forEach(b => {
                    b.classList.toggle('is-sorted', b.dataset.sort === f.sort);
                    b.textContent = b.dataset.sort.replace('mtime', 'modified') + (b.dataset.sort === f.sort ? (f.dir === 'asc' ? ' ↑' : ' ↓') : '');
                });
                const rows = f.site && !f.loading && !f.error ? this.filesVisible : [];
                show($id('filesLoading'), !!f.site && f.loading && !f.entries.length);
                show($id('filesError'), !!f.site && !f.loading && !!f.error);
                if (f.error) $id('filesErrorText').textContent = f.error;
                const empty = !f.site || (!f.loading && !f.error && rows.length === 0 && !f.edit);
                show($id('filesEmpty'), empty);
                show($id('filesHead'), !!f.site && !empty);
                if (empty) {
                    const filtered = !!f.filter && f.entries.length > 0;
                    const hiddenOnly = !f.hidden && f.entries.length > 0 && f.entries.every(e => e.name[0] === '.');
                    $id('filesEmptyText').textContent = !f.site ? 'Pick a site.' : filtered ? 'Nothing matches.' : hiddenOnly ? 'Only hidden files here.' : 'Empty folder.';
                    $id('filesEmptyHint').textContent = !f.site ? 'Its files open here — browse, edit, upload, and tidy up without leaving the dashboard.' : filtered ? 'Press Esc to clear the filter.' : hiddenOnly ? 'Turn on "hidden" to see them.' : (f.writable ? 'Drop files here to upload them, or use + file and + folder.' : 'This folder is not writable.');
                }
                const tpl = $id('tpl-file-row');
                const anchor = $id('filesLoading');
                const frag = document.createDocumentFragment();
                const mkInput = (row, value) => {
                    row.classList.add('is-editing');
                    const nameEl = row.querySelector('.file-name');
                    nameEl.innerHTML = '';
                    const input = document.createElement('input');
                    input.type = 'text'; input.className = 'file-name-input'; input.value = value; input.spellcheck = false; input.autocomplete = 'off';
                    input.setAttribute('autocapitalize', 'off');
                    nameEl.appendChild(input);
                    row.querySelector('.file-row-actions').remove();
                };
                if (f.site && f.path && !f.filter) {
                    const up = tpl.content.firstElementChild.cloneNode(true);
                    up.classList.add('is-up', 'is-dir');
                    up.dataset.up = '1';
                    up.querySelector('.file-icon').innerHTML = this.filesIcon({ type: 'dir' });
                    up.querySelector('.file-name-text').textContent = '..';
                    up.querySelector('.file-link').remove();
                    up.querySelector('.file-row-actions').remove();
                    up.title = 'Up to ' + (this.filesParent(f.path) || this.filesRoot);
                    frag.appendChild(up);
                }
                if (f.edit && f.edit.mode === 'create') {
                    const row = tpl.content.firstElementChild.cloneNode(true);
                    row.classList.toggle('is-dir', f.edit.type === 'dir');
                    row.dataset.edit = 'create';
                    row.querySelector('.file-icon').innerHTML = this.filesIcon({ type: f.edit.type });
                    mkInput(row, f.edit.value);
                    row.querySelector('.file-name-input').placeholder = f.edit.type === 'dir' ? 'folder name' : 'file name';
                    frag.appendChild(row);
                }
                for (const e of rows) {
                    const row = tpl.content.firstElementChild.cloneNode(true);
                    row.dataset.name = e.name;
                    row.dataset.type = e.type;
                    row.classList.toggle('is-dir', e.type === 'dir');
                    row.classList.toggle('is-hidden', e.name[0] === '.');
                    row.classList.toggle('is-broken', !!e.broken);
                    row.classList.toggle('is-selected', f.selected === e.name);
                    row.querySelector('.file-icon').innerHTML = this.filesIcon(e);
                    if (f.edit && f.edit.mode === 'rename' && f.edit.name === e.name) {
                        mkInput(row, f.edit.value);
                    } else {
                        row.querySelector('.file-name-text').textContent = e.name;
                        const link = row.querySelector('.file-link');
                        if (e.link) { link.textContent = typeof e.link === 'string' ? e.link : 'symlink'; link.title = e.broken ? 'Broken symlink' : 'Symlink to ' + link.textContent; } else link.remove();
                        const del = row.querySelector('.file-row-del');
                        const armed = f.delArm === e.name;
                        del.classList.toggle('armed', armed);
                        del.textContent = armed ? 'sure?' : '×';
                        del.title = armed ? 'Click again to delete' + (e.type === 'dir' && !e.link ? ' the folder and everything in it' : '') : 'Delete';
                        if (e.name === 'public' && !f.path) { del.remove(); row.querySelector('.file-row-rename').remove(); }
                        if (!f.writable) row.querySelector('.file-row-actions').remove();
                    }
                    row.querySelector('.file-size').textContent = e.type === 'dir' ? '' : (e.broken ? '' : this.formatSize(e.size));
                    const t = row.querySelector('.file-time');
                    t.textContent = e.mtime ? this.formatRelative(e.mtime) : '';
                    t.title = e.mtime ? new Date(e.mtime * 1000).toLocaleString() : '';
                    frag.appendChild(row);
                }
                list.insertBefore(frag, anchor);
                if (f.selected) {
                    const sel = list.querySelector('.file-row.is-selected');
                    if (sel) sel.scrollIntoView({ block: 'nearest' });
                }
            },

            renderFilesEditor() {
                const f = this.files;
                const main = $id('filesMain');
                const file = f.file;
                main.classList.toggle('has-file', !!file);
                const ta = $id('filesText');
                const prev = $id('filesPreview');
                const note = $id('filesNote');
                if (!file) { show($id('filesCode'), false); show(prev, false); show(note, false); f.renderedPath = null; return; }
                const kind = file.loading ? 'loading' : file.kind;
                show($id('filesCode'), kind === 'text');
                show(prev, kind === 'image');
                show(note, kind !== 'text' && kind !== 'image');
                $id('filesCode').classList.toggle('is-wrapped', f.wrap);
                if (kind === 'text') {
                    if (f.renderedPath !== file.path) {
                        ta.value = file.content;
                        ta.scrollTop = 0;
                        f.renderedPath = file.path;
                        f.dirty = false;
                        this.renderFilesHighlight(true);
                    }
                    ta.disabled = file.writable === false || !!file.lossy;
                    ta.readOnly = false;
                } else if (kind === 'image') {
                    const img = $id('filesPreviewImg');
                    const url = this.filesRawUrl(file.path) + '&v=' + (file.mtime || 0);
                    if (img.getAttribute('src') !== url) img.src = url;
                    img.alt = this.filesBase(file.path);
                } else {
                    const text = $id('filesNoteText'), hint = $id('filesNoteHint'), dl = $id('filesNoteDownload');
                    if (kind === 'loading') { text.textContent = 'Loading…'; hint.textContent = ''; show(dl, false); }
                    else if (kind === 'error') { text.textContent = file.error || 'Could not open that file.'; hint.textContent = ''; show(dl, false); }
                    else if (kind === 'large') { text.textContent = 'Too large to edit here.'; hint.textContent = this.formatSize(file.size) + ' — the editor opens files up to 2 MB.'; show(dl, true); }
                    else { text.textContent = 'Binary file.'; hint.textContent = this.formatSize(file.size) + ' — nothing to show as text.'; show(dl, true); }
                    dl.href = this.filesRawUrl(file.path, true);
                    dl.setAttribute('download', this.filesBase(file.path));
                }
            },

            renderFilesFooter() {
                if (this.view !== 'files') return;
                const f = this.files;
                let label = '', hint = '';
                if (f.uploading) {
                    hint = 'uploading ' + Math.min(f.uploading.done + 1, f.uploading.total) + ' of ' + f.uploading.total + (f.uploading.pct ? ' · ' + f.uploading.pct + '%' : '');
                }
                if (f.file && !f.file.loading) {
                    const file = f.file;
                    const parts = [];
                    if (file.kind === 'text') { const v = $id('filesText').value; parts.push((v ? v.split('\n').length : 0).toLocaleString() + ' lines'); }
                    if (file.kind === 'image' && file.width) parts.push(file.width + '×' + file.height);
                    if (file.size !== undefined) parts.push(this.formatSize(file.size));
                    if (file.mtime) { const rel = this.formatRelative(file.mtime); parts.push(rel === 'now' ? 'modified just now' : 'modified ' + rel + ' ago'); }
                    if (file.lossy) parts.push('not UTF-8 · read-only');
                    else if (file.writable === false) parts.push('read-only');
                    label = parts.join(' · ');
                    if (!hint && file.kind === 'text' && !$id('filesText').disabled) hint = f.dirty ? '⌘S to save' : 'Esc to close';
                } else if (f.site && !f.loading && !f.error) {
                    const rows = this.filesVisible;
                    const dirs = rows.filter(e => e.type === 'dir').length;
                    const files = rows.length - dirs;
                    const bytes = rows.reduce((t, e) => t + (e.type === 'dir' ? 0 : (e.size || 0)), 0);
                    const parts = [];
                    if (dirs) parts.push(dirs + ' folder' + (dirs === 1 ? '' : 's'));
                    if (files) parts.push(files + ' file' + (files === 1 ? '' : 's'));
                    if (bytes) parts.push(this.formatSize(bytes));
                    const hiddenN = f.hidden ? 0 : f.entries.filter(e => e.name[0] === '.').length;
                    if (hiddenN) parts.push(hiddenN + ' hidden');
                    label = parts.join(' · ');
                    if (!hint && rows.length) hint = '↑↓ move · ↵ open · ⌫ up';
                }
                $id('filesCount').textContent = label;
                $id('filesHint').textContent = hint;
            },

            filesKeydown(e, typing) {
                const f = this.files;
                const ta = $id('filesText');
                const inEditor = document.activeElement === ta;
                if ((e.metaKey || e.ctrlKey) && !e.shiftKey && !e.altKey && e.key.toLowerCase() === 's') {
                    if (f.file && f.file.kind === 'text') { e.preventDefault(); this.saveFile(); return true; }
                    return false;
                }
                if (inEditor) {
                    if (e.key === 'Escape') { e.preventDefault(); if (this.siteDeleteConfirm) this.closeSiteDeleteConfirm(); else if (this.fileCtx.open) this.closeFileCtx(); else ta.blur(); return true; }
                    if (e.key === 'Tab' && !e.shiftKey && !ta.disabled) {
                        e.preventDefault();
                        const s = ta.selectionStart, end = ta.selectionEnd;
                        ta.setRangeText('\t', s, end, 'end');
                        f.dirty = true; this.renderFilesBar(); this.renderFilesFooter(); this.renderFilesHighlight();
                        return true;
                    }
                    return false;
                }
                if (typing) return false;
                if (e.key === 'Escape') {
                    if (this.siteDeleteConfirm) { this.closeSiteDeleteConfirm(); return true; }
                    if (this.fileCtx.open) { this.closeFileCtx(); return true; }
                    if (this.ctxMenu.open) { this.closeRowMenu(); return true; }
                    if (this.showDbModal) { this.setDbModal(false); return true; }
                    if (f.edit) { this.cancelFilesEdit(); return true; }
                    if (f.delArm) { f.delArm = null; this.renderFilesList(); this.renderFilesBar(); return true; }
                    if (f.file) { this.closeFile(); return true; }
                    if (f.filter) { f.filter = ''; $id('filesFilter').value = ''; this.renderFilesChrome(); this.renderFilesList(); this.renderFilesFooter(); return true; }
                    if (f.path) { this.filesUp(); return true; }
                    return true;
                }
                if (e.ctrlKey || e.metaKey || e.altKey) return false;
                if (e.key === '/') { e.preventDefault(); if (!f.file) $id('filesFilter').focus(); return true; }
                if (e.key === 'Backspace') { e.preventDefault(); this.filesUp(); return true; }
                if (f.file || !f.site) return false;
                const rows = this.filesVisible;
                if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'j' || e.key === 'k') {
                    e.preventDefault();
                    if (!rows.length) return true;
                    const i = rows.findIndex(r => r.name === f.selected);
                    const next = (e.key === 'ArrowDown' || e.key === 'j') ? Math.min(rows.length - 1, i + 1) : Math.max(0, i - 1);
                    f.selected = rows[next].name;
                    this.renderFilesList();
                    return true;
                }
                if (e.key === 'Enter' && f.selected) {
                    const sel = rows.find(r => r.name === f.selected);
                    if (sel && !sel.broken) { e.preventDefault(); this.filesNavigate(this.filesJoin(f.path, sel.name), sel.type); }
                    return true;
                }
                if (e.key === 'Delete' && f.selected && f.writable) { e.preventDefault(); this.deleteFilesEntry(f.selected); return true; }
                if (e.key === 'F2' && f.selected && f.writable) { e.preventDefault(); this.startFilesRename(f.selected); return true; }
                return false;
            },

            bindFilesEvents() {
                const f = this.files;
                try { f.hidden = localStorage.getItem('files.hidden') !== '0'; f.wrap = localStorage.getItem('files.wrap') === '1'; } catch (e) { /* private mode */ }
                const filter = $id('filesFilter');
                filter.addEventListener('input', () => { f.filter = filter.value; f.selected = null; this.renderFilesChrome(); this.renderFilesList(); this.renderFilesFooter(); });
                filter.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); f.filter = ''; filter.value = ''; filter.blur(); this.renderFilesChrome(); this.renderFilesList(); this.renderFilesFooter(); }
                    if (e.key === 'Enter') { const first = this.filesVisible[0]; if (first && !first.broken) { e.preventDefault(); filter.blur(); this.filesNavigate(this.filesJoin(f.path, first.name), first.type); } }
                });
                $id('btnFilesFilterClear').addEventListener('click', () => { f.filter = ''; filter.value = ''; this.renderFilesChrome(); this.renderFilesList(); this.renderFilesFooter(); filter.focus(); });
                $id('filesSiteChipClear').addEventListener('click', () => this.setFilesSite(null));
                $id('filesHidden').addEventListener('change', (e) => { f.hidden = e.target.checked; try { localStorage.setItem('files.hidden', f.hidden ? '1' : '0'); } catch (err) {} this.renderFilesList(); this.renderFilesFooter(); });
                $id('btnFilesNewFile').addEventListener('click', () => this.startFilesCreate('file'));
                $id('btnFilesNewFolder').addEventListener('click', () => this.startFilesCreate('dir'));
                $id('btnFilesUpload').addEventListener('click', () => $id('filesUploadInput').click());
                $id('filesUploadInput').addEventListener('change', (e) => {
                    const list = Array.from(e.target.files || []).map(file => ({ file, path: file.name }));
                    e.target.value = '';
                    this.uploadFiles(list);
                });
                $id('btnFilesReveal').addEventListener('click', () => this.revealFiles());
                $id('btnFilesRefresh').addEventListener('click', () => { this.loadFilesDir(); if (f.file && !f.dirty) this.loadFile(); });
                const siteFilter = $id('filesSiteFilter');
                siteFilter.addEventListener('input', () => { f.siteFilter = siteFilter.value; this.renderFilesSide(); });
                siteFilter.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); f.siteFilter = ''; siteFilter.value = ''; siteFilter.blur(); this.renderFilesSide(); }
                    if (e.key === 'Enter') {
                        const q = f.siteFilter.trim().toLowerCase();
                        const first = [...this.sites].sort((a, b) => a.name.localeCompare(b.name)).find(s => !q || s.name.toLowerCase().includes(q));
                        if (first) { e.preventDefault(); this.setFilesSite(first.name); }
                    }
                });
                $id('filesSites').addEventListener('click', (e) => {
                    const row = e.target.closest('.db-row');
                    if (row) this.setFilesSite(row.dataset.site);
                });
                $id('filesCrumbs').addEventListener('click', (e) => {
                    const b = e.target.closest('.files-crumb');
                    if (!b) return;
                    if (b.classList.contains('is-current')) {
                        const p = b.dataset.absFull;
                        if (!p) return;
                        navigator.clipboard.writeText(p).then(() => this.showSnack('Path copied.')).catch(() => this.showSnack('Could not copy.', true));
                        return;
                    }
                    this.filesNavigate(b.dataset.path, 'dir');
                });
                $id('filesHead').addEventListener('click', (e) => {
                    const b = e.target.closest('button[data-sort]');
                    if (!b) return;
                    if (f.sort === b.dataset.sort) f.dir = f.dir === 'asc' ? 'desc' : 'asc';
                    else { f.sort = b.dataset.sort; f.dir = b.dataset.sort === 'name' ? 'asc' : 'desc'; }
                    this.renderFilesList();
                });
                const list = $id('filesList');
                list.addEventListener('click', (e) => {
                    const row = e.target.closest('.file-row');
                    if (!row || row.classList.contains('is-editing')) return;
                    if (row.dataset.up) { this.filesUp(); return; }
                    if (e.target.closest('.file-row-rename')) { e.stopPropagation(); this.startFilesRename(row.dataset.name); return; }
                    if (e.target.closest('.file-row-del')) { e.stopPropagation(); this.deleteFilesEntry(row.dataset.name); return; }
                    const entry = f.entries.find(x => x.name === row.dataset.name);
                    if (!entry) return;
                    f.selected = entry.name;
                    if (entry.broken) { this.showSnack('That symlink points nowhere.', true); this.renderFilesList(); return; }
                    this.filesNavigate(this.filesJoin(f.path, entry.name), entry.type);
                });
                list.addEventListener('keydown', (e) => {
                    const input = e.target.closest('.file-name-input');
                    if (!input) return;
                    if (e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); f.edit.value = input.value; this.commitFilesEdit(); }
                    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); this.cancelFilesEdit(); }
                });
                list.addEventListener('input', (e) => { const input = e.target.closest('.file-name-input'); if (input && f.edit) f.edit.value = input.value; });
                list.addEventListener('focusout', (e) => {
                    const input = e.target.closest && e.target.closest('.file-name-input');
                    if (!input || !f.edit) return;
                    // Clicking away commits a rename with a real change and drops an empty new-item row.
                    setTimeout(() => { if (f.edit && !list.contains(document.activeElement)) { if (f.edit.value.trim() && f.edit.value !== f.edit.name) this.commitFilesEdit(); else this.cancelFilesEdit(); } }, 0);
                });
                // Drag and drop onto the listing (not the editor).
                const main = $id('filesMain');
                main.addEventListener('dragenter', (e) => { if (!f.site || f.file || !f.writable || !e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes('Files')) return; e.preventDefault(); f.drag++; main.classList.add('is-dragging'); });
                main.addEventListener('dragover', (e) => { if (!main.classList.contains('is-dragging')) return; e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; });
                main.addEventListener('dragleave', () => { if (!main.classList.contains('is-dragging')) return; f.drag = Math.max(0, f.drag - 1); if (!f.drag) main.classList.remove('is-dragging'); });
                main.addEventListener('drop', async (e) => {
                    if (!main.classList.contains('is-dragging')) return;
                    e.preventDefault();
                    f.drag = 0; main.classList.remove('is-dragging');
                    const list = await this.collectDropped(e.dataTransfer);
                    this.uploadFiles(list);
                });
                // Editor.
                const ta = $id('filesText');
                ta.addEventListener('input', () => {
                    const was = f.dirty;
                    f.dirty = f.file && f.file.kind === 'text' ? ta.value !== f.file.content : false;
                    if (was !== f.dirty) this.renderFilesBar();
                    this.renderFilesFooter();
                    this.renderFilesHighlight();
                });
                $id('btnFileSave').addEventListener('click', () => this.saveFile());
                $id('btnFileRevert').addEventListener('click', () => this.revertFile());
                $id('btnFileDelete').addEventListener('click', () => this.deleteOpenFile());
                $id('btnFileWrap').addEventListener('click', () => { f.wrap = !f.wrap; try { localStorage.setItem('files.wrap', f.wrap ? '1' : '0'); } catch (err) {} this.renderFilesEditor(); this.renderFilesBar(); this.renderFilesHighlight(true); });
                // The highlighted layer follows the textarea's scroll and size.
                ta.addEventListener('scroll', () => this.syncFilesHighlight(), { passive: true });
                window.addEventListener('resize', () => { if (this.view === 'files' && f.file) this.syncFilesHighlight(); });
                // Right-click menus: a row, the listing (= the open folder), a crumb.
                list.addEventListener('contextmenu', (e) => {
                    if (!f.site || f.file) return;
                    const row = e.target.closest('.file-row');
                    if (row && (row.classList.contains('is-editing') || row.dataset.up)) return;
                    if (row) {
                        const en = f.entries.find(x => x.name === row.dataset.name);
                        if (!en || en.broken) return;
                        this.openFileCtx({ path: this.filesJoin(f.path, en.name), name: en.name, type: en.type, inList: true }, e);
                    } else {
                        this.openFileCtx({ path: f.path, name: f.path ? this.filesBase(f.path) : '', type: 'dir', inList: false }, e);
                    }
                });
                $id('filesCrumbs').addEventListener('contextmenu', (e) => {
                    const b = e.target.closest('.files-crumb');
                    if (!b || !f.site) return;
                    const p = b.dataset.path;
                    const isFile = !!(f.file && f.file.path === p);
                    this.openFileCtx({ path: p, name: p ? this.filesBase(p) : '', type: isFile ? 'file' : 'dir', inList: false }, e);
                });
                $id('fileCtxMenu').addEventListener('click', (e) => {
                    const b = e.target.closest('.ctx-item');
                    if (b) this.fileCtxRun(b.dataset.act);
                });
                document.addEventListener('click', (e) => {
                    if (!this.fileCtx.open || e.timeStamp === this.fileCtx.openedAt) return;
                    if (!$id('fileCtxMenu').contains(e.target)) this.closeFileCtx();
                });
                window.addEventListener('scroll', () => { if (this.fileCtx.open) this.closeFileCtx(); }, { passive: true });
                window.addEventListener('resize', () => { if (this.fileCtx.open) this.closeFileCtx(); });
                $id('btnSiteDeleteCancel').addEventListener('click', () => this.closeSiteDeleteConfirm());
                $id('btnSiteDeleteConfirm').addEventListener('click', () => this.confirmSiteDelete());
                $id('siteDeleteModal').addEventListener('click', (e) => { if (e.target === e.currentTarget) this.closeSiteDeleteConfirm(); });
                window.addEventListener('beforeunload', (e) => { if (f.dirty) { e.preventDefault(); e.returnValue = ''; } });
            },

            // --- Command palette -------------------------------------------
            // Results mix matching sites with global commands. Sites are ranked
            // by match position so a prefix hit beats a mid-string one.
            get paletteResults() {
                const q = this.palette.query.trim().toLowerCase();
                const out = [];
                const commands = [
                    { key: 'cmd:add',     kind: 'cmd', label: 'Add site',            meta: '',  run: () => { this.closePalette(); this.toggleAdd(); } },
                    { key: 'cmd:reload',  kind: 'cmd', label: 'Reload server',       meta: '',  run: () => { this.closePalette(); this.reloadServer(); } },
                    { key: 'cmd:sizes',   kind: 'cmd', label: 'Refresh disk sizes',  meta: '',  run: () => { this.closePalette(); this.refreshSizes(); } },
                    { key: 'cmd:db',      kind: 'cmd', label: 'Databases',           meta: '',  run: () => { this.closePalette(); this.setView('db'); } },
                    { key: 'cmd:logs',    kind: 'cmd', label: 'Logs',                meta: '',  run: () => { this.closePalette(); this.setView('logs'); } },
                    { key: 'cmd:files',   kind: 'cmd', label: 'Files',               meta: '',  run: () => { this.closePalette(); this.setView('files'); } },
                    { key: 'cmd:adminer', kind: 'cmd', label: 'Open Adminer',        meta: 'external', run: () => { this.closePalette(); window.open(this.adminerUrl, '_blank', 'noopener'); } },
                    { key: 'cmd:mailview',kind: 'cmd', label: 'Mail',                meta: '',  run: () => { this.closePalette(); this.setView('mail'); } },
                    { key: 'cmd:mail',    kind: 'cmd', label: 'Open Mailpit',        meta: 'external', run: () => { this.closePalette(); window.open(this.mailpitUrl, '_blank', 'noopener'); } },
                    { key: 'cmd:creds',   kind: 'cmd', label: 'Database credentials',meta: '',  run: () => { this.closePalette(); this.setDbModal(true); } },
                    { key: 'cmd:theme',   kind: 'cmd', label: 'Toggle theme',        meta: '',  run: () => { this.closePalette(); this.toggleTheme(); } },
                ];
                let sites = this.sites;
                if (q) {
                    sites = sites
                        .map(s => ({ s, i: s.name.toLowerCase().indexOf(q) }))
                        .filter(x => x.i !== -1)
                        .sort((a, b) => a.i - b.i || a.s.name.localeCompare(b.s.name))
                        .map(x => x.s);
                } else {
                    // No query: show pinned first, then whatever the list is
                    // sorted by, capped so the palette stays a menu not a dump.
                    sites = this.filteredSites;
                }
                for (const site of sites.slice(0, 40)) {
                    out.push({
                        key: 'site:' + site.name,
                        kind: site.type === 'WordPress' ? 'wp' : 'static',
                        label: site.name + '.localhost',
                        meta: this.formatSize(site.size_bytes),
                        site,
                        run: () => { this.closePalette(); this.openSitePage(site.name); }
                    });
                }
                for (const c of commands) {
                    if (!q || c.label.toLowerCase().includes(q)) out.push(c);
                }
                return out;
            },

            async reloadServer() {
                this.showSnack('Reloading server…');
                const res = await this.apiPostRetry('reload_server', {}, 3, 10000);
                if (res.success) this.showSnack('Server reloaded.');
            },

            // --- Row actions -----------------------------------------------
            // macOS says "Finder"; everywhere else the file manager has no
            // one name, so stay generic rather than lie about it.
            get revealLabel() {
                return navigator.platform && navigator.platform.startsWith('Mac')
                    ? 'Reveal in Finder' : 'Open folder';
            },

            setDbModal(on) {
                if (on) { this.openService('mariadb'); return; }
                this.sweepModalOpen = false;
                if (this.trafficModal) this.trafficModal.open = false;
                this.trafficModal = null;
                $id('dbModal').classList.remove('is-wide');
                this.showDbModal = false;
                show($id('dbModal'), false);
            },

            // One panel for every nav service. The probe is cached briefly so
            // flipping between caddy / mariadb / mailpit is instant.
            async openService(name) {
                const esc = (v) => String(v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
                this.showDbModal = true;
                show($id('dbModal'), true);
                const svcTitle = $id('svcTitle'), svcStatus = $id('svcStatus'), svcRows = $id('svcRows'), svcNote = $id('svcNote'), svcActions = $id('svcActions');
                svcTitle.textContent = { caddy: 'Caddy', mariadb: 'MariaDB', mailpit: 'Mailpit' }[name] || name;
                svcStatus.textContent = 'Checking…'; svcStatus.classList.remove('is-down');
                svcRows.innerHTML = ''; svcNote.textContent = '';
                svcActions.innerHTML = '<button class="pill" id="btnDbClose">close</button>';
                $id('btnDbClose').addEventListener('click', () => this.setDbModal(false));
                try {
                    if (!this.serviceInfo || (Date.now() - this.serviceInfo.at) > 20000) {
                        const data = await this.apiPost('service_info', {}, { quiet: true, timeoutMs: 8000 });
                        if (!data.success) throw new Error(data.message || 'probe failed');
                        this.serviceInfo = { at: Date.now(), data };
                    }
                    const svc = this.serviceInfo.data.services[name];
                    if (!svc) throw new Error('unknown service');
                    svcStatus.textContent = svc.status;
                    svcStatus.classList.toggle('is-down', !svc.running);
                    svcRows.innerHTML = svc.rows.map(([k, v]) => {
                        const isUrl = /^https?:\/\//.test(v);
                        const val = isUrl ? '<a href="' + esc(v) + '" target="_blank" rel="noopener">' + esc(v.replace(/^https?:\/\//, '')) + '</a>' : esc(v);
                        return '<div class="db-cred-row"><span class="db-cred-label">' + esc(k) + '</span><code class="db-cred-value">' + val + '</code></div>';
                    }).join('');
                    svcNote.textContent = svc.note || '';
                    (svc.actions || []).forEach(a => {
                        let el;
                        if (a.kind === 'open') { el = document.createElement('a'); el.href = a.href; el.target = '_blank'; el.rel = 'noopener'; }
                        else { el = document.createElement('button'); el.type = 'button'; el.addEventListener('click', () => { this.setDbModal(false); if (a.kind === 'reload') this.reloadServer(); if (a.kind === 'mail') this.setView('mail'); if (a.kind === 'db') this.setView('db'); if (a.kind === 'logs') this.setView('logs'); }); }
                        el.className = 'pill'; el.textContent = a.label;
                        svcActions.insertBefore(el, $id('btnDbClose'));
                    });
                } catch (e) {
                    svcStatus.textContent = 'Could not read service status.'; svcStatus.classList.add('is-down');
                }
            },

            promptRename(site) {
                this.rename = { open: true, site, value: site.name, busy: false };
                show($id('renameModal'), true);
                this.renderRename();
                const el = $id('renameInput');
                el.value = site.name;
                el.focus();
                el.select();
            },

            closeRename() {
                this.rename.open = false;
                show($id('renameModal'), false);
            },

            async submitRename() {
                const site = this.rename.site;
                const next = (this.rename.value || '').trim();
                if (!site || !next || next === site.name) { this.closeRename(); return; }
                if (!/^[a-zA-Z0-9-]+$/.test(next)) {
                    this.showSnack('Use letters, numbers and hyphens only.', true);
                    return;
                }
                this.rename.busy = true;
                this.renderRename();
                // Renaming rewrites the Caddyfile, so the response can land
                // mid-reload exactly like a delete does — same retry policy.
                const res = await this.apiPostRetry('rename_site', { site_name: site.name, new_name: next });
                this.rename.busy = false;
                this.renderRename();
                if (!res.success) return;   // apiPost surfaced the reason
                this.closeRename();
                // Carry over UI state that is keyed by name, or a pinned site
                // would silently unpin itself on rename.
                if (this.isPinned(site.name)) {
                    this.pinned = this.pinned.map(n => (n === site.name ? next : n));
                    localStorage.setItem('pinned', JSON.stringify(this.pinned));
                }
                if (this.selectedName === site.name) this.selectedName = next;
                this.showSnack(res.message || 'Renamed.');
                await this.getSites();
            },

            async revealSite(name) {
                const res = await this.apiPost('reveal_site', { site_name: name });
                if (res.success) this.showSnack(res.message || 'Opened in the file manager.');
            },

            openSiteDb(site) {
                // Adminer takes the schema in the query string, so this lands
                // on the site's own tables instead of the server root.
                const url = this.adminerUrl + '/?username=' + encodeURIComponent(DB_USER) +
                            '&db=' + encodeURIComponent(site.db_name || ('cove_' + site.name).replace(/[^a-zA-Z0-9_]/g, '_'));
                window.open(url, '_blank', 'noopener');
            },

            // --- Domains (cove mappings) --------------------------------------
            openDomainsModal(site) {
                this.domainsModal = { open: true, site, busy: false, pending: null };
                $id('domainsInput').value = '';
                this.renderDomainsModal();
                $id('domainsInput').focus();
            },

            closeDomainsModal() {
                this.domainsModal.open = false;
                show($id('domainsModal'), false);
            },

            renderDomainsModal() {
                const m = this.domainsModal;
                show($id('domainsModal'), m.open);
                if (!m.open) return;
                // Read the live site entry: an add/remove refreshes the list
                // and the entry captured at open time would be stale.
                const site = this.sites.find(s => s.name === m.site.name) || m.site;
                const host = site.name + '.localhost';
                const wild = '*.' + host;
                $id('domainsModalSite').textContent = host;
                const rows = [{ name: host, meta: 'primary', kind: 'primary' }];
                if (site.multisite === 'subdomain') rows.push({ name: wild, meta: 'multisite', kind: 'implied' });
                for (const d of (site.mappings || [])) {
                    rows.push({
                        name: d,
                        meta: d.startsWith('*.') ? 'wildcard' : (/\.localhost$/i.test(d) ? '' : '/etc/hosts'),
                        kind: 'mapping',
                    });
                }
                const list = $id('domainsList');
                list.textContent = '';
                const tpl = $id('tpl-dom-row');
                for (const r of rows) {
                    const el = tpl.content.firstElementChild.cloneNode(true);
                    el.classList.add(r.kind);
                    el.querySelector('.dom-name').textContent = r.name;
                    el.querySelector('.dom-meta').textContent = r.meta;
                    const rm = el.querySelector('.dom-remove');
                    rm.dataset.domain = r.name;
                    rm.disabled = m.busy;
                    list.appendChild(el);
                }
                // The common ask — every subdomain of the site — as one click,
                // until it is covered (explicitly or by a subdomain multisite).
                const hasWild = site.multisite === 'subdomain' || (site.mappings || []).includes(wild);
                const hint = $id('domainsHint');
                hint.textContent = '';
                if (!hasWild && !m.busy) {
                    hint.append('Accept any subdomain: ');
                    const a = document.createElement('a');
                    a.href = '#';
                    a.dataset.domain = wild;
                    a.textContent = 'add ' + wild;
                    hint.appendChild(a);
                }
                $id('domainsInput').disabled = m.busy;
                const add = $id('btnDomainsAdd');
                add.disabled = m.busy;
                add.textContent = m.busy && m.pending === 'add' ? 'adding…' : 'add';
                $id('domainsFoot').textContent = m.busy ? 'Reloading Caddy…' : 'cove mappings ' + site.name;
            },

            addDomain(raw) { return this.changeDomain('add_mapping', (raw || '').trim().toLowerCase()); },
            removeDomain(domain) { return this.changeDomain('remove_mapping', domain); },

            async changeDomain(action, domain) {
                const m = this.domainsModal;
                const site = m.site;
                if (!site || !domain || m.busy) return;
                if (!/^(\*\.)?[a-z0-9_]([a-z0-9._-]*[a-z0-9_])?$/i.test(domain) || domain.length > 253) {
                    this.showSnack('Use a hostname: letters, numbers, dots and hyphens, with an optional leading *.', true);
                    return;
                }
                m.busy = true;
                m.pending = action === 'add_mapping' ? 'add' : 'remove';
                this.renderDomainsModal();
                // Both directions rewrite the Caddyfile and reload the Caddy
                // serving this page — same dropped-response retry as rename.
                // Five attempts, not three: with a hundred-odd sites the adapt
                // alone runs past the default retry window.
                const res = await this.apiPostRetry(action, { site_name: site.name, domain }, 5);
                m.busy = false;
                m.pending = null;
                if (!res.success) { this.renderDomainsModal(); return; } // apiPost surfaced the reason
                const live = this.sites.find(s => s.name === site.name);
                if (live) live.mappings = res.mappings || [];
                if (action === 'add_mapping') $id('domainsInput').value = '';
                this.renderDomainsModal();
                if (res.hosts_pending) {
                    this.showSnack(res.message + ' Run cove reload in a terminal to add it to /etc/hosts.', false, { duration: 12000 });
                } else {
                    this.showSnack(res.message);
                }
                this.getSites();
            },

            // --- Per-site PHP version ---------------------------------------
            loadPhpInfo(force = false) {
                if (this.phpInfo && !force) return Promise.resolve(this.phpInfo);
                return fetch('/api.php?action=php_info')
                    .then(r => r.json())
                    .then(d => { this.phpInfo = d; return d; })
                    .catch(() => null); // offline/mid-reload — the modal shows Loading… until retried
            },

            openPhpModal(site) {
                this.phpModal = { open: true, site };
                this.renderPhpModal();
                // Refresh every open: an install may have finished since the
                // last fetch, flipping a greyed row to clickable.
                this.loadPhpInfo(true).then(() => this.renderPhpModal());
            },

            closePhpModal() {
                this.phpModal.open = false;
                show($id('phpModal'), false);
            },

            async choosePhp(version) {
                const site = this.phpModal.site;
                if (!site || !version || this.phpApplying[site.name]) return;
                // Close immediately and show progress on the row itself — the
                // pulsing chip is the status, not a modal spinner.
                this.closePhpModal();
                this.phpApplying[site.name] = version;
                this.renderList();
                // The server backgrounds the whole change (it reloads the very
                // Caddy serving this dashboard), so this returns immediately
                // and the poll below watches for the pin state to flip.
                const res = await this.apiPostRetry('set_php', { site_name: site.name, php_version: version });
                if (!res.success) {
                    delete this.phpApplying[site.name];
                    this.renderList();
                    return; // apiPost surfaced the reason
                }
                if (!res.applying) {
                    // Idempotent no-op: the site was already on the requested
                    // version (e.g. a retried request that had already landed).
                    delete this.phpApplying[site.name];
                    this.renderList();
                    return;
                }
                if (res.installing) {
                    this.showSnack('Installing PHP ' + version + ' via Homebrew — this can take a few minutes…', false, { duration: 300000 });
                }
                this.startPhpPoll(site.name, version, res.installing ? 15 * 60 * 1000 : 90 * 1000);
            },

            startPhpPoll(name, version, timeoutMs) {
                // The change runs detached server-side; the pin state flipping
                // in list_sites is the completion signal. Polled with a raw
                // fetch, not getSites(), so the visible list does not flash
                // "Loading…" every few seconds — and a fetch that dies against
                // the mid-reload server just polls again.
                if (this.phpInstallPoll) clearInterval(this.phpInstallPoll);
                const started = Date.now();
                const wantPin = version === 'default' ? null : version;
                this.phpInstallPoll = setInterval(async () => {
                    try {
                        const r = await fetch('/api.php?action=list_sites');
                        const data = await r.json();
                        const site = data.find(s => s.name === name);
                        if (site && (site.php_version || null) === wantPin) {
                            clearInterval(this.phpInstallPoll);
                            this.phpInstallPoll = null;
                            delete this.phpApplying[name];
                            this.loadPhpInfo(true);
                            await this.getSites();
                            this.showSnack(wantPin
                                ? name + '.localhost is now running PHP ' + version + '.'
                                : name + '.localhost is back on Cove\'s default PHP.');
                        } else if (Date.now() - started > timeoutMs) {
                            clearInterval(this.phpInstallPoll);
                            this.phpInstallPoll = null;
                            delete this.phpApplying[name];
                            this.renderList();
                            this.showSnack('PHP change hasn\'t finished — check ~/Cove/cache/php-apply-' + name + '.log.', true, { duration: 8000 });
                        }
                    } catch (e) { /* mid-reload — keep polling */ }
                }, 3000);
            },

            // Caddy writes one JSON object per line, which is unreadable as a
            // wall of text. Fold each request down to the fields you'd
            // actually scan for — time, status, method, path, duration —
            // and leave anything that isn't a request line untouched.
            get logDisplay() {
                if (this.logView.busy) return 'Loading…';
                const raw = this.logView.text || '';
                if (!raw) return 'No log entries yet.';
                if (this.logView.raw) return raw;
                const out = [];
                for (const line of raw.split('\n')) {
                    const t = line.trim();
                    if (!t) continue;
                    if (t[0] !== '{') { out.push(t); continue; }
                    let o;
                    try { o = JSON.parse(t); } catch (e) { out.push(t); continue; }
                    const req = o.request || {};
                    if (!req.method) { out.push(o.msg ? (o.level || '') + ' ' + o.msg : t); continue; }
                    const time = o.ts ? new Date(o.ts * 1000).toLocaleTimeString() : '';
                    const status = o.status !== undefined ? String(o.status) : '';
                    const dur = typeof o.duration === 'number' ? (o.duration * 1000).toFixed(0) + 'ms' : '';
                    out.push([
                        time,
                        status.padEnd(3),
                        (req.method || '').padEnd(6),
                        req.uri || '',
                        dur
                    ].filter(Boolean).join('  '));
                }
                return out.join('\n') || 'No log entries yet.';
            },

            async viewLog(site, refresh = false) {
                this.logView = { open: true, site: site.name, text: refresh ? this.logView.text : '', truncated: false, busy: true, raw: this.logView.raw };
                show($id('logModal'), true);
                this.renderLog();
                const res = await this.apiPost('site_log', { site_name: site.name });
                this.logView.busy = false;
                if (!res.success) { this.closeLog(); return; }
                this.logView.text = res.log || '';
                this.logView.truncated = !!res.truncated;
                this.renderLog();
                // Logs are read tail-first; jump to the newest lines.
                const el = $id('logPane');
                el.scrollTop = el.scrollHeight;
            },

            closeLog() {
                this.logView.open = false;
                show($id('logModal'), false);
            },

            openPalette() {
                this.palette.open = true;
                this.palette.query = '';
                this.palette.index = 0;
                this.closeRowMenu();
                $id('paletteInput').value = '';
                this.renderPalette();
                $id('paletteInput').focus();
            },

            closePalette() {
                this.palette.open = false;
                show($id('paletteBackdrop'), false);
            },

            paletteMove(delta) {
                const n = this._paletteItems.length;
                if (!n) return;
                this.palette.index = (this.palette.index + delta + n) % n;
                const list = $id('paletteList');
                list.querySelectorAll('.palette-item').forEach(el =>
                    el.classList.toggle('active', Number(el.dataset.index) === this.palette.index));
                const el = list.children[this.palette.index];
                if (el && el.scrollIntoView) el.scrollIntoView({ block: 'nearest' });
            },

            paletteRun(event) {
                const item = this._paletteItems[this.palette.index];
                if (!item) return;
                // A site: Enter opens its page, Shift+Enter the site itself in
                // a new tab, Cmd/Ctrl+Enter a one-time admin login.
                if (event && (event.metaKey || event.ctrlKey) && item.site && item.site.type === 'WordPress') {
                    this.closePalette();
                    this.getLoginLink(item.site.name);
                    return;
                }
                if (event && event.shiftKey && item.site) {
                    this.closePalette();
                    this.openSite(item.site);
                    return;
                }
                item.run();
            },

            paletteRunItem(item) { if (item) item.run(); },

            // --- Row context menu ------------------------------------------
            openRowMenu(site, event) {
                // Show first, then clamp using the menu's real size — the item
                // set varies by site type, so a guessed height either wastes
                // margin or lets the bottom items land off-screen.
                this.ctxMenu = { open: true, site, x: event.clientX, y: event.clientY, openedAt: event.timeStamp };
                this.renderCtxMenu();
                const rect = $id('ctxMenu').getBoundingClientRect();
                this.ctxMenu.x = Math.max(8, Math.min(event.clientX, window.innerWidth - rect.width - 8));
                this.ctxMenu.y = Math.max(8, Math.min(event.clientY, window.innerHeight - rect.height - 8));
                this.renderCtxMenu();
                this.renderList(); // row highlight
            },

            closeRowMenu() {
                if (!this.ctxMenu.open) return;
                this.ctxMenu.open = false;
                show($id('ctxMenu'), false);
                this.renderList();
            },

            // --- Pinning ---------------------------------------------------
            isPinned(name) { return this.pinned.includes(name); },

            togglePin(name) {
                if (this.isPinned(name)) {
                    this.pinned = this.pinned.filter(n => n !== name);
                } else {
                    this.pinned = [...this.pinned, name];
                }
                localStorage.setItem('pinned', JSON.stringify(this.pinned));
                this.render();
            },

            // --- Keyboard list navigation ----------------------------------
            moveSelection(delta) {
                const list = this.filteredSites;
                if (!list.length) return;
                const cur = list.findIndex(s => s.name === this.selectedName);
                let next = cur === -1 ? (delta > 0 ? 0 : list.length - 1) : cur + delta;
                next = Math.max(0, Math.min(list.length - 1, next));
                this.selectedName = list[next].name;
                this.renderList();
                const el = document.querySelectorAll('.site-row')[next];
                if (el && el.scrollIntoView) el.scrollIntoView({ block: 'nearest' });
            },

            selectedSite() {
                return this.filteredSites.find(s => s.name === this.selectedName) || null;
            },

            setSort(key) {
                // Click the active header to flip direction; a new key
                // starts at its natural default (a→z for name, biggest /
                // most recent first for size and modified).
                if (this.sort === key) {
                    this.sortDir = this.sortDir === 'asc' ? 'desc' : 'asc';
                } else {
                    this.sort = key;
                    this.sortDir = key === 'name' ? 'asc' : 'desc';
                }
                localStorage.setItem('sort', this.sort);
                localStorage.setItem('sortDir', this.sortDir);
                this.render();
            },

            openSite(site) {
                // Don't navigate when the click was part of a drag-to-select,
                // so users can still grab the domain/size text to copy.
                if (window.getSelection && window.getSelection().toString()) return;
                window.open(site.domain, '_blank', 'noopener');
            },

            showSnack(msg, isError = false, opts = {}) {
                if (this.snackbar.timer) clearTimeout(this.snackbar.timer);
                this.snackbar = {
                    visible: true, message: msg, isError, timer: null,
                    action: opts.action || null,
                    actionLabel: opts.actionLabel || ''
                };
                this.snackbar.timer = setTimeout(() => { this.snackbar.visible = false; this.renderSnackbar(); }, opts.duration || 3500);
                this.renderSnackbar();
            },

            async apiPost(action, payload = {}, opts = {}) {
                const { timeoutMs = 0, quiet = false } = opts;
                const ctrl = timeoutMs ? new AbortController() : null;
                const timer = ctrl ? setTimeout(() => ctrl.abort(), timeoutMs) : null;
                try {
                    const res = await fetch('/api.php', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ action, ...payload }),
                        ...(ctrl ? { signal: ctrl.signal } : {})
                    }).then(r => r.json());
                    if (!res.success && !quiet) this.showSnack(res.message || 'An error occurred.', true);
                    return res;
                } catch (e) {
                    // transport marks network-level failures (connection
                    // dropped, timeout) as distinct from server-reported
                    // errors — only these are worth retrying.
                    if (!quiet) this.showSnack('Network error.', true);
                    return { success: false, transport: true };
                } finally {
                    if (timer) clearTimeout(timer);
                }
            },

            async apiPostRetry(action, payload = {}, attempts = 3, timeoutMs = 30000) {
                // The Caddy/FrankenPHP reload the dashboard triggers after
                // add/delete can momentarily drop or hang requests to the
                // dashboard itself. Retry transport failures a few times so
                // an action that lands mid-reload isn't silently lost.
                let res;
                for (let i = 1; i <= attempts; i++) {
                    res = await this.apiPost(action, payload, { timeoutMs, quiet: i < attempts });
                    if (res.success || !res.transport) return res;
                    if (i < attempts) await new Promise(r => setTimeout(r, 3000));
                }
                return res;
            },

            async getSites() {
                this.requestShotSweep();
                this.isLoading = true;
                this.render();
                try {
                    const r = await fetch('/api.php?action=list_sites');
                    const data = await r.json();
                    // Sites staged for deletion are still on disk (nothing
                    // is sent to the backend until the undo window closes),
                    // so a refresh landing mid-window would re-add the rows
                    // the user just deleted — and undo would then push a
                    // second copy of the same row.
                    const staged = new Set(this.pendingDelete ? this.pendingDelete.sites.map(s => s.name) : []);
                    this.sites = data
                        .map(s => ({ ...s, isLoggingIn: false }))
                        .filter(s => !staged.has(s.name));
                } catch (e) {
                    this.showSnack('Could not fetch sites.', true);
                } finally {
                    this.isLoading = false;
                    this.render();
                }
            },

            // A name for an imported site from its archive's filename:
            // "sable-2023-12-22-pre-plant-20260913-120048.zip" → "sable-2023-12-22-pre-plant".
            nameFromArchive(filename) {
                let n = filename.replace(/\.(tar\.gz|tgz|zip)$/i, '').toLowerCase();
                n = n.replace(/[-_ ]?\d{8}[-_]\d{6}(-\d+)?$/, '').replace(/[-_ ]?\d{4}-\d{2}-\d{2}t?\d{2}-?\d{2}-?\d{2}.*$/, '');
                n = n.replace(/[^a-z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
                n = n.replace(/\.localhost$/, '').replace(/-(backup|export|snapshot|files|site)$/, '');
                if (!n) n = 'imported';
                let cand = n, i = 2;
                while (this.sites.some(s => s.name === cand)) cand = n + '-' + (i++);
                return cand;
            },

            setImportFile(file) {
                if (file && !/\.(zip|tar\.gz|tgz)$/i.test(file.name)) { this.showSnack('That is not a zip or tar.gz.', true); return; }
                this.importFile = file || null;
                const drop = $id('addDrop');
                drop.classList.toggle('has-file', !!file);
                $id('addRow').classList.toggle('has-import', !!file);
                show($id('addDropFile'), !!file);
                show($id('addDropText'), !file);
                if (file) {
                    $id('addDropName').textContent = file.name + ' · ' + this.formatSize(file.size);
                    if (!this.newSite.name) { this.newSite.name = this.nameFromArchive(file.name); $id('newSiteName').value = this.newSite.name; }
                    this.newSite.isPlain = false;
                    $id('newSitePlain').checked = false;
                }
                this.render();
                $id('newSiteName').focus();
            },

            async importSite() {
                const name = this.newSite.name;
                const file = this.importFile;
                if (!name || !file) return;
                this.newSite.isLoading = true;
                this.importing = { pct: 0, phase: 'uploading' };
                this.render();
                const fd = new FormData();
                fd.append('action', 'import_site');
                fd.append('site_name', name);
                fd.append('files[]', file, file.name);
                const res = await new Promise(resolve => {
                    const xhr = new XMLHttpRequest();
                    xhr.open('POST', '/api.php');
                    xhr.upload.onprogress = (e) => { if (e.lengthComputable && this.importing) { this.importing.pct = Math.round(e.loaded / e.total * 100); if (this.importing.pct >= 100) this.importing.phase = 'importing'; this.renderImportProgress(); } };
                    xhr.onload = () => { try { resolve(JSON.parse(xhr.responseText)); } catch (e) { resolve({ success: false, message: 'Import failed (' + xhr.status + ').' }); } };
                    xhr.onerror = () => resolve({ success: false, message: 'Network error during the upload.' });
                    xhr.send(fd);
                });
                this.importing = null;
                this.newSite.isLoading = false;
                if (!res.success) {
                    this.showSnack(res.message || 'The import failed.', true);
                    if (res.output) console.warn('cove import:', res.output);
                    this.render();
                    return;
                }
                this.sites.push({
                    name,
                    domain: 'https://' + name + '.localhost' + PORT_SUFFIX,
                    type: 'WordPress',
                    display_path: '~/Cove/Sites/' + name + '.localhost',
                    full_path: SITES_DIR + '/' + name + '.localhost',
                    size_bytes: (typeof res.size_bytes === 'number') ? res.size_bytes : null,
                    modified_at: Math.floor(Date.now() / 1000),
                    isLoggingIn: false,
                });
                this.showSnack('Imported ' + name + '.localhost.');
                this.setImportFile(null);
                this.newSite.name = '';
                $id('newSiteName').value = '';
                this.adding = false;
                this.apiPost('reload_server');
                this.alerts.push({ id: Date.now() + Math.random(), name, isPlain: false, isLoggingIn: false });
                this.render();
                this.getSites();
            },

            renderImportProgress() {
                const imp = this.importing;
                show($id('addProgress'), !!imp);
                $id('addRow').classList.toggle('is-importing', !!imp);
                if (imp) $id('addProgressText').textContent = imp.phase === 'uploading' ? 'uploading ' + imp.pct + '%…' : 'importing — creating the site, restoring files and database, rewriting URLs. A large archive takes a few minutes.';
                const label = $id('createLabel');
                if (imp) label.textContent = imp.phase === 'uploading' ? 'uploading…' : 'importing…';
                else if (this.importFile) label.textContent = 'create & import';
            },

            async addSite() {
                if (!this.newSite.name) return;
                if (this.importFile) { this.importSite(); return; }
                this.newSite.isLoading = true;
                this.render();
                const name = this.newSite.name;
                const isPlain = this.newSite.isPlain;
                // 'latest' is the server's default, so it's sent as nothing
                // at all — keeps the generated command identical to what a
                // plain `cove add <name>` produces.
                const wpVersion = isPlain ? '' : this.newSite.wpVersion;

                const add = await this.apiPost('add_site', { site_name: name, is_plain: isPlain, wp_version: (wpVersion && wpVersion !== 'latest') ? wpVersion : undefined });
                if (add.success) {
                    // Optimistic insert: we already know every field the row
                    // template uses. No auto-refresh — the Caddy reload that
                    // follows can take tens of seconds on fleets with lots of
                    // sites and would either hang the fetch or drop the UI
                    // into an ERR_CONNECTION_REFUSED during the config swap.
                    this.sites.push({
                        name,
                        domain: 'https://' + name + '.localhost' + PORT_SUFFIX,
                        type: isPlain ? 'Plain' : 'WordPress',
                        display_path: '~/Cove/Sites/' + name + '.localhost',
                        full_path: SITES_DIR + '/' + name + '.localhost',
                        // Server calculates size in add_site and returns it
                        // alongside success. Fall back to null so the row
                        // shows "—" until the next refresh if anything failed.
                        size_bytes: (typeof add.size_bytes === 'number') ? add.size_bytes : null,
                        modified_at: Math.floor(Date.now() / 1000),
                        isLoggingIn: false,
                    });
                    this.showSnack('Site created.');
                    this.newSite.name = '';
                    $id('newSiteName').value = '';
                    this.newSite.wpVersion = 'latest';
                    $id('wpVersionSelect').value = 'latest';
                    this.adding = false;
                    this.apiPost('reload_server'); // fire and forget — Caddy reloads in the background

                    // Surface a persistent alert so the user can jump
                    // straight into the new site without hunting for the
                    // row. WP sites get a one-time admin login; plain
                    // sites get a simple "open site" link.
                    this.alerts.push({
                        id: Date.now() + Math.random(),
                        name,
                        isPlain,
                        isLoggingIn: false,
                    });
                }
                this.newSite.isLoading = false;
                this.render();
            },

            async loginToNewSite(alert) {
                alert.isLoggingIn = true;
                this.renderAlerts();
                const res = await this.apiPost('get_login_link', { site_name: alert.name });
                if (res.success && res.url) {
                    window.open(res.url, '_blank');
                    // Acted on — banner's job is done. The new tab has the
                    // one-time URL; dashboard can drop the prompt.
                    this.dismissAlert(alert.id);
                }
                alert.isLoggingIn = false;
                this.renderAlerts();
            },

            dismissAlert(id) {
                this.alerts = this.alerts.filter(a => a.id !== id);
                this.renderAlerts();
            },

            deleteSite(name) {
                const site = this.sites.find(s => s.name === name);
                if (!site) return;
                this.stageDeletes([site]);
            },

            bulkDelete() {
                // A dialog, not an armed button: it names every site the
                // filter matched and asks for the count to be typed before
                // anything is staged. The undo snackbar still follows.
                const sites = [...this.filteredSites];
                if (!sites.length) return;
                this.bulkConfirm = { names: sites.map(s => s.name) };
                const n = sites.length;
                $id('bulkDeleteTitle').textContent = 'Delete ' + n + ' site' + (n === 1 ? '' : 's') + '?';
                $id('bulkDeleteSub').textContent = 'Every site below goes: its directory (public/, uploads, logs) and its database. You get a few seconds to undo afterwards.';
                const list = $id('bulkDeleteList');
                list.innerHTML = '';
                for (const s of sites) { const li = document.createElement('li'); li.textContent = s.name + '.localhost'; list.appendChild(li); }
                const input = $id('bulkDeleteInput');
                input.value = '';
                input.placeholder = 'type ' + n + ' to confirm';
                this.renderBulkConfirm();
                show($id('bulkDeleteModal'), true);
                input.focus();
            },

            renderBulkConfirm() {
                const c = this.bulkConfirm;
                if (!c) return;
                const n = c.names.length;
                const ok = $id('bulkDeleteInput').value.trim() === String(n);
                const btn = $id('btnBulkDeleteConfirm');
                btn.disabled = !ok;
                btn.textContent = 'delete ' + n + ' site' + (n === 1 ? '' : 's');
                $id('bulkDeleteHint').textContent = ok ? 'Ready.' : 'Type the number of sites, ' + n + ', to enable the button.';
            },

            closeBulkConfirm() {
                this.bulkConfirm = null;
                show($id('bulkDeleteModal'), false);
            },

            confirmBulkDelete() {
                const c = this.bulkConfirm;
                if (!c || $id('bulkDeleteInput').value.trim() !== String(c.names.length)) return;
                this.closeBulkConfirm();
                const sites = this.sites.filter(s => c.names.includes(s.name));
                this.stageDeletes(sites);
            },

            stageDeletes(sitesToDelete) {
                // Pull the rows from the list immediately (the UI feels
                // instant) but hold the backend work for an undo window.
                // Nothing is deleted server-side until the window passes.
                if (this.pendingDelete) clearTimeout(this.pendingDelete.timer);
                const staged = this.pendingDelete ? this.pendingDelete.sites : [];
                for (const site of sitesToDelete) {
                    const idx = this.sites.findIndex(s => s.name === site.name);
                    if (idx !== -1) { this.sites.splice(idx, 1); staged.push(site); }
                }
                if (!staged.length) { this.pendingDelete = null; this.render(); return; }
                this.pendingDelete = {
                    sites: staged,
                    timer: setTimeout(() => this.commitPendingDeletes(), 5000)
                };
                this.render();
                const label = staged.length === 1
                    ? 'Deleted ' + staged[0].name + '.'
                    : 'Deleted ' + staged.length + ' sites.';
                this.showSnack(label, false, {
                    actionLabel: 'undo',
                    action: () => this.undoPendingDeletes(),
                    duration: 5000
                });
            },

            commitPendingDeletes() {
                if (!this.pendingDelete) return;
                const names = this.pendingDelete.sites.map(s => s.name);
                this.pendingDelete = null;
                // processDeleteQueue drains the queue single-file so
                // concurrent deletes don't race on shared state (Caddyfile
                // regeneration, /etc/hosts edits).
                this.deleteQueue.push(...names);
                this.processDeleteQueue();
            },

            undoPendingDeletes() {
                if (!this.pendingDelete) return;
                clearTimeout(this.pendingDelete.timer);
                // renderList re-sorts, so push order is fine.
                this.sites.push(...this.pendingDelete.sites);
                this.pendingDelete = null;
                if (this.snackbar.timer) clearTimeout(this.snackbar.timer);
                this.snackbar.visible = false;
                this.render();
                this.renderSnackbar();
            },

            async processDeleteQueue() {
                // Single-flight runner: whichever call picks up the lock drains the
                // full queue. Concurrent deleteSite() calls just enqueue and return.
                if (this.isProcessingQueue) return;
                this.isProcessingQueue = true;

                let anyFailed = false;
                try {
                    // Outer loop catches deletes queued while we were awaiting the
                    // reload below — otherwise they'd sit forever because the next
                    // deleteSite() call short-circuits on isProcessingQueue.
                    while (this.deleteQueue.length > 0) {
                        while (this.deleteQueue.length > 0) {
                            const target = this.deleteQueue.shift();
                            const del = await this.apiPostRetry('delete_site', { site_name: target });
                            if (del.success) {
                                // Don't stomp a newer batch's undo snackbar
                                // with a routine confirmation.
                                if (!this.pendingDelete) this.showSnack('Site deleted.');
                            } else {
                                anyFailed = true; // apiPost already surfaced the error
                            }
                        }
                        // Kick a reload at the end of the batch. Race-safety
                        // lives server-side: cove_reload() uses a mkdir lock
                        // with a pending marker to coalesce concurrent calls,
                        // since reload_server itself backgrounds the shell
                        // command (shell_exec '...&') and returns instantly.
                        // Two unsynchronized frankenphp reload calls otherwise
                        // deadlock Caddy's admin server (10s shutdown timeout).
                        await this.apiPostRetry('reload_server', {}, 3, 10000);
                    }
                } finally {
                    this.isProcessingQueue = false;
                }

                // If anything failed mid-queue the optimistic UI is now out of sync
                // with the backend (e.g. a survivor is missing from our list).
                // Cheapest correct fix: re-fetch the authoritative list.
                if (anyFailed) await this.getSites();
            },

            async getLoginLink(name) {
                const site = this.sites.find(s => s.name === name);
                if (!site) return;
                site.isLoggingIn = true;
                this.renderList();
                this.renderSitePage();
                const res = await this.apiPost('get_login_link', { site_name: name });
                if (res.success && res.url) {
                    window.open(res.url, '_blank');
                    this.showSnack('Login link opened in a new tab.');
                }
                site.isLoggingIn = false;
                this.renderList();
                this.renderSitePage();
            },

            async copyPath(path) {
                try {
                    await navigator.clipboard.writeText(path);
                    this.showSnack('Path copied to clipboard.');
                } catch (e) {
                    this.showSnack('Could not copy path.', true);
                }
            },

            async refreshSizes() {
                this.isRefreshingSizes = true;
                this.renderFooter();
                const res = await this.apiPost('refresh_sizes');
                if (res.success) {
                    await this.getSites();
                    this.showSnack('Disk sizes updated.');
                }
                this.isRefreshingSizes = false;
                this.renderFooter();
            }
        };

        // The script sits at the end of <body>, so the DOM is already parsed.
        app.init();
    </script>
</body>
</html>
EOM

    # Find the absolute path to this script to pass to the GUI
    local script_dir
    script_dir=$(cd "$(dirname "$0")" && pwd)
    local absolute_script_path="$script_dir/$(basename "$0")"
    
    # Escape the paths for use in `sed`
    local escaped_path
    escaped_path=$(printf '%s\n' "$absolute_script_path" | sed -e 's/[\/&]/\\&/g')
    local escaped_sites_dir
    escaped_sites_dir=$(printf '%s\n' "$SITES_DIR" | sed -e 's/[\/&]/\\&/g')
    local escaped_home
    escaped_home=$(printf '%s\n' "$HOME" | sed -e 's/[\/&]/\\&/g')
    
    # Substitute placeholders in both api.php and index.php
    sed -e "s/COVE_EXECUTABLE_PATH_PLACEHOLDER/${escaped_path}/g" \
        -e "s/SITES_DIR_PLACEHOLDER/${escaped_sites_dir}/g" \
        -e "s/USER_HOME_PLACEHOLDER/${escaped_home}/g" \
        -e "s/IS_WSL_PLACEHOLDER/${IS_WSL}/g" \
        "$GUI_DIR/api.php.tmp" > "$GUI_DIR/api.php"

    sed -e "s/SITES_DIR_PLACEHOLDER/${escaped_sites_dir}/g" \
        "$GUI_DIR/index.php.tmp" > "$GUI_DIR/index.php"
        
    # Clean up temp files
    rm "$GUI_DIR/api.php.tmp" "$GUI_DIR/index.php.tmp"
}

# --- Help Functions ---
# Help formatting. On a terminal the group names are bold and the command
# is shown as it is typed, "cove add", in the accent colour; piped or
# redirected output gets plain text.
help_section() {
    if [ -t 1 ]; then printf '\033[1m%s\033[0m\n' "$1"; else echo "$1"; fi
}
help_cmd() {
    local cmd="$1" desc="$2"
    if [ -t 1 ]; then
        printf '  \033[2mcove\033[0m \033[36m%-16s\033[0m %s\n' "$cmd" "$desc"
    else
        printf '  cove %-16s %s\n' "$cmd" "$desc"
    fi
}

show_general_help() {
    echo "Cove - A tool for managing local development sites."
    echo ""
    echo "Usage: cove <command> [options]"
    echo ""
    echo "For help with a specific command, run: cove <command> --help"
    echo ""
    help_section "Sites"
    help_cmd add "Creates a new WordPress or plain static site."
    help_cmd import "Create a new site from a backup archive (zip or tar.gz)."
    help_cmd clone "Copies an existing site, database and all, under a new name."
    help_cmd list "Lists all sites currently managed by Cove."
    help_cmd rename "Renames a site, its directory, and database."
    help_cmd delete "Deletes a site's directory and associated database."
    help_cmd path "Outputs the full path to a site's directory."
    help_cmd url "Prints the HTTPS URL for a given site."
    echo ""
    help_section "WordPress"
    help_cmd login "Generates a one-time login link for a WordPress site."
    help_cmd wp "Runs WP-CLI inside a site from anywhere."
    help_cmd core "Report or update the WordPress version of your sites."
    help_cmd network "Lists the sites on a multisite network."
    help_cmd php "Pin a site to an older PHP (native php-fpm behind FrankenPHP)."
    echo ""
    help_section "Backups & transfer"
    help_cmd backup "A site's files and database as one zip, in ~/Cove/Backups."
    help_cmd snapshot "Take, list, restore, or delete snapshots of a site."
    help_cmd history "Nightly saves of plugins and themes; roll any of them back."
    help_cmd db "Manage databases (e.g., 'cove db backup')."
    help_cmd pull "Pulls a remote WordPress site into Cove via SSH."
    help_cmd push "Pushes a local Cove site to a remote WordPress site via SSH."
    help_cmd transfer "Inspect the backup/restore engine used by pull and push."
    echo ""
    help_section "Inspect"
    help_cmd log "View logs for a site or the global error log."
    help_cmd screenshot "Capture a site's front page with a headless browser."
    help_cmd health "Diagnose crashes, OPcache pressure, and on-disk hygiene."
    help_cmd status "Check the status of all background services."
    echo ""
    help_section "Serving & access"
    help_cmd share "Create a temporary public tunnel to share a site."
    help_cmd lan "Enable LAN access to sites for mobile app sync."
    help_cmd tailscale "Expose all sites to your Tailscale network."
    help_cmd mappings "Extra domains a site answers on; a '*.' entry covers every subdomain."
    help_cmd directive "Add or remove custom Caddyfile rules for a site."
    help_cmd proxy "Manage standalone reverse proxy entries."
    help_cmd ports "Reconfigure HTTP/HTTPS ports + update site URLs."
    help_cmd trust "Install Cove's local CA into browser + system trust stores."
    if [ "$IS_WSL" = true ]; then
        help_cmd wsl-hosts "Show Windows hosts file update commands."
    fi
    echo ""
    help_section "Services & PHP"
    help_cmd enable "Starts the Caddy, MariaDB, and Mailpit background services."
    help_cmd disable "Stops all background services managed by Cove."
    help_cmd reload "Regenerates the Caddyfile and reloads the Caddy server."
    help_cmd memory "Show or raise PHP memory_limit across Cove + Homebrew PHPs."
    help_cmd opcache "Show or resize FrankenPHP's shared OPcache (all sites share it)."
    help_cmd signals "Check or repair FrankenPHP's SIGSEGV handler (parallel extension crash guard)."
    echo ""
    help_section "Cove itself"
    help_cmd install "Installs and configures Homebrew dependencies."
    help_cmd upgrade "Upgrades Cove to the latest available version."
    help_cmd version "Displays the current version of Cove."
    if [ "$OS" == "macos" ]; then
        help_cmd menubar "Manage the macOS menu bar companion app."
    elif [ "$OS" == "linux" ] && [ "$IS_WSL" != true ]; then
        help_cmd menubar "Manage the system tray companion app."
    fi
}

display_command_help() {
    local cmd="$1"
    case "$cmd" in
        install)
            echo "Usage: cove install [--yes] [--http PORT] [--https PORT]"
            echo "                    [--db-root-user USER] [--db-root-pass PASS]"
            echo ""
            echo "Installs and configures Homebrew dependencies like Caddy, MariaDB, and Mailpit."
            echo "It also sets up the required directory structure inside '~/Cove'."
            echo ""
            echo "Options:"
            echo "  --yes, -y, --force   Skip confirmation prompts for scripted installs."
            echo "                       Auto-enabled when stdin is not a TTY."
            echo "  --http PORT          Set the HTTP port outright, skipping the port menus."
            echo "  --https PORT         Set the HTTPS port outright, skipping the port menus."
            echo "                       Without these, a scripted install keeps the configured"
            echo "                       ports and reports (rather than prompts on) a conflict."
            echo "  --db-root-user USER  MariaDB root user, used only if automatic database setup"
            echo "  --db-root-pass PASS  fails. Without them that fallback needs a terminal."
            ;;
        enable)
            echo "Usage: cove enable"
            echo ""
            echo "Starts the Caddy, MariaDB, and Mailpit background services."
            ;;
        disable)
            echo "Usage: cove disable"
            echo ""
            echo "Stops all background services managed by Cove."
            ;;
        status)
            echo "Usage: cove status [--porcelain]"
            echo ""
            echo "Checks the status of all background services."
            echo ""
            echo "Options:"
            echo "  --porcelain    Stable machine-readable output (key=value per line),"
            echo "                 as consumed by the menu bar app."
            ;;
        health)
            echo "Usage: cove health"
            echo ""
            echo "Read-only diagnostic. Reports service liveness, the FrankenPHP"
            echo "process state and last exit code, recent hard segfaults"
            echo "(classified as OPcache vs Imagick vs other), live OPcache"
            echo "pressure, and on-disk hygiene (zombie site dirs, oversized"
            echo "logs). Recommends fixes but changes nothing."
            ;;
        transfer)
            echo "Usage: cove transfer probe [site]"
            echo ""
            echo "Reports which tools the backup/restore engine behind 'cove pull' and"
            echo "'cove push' will use here. Cove implements backup and restore itself"
            echo "rather than fetching an external script, and degrades gracefully:"
            echo "archiving prefers zip, then tar, then PHP; the database is dumped and"
            echo "imported with mysqldump/mysql when present and through WordPress's own"
            echo "\$wpdb when not. Since the target is always a WordPress install, PHP is"
            echo "guaranteed — so a host with none of zip, unzip, tar, or a MySQL client"
            echo "still transfers, just more slowly. Missing tools are installed when the"
            echo "host allows it, and a remote with no WP-CLI gets wp-cli.phar sideloaded"
            echo "over SSH."
            ;;
        trust)
            echo "Usage: cove trust"
            echo ""
            echo "Installs Cove's local root certificate into the system trust store"
            echo "and browser NSS databases (Firefox, Chromium — including snap)."
            echo "Run once after install; re-run anytime to refresh."
            ;;
        list)
            echo "Usage: cove list [--totals]"
            echo ""
            echo "Lists all sites currently managed by Cove, showing their domain and type (WordPress/Plain)."
            echo ""
            echo "Flags:"
            echo "  --totals       Calculates and displays the size of each site's public directory."
            ;;
        add)
            echo "Usage: cove add <name> [flavor]"
            echo ""
            echo "Creates a new local site accessible at 'https://<name>.localhost'."
            echo ""
            echo "Arguments:"
            echo "  <name>         The name for the new site. Becomes the subdomain."
            echo "  [flavor]       What goes inside the site. Defaults to the latest WordPress."
            echo "                   <version>  A WordPress version: 6.4, 6.4.3, or 6.9-RC1."
            echo "                   nightly    WordPress trunk, rebuilt daily."
            echo "                   latest     The newest WordPress release (the default)."
            echo "                   plain      A static HTML site with no database."
            echo ""
            echo "Flags:"
            echo "  --plain        Alias for the 'plain' flavor."
            echo "  --php=<ver>    Pin the site to an older PHP (see 'cove php')."
            echo "  --multisite    Install a WordPress multisite network (subdirectory"
            echo "                 mode: <name>.localhost/store/). Use --multisite=subdomain"
            echo "                 for subdomain mode (store.<name>.localhost) — subsites"
            echo "                 resolve and get HTTPS automatically, no extra setup."
            echo ""
            echo "Examples:"
            echo "  cove add mysite                        Latest WordPress."
            echo "  cove add mysite 6.4.3                  WordPress pinned to 6.4.3."
            echo "  cove add mysite nightly                WordPress trunk."
            echo "  cove add mysite plain                  Static site, no database."
            echo "  cove add mysite --multisite            Subdirectory multisite network."
            echo "  cove add mysite --multisite=subdomain  Subdomain multisite network."
            ;;
        clone)
            echo "Usage: cove clone <source> <new-name>"
            echo ""
            echo "Copies an existing site to a new one — files, database, and custom"
            echo "Caddy directives — rewriting the site URL to the new hostname."
            echo ""
            echo "Seed a site once (WooCommerce, users, sample content) and stamp copies"
            echo "of it instead of building the same fixture over and over."
            echo ""
            echo "Arguments:"
            echo "  <source>       The existing site to copy."
            echo "  <new-name>     Name for the copy. Becomes the subdomain."
            echo ""
            echo "Notes:"
            echo "  Admin credentials are inherited from the source site."
            echo "  On APFS and btrfs the file copy is copy-on-write, so it is fast and"
            echo "  the two copies share disk until one is written to."
            echo ""
            echo "Example:"
            echo "  cove clone woo-template poc-acme"
            ;;
        core)
            echo "Usage: cove core <check|update> [options]"
            echo ""
            echo "Reports and updates the WordPress version installed on your sites."
            echo "Distinct from 'cove upgrade', which upgrades Cove itself."
            echo ""
            echo "Subcommands:"
            echo "  check                        Show every site's WordPress version, flagging"
            echo "                               releases wp.org marks outdated or insecure."
            echo "  update <site> [version]      Update one site to the latest release, or to a"
            echo "                               specific version (which may be a downgrade)."
            echo "  update --all                 Update every site that is behind."
            echo ""
            echo "Flags:"
            echo "  --all          Apply to every WordPress site."
            echo "  --dry-run      List what would change without touching anything."
            echo "  --yes, -y      Skip the confirmation prompt."
            echo ""
            echo "Examples:"
            echo "  cove core check"
            echo "  cove core update mysite"
            echo "  cove core update mysite 6.4.3"
            echo "  cove core update --all --dry-run"
            ;;
        delete)
            echo "Usage: cove delete <name> [--force]"
            echo ""
            echo "Deletes a site's directory and associated WordPress database."
            echo ""
            echo "Arguments:"
            echo "  <name>         The name of the site to delete."
            echo ""
            echo "Flags:"
            echo "  --force        Deletes a site without the interactive confirmation prompt."
            ;;
        rename)
            echo "Usage: cove rename <old-name> <new-name>"
            echo ""
            echo "Renames an existing local site."
            echo "This command will rename the site's directory, update its database name and"
            echo "contents for WordPress sites, and regenerate the server configuration."
            echo ""
            echo "Arguments:"
            echo "  <old-name>     The current name of the site to rename."
            echo "  <new-name>     The new name for the site."
            ;;
        directive)
            echo "Usage: cove directive <subcommand>"
            echo ""
            echo "Add or remove custom Caddyfile rules for a site."
            echo "Opens an editor to add/edit rules which are then included in the main Caddyfile."
            echo
            echo "Subcommands:"
            echo "  add                 Adds a rule to the Caddyfile for the specified site."
            echo "  update              Updates a rule in the Caddyfile for the specified site."
            echo "  delete <name>       Deletes custom rules from the Caddyfile for the specified site."
            echo "  list                Lists all custom directives for all managed sites."
            echo ""
            echo "Flags:"
            echo "  --rules \"...\"       Directives as a string, instead of opening the editor."
